/// A VCS artifact (PR / issue / commit) referenced in a session, scraped locally
/// from transcript tool output. Scope is any PR/issue/MR URL or `git commit`
/// summary that appears in tool output (not only artifacts the session authored
/// — e.g. a `gh pr view` of someone else's PR also counts). Opt-in (stripped
/// before upload unless the backend activity hint enabled it); values are
/// canonical and content-free by construction (clean authority, no credentials/
/// query/percent-encoding, path truncated at the numeric id) so the backend
/// accepts them unchanged.
#[derive(Debug, Clone, Serialize, PartialEq, Eq, PartialOrd, Ord)]
pub struct SessionArtifact {
    pub kind: String,
    pub value: String,
}

/// Maximum VCS artifacts retained per session (runaway-transcript guard).
const MAX_SESSION_ARTIFACTS: usize = 50;

fn is_zero_u64(value: &u64) -> bool {
    *value == 0
}

fn is_zero_u8(value: &u8) -> bool {
    *value == 0
}

fn is_zero_u16(value: &u16) -> bool {
    *value == 0
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn default_true() -> bool {
    true
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ScanTraversalPath {
    scan_root: PathBuf,
    path: PathBuf,
    #[serde(default = "default_true")]
    census_member: bool,
    #[serde(default)]
    watcher_hint: bool,
}

/// C1b: the stale Claude families a red-retry traversal start carried instead
/// of re-arming them, and the one replay buffer that start funded for their
/// cancellations. `replay` is reserved at the start for every carried
/// family's worst case (all its indexed members) and re-reserved when a page
/// resumes the traversal, because a saved and loaded buffer keeps no spare
/// capacity. A cancellation only pushes into that reserved capacity; page
/// selection drains it within the page's file limit.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
struct ClaudeStaleFamilyCarry {
    /// Bound to the retained state, independently of the lenient progress
    /// leaf. Missing (including an older decoder's rewrite) means BASE.
    #[serde(
        skip_serializing_if = "Option::is_none",
        deserialize_with = "deserialize_lenient_default"
    )]
    origin: Option<ClaudeStaleFamilyCarryOrigin>,
    /// Carried roots not yet cancelled or uncarried.
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    roots: BTreeSet<String>,
    /// Fix 2 capped roots also use the funded member-change cancellation.
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    capped_roots: BTreeSet<String>,
    /// Passed members a cancellation queued again in this window.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    replay: Vec<ScanTraversalPath>,
}

// #720 wrote the union into `roots`. Accept that shape on decode, but never
// expose capped roots to a pre-#720 reader, whose roots mean C1b only.
impl Serialize for ClaudeStaleFamilyCarry {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        #[derive(Serialize)]
        struct View<'a> {
            #[serde(skip_serializing_if = "Option::is_none")]
            origin: &'a Option<ClaudeStaleFamilyCarryOrigin>,
            #[serde(skip_serializing_if = "C1bRoots::is_empty")]
            roots: C1bRoots<'a>,
            #[serde(skip_serializing_if = "BTreeSet::is_empty")]
            capped_roots: &'a BTreeSet<String>,
            #[serde(skip_serializing_if = "Vec::is_empty")]
            replay: &'a Vec<ScanTraversalPath>,
        }
        struct C1bRoots<'a>(&'a ClaudeStaleFamilyCarry);
        impl C1bRoots<'_> {
            fn is_empty(&self) -> bool {
                self.0
                    .roots
                    .difference(&self.0.capped_roots)
                    .next()
                    .is_none()
            }
        }
        impl Serialize for C1bRoots<'_> {
            fn serialize<S: Serializer>(
                &self,
                serializer: S,
            ) -> std::result::Result<S::Ok, S::Error> {
                serializer.collect_seq(self.0.roots.difference(&self.0.capped_roots))
            }
        }
        View {
            origin: &self.origin,
            roots: C1bRoots(self),
            capped_roots: &self.capped_roots,
            replay: &self.replay,
        }
        .serialize(serializer)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ClaudeStaleFamilyCarryOrigin {
    context_fingerprint: String,
    process: u64,
    full_rearm_window: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    admission: Option<ClaudeRetryAdmission>,
}

/// Scheduling only: no request, account, or coverage proof. A completed
/// bounded walk advances this cursor; uncovered families keep their bytes.
#[derive(Debug, Clone, Serialize, Deserialize)]
struct ClaudeRetryAdmission {
    after_root: Option<String>,
    upper_root: String,
    complete: bool,
    #[serde(default)]
    roots_complete: bool,
    progressed: bool,
    served_before: u64,
    #[serde(default)]
    due_through: u64,
    #[serde(default)]
    due_after_path: Option<String>,
    #[serde(default)]
    due_upper_path: Option<String>,
    #[serde(default)]
    due_complete: bool,
    #[serde(default)]
    oversized_root: Option<String>,
    #[serde(default)]
    oversized_after_path: Option<String>,
    /// At least one complete accepted singleton could not fund carry storage.
    /// It keeps custody, without a carry/proof grant or a runnable re-arm.
    #[serde(default)]
    storage_deferred: bool,
}

impl ClaudeStaleFamilyCarry {
    fn contains(&self, root: &str) -> bool {
        self.roots.contains(root) || self.capped_roots.contains(root)
    }

    fn is_empty(&self) -> bool {
        self.roots.is_empty()
            && self.capped_roots.is_empty()
            && self.replay.is_empty()
            && self
                .origin
                .as_ref()
                .and_then(|origin| origin.admission.as_ref())
                .is_none()
    }
}

/// Cost-only memory of the Claude duplicate fence's whole-index re-arms
/// (full-rearm Fix 1 and Fix 2). Nothing here can open the fence, credit
/// request evidence or change a body: it only decides whether a due full
/// re-arm, or a stale-pending re-arm after one, would re-read every family
/// file to no effect. Content-free and local: roots and members appear only
/// as truncated SHA-256 digests, windows as census clocks. Decoded leniently
/// (`deserialize_lenient_default`): a malformed value loads empty, so the next
/// due re-arm runs as before and the index is never quarantined for it.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
struct ClaudeFullRearmProgress {
    // Process-local proof: every decode drops it. A restart between read and
    // close therefore fails closed, even if persisted scheduling survives.
    #[serde(skip)]
    rebuild_read_full: bool,
    #[serde(skip)]
    complete_rebuild_read: Option<ClaudeCompleteRebuildRead>,
    /// Census window the page observations below belong to.
    #[serde(skip_serializing_if = "Option::is_none")]
    observed_window: Option<String>,
    /// Digests of roots whose pending is invalid in `observed_window` and one
    /// of whose members parsed there is structurally invalid on its own
    /// (`claude_member_invalidity_is_structural`).
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    structural_roots: BTreeSet<String>,
    /// A page of `observed_window` invalidated a family for a reason that is
    /// not structural (cap, member changed, occurrence key mismatch).
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    other_invalidation_observed: bool,
    // Diagnostic only: a resumed process starts fresh counters, never authority.
    #[serde(skip)]
    ignored_vetoes: u16,
    /// A changed or lost baseline owes a real full re-arm even if a later
    /// observation returns to the old bytes before the deadline.
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    structural_rearm_owed: bool,
    /// The structural set a complete-observation full-rearm terminal recorded.
    #[serde(skip_serializing_if = "Option::is_none")]
    structural_record: Option<ClaudeStructuralInvalidRecord>,
    /// The scanner retires its checkpoint before the terminal fold, so keep
    /// that traversal's origin available until the fold schedules a window.
    #[serde(skip_serializing_if = "Option::is_none")]
    traversal_origin: Option<ClaudeFullRearmWindow>,
    /// Fix 2: a terminal performed a full re-arm behind a closed fence, so
    /// the next traversal start opens a full-rearm window.
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    full_rearm_window_next: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    full_rearm_window: Option<ClaudeFullRearmWindow>,
    /// The fence deadline the stale re-arms below were counted against.
    #[serde(skip_serializing_if = "Option::is_none")]
    stale_rearm_fence_deadline: Option<u64>,
    #[serde(skip_serializing_if = "is_zero_u8")]
    stale_rearms_at_deadline: u8,
    /// A closed terminal since the last full re-arm held a first proof on a
    /// dormant owner (C1a). Only a full re-arm re-reads that owner, so the
    /// skip stays vetoed until one runs or the fence opens.
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    first_proof_hold_since_full_rearm: bool,
    /// Option A (SOURCE 2026-10-27): root digests of the families whose local
    /// holds stamped `CompletedBlockingHolds` in this sweep, at most
    /// `MAX_SCOPED_HELD_FAMILY_ROOTS`. `Some` only while every stamp of the
    /// sweep flag named its held families; read only through
    /// `ScanIndex::unchanged_proof_unsettled_families`. Lost or malformed, it
    /// loads `None`, which keeps the sweep-wide unchanged-proof veto.
    #[serde(skip_serializing_if = "Option::is_none")]
    held_family_roots: Option<BTreeSet<String>>,
    /// Lead A ruling (a): the `""` cutover's latch re-arms at one terminal.
    #[serde(skip_serializing_if = "is_zero_u8")]
    contract_cutover: u8,
}

impl ClaudeFullRearmProgress {
    fn is_empty(&self) -> bool {
        self == &Self::default()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ClaudeCompleteRebuildRead {
    origin: ClaudeFullRearmWindow,
    members_digest: String,
}

/// Exact indexed family membership/revisions, including structurally invalid
/// members whose pending accumulation can stop before its final member.
fn claude_rebuild_members_digest(index: &ScanIndex) -> String {
    let mut digest = Sha256::new();
    update_length_prefixed(&mut digest, b"claude_complete_rebuild_read:v1");
    for (key, entry) in &index.files {
        if claude_index_path_member_ref(Path::new(key)).is_some() {
            update_length_prefixed(&mut digest, key.as_bytes());
            update_length_prefixed(&mut digest, entry.source_file_fingerprint.as_bytes());
        }
    }
    format!("{:x}", digest.finalize())
}

/// Seal only a single, uncapped, loss-free pass that actually parsed every
/// current family member. Reusing a checkpoint, a tail, or a cached reduction
/// cannot certify a complete rebuild. Multi-page rebuilds conservatively rearm.
fn seal_claude_complete_rebuild_read(
    index: &mut ScanIndex,
    pending: &[PendingIndexFinalization],
    complete: bool,
) {
    index.claude_full_rearm_progress.complete_rebuild_read = None;
    index.claude_full_rearm_progress.rebuild_read_full &= complete;
    if !index.claude_full_rearm_progress.rebuild_read_full {
        return;
    }
    let reads = pending
        .iter()
        .filter(|read| read.parse_complete)
        .map(|read| {
            (
                read.index_key.as_str(),
                read.source_file_fingerprint.as_str(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let mut members = 0;
    for (key, entry) in &index.files {
        if claude_index_path_member_ref(Path::new(key)).is_some() {
            members += 1;
            if entry.source_file_fingerprint.is_empty()
                || reads.get(key.as_str()).copied() != Some(entry.source_file_fingerprint.as_str())
            {
                return;
            }
        }
    }
    if members == 0 {
        return;
    }
    if let Some(origin) = index.claude_full_rearm_progress.traversal_origin.clone() {
        index.claude_full_rearm_progress.complete_rebuild_read = Some(ClaudeCompleteRebuildRead {
            origin,
            members_digest: claude_rebuild_members_digest(index),
        });
    }
}

fn take_claude_complete_rebuild_read(index: &mut ScanIndex, window: &str) -> bool {
    let Some(proof) = index
        .claude_full_rearm_progress
        .complete_rebuild_read
        .take()
    else {
        return false;
    };
    index.claude_rebuild_read_load_eligible
        && proof.origin.process == claude_full_rearm_process()
        && proof.origin.window_ends.contains(window)
        && index.claude_full_rearm_progress.traversal_origin.as_ref() == Some(&proof.origin)
        && proof.members_digest == claude_rebuild_members_digest(index)
        && !index.bounded_sweep_had_unsettled_upload
        && index.decode_holds.is_empty()
        && index.claude_account_deferred_holds.is_empty()
        && index.claude_usage_authority_quarantine.is_empty()
        && index
            .effective_upload_body_witness_revision_excluded_source_files
            .is_empty()
}

/// The structurally invalid family set of one complete-observation terminal:
/// root digest to the digest of every indexed member's (index key, source
/// file fingerprint), under `basis` (derivation versions and the identity
/// contract digest).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct ClaudeStructuralInvalidRecord {
    basis: String,
    families: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    suppressed_since_unix_seconds: Option<u64>,
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    skipped_full_rearms: u64,
}

/// Fix 2: the census windows whose pending came from a full re-arm (and the
/// one stale re-arm allowed after it), in one traversal context of one
/// daemon process. Another context or a restart ignores it (BASE).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct ClaudeFullRearmWindow {
    context_fingerprint: String,
    process: u64,
    window_ends: BTreeSet<String>,
    /// Committed member revisions before this deadline's stale re-arm.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    member_digests: BTreeMap<String, Option<String>>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
struct ScanTraversalCounts {
    discovered_file_count: usize,
    directory_entry_cap_exceeded_count: usize,
    symlink_rejected_count: usize,
    unreadable_path_count: usize,
    unreadable_causes: UnreadableCauses,
    /// PR-P: held fork children per parent cause, traversal-cumulative.
    /// Additive: old checkpoints load as zero (struct-level `serde(default)`).
    parent_unresolvable: ParentUnresolvableCauses,
    oversized_file_count: usize,
    disappeared_file_count: usize,
    malformed_json_line_count: usize,
    invalid_utf8_line_count: usize,
    over_line_cap_count: usize,
    recognized_usage_drop_count: usize,
    ownership_incomplete_file_count: usize,
    zero_snapshot_usage_evidence_count: usize,
    dropped_usage_record_count: u64,
    /// Subset of the public loss counters above that has a durable terminal
    /// disposition. These remain disclosed but do not make an exhausted
    /// traversal retryable.
    #[serde(default)]
    terminal_over_line_cap_count: usize,
    #[serde(default)]
    terminal_recognized_usage_drop_count: usize,
    #[serde(default)]
    terminal_dropped_usage_record_count: u64,
    /// Non-progressing residue promoted to terminal by the generation that
    /// re-derived it. Ownership-incomplete Codex rollouts whose parent
    /// resolution is not pending, files with usage evidence but no entity, and
    /// the usage records those files drop are deterministic functions of their
    /// unchanged bytes, sidecar and parent evidence. Their files are never
    /// checkpointed, so every generation parses them again and reaches the
    /// same counts; retrying the traversal cannot change them. Once discovery
    /// finishes without any retryable problem they are settled here so the
    /// census can complete with the loss named, instead of holding every
    /// downstream completeness gate red for as long as those files exist.
    /// See `settle_non_progressing_residue`.
    #[serde(default)]
    terminal_ownership_incomplete_file_count: usize,
    #[serde(default)]
    terminal_zero_snapshot_usage_evidence_count: usize,
    // Persisted positional slots: diagnostic additions must remain last.
    /// retired_<old>: decode-only placeholder; keeps positional slots; never written.
    #[serde(rename = "unchanged_reread_admitted", default, skip_serializing)]
    retired_unchanged_reread_admitted: serde::de::IgnoredAny,
    /// retired_<old>: decode-only placeholder; keeps positional slots; never written.
    #[serde(rename = "reread_budget_refused", default, skip_serializing)]
    retired_reread_budget_refused: serde::de::IgnoredAny,
    #[serde(skip_serializing_if = "ownership::Counts::is_empty")]
    causes: ownership::Counts,
}

/// Residue a generation disclosed as terminal after settling. Counts exclude
/// the over-line-cap loss that already carried its own terminal disposition.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct SettledScanResidue {
    ownership_incomplete_file_count: usize,
    zero_snapshot_usage_evidence_count: usize,
    dropped_usage_record_count: u64,
}

impl ScanTraversalCounts {
    fn record_unreadable(&mut self, cause: UnreadableCause, count: usize) {
        // Preserve the existing public count and operational predicates.
        self.unreadable_path_count += count;
        self.unreadable_causes.record(cause, count as u64);
    }

    /// Loss that a later traversal can still change: a directory the walk
    /// could not enter or finish, an object it could not open or read, a root
    /// that vanished, or a line the parser rejected. These keep their retry
    /// semantics: the census stays red and the bounded retry latch re-walks.
    fn has_retryable_problems(&self) -> bool {
        self.symlink_rejected_count > 0
            || self.directory_entry_cap_exceeded_count > 0
            || self.unreadable_path_count > 0
            || self.oversized_file_count > 0
            || self.disappeared_file_count > 0
            || self.malformed_json_line_count > 0
            || self.invalid_utf8_line_count > 0
            || self.over_line_cap_count > self.terminal_over_line_cap_count
    }

    /// Non-progressing residue this generation has not yet disclosed as
    /// terminal.
    fn has_unsettled_residue(&self) -> bool {
        self.ownership_incomplete_file_count > self.terminal_ownership_incomplete_file_count
            || self.zero_snapshot_usage_evidence_count
                > self.terminal_zero_snapshot_usage_evidence_count
            || self.recognized_usage_drop_count > self.terminal_recognized_usage_drop_count
            || self.dropped_usage_record_count > self.terminal_dropped_usage_record_count
    }

    fn has_errors(&self) -> bool {
        self.has_retryable_problems() || self.has_unsettled_residue()
    }

    /// Promote the non-progressing residue to terminal for this generation.
    ///
    /// Only a generation that has finished discovery and carries no retryable
    /// problem may settle: a walk that could not enter a directory or read an
    /// object may simply not have seen the file that would resolve a fork, so
    /// its residue is not yet known to be non-progressing. The promotion is an
    /// assignment, not an accumulation, so a retained traversal that parses
    /// further pages settles again from the counts it actually re-derived.
    /// Returns true when something was newly settled.
    fn settle_non_progressing_residue(&mut self) -> bool {
        if self.has_retryable_problems() || !self.has_unsettled_residue() {
            return false;
        }
        self.terminal_ownership_incomplete_file_count = self.ownership_incomplete_file_count;
        self.terminal_zero_snapshot_usage_evidence_count = self.zero_snapshot_usage_evidence_count;
        self.terminal_recognized_usage_drop_count = self.recognized_usage_drop_count;
        self.terminal_dropped_usage_record_count = self.dropped_usage_record_count;
        true
    }

    /// The residue this generation settled, if any. Over-line-cap loss carries
    /// its own per-file terminal disposition and is excluded here; its dropped
    /// record share equals `terminal_over_line_cap_count` by construction
    /// (`ParsedJsonlFile::terminal_loss`, `ScanCensus::add_terminal_jsonl_loss`).
    fn settled_residue(&self) -> Option<SettledScanResidue> {
        let dropped_usage_record_count = self
            .terminal_dropped_usage_record_count
            .saturating_sub(self.terminal_over_line_cap_count as u64);
        (self.terminal_ownership_incomplete_file_count > 0
            || self.terminal_zero_snapshot_usage_evidence_count > 0
            || dropped_usage_record_count > 0)
            .then_some(SettledScanResidue {
                ownership_incomplete_file_count: self.terminal_ownership_incomplete_file_count,
                zero_snapshot_usage_evidence_count: self
                    .terminal_zero_snapshot_usage_evidence_count,
                dropped_usage_record_count,
            })
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(default)]
struct TerminalJsonlLoss {
    over_line_cap_count: usize,
    recognized_usage_drop_count: usize,
    dropped_usage_record_count: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct TerminalJsonlDisposition {
    source_file_fingerprint: String,
    parser_generation: String,
    loss: TerminalJsonlLoss,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ScanTraversalCheckpoint {
    context_fingerprint: String,
    census_window_end: String,
    scan_roots: Vec<PathBuf>,
    pending_directories: VecDeque<ScanTraversalPath>,
    pending_candidates: VecDeque<ScanTraversalPath>,
    observed_index_keys: BTreeSet<String>,
    /// Complete current Codex rollout population, including files outside the
    /// usage lookback. Parent-prefix uniqueness cannot ignore an older
    /// duplicate source-session id merely because it is not a usage candidate.
    #[serde(default, skip_serializing_if = "BTreeSet::is_empty")]
    codex_rollout_paths: BTreeSet<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    codex_join_directory_census: Option<codex_file_join::DirectoryCensus>,
    reconciliation_upper_bound: Option<String>,
    reconciliation_after: Option<String>,
    reconciliation_started: bool,
    #[serde(default)]
    watcher_hint_seen: bool,
    /// Scheduling only: a freshness page owes the next ordinary page to the
    /// census. Persist across restart so continuous appends cannot starve it.
    #[serde(default, skip_serializing_if = "is_false")]
    codex_freshness_yield: bool,
    /// At least one ordinary fork needs another clean generation after its
    /// parent ledger was discovered/refreshed later in this bounded pass.
    #[serde(default)]
    codex_parent_resolution_retry_required: bool,
    #[serde(default)]
    unhealthy_retry_attempt: u8,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    unhealthy_retry_not_before_unix_seconds: Option<u64>,
    /// Local scheduling witnesses only. Keys and content markers are hashes;
    /// the sweep-wide oversized count still vetoes every completeness gate.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    oversized_discovery: BTreeMap<String, oversized_discovery::Debt>,
    counts: ScanTraversalCounts,
    /// Files this generation parsed cleanly but could not checkpoint because
    /// their content yields non-progressing residue. Recorded so the settled
    /// counts name their files instead of silently folding them into totals.
    #[serde(default, skip_serializing_if = "ScanTraversalResidue::is_empty")]
    residue: ScanTraversalResidue,
}

// A candidate's scan root is not only where its no-follow open starts: it is
// hashed into the `sampled_native_reduction:v1` scope (`sampled_scan`'s
// `file_scope`), and a scope change makes `ReadPlan::select_mode` take
// `Full(ScopeChanged)`. Under nested roots the two lookups below can differ,
// so each call site keeps the rule it already had; switching one changes later
// Full/Tail decisions. Without nesting at most one root matches and they agree.
impl ScanTraversalCheckpoint {
    /// The deepest configured scan root containing `path`, independent of
    /// `scan_roots` order.
    fn owning_scan_root(&self, path: &Path) -> Option<&PathBuf> {
        self.scan_roots
            .iter()
            .filter(|root| path.starts_with(root))
            .max_by_key(|root| root.components().count())
    }

    /// The first configured scan root, in `scan_roots` order, containing
    /// `path`. Kept by the retry due seed and held-audit progress.
    fn first_matching_scan_root(&self, path: &Path) -> Option<&PathBuf> {
        self.scan_roots.iter().find(|root| path.starts_with(root))
    }
}

/// Per-generation bookkeeping behind `ScanTraversalCounts::settle_non_progressing_residue`.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
struct ScanTraversalResidue {
    /// Local index keys of the residue files (the same key space as `files`).
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    index_keys: BTreeSet<String>,
    /// Codex session ids those files hold out of the inclusive state-only
    /// fallback. They are never pruned from
    /// `ScanIndex::codex_state_only_blocked_session_ids` by settling: the block
    /// records what the rollout's content proved about its ownership, and
    /// releasing it would publish inclusive `tokens_used` for a thread whose
    /// exclusive usage is exactly what could not be determined.
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    blocked_session_ids: BTreeSet<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    codex_inventory_hold: Option<CodexInventoryHold>,
}

impl ScanTraversalResidue {
    fn is_empty(&self) -> bool {
        self.index_keys.is_empty()
            && self.blocked_session_ids.is_empty()
            && self.codex_inventory_hold.is_none()
    }
}

/// Upper bound on each key set of a `CodexInventoryHold`.
const MAX_CODEX_INVENTORY_HOLD_KEYS: usize = MAX_BACKFILL_FILES_PER_SOURCE;

/// Codex candidates a page held only because its header inventory was
/// incomplete, with the evidence that made it incomplete.
///
/// Such a page holds every candidate, including sessions whose own ownership
/// is fine: an unreadable first record may belong to any of them. Those
/// candidates leave the traversal queue, so without this record they waited
/// for their next write or the next walk. They are queued again once the
/// recorded evidence moves (see `release_codex_inventory_hold`), and pass the
/// unchanged inventory and ownership gates like any other candidate. While the
/// evidence stays put nothing is re-read.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
struct CodexInventoryHold {
    /// Local index keys of the held candidates.
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    owed: BTreeSet<String>,
    /// Roster files whose first record was refused, with their metadata
    /// witness at the refusal.
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    refused_headers: BTreeMap<String, Option<String>>,
    /// Held candidates outside the roster, with their metadata witness.
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    outside_roster: BTreeMap<String, Option<String>>,
    /// The walk still had directories to visit. Released once it has none.
    awaiting_directories: bool,
}

/// Durable record of the residue disclosed by the last census that completed
/// with named, non-progressing loss. Written when a generation completes and
/// cleared when a generation completes clean, so an operator reading the index
/// can see which files the machine cannot checkpoint and which Codex sessions
/// are held out of the state-only fallback, rather than inferring it from
/// per-cycle log lines.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
struct ScanResidueWitness {
    census_window_end: String,
    ownership_incomplete_file_count: usize,
    zero_snapshot_usage_evidence_count: usize,
    dropped_usage_record_count: u64,
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    index_keys: BTreeSet<String>,
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    codex_state_only_blocked_session_ids: BTreeSet<String>,
}

impl ScanResidueWitness {
    /// Same residue, ignoring the census clock that advances every cycle.
    fn same_residue(&self, other: &Self) -> bool {
        self.ownership_incomplete_file_count == other.ownership_incomplete_file_count
            && self.zero_snapshot_usage_evidence_count == other.zero_snapshot_usage_evidence_count
            && self.dropped_usage_record_count == other.dropped_usage_record_count
            && self.index_keys == other.index_keys
            && self.codex_state_only_blocked_session_ids
                == other.codex_state_only_blocked_session_ids
    }

    /// Residue files that live under an archived Codex sessions root. An
    /// archived rollout is still inside the configured scan roots, so it is
    /// parsed like any other; the distinction only names where the residue
    /// sits so a report can say so without printing a local path.
    fn archived_residue_file_count(&self) -> usize {
        self.index_keys
            .iter()
            .filter(|key| {
                Path::new(key)
                    .components()
                    .any(|component| component.as_os_str() == "archived_sessions")
            })
            .count()
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
struct CodexParentOwnershipLedger {
    /// Exact ordered, content-free turn/usage signatures from the complete
    /// physical parent rollout. A child must match a non-empty prefix before
    /// its first divergent signature can prove the local boundary.
    signatures: Vec<String>,
    #[serde(default)]
    #[serde(alias = "complete")]
    scan_complete: bool,
    /// Opened-object witness for the exact parent rollout that produced the
    /// signatures. Persisted evidence is usable only after the current parent
    /// path revalidates to this identity; a changed parent therefore makes its
    /// children retry instead of treating the newly inherited suffix as local.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    opened_object_identity: String,
    /// The ctime, mtime and file birth (unix nanos) of that same open. A
    /// later open with this mtime and exactly this birth whose identity,
    /// rebuilt with this ctime and fresh content samples, equals
    /// `opened_object_identity` still revalidates the ledger when only ctime
    /// moved (chmod, xattr, hard link). Zero on older ledgers (or without a
    /// birth), which keep the exact identity comparison.
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    opened_changed_nanos: u64,
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    opened_modified_nanos: u64,
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    opened_birth_nanos: u64,
    /// PR-P: a step-map-only witness that this parent yields no usable ledger
    /// (never persisted, never `scan_complete`, so every existing reader
    /// ignores it). A ledger insert under the same key replaces it.
    #[serde(skip)]
    unresolvable: Option<CodexParentUnresolvable>,
}

/// U1a-2a: the `cause` of a held side verdict (and of a lineage owe) with no
/// `CodexParentUnresolvable`: P's own fork lineage is still pending. Outside
/// every ordinal (`CodexParentUnresolvable::COUNT` is 12).
#[cfg_attr(not(test), allow(dead_code))] // first production caller is the side writers
pub(in crate::snapshots) const CAUSE_NO_EVIDENCE: u8 = 255;
/// U1a-2a: a side request is evicted at this many charged attempts.
pub(in crate::snapshots) const SIDE_REQUEST_EVICT_ATTEMPTS: u8 = 7;
const _: () = assert!(CodexParentUnresolvable::COUNT < CAUSE_NO_EVIDENCE as usize);

/// U1a-2a: the verdict of a parent rollout P's latest certified parse, as
/// the parent of forks whose boundary needs P's prefix. It says whether P's
/// own parse settled; it is never ownership evidence for P or a child.
#[cfg_attr(not(test), allow(dead_code))] // first production caller is the side writers
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub(in crate::snapshots) enum SideVerdict {
    Settled,
    /// `lineage`: held because P's own fork lineage is unresolved. `cause`:
    /// P's own `CodexParentUnresolvable` ordinal, else `CAUSE_NO_EVIDENCE`.
    Held {
        lineage: bool,
        cause: u8,
    },
}
impl crate::heap_layout_bound::HeapLayoutBound for SideVerdict {
    const INLINE_ONLY: bool = true;
    const STABLE_HEAP: bool = true;
    fn heap_bound(&self, c: &mut crate::heap_layout_bound::Counter) -> Option<()> {
        c.add(0)
    }
}

/// U1a-2a: the one side verdict of a parse of P, used by every side writer.
/// Held iff the parse is not complete in PR-P's raw terms.
fn codex_parent_side_verdict(parsed: &ParsedJsonlFile) -> SideVerdict {
    let held = parsed.ownership_incomplete_file_count > 0
        || parsed.codex_parent_resolution_pending
        || !parsed.report.complete()
        || parsed.recognized_usage_drop_count > 0;
    if !held {
        return SideVerdict::Settled;
    }
    SideVerdict::Held {
        lineage: parsed.codex_parent_session_ref.is_some()
            && (parsed.codex_parent_unresolvable.is_some()
                || parsed.codex_parent_resolution_pending),
        cause: codex_parent_side_cause(parsed),
    }
}

/// U1a-2a: the verdict without P's lineage term, for the invalid-census keep
/// only. It discounts the ownership hold that lineage itself sets
/// (`defer_parent_resolution`), so a real downgrade still overwrites.
#[cfg_attr(not(test), allow(dead_code))] // first production caller is the side writers
fn codex_parent_side_verdict_without_lineage(parsed: &ParsedJsonlFile) -> SideVerdict {
    let held = !parsed.report.complete()
        || parsed.recognized_usage_drop_count > 0
        || parsed.dropped_usage_record_count > 0
        || (parsed.ownership_incomplete_file_count > 0
            && parsed.codex_parent_unresolvable.is_none()
            && !parsed.codex_parent_resolution_pending);
    if !held {
        return SideVerdict::Settled;
    }
    SideVerdict::Held {
        lineage: false,
        cause: codex_parent_side_cause(parsed),
    }
}

fn codex_parent_side_cause(parsed: &ParsedJsonlFile) -> u8 {
    parsed
        .codex_parent_unresolvable
        .map_or(CAUSE_NO_EVIDENCE, |cause| cause.index() as u8)
}

/// U1a-2a: the scope every side seal is minted and admitted under. It changes
/// with Codex's parser or scan-identity version, so an older seal refuses
/// `ScopeChanged`. Independent of the scan's curve/identity `Scope`.
fn codex_parent_side_scope() -> crate::transcript_acquisition::Scope {
    crate::transcript_acquisition::Scope(sha256_hex(&[
        "codex_parent_side:v1",
        SnapshotSource::Codex.parser_version(),
        SnapshotSource::Codex.scan_identity_version(),
    ]))
}

/// U1a-2a: P is over main's Codex file cap, so no side record is kept for it.
/// The same predicate main's cap sites use.
#[cfg_attr(not(test), allow(dead_code))] // first production caller is the fence
fn codex_parent_over_cap(len: u64) -> bool {
    len > max_jsonl_file_bytes(SnapshotSource::Codex)
}

/// U1a-2a: the pacing a covering side record keeps after its request is
/// removed, so a re-request for the same object inherits it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub(in crate::snapshots) struct SidePace {
    pub(in crate::snapshots) not_before_unix_seconds: u64,
    pub(in crate::snapshots) attempts_floor: u8,
}
crate::heap_layout_bound::fields!(SidePace; not_before_unix_seconds, attempts_floor);
impl SidePace {
    /// `max(existing, new)` per field: a stub never loosens.
    pub(in crate::snapshots) fn merged(existing: Option<Self>, new: Self) -> Self {
        existing.map_or(new, |old| Self {
            not_before_unix_seconds: old.not_before_unix_seconds.max(new.not_before_unix_seconds),
            attempts_floor: old.attempts_floor.max(new.attempts_floor),
        })
    }

    /// Fix round 2 (DM2): the pace still binds at `now`: a floor, or a
    /// `not_before` still ahead. Its record is not epoch-pruned meanwhile.
    pub(in crate::snapshots) fn active(&self, now: u64) -> bool {
        self.attempts_floor > 0 || self.not_before_unix_seconds > now
    }
}

/// U1a-2a: a side request's state. `Live` is pending; the others are
/// tombstones that only a cure (growth, a new object, a stamp change for the
/// byte-determined ones) re-arms.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub(in crate::snapshots) enum SideRequestState {
    Live,
    /// Seven charged attempts ended without a record.
    Evicted,
    /// A certified read covered less than the children need.
    Short {
        covered: u64,
    },
    /// The source report showed data loss.
    Lossy,
    /// A certified read ended on an unsealed row with a settled verdict.
    Unsealed,
}
impl crate::heap_layout_bound::HeapLayoutBound for SideRequestState {
    const INLINE_ONLY: bool = true;
    const STABLE_HEAP: bool = true;
    fn heap_bound(&self, c: &mut crate::heap_layout_bound::Counter) -> Option<()> {
        c.add(0)
    }
}

/// U1a-2a: one paced request that main also parses an unchanged parent P,
/// so that P's side verdict can be recorded. Keyed by P's index key.
/// Persisted at the next successful save; the process side ledger holds
/// unsaved charges.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub(in crate::snapshots) struct SideRequest {
    /// P's real (dev, ino); the side path is unix-only.
    pub(in crate::snapshots) dev_ino: (u64, u64),
    /// The largest sealed offset any fencing child needs.
    pub(in crate::snapshots) needed_extent: u64,
    pub(in crate::snapshots) state: SideRequestState,
    /// P's extent and ctime when `state` was decided.
    pub(in crate::snapshots) state_extent: u64,
    pub(in crate::snapshots) state_ctime: (i64, i64),
    /// P's extent and ctime at the last charged attempt.
    pub(in crate::snapshots) attempt_extent: u64,
    pub(in crate::snapshots) attempt_ctime: (i64, i64),
    /// Charged at the start of each read; `Evicted` at
    /// `SIDE_REQUEST_EVICT_ATTEMPTS`.
    pub(in crate::snapshots) attempts: u8,
    pub(in crate::snapshots) not_before_unix_seconds: u64,
    /// A capacity loss's reservation (U1a-2b). Always `None` for a singleton.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(in crate::snapshots) needed_charge: Option<usize>,
    /// U1a-2a (D6(b)): `codex_parent_proof_wrap_epoch` at the last child
    /// reference (a fence use) or live sweep visit. 0 is unknown (legacy,
    /// or armed before the first wrap): the sweep stamps it, never prunes
    /// it. Index-only: the ledger projection carries no epoch.
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    pub(in crate::snapshots) referenced_epoch: u64,
}
crate::heap_layout_bound::fields!(SideRequest; dev_ino, needed_extent, state, state_extent, state_ctime, attempt_extent, attempt_ctime, attempts, not_before_unix_seconds, needed_charge, referenced_epoch);
impl SideRequest {
    /// The backoff after the `attempts`-th charged attempt: 60 s doubling,
    /// capped at one hour.
    pub(in crate::snapshots) fn backoff_seconds(attempts: u8) -> u64 {
        let exponent = u32::from(attempts.max(1) - 1).min(6);
        (60_u64 << exponent).min(3600)
    }
}

/// U1a-2a: P's side record, the ScanIndex verdict for an unchanged parent
/// (design rev 18.1 §2.4, plus rev 9's `generation`/`referenced_epoch`).
/// Content-free: digests, stamps and scalars only.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub(in crate::snapshots) struct CodexParentSide {
    pub(in crate::snapshots) verdict: SideVerdict,
    /// `Checkpoint::seal_as(commit_now, &codex_parent_side_scope())` of the
    /// certified checkpoint the verdict was parsed from.
    pub(in crate::snapshots) seal: crate::transcript_acquisition::PrefixSeal,
    /// The unnormalized stamp the verdict parsed (`wake_compatible`).
    pub(in crate::snapshots) parsed: sampled_scan::codex_cursor::OpenStamp,
    /// A removed request's pacing, kept for a re-request of this object.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(in crate::snapshots) pace: Option<SidePace>,
    /// Bumped on a verdict change; absent → present takes
    /// `++ScanIndex::codex_parent_side_generation`.
    pub(in crate::snapshots) generation: u64,
    /// `codex_parent_proof_wrap_epoch` at create, and at a live update.
    pub(in crate::snapshots) referenced_epoch: u64,
}
crate::heap_layout_bound::fields!(CodexParentSide; verdict, seal, parsed, pace, generation, referenced_epoch);

/// U1a-2a (row 4; rev 9 §2.3, rev 10 §2.3): whether P's side record may be
/// created or keep its epoch fresh. `p_key` is P's index path key; `p_ids`
/// is every id main looks P up by (the resolved ledger/header id plus each
/// resolved `codex_session_id_candidates_from_path` id), so a header-less
/// parent known only by its path ids matches. Live when a child's ownership
/// ref names P, P has a side request, or an owed proof entry names P.
pub(in crate::snapshots) fn codex_parent_side_live(
    index: &ScanIndex,
    p_key: &str,
    p_ids: &[String],
) -> bool {
    codex_parent_side_referenced(index, p_ids)
        || index.codex_parent_side_requests.contains_key(p_key)
}

/// U1a-2a (row 32, D6(b)): P is referenced by a child: a child's parent
/// ref or an owed proof names one of `p_ids`. Liveness without P's own
/// request, which the request epoch prune asks about.
pub(in crate::snapshots) fn codex_parent_side_referenced(
    index: &ScanIndex,
    p_ids: &[String],
) -> bool {
    p_ids.iter().any(|id| {
        index.codex_parent_ownership_refs.contains(id.as_str())
            || index
                .codex_parent_proof_parents_live
                .contains_key(id.as_str())
    })
}

/// U1a-2a (row 32): side keys (records ∪ requests) one sweep visits.
pub(in crate::snapshots) const CODEX_SIDE_SWEEP_KEYS: usize = 64;

/// U1a-2a (D6(b)): `epoch` is more than two completed wraps behind `wrap`.
/// Subtractive and checked: an epoch ahead of the clock (a restored or
/// corrupt index) is never stale, and nothing overflows at `u64::MAX`.
pub(in crate::snapshots) fn codex_side_epoch_stale(epoch: u64, wrap: u64) -> bool {
    wrap.checked_sub(epoch).is_some_and(|age| age > 2)
}

/// U1a-2a (row 32): what one sweep removed.
#[cfg_attr(not(test), allow(dead_code))] // first production caller is the proof hook (s row 31)
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(in crate::snapshots) struct SideSweep {
    pub(in crate::snapshots) orphans: usize,
    pub(in crate::snapshots) records_pruned: usize,
    pub(in crate::snapshots) requests_pruned: usize,
}

/// U1a-2a: what one Codex pass carries from C14: its side-ledger namespace
/// (the destination index file), its outage gate, and that index file's
/// path (the proof holder's binding, s row 31).
///
/// Stage 1 interface (`stage1/c14c15-answer.md` §2; parent r79): the four
/// continuation exclusions are predicates of the pass's `kind`, so the
/// Stage 1 lease only sets `CodexPageKind::Continuation`: no G7 charge, no
/// side due, no row 31 proof hook (not even a held job's step or suspend)
/// and no row 32 sweep. The ordinary save outage (`gate.side_allowed`
/// false) is separate: no side due or G7, no proof visit, start or finish,
/// but a held job may step fd-only and suspend, and the sweep runs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct CodexSidePass {
    pub(in crate::snapshots) ns: u128,
    pub(in crate::snapshots) gate: sampled_scan::side_ledger::GateOpen,
    pub(in crate::snapshots) index_path: PathBuf,
    pub(in crate::snapshots) kind: CodexPageKind,
}
impl CodexSidePass {
    fn ordinary(&self) -> bool {
        self.kind == CodexPageKind::Ordinary
    }

    /// G7 (row 15): a side read may be charged.
    pub(in crate::snapshots) fn side_charge_allowed(&self) -> bool {
        self.ordinary() && self.gate.side_allowed
    }

    /// Rows 5, 9: a side request may be due (or tombstoned by its due check).
    pub(in crate::snapshots) fn side_due_allowed(&self) -> bool {
        self.ordinary() && self.gate.side_allowed
    }

    /// Row 31: the proof hook may run at all (a held job's step or suspend
    /// included).
    pub(in crate::snapshots) fn proof_hook_allowed(&self) -> bool {
        self.ordinary()
    }

    /// Row 32: the side sweep may mutate side state.
    pub(in crate::snapshots) fn sweep_allowed(&self) -> bool {
        self.ordinary()
    }
}

/// U1a-2a (Stage 1 interface, parent r79): which page a Codex pass serves.
/// Production builds only `Ordinary` until the Stage 1 lease adds
/// continuation pages.
#[cfg_attr(not(test), allow(dead_code))] // `Continuation` is Stage 1's
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(in crate::snapshots) enum CodexPageKind {
    Ordinary,
    Continuation,
}
impl crate::heap_layout_bound::HeapLayoutBound for CodexSidePass {
    fn heap_bound(&self, c: &mut crate::heap_layout_bound::Counter) -> Option<()> {
        crate::heap_layout_bound::HeapLayoutBound::heap_bound(&self.index_path, c)
    }
}

/// M1 durable warm-cache reuse: selects this source's store (beside
/// `index_path`) for the pass and binds the pass's sampled scope and
/// identity-capture mode, which its records bind to. A freshly loaded index
/// (absent, quarantined or undecodable) selectively cleans the store: records bind
/// to an index that no longer exists. Removal needs the state-directory
/// lock; selecting the store and restoring from it need none.
#[cfg(unix)]
pub(crate) fn begin_durable_pass(
    cache: &sampled_scan::SharedCache,
    support_dir: &Path,
    source: SnapshotSource,
    index_path: &Path,
    index_fresh: bool,
    namespace: &crate::transcript_acquisition::Scope,
    identity_capture: bool,
) {
    cache.durable_begin_pass(source, index_path, namespace, identity_capture);
    if index_fresh {
        if let Some(writer) = crate::locked_state_dir::held_for(support_dir) {
            let _ = cache.durable_remove(writer, source);
        }
    }
}

/// M1: after the pass's final index save, writes this source's admitted,
/// still-resident copies the save kept, then collects records it no longer
/// keeps. A store failure is never a sync failure: the store is a cache, and
/// a missing record only means a Full read. Writes and GC require the
/// daemon's held state-directory lock (#801); without it (not the daemon)
/// nothing is written and the skip is counted.
#[cfg(unix)]
pub(crate) fn durable_after_save(
    cache: &sampled_scan::SharedCache,
    support_dir: &Path,
    source: SnapshotSource,
    index: &ScanIndex,
) {
    match crate::locked_state_dir::held_for(support_dir) {
        Some(writer) => {
            let _ = cache.durable_write_after_save(writer, source, index);
            let _ = cache.durable_gc(writer, source, index);
        }
        None => cache.durable_note_unlocked(source),
    }
    if let Some((counters, store)) = cache.durable_counters(source) {
        eprintln!("{}", counters.summary(source, &store));
    }
    cache.durable_alarm(source);
}

/// U1a-2a (C14), Codex only: open the pass's side-ledger gate, then prune
/// and hydrate this index's ledger entries into the index as loaded. Touches
/// only side requests.
pub(crate) fn begin_codex_side_pass(
    cache: &sampled_scan::SharedCache,
    index_path: &Path,
    index: &mut ScanIndex,
) -> CodexSidePass {
    begin_codex_side_pass_of(cache, index_path, index, CodexPageKind::Ordinary)
}

/// C14 for a page of `kind`: the same gate read, prune and hydrate; only an
/// ordinary page resets the gate (`SideLedger::begin_pass_of`, C-1).
fn begin_codex_side_pass_of(
    cache: &sampled_scan::SharedCache,
    index_path: &Path,
    index: &mut ScanIndex,
    kind: CodexPageKind,
) -> CodexSidePass {
    let ns = sampled_scan::side_ledger::namespace_of(index_path);
    let (gate, wanted) = cache
        .side_ledger()
        .open_index_pass(ns, sampled_scan::now_seconds(), kind);
    // R2-L2: one SHA-256 per file key, with the leaf lock released (C14 is
    // single-threaded under `SNAPSHOT_SYNC_LOCK`).
    let keys = wanted
        .as_ref()
        .map(|wanted| sampled_scan::side_ledger::index_parent_keys(&index.files, wanted));
    let mut ledger = cache.side_ledger();
    if let Some((wanted, keys)) = wanted.as_ref().zip(keys.as_ref()) {
        ledger.hydrate_index_pass(ns, wanted, keys, index);
    }
    let ledger_entries = ledger.len();
    drop(ledger);
    note_codex_side_gauges(index, ledger_entries);
    CodexSidePass {
        ns,
        gate,
        index_path: index_path.to_path_buf(),
        kind,
    }
}

