/// Content-free proof of the code and wire contract that rejected an entity.
/// A semantic fingerprint alone is insufficient: a parser or validator fix
/// can make the same entity acceptable without changing that fingerprint.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SnapshotQuarantineWitness {
    pub contract: String,
    pub collector_version: String,
    pub parser_version: String,
    pub scan_identity_version: String,
    pub snapshot_schema_version: u16,
    pub entity_ack_contract: String,
    /// Local admission policy, not part of wire or semantic identity. Legacy
    /// records predate the backend-first 640 KiB admission repair.
    #[serde(default = "legacy_snapshot_item_wire_byte_limit")]
    pub item_wire_byte_limit: usize,
}

const fn legacy_snapshot_item_wire_byte_limit() -> usize {
    128 * 1024
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SnapshotQuarantineRecord {
    /// Reconstruction semantics last assessed; legacy records were assessed under v1.
    #[serde(
        default = "terminal_contract_retry::legacy_contract",
        deserialize_with = "terminal_contract_retry::decode_contract"
    )]
    pub reconstruction_contract: u16,
    /// Claimed source acquisitions for a contract-origin retry at this version.
    /// None is an ordinary retry; Some(0) is a newly owed contract attempt.
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "terminal_contract_retry::decode_claims"
    )]
    pub contract_retry_claims: Option<u16>,
    pub witness: SnapshotQuarantineWitness,
    pub retry_after_unix_seconds: u64,
    /// Optional exact hash-neutral body rejected under this contract. A body
    /// correction with the same semantic fingerprint bypasses quarantine.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub upload_body_witness: Option<String>,
    #[serde(default = "initial_snapshot_reconstruction_failure_count")]
    pub failed_reconstruction_count: u8,
    #[serde(default)]
    pub disposition: SnapshotQuarantineDisposition,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SnapshotQuarantineDisposition {
    #[default]
    RetryPending,
    UnprovenTerminal,
    SupersededTerminal,
}

const fn initial_snapshot_reconstruction_failure_count() -> u8 {
    1
}

pub fn snapshot_quarantine_witness(source: SnapshotSource) -> SnapshotQuarantineWitness {
    SnapshotQuarantineWitness {
        contract: SNAPSHOT_QUARANTINE_CONTRACT_VERSION.to_string(),
        collector_version: collector_version(),
        parser_version: source.parser_version().to_string(),
        scan_identity_version: source.scan_identity_version().to_string(),
        snapshot_schema_version: SNAPSHOT_SCHEMA_VERSION,
        entity_ack_contract: SNAPSHOT_ENTITY_ACK_CONTRACT.to_string(),
        item_wire_byte_limit: MAX_SNAPSHOT_ITEM_WIRE_BYTES,
    }
}

/// Reuse the existing refusal witness to distinguish an assessed body under
/// a changed upload policy. This is refusal/backoff evidence, never acceptance.
pub(crate) fn snapshot_quarantine_witness_for_context(
    source: SnapshotSource,
    context: &str,
) -> SnapshotQuarantineWitness {
    let mut witness = snapshot_quarantine_witness(source);
    if matches!(source, SnapshotSource::ClaudeCode | SnapshotSource::Codex) {
        witness.contract.push_str(":upload_context:");
        witness.contract.push_str(context);
    }
    witness
}

/// A policy-only reassessment must not spend an ordinary retry or move its deadline.
pub(crate) fn quarantine_context_only_changed(
    previous: &SnapshotQuarantineWitness,
    active: &SnapshotQuarantineWitness,
) -> bool {
    if previous.contract == active.contract
        || previous.contract.split(":upload_context:").next()
            != active.contract.split(":upload_context:").next()
    {
        return false;
    }
    let mut normalized = previous.clone();
    normalized.contract.clone_from(&active.contract);
    normalized == *active
}

pub fn snapshot_quarantine_record(source: SnapshotSource) -> SnapshotQuarantineRecord {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or_default();
    SnapshotQuarantineRecord {
        contract_retry_claims: None,
        reconstruction_contract: crate::snapshots::terminal_contract_retry::current_contract(),
        witness: snapshot_quarantine_witness(source),
        retry_after_unix_seconds: now.saturating_add(SNAPSHOT_QUARANTINE_RETRY_SECONDS),
        upload_body_witness: None,
        failed_reconstruction_count: initial_snapshot_reconstruction_failure_count(),
        disposition: SnapshotQuarantineDisposition::RetryPending,
    }
}

pub(crate) fn snapshot_quarantine_deadline_is_bounded(record: &SnapshotQuarantineRecord) -> bool {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or_default();
    snapshot_quarantine_deadline_is_bounded_at(record, now)
}

fn snapshot_quarantine_deadline_is_bounded_at(record: &SnapshotQuarantineRecord, now: u64) -> bool {
    // Fresh quarantine is deterministically staggered across [6h, 12h).
    // Anything further out is corrupt state or evidence the wall clock moved
    // backwards. In either case local state must never become a permanent
    // authority that fences a repaired backend forever.
    match record.disposition {
        SnapshotQuarantineDisposition::RetryPending => {
            record.failed_reconstruction_count < MAX_SNAPSHOT_RECONSTRUCTION_FAILURES
                && record.retry_after_unix_seconds
                    <= now.saturating_add(SNAPSHOT_QUARANTINE_RETRY_SECONDS.saturating_mul(2))
        }
        SnapshotQuarantineDisposition::UnprovenTerminal => {
            record.failed_reconstruction_count == MAX_SNAPSHOT_RECONSTRUCTION_FAILURES
                && record.retry_after_unix_seconds == 0
        }
        SnapshotQuarantineDisposition::SupersededTerminal => {
            record.failed_reconstruction_count <= MAX_SNAPSHOT_RECONSTRUCTION_FAILURES
                && record.retry_after_unix_seconds == 0
        }
    }
}

fn scan_index_schema_version() -> u16 {
    SCAN_INDEX_SCHEMA_VERSION
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScanIndexEntry {
    pub size_bytes: u64,
    pub modified_unix_seconds: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub modified_unix_nanos: Option<u64>,
    pub source_file_fingerprint: String,
    pub last_snapshot_fingerprint: Option<String>,
    /// Local-only witness for additive wire evidence intentionally excluded
    /// from semantic identity. This lets an absent/present/corrected context
    /// curve upload once without changing the server entity fingerprint.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_upload_body_witness: Option<String>,
    /// Local projection revision that produced this file's settled body witness.
    /// Missing legacy revisions remain zero; zero preserves default scan behavior.
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    pub effective_upload_body_witness_revision: u64,
    /// Marks entries written by the semantic-sync scan derivation. `None`
    /// identifies a pre-cutover entry that can be adopted without reparsing
    /// when transcript size and mtime are unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scan_identity_version: Option<String>,
    /// Applied only through the existing common file/body acknowledgement.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub codex_joined_member_set: Option<String>,
    /// Pending proof, captured before POST; never an applied/accepted witness.
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "deserialize_codex_protected_owner"
    )]
    pub codex_captured_joined_member_set: Option<String>,
    /// Hash-only logical owner for protecting joined/priced history from a
    /// state-only replacement after physical source retirement. No attribution.
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "deserialize_codex_protected_owner"
    )]
    pub codex_protected_owner: Option<String>,
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "codex_file_join::deserialize_receipt"
    )]
    pub codex_applied_tier_receipt: Option<codex_file_join::AppliedTierReceipt>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub codex_applied_tier_receipt_required: bool,
    /// Captured selector evidence does not authorize a file/body checkpoint.
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "codex_file_join::deserialize_receipt"
    )]
    pub codex_captured_tier_receipt: Option<codex_file_join::AppliedTierReceipt>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub codex_captured_tier_receipt_required: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub codex_captured_uncommitted: bool,
    /// Local-only Codex counting version of this entry's published body: set
    /// by a V2 writer together with `last_snapshot_fingerprint`, so selected
    /// saves, held-key restores and committable subsets move both as one entry.
    /// Older binaries drop it; an acknowledged entry without it stays Legacy.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub codex_counting_v2: bool,
    /// Hash-only session binding observed by a complete owned parse. Counting
    /// evidence follows this binding across physical moves; it grants no
    /// history protection or account authority.
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        deserialize_with = "deserialize_codex_protected_owner"
    )]
    pub codex_counting_owner: Option<String>,
    /// The ctime (unix nanos) in the opened-object identity that produced
    /// `source_file_fingerprint` (Claude and Codex only). With size, mtime
    /// and file birth unchanged the next scan rebuilds the identity from it,
    /// so a ctime-only change never triggers a re-read. Older binaries drop
    /// it; zero keeps the live-identity comparison once.
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    pub(crate) opened_changed_nanos: u64,
    /// The file birth (unix nanos) of that open: the object generation the
    /// stored ctime belongs to. Zero (unavailable) never adopts the ctime.
    #[serde(default, skip_serializing_if = "is_zero_u64")]
    pub(crate) opened_birth_nanos: u64,
    /// Local-only exact current-context acceptance. Appended for old readers.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) upload_context_receipt: Option<upload_context_receipt::Receipt>,
}
impl ScanIndexEntry {
    fn codex_recovery_is_pending(&self) -> bool {
        self.codex_captured_joined_member_set.is_some()
            || self.codex_captured_tier_receipt_required
            || self.codex_captured_tier_receipt.is_some()
            || self.codex_captured_uncommitted
    }
    fn codex_history_is_protected(&self) -> bool {
        self.codex_protected_owner.is_some()
            || self.codex_joined_member_set.is_some()
            || self.codex_captured_joined_member_set.is_some()
            || self.codex_applied_tier_receipt.is_some()
            || self.codex_applied_tier_receipt_required
            || self.codex_captured_tier_receipt.is_some()
            || self.codex_captured_tier_receipt_required
            || self.codex_captured_uncommitted
    }
}
fn deserialize_codex_protected_owner<'de, D: serde::Deserializer<'de>>(
    deserializer: D,
) -> std::result::Result<Option<String>, D::Error> {
    let value = Option::<Value>::deserialize(deserializer)?;
    Ok(value.map(|value| value.as_str().unwrap_or("").to_owned()))
}
/// U1a: decode a string-keyed map one entry at a time; entries this binary
/// cannot decode (unknown tag, newer shape) are dropped. A non-object is an
/// empty map, so this field can never quarantine the index.
fn deserialize_lenient_map<'de, D, V>(
    deserializer: D,
) -> std::result::Result<BTreeMap<String, V>, D::Error>
where
    D: serde::Deserializer<'de>,
    V: serde::de::DeserializeOwned,
{
    let Value::Object(raw) = Value::deserialize(deserializer)? else {
        return Ok(BTreeMap::new());
    };
    Ok(raw
        .into_iter()
        .filter_map(|(key, value)| serde_json::from_value(value).ok().map(|value| (key, value)))
        .collect())
}
/// Decode a cost-only leaf as a whole; any value this binary cannot decode
/// (wrong shape, newer layout) is its empty default, never an index error.
fn deserialize_lenient_default<'de, D, V>(deserializer: D) -> std::result::Result<V, D::Error>
where
    D: serde::Deserializer<'de>,
    V: serde::de::DeserializeOwned + Default,
{
    let value = Value::deserialize(deserializer)?;
    Ok(serde_json::from_value(value).unwrap_or_default())
}
thread_local! {
    /// Side requests `deserialize_codex_side_requests` dropped on this thread
    /// since the last take. Only `ScanIndex::load` takes and counts them.
    static DROPPED_CODEX_SIDE_REQUESTS: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
}
/// U1a-2a (D4): the request map must be an object (the outer shape is
/// unchanged); a request this binary cannot decode is dropped. It is unknown
/// scheduling evidence: P then has no request, never a record or an
/// admission, and an in-process ledger charge for it still hydrates at C14.
fn deserialize_codex_side_requests<'de, D: serde::Deserializer<'de>>(
    deserializer: D,
) -> std::result::Result<BTreeMap<String, SideRequest>, D::Error> {
    let raw = BTreeMap::<String, Value>::deserialize(deserializer)?;
    let mut dropped = 0_u64;
    let requests = raw
        .into_iter()
        .filter_map(|(key, value)| match serde_json::from_value(value) {
            Ok(request) => Some((key, request)),
            Err(_) => {
                dropped += 1;
                None
            }
        })
        .collect();
    DROPPED_CODEX_SIDE_REQUESTS.with(|count| count.set(count.get().saturating_add(dropped)));
    Ok(requests)
}
fn take_dropped_codex_side_requests() -> u64 {
    DROPPED_CODEX_SIDE_REQUESTS.with(|count| count.replace(0))
}
fn valid_codex_protected_owner(owner: &str) -> bool {
    owner.len() == 64
        && owner
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}
fn codex_protected_owner(session: &str) -> String {
    sha256_hex(&["codex_protected_owner:v1", &resolve_codex_identity(session)])
}

