macro_rules! scan_result {
    (pub struct $name:ident { pub source: SnapshotSource,
        $($(#[$attr:meta])* $vis:vis $field:ident: $ty:ty,)*
    }) => {
        #[derive(Debug, Clone)]
        pub struct $name { pub source: SnapshotSource, $($(#[$attr])* $vis $field: $ty,)* }
        impl $name {
            fn empty(source: SnapshotSource) -> Self {
                Self { source, $($field: Default::default(),)* }
            }
        }
    };
}
scan_result! {
pub struct SourceScanResult {
    pub source: SnapshotSource,
    pub backfill_window_days: u64,
    pub backfill_file_limit: usize,
    pub discovered_file_count: usize,
    pub skipped_file_count_due_to_limit: usize,
    pub scan_cap_hit: bool,
    pub scanned_file_count: usize,
    pub scanned_session_count: usize,
    pub semantic_noop_count: usize,
    pub census_complete: bool,
    pub census_window_end: String,
    /// State-only Codex census is separate from transcript discovery. If an
    /// existing SQLite source was unreadable, its previous durable map must be
    /// retained even while healthy transcript siblings progress.
    pub state_census_complete: bool,
    /// Display/naming sidecars are optional enrichment, but a partial read
    /// cannot publish a source-wide manifest or advance the upload context.
    pub sidecar_census_complete: bool,
    pub symlink_rejected_count: usize,
    pub directory_entry_cap_exceeded_count: usize,
    pub unreadable_path_count: usize,
    pub oversized_file_count: usize,
    pub disappeared_file_count: usize,
    pub malformed_json_line_count: usize,
    pub invalid_utf8_line_count: usize,
    pub over_line_cap_count: usize,
    pub recognized_usage_drop_count: usize,
    pub ownership_incomplete_file_count: usize,
    pub(crate) causes: ownership::Counts,
    pub zero_snapshot_confirmed_count: usize,
    pub zero_snapshot_usage_evidence_count: usize,
    pub dropped_usage_record_count: u64,
    /// The generation's SETTLED share of each public loss counter above
    /// (`ScanTraversalCounts::terminal_*`): loss that carries a durable
    /// terminal disposition or was settled as non-progressing once discovery
    /// finished without a retryable problem. Each is a decomposition of the
    /// public counter it is named after, never an addend, so `terminal <=
    /// public` always holds; equality in every class is what lets a receipt
    /// prove that all the loss it discloses is loss no retry can change.
    pub terminal_ownership_incomplete_file_count: usize,
    pub terminal_zero_snapshot_usage_evidence_count: usize,
    pub terminal_recognized_usage_drop_count: usize,
    pub terminal_dropped_usage_record_count: u64,
    pub terminal_over_line_cap_count: usize,
    /// Cardinalities of the residue witness this generation recorded
    /// (`ScanIndex::scan_residue_witness`), counts only. All zero when the
    /// generation did not complete (the durable witness then describes an
    /// earlier census, not this scan) and when it completed clean.
    pub census_residue_index_key_count: usize,
    pub census_residue_archived_rollout_count: usize,
    pub census_residue_blocked_session_count: usize,
    pub snapshots: Vec<SnapshotItem>,
    pending_finalization: Vec<PendingIndexFinalization>,
    pub(crate) local_codex_diagnostics: Option<CodexScanDiagnostics>,
    /// Local-only V2 counting receipts of this scan, moved out of its census.
    /// `None` when no configured counting parse finished (never a zero block).
    pub(crate) codex_counting_v2: Option<Box<crate::codex_scan_diagnostics::CountingV2Receipts>>,
    codex_join_validation: Option<codex_file_join::Validation>,
    codex_legacy_join_baselines: Vec<codex_file_join::LegacyBaseline>,
    /// Slice D1 shadow, measured by a complete Claude terminal scan before
    /// any fold. Count-only; the usage fold copies it into its counters.
    pub(crate) claude_request_census_shadow: Option<ClaudeRequestCensusShadowCounts>,
    /// Stage 1 hunk A: the paused cursor job's continuation ticket, minted
    /// at this page's pause (`PauseEnd::Paused` only). None on every other
    /// end, and on an unaccelerated attempt.
    continuation_ticket: Option<sampled_scan::codex_cursor::CodexCursorTicket>,
    continuation_evidence: Option<Arc<Mutex<Option<CodexContinuationEvidence>>>>,
}
}
#[derive(Clone, Debug)]
pub(crate) struct CodexJoinValidator(codex_file_join::Validation);
impl CodexJoinValidator {
    pub(crate) fn validate(&self, snapshots: &[SnapshotItem]) -> Result<()> {
        let owners = snapshots
            .iter()
            .map(|item| resolve_codex_identity(&item.source_session_id))
            .collect();
        self.0.validate(&owners).map(|_| ())
    }
}
impl SourceScanResult {
    pub(crate) fn take_continuation_evidence(&mut self) -> Option<CodexContinuationEvidence> {
        self.continuation_evidence.take()?.lock().ok()?.take()
    }
    /// Stage 1 hunk A: the ticket `CodexCursorPort::ticket_for` reads.
    pub(crate) fn continuation_ticket(
        &self,
    ) -> Option<&sampled_scan::codex_cursor::CodexCursorTicket> {
        self.continuation_ticket.as_ref()
    }
    pub(crate) fn validate_codex_checkpoint(&self) -> Result<()> {
        if let Some(validation) = &self.codex_join_validation {
            validation.validate_all()?;
        }
        Ok(())
    }
    pub(crate) fn reconcile_codex_legacy_joining(
        &mut self,
        index: &mut ScanIndex,
        previous: &ScanIndex,
        machine_id: &str,
        mut project: impl FnMut(&mut ScanIndex, &mut Vec<SnapshotItem>),
    ) {
        let mut held = BTreeSet::new();
        for mut baseline in std::mem::take(&mut self.codex_legacy_join_baselines) {
            project(index, &mut baseline.snapshots);
            let matches = |snapshots: &[SnapshotItem]| {
                let fingerprints = snapshots
                    .iter()
                    .map(|snapshot| snapshot_fingerprint(SnapshotSource::Codex, snapshot))
                    .collect::<BTreeSet<_>>();
                snapshot_file_entity_set_hex(fingerprints) == baseline.expected
            };
            if matches(&baseline.snapshots) {
                continue;
            }
            // Explicit missing/conflict creator evidence intentionally retracts
            // legacy guessed ownership. Compare with the previously cached
            // binding only to isolate that authorized correction; never emit it.
            for item in &mut baseline.snapshots {
                if item
                    .session_account_evidence
                    .as_ref()
                    .is_some_and(|evidence| {
                        evidence.evidence_source == "codex_creator_header:v1"
                            && matches!(evidence.identity_disposition, Some("missing" | "conflict"))
                    })
                {
                    let key =
                        sha256_hex(&["session_owner:v1", machine_id, &item.source_session_id]);
                    if let Some(binding) = previous.session_account_bindings.get(&key) {
                        set_session_account_hash(item, Some(&binding.account_identifier_hash));
                    }
                }
            }
            if !matches(&baseline.snapshots) {
                held.insert(baseline.owner);
            }
        }
        if held.is_empty() {
            if self.census_complete
                && !self.pending_finalization.iter().any(|pending| {
                    index
                        .files
                        .get(&pending.index_key)
                        .is_some_and(|entry| entry.codex_applied_tier_receipt.is_some())
                })
            {
                index.traversal = None;
                index.resume_after_path = None;
                index.resume_upper_bound_path = None;
                index.resume_census_window_end = None;
            }
            return;
        }
        self.hold_codex_groups(
            index,
            previous,
            &held,
            "legacy applied output could not be reproduced",
        );
    }
    pub(crate) fn hold_codex_groups(
        &mut self,
        index: &mut ScanIndex,
        previous: &ScanIndex,
        held: &BTreeSet<String>,
        reason: &str,
    ) {
        if held.is_empty() {
            return;
        }
        self.census_complete = false;
        self.scan_cap_hit = true;
        if let Some(diagnostic) = self.local_codex_diagnostics.as_mut() {
            diagnostic.gates.census_complete = false;
            diagnostic.gates.traversal_healthy = false;
        }
        let sources = self
            .snapshots
            .iter()
            .filter(|snapshot| held.contains(&resolve_codex_identity(&snapshot.source_session_id)))
            .filter_map(|snapshot| snapshot.source_file_fingerprint.as_ref())
            .collect::<BTreeSet<_>>();
        let mut keys = index
            .files
            .iter()
            .filter(|(_, entry)| sources.contains(&entry.source_file_fingerprint))
            .map(|(key, _)| key.clone())
            .collect::<BTreeSet<_>>();
        if let Some(validation) = &self.codex_join_validation {
            keys.extend(
                validation
                    .groups
                    .iter()
                    .filter(|group| held.contains(&group.owner))
                    .flat_map(|group| {
                        group
                            .members
                            .iter()
                            .map(|member| local_index_key(&member.path))
                    }),
            );
        }
        self.ownership_incomplete_file_count += keys.len();
        self.causes.add(ownership::GROUP, keys.len());
        for key in &keys {
            index.remove_file_entry(key);
            if let Some(entry) = previous.files.get(key) {
                index.files.insert(key.clone(), entry.clone());
            }
            if let Some(fingerprints) = previous.file_snapshot_fingerprints.get(key) {
                index
                    .file_snapshot_fingerprints
                    .insert(key.clone(), fingerprints.clone());
            }
            if previous.confirmed_empty_files.contains(key) {
                index.confirmed_empty_files.insert(key.clone());
            }
            index.revert_codex_blocked_attribution(previous, key);
        }
        self.pending_finalization
            .retain(|pending| !keys.contains(&pending.index_key));
        self.snapshots.retain(|snapshot| {
            !held.contains(&resolve_codex_identity(&snapshot.source_session_id))
        });
        if let Some(traversal) = index.traversal.as_mut() {
            traversal.counts.ownership_incomplete_file_count += keys.len();
            traversal.counts.causes.add(ownership::GROUP, keys.len());
            traversal
                .counts
                .record_unreadable(UnreadableCause::LegacyHold, 1);
            traversal.residue.index_keys.extend(keys);
            traversal
                .residue
                .blocked_session_ids
                .extend(held.iter().cloned());
            let now = rfc3339_unix_seconds(&self.census_window_end).unwrap_or_default();
            traversal.unhealthy_retry_attempt = traversal
                .unhealthy_retry_attempt
                .saturating_add(1)
                .min(UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS);
            traversal.unhealthy_retry_not_before_unix_seconds = Some(now.saturating_add(
                unhealthy_scan_retry_delay_seconds(traversal.unhealthy_retry_attempt),
            ));
        }
        index
            .codex_state_only_blocked_session_ids
            .extend(held.iter().cloned());
        index
            .codex_state_only_blocked_unattributed
            .extend(held.iter().cloned());
        if let Some(validation) = &mut self.codex_join_validation {
            validation
                .groups
                .retain(|group| !held.contains(&group.owner));
        }
        index.scan_residue_witness = previous.scan_residue_witness.clone();
        eprintln!(
            "ottto-service: held {} Codex file group(s): {reason}",
            held.len()
        );
    }
    pub(crate) fn finish_codex_capture_boundary(&self, index: &mut ScanIndex) {
        if self.census_complete {
            index.traversal = None;
            index.resume_after_path = None;
            index.resume_upper_bound_path = None;
            index.resume_census_window_end = None;
        }
    }
    /// Index keys this scan read to completion, with their parsed source
    /// fingerprints.
    pub(crate) fn completed_parses(&self) -> impl Iterator<Item = (&str, &str)> {
        self.pending_finalization
            .iter()
            .filter(|pending| pending.parse_complete)
            .map(|pending| {
                (
                    pending.index_key.as_str(),
                    pending.source_file_fingerprint.as_str(),
                )
            })
    }
    pub(crate) fn codex_joining_validator(&self) -> Option<CodexJoinValidator> {
        self.codex_join_validation.clone().map(CodexJoinValidator)
    }
}

#[derive(Debug, Clone)]
struct PendingIndexFinalization {
    sampled_audit_verified: bool,
    codex_pending_recovery: bool,
    index_key: String,
    source_file_fingerprint: String,
    previous_snapshot_fingerprint: Option<String>,
    previous_upload_body_witness: Option<String>,
    parse_complete: bool,
    diagnostic_reason: FileReason,
    parsed_snapshot_count: usize,
    effective_upload_body_witness_revision: u64,
}

#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
pub struct SnapshotUploadPolicy {
    pub session_titles_enabled: bool,
    pub workspace_labels_enabled: bool,
    pub session_artifacts_enabled: bool,
    pub session_attribution_enabled: bool,
    /// Backend capability derived from the existing session-title privacy
    /// choice. It is not a separate user setting and defaults off for older
    /// backends that do not advertise the additive private-label contract.
    pub session_attribution_labels_enabled: bool,
}

pub(crate) fn snapshot_source_from_api_slug(value: &str) -> Option<SnapshotSource> {
    match value {
        "codex" => Some(SnapshotSource::Codex),
        "claude_code" => Some(SnapshotSource::ClaudeCode),
        "pi" => Some(SnapshotSource::Pi),
        _ => None,
    }
}

impl Default for SnapshotUploadPolicy {
    fn default() -> Self {
        Self {
            session_titles_enabled: true,
            workspace_labels_enabled: true,
            // Opt-in: artifacts are stripped before upload unless the backend
            // activity hint explicitly enables them for the org.
            session_artifacts_enabled: false,
            // Opt-in: compact facts stay local unless the backend explicitly
            // enables the additive attribution contract.
            session_attribution_enabled: false,
            session_attribution_labels_enabled: false,
        }
    }
}

pub fn apply_upload_policy(
    source: SnapshotSource,
    snapshots: &mut [SnapshotItem],
    policy: SnapshotUploadPolicy,
) {
    for item in snapshots {
        let mut fingerprint_needs_refresh = false;
        if !policy.session_titles_enabled
            && (item.session_display_name.is_some() || item.session_display_name_source.is_some())
        {
            item.session_display_name = None;
            item.session_display_name_source = None;
            fingerprint_needs_refresh = true;
        }
        if !policy.workspace_labels_enabled
            && (item.workspace_display_label.is_some()
                || item.workspace_label_source.is_some()
                || item.repository_label.is_some()
                || item.repository_label_source.is_some())
        {
            item.workspace_display_label = None;
            item.workspace_label_source = None;
            item.repository_label = None;
            item.repository_label_source = None;
            fingerprint_needs_refresh = true;
        }
        if !policy.session_artifacts_enabled && !item.session_artifacts.is_empty() {
            item.session_artifacts.clear();
            fingerprint_needs_refresh = true;
        }
        if !policy.session_attribution_enabled && !item.attribution_facts.is_empty() {
            item.attribution_facts.clear();
            fingerprint_needs_refresh = true;
        } else if (!policy.session_titles_enabled || !policy.session_attribution_labels_enabled)
            && crate::session_attribution::strip_display_labels(&mut item.attribution_facts)
        {
            fingerprint_needs_refresh = true;
        }
        if !policy.session_attribution_labels_enabled {
            if let Some(summary) = item.activity_summary.as_mut() {
                if !summary.skills.is_empty() {
                    summary.skills.clear();
                    fingerprint_needs_refresh = true;
                }
            }
        }
        if let Some(start) = item.session_start.as_mut() {
            // Outside the fingerprint: consent changes only which identity an
            // opening file carries, never the session's content.
            start.apply_upload_policy(
                policy.workspace_labels_enabled,
                policy.session_attribution_enabled,
            );
        }
        if fingerprint_needs_refresh {
            item.snapshot_fingerprint = snapshot_fingerprint(source, item);
        }
        fit_context_curve_to_snapshot_item_budget(
            source,
            item,
            policy,
            MAX_SNAPSHOT_ITEM_WIRE_BYTES,
        );
    }
}

fn snapshot_item_wire_size(
    source: SnapshotSource,
    item: &SnapshotItem,
    policy: SnapshotUploadPolicy,
) -> usize {
    serde_json::to_vec(&SnapshotItemWire {
        snapshot: item,
        semantic_envelope: snapshot_semantic_envelope(source, item, policy),
    })
    .map(|encoded| encoded.len())
    .unwrap_or(usize::MAX)
}

fn fit_context_curve_to_snapshot_item_budget(
    source: SnapshotSource,
    item: &mut SnapshotItem,
    policy: SnapshotUploadPolicy,
    item_wire_budget: usize,
) {
    if item.context_curve.is_none()
        || snapshot_item_wire_size(source, item, policy) <= item_wire_budget
    {
        return;
    }
    while item
        .context_curve
        .as_mut()
        .is_some_and(prune_one_context_curve_fill_point)
    {
        if snapshot_item_wire_size(source, item, policy) <= item_wire_budget {
            return;
        }
    }
    let Some(curve) = item.context_curve.as_ref() else {
        return;
    };
    item.context_curve = Some(unavailable_context_curve(
        &curve.parser_revision,
        &curve.ownership_revision,
        "payload_budget_exceeded",
        0,
        0,
    ));
}

fn snapshot_item_wire_size_is_allowed(
    item_size: usize,
    item_without_curve_size: usize,
    context_curve_coverage: Option<&str>,
) -> bool {
    item_size <= MAX_SNAPSHOT_ITEM_WIRE_BYTES
        || (context_curve_coverage == Some("payload_budget_exceeded")
            && item_without_curve_size <= MAX_SNAPSHOT_ITEM_WIRE_BYTES
            && item_size <= MAX_SNAPSHOT_ITEM_CLEAR_WIRE_BYTES)
}

/// Bind incremental state to the exact bytes/semantics that will go on the
/// wire. This MUST run after every enrichment, privacy policy, and account
/// cutoff. Parser-time fingerprints are provisional only: committing them
/// earlier can suppress a later policy/enrichment correction forever.
pub fn finalize_scan_after_policy(
    source: SnapshotSource,
    result: &mut SourceScanResult,
    index: &mut ScanIndex,
) {
    finalize_scan_after_policy_with_body_witness(
        source,
        result,
        index,
        snapshot_upload_body_witness,
    );
}

/// Sample existing quarantine metadata only. These are working-index witnesses
/// at finalization, not a claim about later partial-checkpoint persistence.
pub(crate) fn prepare_codex_recovery_diagnostics(
    result: &mut SourceScanResult,
    index: &ScanIndex,
    quarantines: &BTreeMap<String, SnapshotQuarantineRecord>,
) {
    let Some(diagnostic) = result.local_codex_diagnostics.as_mut() else {
        return;
    };
    diagnostic.lineage = [None; LINEAGE_SAMPLES];
    diagnostic.sample_offset = 0;
    diagnostic.quarantine_count = quarantines.len() as u64;
    if quarantines.is_empty() {
        return;
    }
    let offset = (diagnostic.generation % quarantines.len() as u64) as usize;
    diagnostic.sample_offset = offset as u64;
    for (slot, (fingerprint, quarantine)) in quarantines
        .iter()
        .cycle()
        .skip(offset)
        .take(quarantines.len().min(LINEAGE_SAMPLES))
        .enumerate()
    {
        let mut sample = RecoveryLineage::new(fingerprint, quarantine.disposition);
        for (key, fingerprints) in &index.file_snapshot_fingerprints {
            if fingerprints.contains(fingerprint) {
                sample.before_current = true;
                sample.associated_file_count = sample.associated_file_count.saturating_add(1);
                if sample.file_key_digest.is_none() {
                    sample.file_key_digest = Some(codex_scan_diagnostics::digest(key));
                    sample.previous_body_digest = result
                        .pending_finalization
                        .iter()
                        .find(|pending| &pending.index_key == key)
                        .and_then(|pending| pending.previous_upload_body_witness.as_deref())
                        .or_else(|| {
                            index
                                .files
                                .get(key)
                                .and_then(|entry| entry.last_upload_body_witness.as_deref())
                        })
                        .map(codex_scan_diagnostics::digest);
                }
            }
        }
        // Preserve the canonical current-set fallback for pre-entity-map indexes.
        for (key, entry) in &index.files {
            if !index.file_snapshot_fingerprints.contains_key(key)
                && entry.last_snapshot_fingerprint.as_ref() == Some(fingerprint)
            {
                sample.before_current = true;
                sample.associated_file_count = sample.associated_file_count.saturating_add(1);
                if sample.file_key_digest.is_none() {
                    sample.file_key_digest = Some(codex_scan_diagnostics::digest(key));
                    sample.legacy_file_association = true;
                    sample.previous_body_digest = entry
                        .last_upload_body_witness
                        .as_deref()
                        .map(codex_scan_diagnostics::digest);
                }
            }
        }
        sample.before_current |= index
            .codex_state_only_snapshot_fingerprints
            .values()
            .any(|current| current == fingerprint);
        diagnostic.lineage[slot] = Some(sample);
    }
}

/// Finalize using the additive body witness of the effective upload projection.
/// The witness function sees recomputed semantic fingerprints and must return
/// a stable witness for both file no-op suppression and quarantine retries.
/// It does not modify the local snapshot items or semantic entity identity.
pub fn finalize_scan_after_policy_with_body_witness(
    source: SnapshotSource,
    result: &mut SourceScanResult,
    index: &mut ScanIndex,
    mut body_witness: impl FnMut(&SnapshotItem) -> String,
) {
    // Backstop of the one emission seam: no held history body is finalized.
    index.veto_claude_history_emission(source, &mut result.snapshots);
    for snapshot in &mut result.snapshots {
        snapshot.snapshot_fingerprint = snapshot_fingerprint(source, snapshot);
        index.snapshot_activity_at.insert(
            snapshot.snapshot_fingerprint.clone(),
            snapshot_semantic_activity_at(snapshot),
        );
    }

    index.preserve_decode_held_files(source, &result.snapshots, &mut result.pending_finalization);
    result
        .snapshots
        .retain(|snapshot| !index.decode_holds_snapshot(source, snapshot));
    if !index.decode_holds.is_empty() {
        result.census_complete = false;
        index.mark_bounded_sweep_unsettled();
    }
    let mut by_source_file: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut by_source_file_body_witness: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for snapshot in &result.snapshots {
        if let Some(source_file_fingerprint) = snapshot.source_file_fingerprint.as_ref() {
            by_source_file
                .entry(source_file_fingerprint.clone())
                .or_default()
                .insert(snapshot.snapshot_fingerprint.clone());
            by_source_file_body_witness
                .entry(source_file_fingerprint.clone())
                .or_default()
                .insert(body_witness(snapshot));
        }
    }

    let mut noop_source_files = BTreeSet::new();
    let mut carried_noop_entities = BTreeSet::new();
    for pending in &result.pending_finalization {
        if let Some(diagnostic) = result.local_codex_diagnostics.as_mut() {
            let key_digest = codex_scan_diagnostics::digest(&pending.index_key);
            for sample in diagnostic.lineage.iter_mut().flatten() {
                if sample.file_key_digest == Some(key_digest) {
                    sample.file_reason = pending.diagnostic_reason;
                    sample.parsed_count = pending.parsed_snapshot_count as u64;
                }
            }
        }
        if !pending.parse_complete {
            continue;
        }
        if index.finalize_claude_held_history(&pending.index_key, &pending.source_file_fingerprint)
        {
            continue;
        }
        let final_fingerprints = by_source_file
            .get(&pending.source_file_fingerprint)
            .cloned()
            .unwrap_or_default();
        let final_group_fingerprint = (!final_fingerprints.is_empty())
            .then(|| snapshot_file_entity_set_hex(&final_fingerprints));
        let final_upload_body_witness = by_source_file_body_witness
            .get(&pending.source_file_fingerprint)
            .filter(|witnesses| !witnesses.is_empty())
            .map(snapshot_file_upload_body_set_hex);
        if pending.sampled_audit_verified {
            crate::local_resource_diagnostics::sampled_audit_comparison(
                source.api_slug(),
                (
                    final_group_fingerprint.as_deref(),
                    pending.previous_snapshot_fingerprint.as_deref(),
                ),
                (
                    final_upload_body_witness.as_deref(),
                    pending.previous_upload_body_witness.as_deref(),
                ),
            );
        }
        let quarantine_retry_required = result.snapshots.iter().any(|snapshot| {
            snapshot.source_file_fingerprint.as_deref()
                == Some(pending.source_file_fingerprint.as_str())
                && index.quarantine_requires_retry_body(
                    &snapshot.snapshot_fingerprint,
                    &body_witness(snapshot),
                )
        });
        if source == SnapshotSource::ClaudeCode {
            if let Some((root, member)) =
                claude_index_path_family_member(Path::new(&pending.index_key))
            {
                if let Some(account_pending) = index.claude_account_family_pending.get_mut(&root) {
                    let mut owned = result
                        .snapshots
                        .iter()
                        .filter(|item| {
                            item.source_file_fingerprint.as_deref()
                                == Some(pending.source_file_fingerprint.as_str())
                        })
                        .peekable();
                    let account = &account_pending.account_identifier_hash;
                    let qualified = !account_pending.invalid
                        && owned.peek().is_some()
                        && owned.all(|item| {
                            item.source_session_id == member
                                && exact_session_account_hash(item).as_ref() == Some(account)
                        });
                    if let Some(requests) = account_pending.member_requests.get_mut(&member) {
                        requests.identity_revision = qualified
                            .then(|| {
                                claude_account_identity_revision(
                                    &pending.source_file_fingerprint,
                                    final_group_fingerprint.as_deref(),
                                    final_upload_body_witness.as_deref(),
                                )
                            })
                            .flatten();
                    }
                }
            }
        }
        if let Some(entry) = index.files.get_mut(&pending.index_key) {
            entry.last_snapshot_fingerprint = final_group_fingerprint.clone();
            entry.last_upload_body_witness = final_upload_body_witness.clone();
        }
        let stamped = index.stamp_effective_upload_body_witness_revision(
            &pending.index_key,
            &pending.source_file_fingerprint,
            pending.effective_upload_body_witness_revision,
        );
        if stamped && source == SnapshotSource::ClaudeCode {
            // The settled body's money-rule marks (design item 8), with its stamp.
            let mut items = result
                .snapshots
                .iter()
                .filter(|item| {
                    item.source_file_fingerprint.as_deref()
                        == Some(pending.source_file_fingerprint.as_str())
                })
                .peekable();
            if items.peek().is_some() {
                // The retired permit bit stays as stored.
                let retired = index
                    .claude_money_birth_store
                    .money_marks(claude_money_birth_store::location_key(&pending.index_key))
                    & claude_request_money::e2::money_mark::RETIRED_PERMIT;
                let marks = items.fold(retired, |marks, item| {
                    marks | claude_request_money::e2::money_marks(item)
                });
                index
                    .claude_money_birth_store
                    .set_money_marks(&pending.index_key, marks);
            }
        }
        if let Some(diagnostic) = result.local_codex_diagnostics.as_mut() {
            let key_digest = codex_scan_diagnostics::digest(&pending.index_key);
            for sample in diagnostic.lineage.iter_mut().flatten() {
                if sample.file_key_digest == Some(key_digest) {
                    sample.finalized = true;
                    sample.finalized_entity_count = final_fingerprints.len() as u64;
                    for (slot, fingerprint) in
                        final_fingerprints.iter().take(LINEAGE_SAMPLES).enumerate()
                    {
                        sample.successor_digests[slot] =
                            codex_scan_diagnostics::digest(fingerprint);
                    }
                    sample.final_body_digest = final_upload_body_witness
                        .as_deref()
                        .map(codex_scan_diagnostics::digest);
                    sample.final_body_revision = index
                        .files
                        .get(&pending.index_key)
                        .map(|entry| entry.effective_upload_body_witness_revision)
                        .unwrap_or_default();
                }
            }
        }
        // A complete, permitted reconstruction replaces only THIS file's
        // carried incidence. Its already accepted entities must not be offered
        // again when a history hold is released, even without an old body tuple.
        // Legacy/unknown incidence stays funded and protects only its original
        // ACKs even when no file association can be recovered.
        let context_rearm_required = index.file_upload_context_enabled
            && index.file_upload_context_requires_adoption(&pending.index_key);
        if let Some(unknown) = index.accepted_rebuild_incidence.get("") {
            carried_noop_entities.extend(
                unknown
                    .intersection(&final_fingerprints)
                    .filter(|fp| {
                        !context_rearm_required
                            && index.accepted_snapshot_fingerprints.contains(*fp)
                    })
                    .cloned(),
            );
        }
        if let Some(carried) = index.accepted_rebuild_incidence.remove(&pending.index_key) {
            carried_noop_entities.extend(
                carried
                    .intersection(&final_fingerprints)
                    .filter(|fp| {
                        !context_rearm_required
                            && index.accepted_snapshot_fingerprints.contains(*fp)
                    })
                    .cloned(),
            );
        }
        index.accepted_incidence_pending_census = !index.accepted_rebuild_incidence.is_empty();
        if final_fingerprints.is_empty() {
            index.file_snapshot_fingerprints.remove(&pending.index_key);
            index
                .confirmed_empty_files
                .insert(pending.index_key.clone());
        } else {
            index
                .file_snapshot_fingerprints
                .insert(pending.index_key.clone(), final_fingerprints);
            index.confirmed_empty_files.remove(&pending.index_key);
        }
        if final_group_fingerprint.is_some()
            && final_group_fingerprint == pending.previous_snapshot_fingerprint
            && final_upload_body_witness == pending.previous_upload_body_witness
            // An unresolved POST may have replaced that older accepted body.
            // Use the pre-replay fact: record() writes provisional new entries.
            && !pending.codex_pending_recovery
            && !quarantine_retry_required
            && !context_rearm_required
        {
            noop_source_files.insert(pending.source_file_fingerprint.clone());
            result.semantic_noop_count = result
                .semantic_noop_count
                .saturating_add(pending.parsed_snapshot_count);
        }
    }
    if source == SnapshotSource::ClaudeCode {
        index.note_claude_history_not_stamped();
    }
    result.snapshots.retain(|snapshot| {
        !carried_noop_entities.contains(&snapshot.snapshot_fingerprint)
            && snapshot
                .source_file_fingerprint
                .as_ref()
                .map(|source_file| !noop_source_files.contains(source_file))
                .unwrap_or(true)
    });

    // State-only Codex entities do not have a source-file fingerprint, so they
    // cannot use the file finalization table above. Rebind their durable map to
    // the final post-enrichment/post-policy/post-cutoff fingerprint here. This
    // is also where no-op suppression belongs: parser-time equality is not
    // authoritative when a privacy policy or account cutoff changed.
    if source == SnapshotSource::Codex && result.state_census_complete {
        let previous = index.codex_state_only_snapshot_fingerprints.clone();
        let mut current = BTreeMap::new();
        let mut noop_state_only = BTreeSet::new();
        for snapshot in &result.snapshots {
            if snapshot.source_file_fingerprint.is_none()
                && snapshot.provenance.collector == "codex_state_sqlite"
            {
                let fingerprint = snapshot.snapshot_fingerprint.clone();
                if previous.get(&snapshot.source_session_id) == Some(&fingerprint)
                    && index.snapshot_activity_at.contains_key(&fingerprint)
                    && !index.quarantine_requires_retry(&fingerprint)
                {
                    noop_state_only.insert(snapshot.source_session_id.clone());
                    result.semantic_noop_count = result.semantic_noop_count.saturating_add(1);
                }
                current.insert(snapshot.source_session_id.clone(), fingerprint);
            }
        }
        index.codex_state_only_snapshot_fingerprints = current;
        result.snapshots.retain(|snapshot| {
            snapshot.source_file_fingerprint.is_some()
                || snapshot.provenance.collector != "codex_state_sqlite"
                || !noop_state_only.contains(&snapshot.source_session_id)
        });
    }
    if result.census_complete {
        if !index.bounded_sweep_had_unsettled_upload {
            index.upload_context_fingerprint = index.active_upload_context_fingerprint.clone();
        }
        index.bounded_sweep_had_unsettled_upload = false;
        index.bounded_sweep_unsettled_causes = 0;
        index.claude_full_rearm_progress.held_family_roots = None;
    }
    index.note_carried_ack_census(source, result.census_complete, SystemTime::now());
    let current_fingerprints = index
        .file_snapshot_fingerprints
        .values()
        .flat_map(BTreeSet::iter)
        .chain(index.codex_state_only_snapshot_fingerprints.values())
        .collect::<BTreeSet<_>>();
    index
        .snapshot_activity_at
        .retain(|fingerprint, _| current_fingerprints.contains(fingerprint));
}

/// The producer-side event clock mirrored by the accepted-log append path.
/// The maximum activity clock is stable across retries and reconstructible on
/// both sides. `collected_at` is deliberately excluded because it is an
/// observation clock; metadata-only entities without semantic activity do not
/// participate in a v2 manifest.
fn snapshot_semantic_activity_at(item: &SnapshotItem) -> Option<String> {
    item.usage_buckets
        .iter()
        .flat_map(|bucket| {
            [
                Some(bucket.bucket_start.as_str()),
                bucket.first_activity_at.as_deref(),
                bucket.last_activity_at.as_deref(),
            ]
        })
        .chain([
            item.source_started_at.as_deref(),
            item.source_ended_at.as_deref(),
            item.source_last_activity_at.as_deref(),
        ])
        .flatten()
        .filter_map(|value| {
            OffsetDateTime::parse(value, &Rfc3339)
                .ok()
                .map(|parsed| (parsed, value))
        })
        .max_by_key(|(parsed, _)| *parsed)
        .map(|(_, value)| value.to_string())
}

/// Reasoning-effort tiers Claude Code reports today. Kept in one place so the
/// transcript reader and the OTLP sidecar admit exactly the same vocabulary.
const CLAUDE_EFFORT_TIERS: &[&str] = &["low", "medium", "high", "xhigh", "max"];

/// The applied reasoning-effort tier recorded on this transcript record.
///
/// Claude Code writes it as a top-level `effort` field on assistant records.
/// Unknown or malformed values degrade to `None` (effort-unknown) rather than
/// inventing a tier, and the vocabulary check keeps a future Claude tier from
/// silently widening the column the backend stores this in.
fn claude_transcript_effort(value: &Value) -> Option<String> {
    let effort = string_at(value, &["effort"])?.trim().to_ascii_lowercase();
    CLAUDE_EFFORT_TIERS
        .contains(&effort.as_str())
        .then_some(effort)
}

/// Apply privacy-safe account identity reduced from Claude Code's local OTLP.
///
/// Reasoning effort comes only from each assistant transcript record. Local
/// OTLP evidence may stamp an exactly covered session or proven account family,
/// but it must never supply or split reasoning-effort tiers.
pub fn apply_claude_effort_evidence(
    snapshots: &mut [SnapshotItem],
    evidence_by_session: &BTreeMap<String, Vec<crate::claude_local_otel::ClaudeLocalOtelEvidence>>,
) {
    let mut witnesses = BTreeMap::new();
    apply_claude_effort_evidence_with_families(
        snapshots,
        evidence_by_session,
        &mut witnesses,
        &BTreeMap::new(),
    );
}

pub fn apply_claude_effort_evidence_with_index(
    snapshots: &mut [SnapshotItem],
    evidence_by_session: &BTreeMap<String, Vec<crate::claude_local_otel::ClaudeLocalOtelEvidence>>,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
) {
    // A fingerprint version mismatch is missing proof, never an observed
    // account change. Preserve owners/ACKs and select the affected files even
    // on a nonterminal page, before the old witness can be forgotten.
    let reprove_roots = index
        .claude_account_family_witnesses
        .iter()
        .filter(|(_, witness)| {
            witness
                .member_request_id_fingerprints
                .values()
                .any(|fp| !is_snapshot_fingerprint(fp))
        })
        .map(|(root, _)| root.clone())
        .collect::<BTreeSet<_>>();
    if !reprove_roots.is_empty() {
        for (key, entry) in &mut index.files {
            if claude_index_path_family_member(Path::new(key))
                .is_some_and(|(root, _)| reprove_roots.contains(&root))
            {
                crate::local_resource_diagnostics::claude_reread::clear(
                    crate::local_resource_diagnostics::claude_reread::ClearSite::AccountReproof,
                    !entry.source_file_fingerprint.is_empty(),
                );
                entry.source_file_fingerprint.clear();
            }
        }
        index
            .claude_account_family_witnesses
            .retain(|root, _| !reprove_roots.contains(root));
    }
    let complete_family_members = if census_complete {
        complete_claude_family_members(index)
    } else {
        BTreeMap::new()
    };
    if census_complete {
        // v29 witnesses predate per-member request-set fingerprints. Removing
        // one without revisiting its unchanged transcript files would strand
        // later child-only reparses: scan identity stays at v24, so no ordinary
        // parser upgrade selects those files. Schedule only the affected
        // complete families for a bounded local reparse before the legacy
        // witness is discarded. The old count-only witness is never used to
        // stamp a v30 parse; the reparse must rebuild exact request coverage.
        let legacy_witness_roots = index
            .claude_account_family_witnesses
            .iter()
            .filter_map(|(root_session_id, witness)| {
                let fingerprint_members = witness
                    .member_request_id_fingerprints
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>();
                let witness_members = witness.members.keys().cloned().collect::<BTreeSet<_>>();
                ((fingerprint_members != witness_members
                    || witness
                        .member_request_id_fingerprints
                        .values()
                        .any(|fp| !is_snapshot_fingerprint(fp)))
                    && complete_family_members.contains_key(root_session_id))
                .then_some(root_session_id.clone())
            })
            .collect::<BTreeSet<_>>();
        for (index_key, entry) in &mut index.files {
            let Some((root_session_id, source_session_id)) =
                claude_index_path_family_member(Path::new(index_key))
            else {
                continue;
            };
            if legacy_witness_roots.contains(&root_session_id)
                && complete_family_members
                    .get(&root_session_id)
                    .is_some_and(|members| members.contains(&source_session_id))
            {
                entry.source_file_fingerprint.clear();
            }
        }
        index
            .claude_account_family_witnesses
            .retain(|root_session_id, witness| {
                complete_family_members
                    .get(root_session_id)
                    .is_some_and(|members| {
                        witness
                            .member_request_id_fingerprints
                            .values()
                            .all(|fp| is_snapshot_fingerprint(fp))
                            && members == &witness.members.keys().cloned().collect::<BTreeSet<_>>()
                            && members
                                == &witness
                                    .member_request_id_fingerprints
                                    .keys()
                                    .cloned()
                                    .collect::<BTreeSet<_>>()
                    })
            });
    }
    let retain_strict_runs = index.decode_holds.is_empty();
    accumulate_claude_family_pending(
        snapshots,
        evidence_by_session,
        &mut index.claude_account_family_pending,
        census_window_end,
        retain_strict_runs,
    );
    let proven_families = if census_complete {
        complete_family_members
            .iter()
            .filter_map(|(root_session_id, complete_members)| {
                index
                    .claude_account_family_pending
                    .get(root_session_id)
                    .filter(|pending| {
                        !pending.invalid
                            && pending.census_window_end == census_window_end
                            && &pending.members.keys().cloned().collect::<BTreeSet<_>>()
                                == complete_members
                            && &pending
                                .member_requests
                                .keys()
                                .cloned()
                                .collect::<BTreeSet<_>>()
                                == complete_members
                            && claude_family_request_ids_are_disjoint(pending)
                    })
                    .map(|pending| {
                        (
                            root_session_id.clone(),
                            ProvenClaudeAccountFamily {
                                members: pending.members.clone(),
                                member_request_id_fingerprints: pending
                                    .member_requests
                                    .iter()
                                    .map(|(source_session_id, request_id_hashes)| {
                                        (
                                            source_session_id.clone(),
                                            request_id_hashes.fingerprint.clone(),
                                        )
                                    })
                                    .collect(),
                            },
                        )
                    })
            })
            .collect::<BTreeMap<_, _>>()
    } else {
        BTreeMap::new()
    };
    for (root, pending) in &index.claude_account_family_pending {
        if pending.invalid {
            index.claude_account_family_witnesses.remove(root);
        }
    }
    let witness_roots_before = index
        .claude_account_family_witnesses
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    apply_claude_effort_evidence_with_families(
        snapshots,
        evidence_by_session,
        &mut index.claude_account_family_witnesses,
        &proven_families,
    );
    if census_complete {
        for pending in index.claude_account_family_pending.values_mut() {
            if pending.census_window_end == census_window_end {
                pending.census_complete = true;
            }
        }
        let current_source_session_ids = snapshots
            .iter()
            .map(|snapshot| snapshot.source_session_id.as_str())
            .collect::<BTreeSet<_>>();
        let newly_proven_roots = proven_families
            .keys()
            .filter(|root_session_id| {
                !witness_roots_before.contains(*root_session_id)
                    && index
                        .claude_account_family_witnesses
                        .contains_key(*root_session_id)
            })
            .collect::<BTreeSet<_>>();
        for (index_key, entry) in &mut index.files {
            let Some((root_session_id, source_session_id)) =
                claude_index_path_family_member(Path::new(index_key))
            else {
                continue;
            };
            if newly_proven_roots.contains(&root_session_id)
                && !current_source_session_ids.contains(source_session_id.as_str())
            {
                // Earlier pages uploaded an honest NULL before the terminal
                // census could prove the family. Reparse them once so the new
                // durable witness emits the correction on the next pass.
                entry.source_file_fingerprint.clear();
            }
        }
    }
}

pub fn claude_pending_family_session_ids(index: &ScanIndex) -> Vec<String> {
    index
        .claude_account_family_pending
        .iter()
        .filter(|(_, pending)| {
            pending.invalid
                || !pending.previous_windows.is_empty()
                || pending
                    .member_requests
                    .values()
                    .any(|requests| requests.identity_revision.is_none())
        })
        .map(|(root, _)| root)
        .chain(index.claude_usage_family_pending.keys())
        .chain(index.claude_usage_family_witnesses.keys())
        .chain(
            index
                .claude_usage_family_witnesses
                .values()
                .flat_map(|witness| witness.legacy_owner_roots.iter()),
        )
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

#[cfg(test)]
thread_local! {
    // Identical-input terminal fixture keeps the pre-elimination row lifetime
    // in its BASE arm. No production switch or persisted state is added.
    static RETAIN_ALL_CLAUDE_PROVEN_ROWS_FOR_TEST: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Replace transcript-only Claude usage with the exact union of transcript
/// responses and locally reported API-request occurrences, but only after a
/// complete filesystem census and an exact enhanced-trace ownership join.
///
/// This mutates usage, cost, and context-posture fields only. Provider graph
/// facts remain the transcript/filesystem truth and are never inferred from
/// telemetry spans.
pub fn apply_claude_reported_usage_with_index(
    snapshots: &mut [SnapshotItem],
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
) -> ClaudeUsageAuthorityDisposition {
    apply_claude_reported_usage_with_identity(
        snapshots,
        api_report,
        trace_report,
        index,
        census_complete,
        census_window_end,
        None,
    )
}

/// As above; with contract-5 evidence, each rebuilt item's requests are also
/// classified and grouped as the rebuild places them.
pub(crate) fn apply_claude_reported_usage_with_identity(
    snapshots: &mut [SnapshotItem],
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
) -> ClaudeUsageAuthorityDisposition {
    apply_claude_reported_usage_with_index_and_limits(
        snapshots,
        api_report,
        trace_report,
        index,
        census_complete,
        census_window_end,
        MAX_CLAUDE_PENDING_USAGE_OCCURRENCES,
        MAX_CLAUDE_DUPLICATE_REQUEST_OWNERS,
        identity,
    )
}

#[allow(clippy::too_many_arguments)]
fn apply_claude_reported_usage_with_index_and_limits(
    snapshots: &mut [SnapshotItem],
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
    max_pending_occurrences: usize,
    max_duplicate_owners: usize,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
) -> ClaudeUsageAuthorityDisposition {
    apply_claude_reported_usage_with_index_limits_and_current_files(
        snapshots,
        api_report,
        trace_report,
        index,
        census_complete,
        census_window_end,
        max_pending_occurrences,
        max_duplicate_owners,
        identity,
        &BTreeSet::new(),
        None,
        None,
        &BTreeMap::new(),
    )
}

/// Current-page reads defer earlier empty-pair completion until finalization
/// and file selection. In particular a failed newer read cannot certify the
/// previously stored empty revision as this page's current result.
#[cfg(test)]
pub(crate) fn apply_claude_reported_usage_to_scan_with_identity(
    scan: &mut SourceScanResult,
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
) -> ClaudeUsageAuthorityDisposition {
    apply_claude_reported_usage_to_scan_with_observations(
        scan,
        api_report,
        trace_report,
        index,
        identity,
        None,
    )
}

// A consumed receipt, not a second graph of snapshots or provider rows. It can
// only be minted by accumulating actual native occurrences into this index.
// No S/possible-owner input and no Clone implementation exist.
pub(crate) struct ClaudeNativeObservations {
    counts: ClaudeDuplicateCensusCounts,
    census_window_end: String,
    index_generation: u64,
}

#[allow(dead_code)] // The inactive driver's pre-offer path is not integrated yet.
pub(crate) fn record_claude_native_observations(
    scan: &SourceScanResult,
    index: &mut ScanIndex,
) -> ClaudeNativeObservations {
    ClaudeNativeObservations {
        counts: accumulate_claude_usage_family_pending_with_limit(
            &scan.snapshots,
            &mut index.claude_usage_family_pending,
            &scan.census_window_end,
            MAX_CLAUDE_PENDING_USAGE_OCCURRENCES,
        ),
        census_window_end: scan.census_window_end.clone(),
        index_generation: index.generation,
    }
}

#[cfg(test)]
pub(crate) fn apply_claude_reported_usage_to_scan_with_observations(
    scan: &mut SourceScanResult,
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
    observations: Option<ClaudeNativeObservations>,
) -> ClaudeUsageAuthorityDisposition {
    apply_claude_reported_usage_to_scan_with_comparison(
        scan,
        api_report,
        trace_report,
        index,
        identity,
        observations,
        None,
        &BTreeMap::new(),
    )
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn apply_claude_reported_usage_to_scan_with_comparison(
    scan: &mut SourceScanResult,
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
    observations: Option<ClaudeNativeObservations>,
    comparison: Option<claude_native_comparison::FoldView<'_>>,
    veto_api_rows: &ClaudeVetoApiRows,
) -> ClaudeUsageAuthorityDisposition {
    // A previous unsettled upload requires a clean followup before manifest /
    // replay settlement, but cannot erase the actual healthy terminal native
    // window. Fold those observations once before any recovered body can leave.
    let native_census_complete = scan.census_complete
        || comparison
            .as_ref()
            .is_some_and(|view| view.native_census_complete(scan));
    let current_files = if index.claude_usage_authority_quarantine.is_empty() {
        BTreeSet::new()
    } else {
        scan.pending_finalization
            .iter()
            .map(|pending| pending.index_key.clone())
            .collect()
    };
    let mut disposition = apply_claude_reported_usage_with_index_limits_and_current_files(
        &mut scan.snapshots,
        api_report,
        trace_report,
        index,
        native_census_complete,
        &scan.census_window_end,
        MAX_CLAUDE_PENDING_USAGE_OCCURRENCES,
        MAX_CLAUDE_DUPLICATE_REQUEST_OWNERS,
        identity,
        &current_files,
        observations,
        comparison,
        veto_api_rows,
    );
    // Slice D1: report only. The shadow was measured by the scan; no fold
    // input above read it.
    disposition.duplicate_census.request_census = scan.claude_request_census_shadow;
    disposition
}

#[allow(clippy::too_many_arguments)]
fn apply_claude_reported_usage_with_index_limits_and_current_files(
    snapshots: &mut [SnapshotItem],
    api_report: &crate::claude_local_otel::ClaudeLocalOtelLoadReport,
    trace_report: &crate::claude_local_otel::ClaudeTraceOwnershipLoadReport,
    index: &mut ScanIndex,
    census_complete: bool,
    census_window_end: &str,
    max_pending_occurrences: usize,
    max_duplicate_owners: usize,
    identity: Option<&claude_request_identity::ScanEvidence<'_>>,
    current_files: &BTreeSet<String>,
    observations: Option<ClaudeNativeObservations>,
    comparison: Option<claude_native_comparison::FoldView<'_>>,
    veto_api_rows: &ClaudeVetoApiRows,
) -> ClaudeUsageAuthorityDisposition {
    let complete_rebuild_read =
        census_complete && take_claude_complete_rebuild_read(index, census_window_end);
    let (negatives, diagnostic) = comparison.map_or((None, None), |view| {
        (view.negatives, view.lease.map(|lease| &lease.diagnostic))
    });
    if let Some(diagnostic) = diagnostic {
        diagnostic.update(|d| d.fold_index_generation = Some(index.generation));
    }
    let mut duplicate_census = match observations {
        Some(observed) => {
            assert_eq!(
                observed.census_window_end, census_window_end,
                "native observations cannot cross census windows"
            );
            assert_eq!(
                observed.index_generation, index.generation,
                "native observations cannot cross selected-index saves"
            );
            observed.counts
        }
        None => accumulate_claude_usage_family_pending_with_limit(
            snapshots,
            &mut index.claude_usage_family_pending,
            census_window_end,
            max_pending_occurrences,
        ),
    };
    duplicate_census.census_complete = census_complete;
    duplicate_census.fence_before = index.claude_duplicate_request_witness_overflowed;
    let reports_healthy = api_report.health.is_complete() && trace_report.is_complete();
    // The canonical ownership reducer validates semantic evidence too (row
    // fingerprints/revisions/clocks and paired clients), beyond file health.
    // No evidence is healthy: the reducer returns Some(empty), not a refusal.
    let ownership = reports_healthy.then(|| {
        classify_claude_legacy_request_owners(api_report.evidence.iter(), &trace_report.evidence)
    });
    let ownership_refusal = ownership
        .as_ref()
        .and_then(|result| result.as_ref().err())
        .copied();
    let legacy_request_owners = ownership.and_then(Result::ok);
    // Sidecar-content refusals cannot be repaired by rereading transcripts.
    // Keep failed reads retryable; canonical ownership remains unchanged.
    let other_evidence_cause = !reports_healthy
        || identity.is_some_and(|evidence| !evidence.unhealthy_roots.is_empty())
        || rfc3339_unix_seconds(census_window_end).is_none()
        || (census_complete
            && index.files.keys().any(|key| {
                claude_index_path_family_member(Path::new(key)).is_some_and(|(_, member)| {
                    index.claude_account_deferred_holds.contains_key(key)
                        || index.claude_owned_start_census.contains_key(&member)
                })
            }));
    index.claude_full_rearm_progress.observe_page(
        snapshots,
        &index.claude_usage_family_pending,
        census_window_end,
        &duplicate_census,
        other_evidence_cause,
    );

    // SOURCE (B): only FE-published sealed prefixes are excluded. Ordinary
    // EOF-recomposed Tail/Unchanged bodies keep positive proof/posture behavior
    // while still owing their Full audit. D1 tail records used directly, without
    // a complete current native body, remain observation-only evidence.
    // Bind prefix provenance by exact revision as well as physical path: a
    // logical family can differ from its index key, and D1 can be missing.
    let uncertified_revisions = index
        .files
        .values()
        .filter(|entry| entry.has_prefix_provenance())
        .map(|entry| entry.source_file_fingerprint.as_str())
        .filter(|revision| !revision.is_empty())
        .collect::<BTreeSet<_>>();
    let mut uncertified_roots = index
        .claude_request_census
        .records()
        .filter(|(_, record)| {
            record.unverified_or_twin()
                && !(record.can_bind_recomposed_body()
                    && snapshots.iter().any(|item| {
                        item.source_file_fingerprint
                            .as_deref()
                            .is_some_and(|revision| {
                                !uncertified_revisions.contains(revision)
                                    && claude_request_census::fingerprint_matches(record, revision)
                            })
                    }))
        })
        .map(|(key, _)| key)
        .chain(
            index
                .files
                .iter()
                .filter(|(_, entry)| entry.has_prefix_provenance())
                .map(|(key, _)| key),
        )
        .filter_map(|key| claude_index_path_family_member(Path::new(key)))
        .map(|(root, _)| root)
        .collect::<BTreeSet<_>>();
    let mut prefix_excluded_bodies = 0u64;
    uncertified_roots.extend(
        snapshots
            .iter()
            .filter(|item| {
                let prefix = item
                    .source_file_fingerprint
                    .as_deref()
                    .is_some_and(|revision| uncertified_revisions.contains(revision));
                prefix_excluded_bodies = prefix_excluded_bodies.saturating_add(u64::from(prefix));
                prefix
            })
            .map(claude_snapshot_family_root),
    );
    crate::local_resource_diagnostics::cache_lifecycle::add(
        crate::local_resource_diagnostics::cache_lifecycle::Event::PrefixExcludedBody,
        prefix_excluded_bodies,
    );
    drop(uncertified_revisions);
    let complete_families = if census_complete {
        complete_claude_usage_family_members(index)
    } else {
        BTreeMap::new()
    };
    let mut ignored_vetoes = ownership_refusal.map_or(0, IgnoredVeto::bit);
    let mut proven = BTreeMap::new();
    let mut reconstructed = BTreeMap::new();
    let witness_roots_before = index
        .claude_usage_family_witnesses
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let witness_fingerprints_before = index
        .claude_usage_family_witnesses
        .iter()
        .map(|(root_session_id, witness)| {
            (
                root_session_id.clone(),
                claude_usage_family_witness_fingerprint(witness),
            )
        })
        .collect::<BTreeMap<_, _>>();
    // A reconstructed family is read only for this call's items (rebuild and
    // posture below); the witness retain already keeps every earlier root.
    // Reconstructing other witnesses cloned their API rows for no reader.
    let item_roots = snapshots
        .iter()
        .map(claude_snapshot_family_root)
        .collect::<BTreeSet<_>>();
    if census_complete && reports_healthy {
        let legacy_exclusions = derive_claude_legacy_usage_exclusions(
            &complete_families,
            &index.claude_usage_family_pending,
            legacy_request_owners.as_ref(),
        );
        for (root_session_id, members) in &complete_families {
            if uncertified_roots.contains(root_session_id) {
                continue;
            }
            let Some(base_pending) = index.claude_usage_family_pending.get(root_session_id) else {
                continue;
            };
            let mut pending = base_pending.clone();
            for member in confirmed_empty_claude_family_members(index, root_session_id) {
                pending
                    .member_request_id_hashes
                    .entry(member.clone())
                    .or_default();
                pending.member_occurrences.entry(member).or_default();
            }
            if pending.invalid
                || pending.census_window_end != census_window_end
                || pending
                    .member_request_id_hashes
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>()
                    != *members
                || pending
                    .member_occurrences
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>()
                    != *members
            {
                continue;
            }
            let Some(mut family) = prove_claude_usage_family(
                root_session_id,
                members,
                &pending,
                api_report.evidence.get(root_session_id),
                trace_report.evidence.get(root_session_id),
                legacy_exclusions.get(root_session_id),
            ) else {
                if api_report.evidence.contains_key(root_session_id)
                    || trace_report.evidence.contains_key(root_session_id)
                {
                    ignored_vetoes |= IgnoredVeto::ProofFailure.bit();
                }
                continue;
            };
            // Only page-item roots consume these rows below. Keep every
            // proven key and witness for rebind, retention and rearm.
            let retain_rows = item_roots.contains(root_session_id);
            #[cfg(test)]
            let retain_rows =
                retain_rows || RETAIN_ALL_CLAUDE_PROVEN_ROWS_FOR_TEST.with(std::cell::Cell::get);
            if !retain_rows {
                family.rows_by_member = BTreeMap::new();
            }
            proven.insert(root_session_id.clone(), family);
        }
        reconstructed = index
            .claude_usage_family_witnesses
            .iter()
            .filter(|(root_session_id, _)| {
                item_roots.contains(*root_session_id)
                    && !uncertified_roots.contains(*root_session_id)
                    && !proven.contains_key(*root_session_id)
            })
            .filter_map(|(root_session_id, witness)| {
                let family = reconstruct_claude_usage_family(
                    root_session_id,
                    witness,
                    api_report,
                    trace_report,
                    legacy_request_owners.as_ref(),
                );
                if family.is_none()
                    && (api_report.evidence.contains_key(root_session_id)
                        || trace_report.evidence.contains_key(root_session_id))
                {
                    ignored_vetoes |= IgnoredVeto::ReconstructionFailure.bit();
                }
                family.map(|family| (root_session_id.clone(), family))
            })
            .collect();
        // Path-(a) tombstone (Round 12): a retired family keeps its witness
        // while tombstoned, so a returning member re-proves against it (or is
        // held by it) instead of being read as a fresh, unproven family.
        let tombstones = &index.claude_retired_family_tombstones;
        let uncertain = index.claude_retired_family_tombstones_uncertain;
        let tombstoned = |root_session_id: &str| {
            claude_root_tombstoned_in(tombstones, uncertain, root_session_id)
        };
        index
            .claude_usage_family_witnesses
            .retain(|root_session_id, _| {
                (complete_families.contains_key(root_session_id) || tombstoned(root_session_id))
                    && (proven.contains_key(root_session_id)
                        || reconstructed.contains_key(root_session_id)
                        || witness_roots_before.contains(root_session_id))
            });
        for (root_session_id, family) in &proven {
            index.rebind_claude_authority_proof(root_session_id, &family.witness);
            index
                .claude_usage_family_witnesses
                .insert(root_session_id.clone(), family.witness.clone());
            index.rebind_retry_pending_claude_authority(root_session_id);
        }
    } else if census_complete {
        // Report availability is not evidence that a previously proven
        // family became unowned. Retain exact witnesses for families still
        // present in the complete filesystem census; changed revisions are
        // held below until the reports can be reconstructed again.
        // A tombstoned family keeps its witness here too (Round 12), and so
        // does every family under the uncertainty fence (Round 13).
        let tombstones = &index.claude_retired_family_tombstones;
        let uncertain = index.claude_retired_family_tombstones_uncertain;
        index
            .claude_usage_family_witnesses
            .retain(|root_session_id, _| {
                complete_families.contains_key(root_session_id)
                    || claude_root_tombstoned_in(tombstones, uncertain, root_session_id)
            });
    } else if reports_healthy {
        reconstructed = index
            .claude_usage_family_witnesses
            .iter()
            .filter(|(root_session_id, _)| {
                item_roots.contains(*root_session_id)
                    && !uncertified_roots.contains(*root_session_id)
            })
            .filter_map(|(root_session_id, witness)| {
                let family = reconstruct_claude_usage_family(
                    root_session_id,
                    witness,
                    api_report,
                    trace_report,
                    legacy_request_owners.as_ref(),
                );
                if family.is_none()
                    && (api_report.evidence.contains_key(root_session_id)
                        || trace_report.evidence.contains_key(root_session_id))
                {
                    ignored_vetoes |= IgnoredVeto::ReconstructionFailure.bit();
                }
                family.map(|family| (root_session_id.clone(), family))
            })
            .collect();
    }

    let mut request_groupings = BTreeMap::new();
    for item in snapshots.iter_mut() {
        // Design item 9 ("None owners" for v1 bodies): an E2 body never
        // reaches the legacy fork-prefix exclusion. Its copies are removed
        // once, by the E2 copy rule. The owners still feed the fence and
        // re-arm decisions below (StateMissing inputs), never a v1 body.
        if claude_request_money::e2::enabled() && item.claude_money.is_some() {
            continue;
        }
        item.usage_accounting_contract = None;
        let root_session_id = claude_snapshot_family_root(item);
        let family = proven
            .get(&root_session_id)
            .or_else(|| reconstructed.get(&root_session_id));
        let Some(family) = family else { continue };
        let Some((rows, excluded_request_hashes)) = claude_reported_usage_inputs(item, family)
        else {
            ignored_vetoes |= IgnoredVeto::MissingInputs.bit();
            continue;
        };
        // The rebuild mirrors each of its rows into the grouping, so groups
        // are bounded by the rows it builds, never by the request count.
        let mut sink = identity.and_then(|evidence| {
            claude_request_identity::RequestSink::for_item(evidence, item, usize::MAX)
                .map(|sink| sink.excluding(item, &excluded_request_hashes))
        });
        if rebuild_claude_reported_usage(item, rows, &excluded_request_hashes, sink.as_mut()) {
            if let Some(sink) = sink {
                request_groupings.insert(item.source_session_id.clone(), sink.finish());
            }
            item.usage_accounting_contract =
                Some("session_exclusive_reported_usage:v1".to_string());
            item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::ClaudeCode, item);
        } else {
            // Ordinary preparation is deterministic in-memory validation.
            // Paid-preflight refusal and sidecar read failure use their own retries.
            ignored_vetoes |= IgnoredVeto::RebuildFailure.bit();
        }
    }
    if identity.is_some_and(|evidence| {
        snapshots.iter().any(|item| {
            claude_request_identity::full_rearm_requests_refused(
                item,
                evidence,
                request_groupings.get(&item.source_session_id),
                &index.claude_duplicate_request_owners,
            )
        })
    }) {
        ignored_vetoes |= IgnoredVeto::RequestsRefused.bit();
    }
    index
        .claude_full_rearm_progress
        .observe_ignored(census_window_end, ignored_vetoes);

    // The complete local transcript census can disprove ownership through a
    // duplicated request id, but uniqueness is not positive ownership: the
    // predecessor may be missing or deleted. Exact inherited-prefix or
    // session-exclusive provider/local proof below must establish the start;
    // all duplicate, missing-id, or unproven-start shapes fail closed.
    let indexed_claude_family_ids = if census_complete {
        index
            .files
            .keys()
            .filter_map(|index_key| claude_index_path_family_member(Path::new(index_key)))
            .flat_map(|(root_session_id, member)| [root_session_id, member])
            .collect::<BTreeSet<_>>()
    } else {
        BTreeSet::new()
    };
    let duplicate_census_invalid =
        index
            .claude_usage_family_pending
            .iter()
            .any(|(root_session_id, pending)| {
                if pending.census_window_end == census_window_end {
                    return pending.invalid;
                }
                claude_stale_pending_keeps_census_invalid(
                    index,
                    root_session_id,
                    pending,
                    census_complete,
                    &indexed_claude_family_ids,
                )
            });
    duplicate_census.census_invalid = duplicate_census_invalid;
    // Reuse the native census join for a negative scheduling veto even when
    // an invalid family masks positive duplicate-dependent ownership outputs.
    // Stable native copies deliberately veto every due suppression (SOURCE).
    let native_duplicate_request_owners = if census_complete {
        let mut owners = BTreeMap::<String, BTreeSet<(String, String)>>::new();
        for (root_session_id, pending) in &index.claude_usage_family_pending {
            if pending.census_window_end != census_window_end {
                continue;
            }
            for (member_session_id, occurrences) in &pending.member_occurrences {
                for request_hash in occurrences.keys() {
                    owners
                        .entry(request_hash.clone())
                        .or_default()
                        .insert((root_session_id.clone(), member_session_id.clone()));
                }
            }
        }
        owners
            .into_iter()
            .filter(|(_, owners)| owners.len() > 1)
            .map(|(request_hash, owners)| {
                (
                    request_hash,
                    owners
                        .into_iter()
                        .map(|(root_session_id, source_session_id)| {
                            claude_duplicate_request_owner(&root_session_id, &source_session_id)
                        })
                        .collect::<BTreeSet<_>>(),
                )
            })
            .collect::<BTreeMap<_, _>>()
    } else {
        BTreeMap::new()
    };
    let native_duplicate_veto = !native_duplicate_request_owners.is_empty()
        || !index.claude_duplicate_request_owners.is_empty();
    if native_duplicate_veto {
        index.claude_full_rearm_progress.observe_page(
            &[],
            &index.claude_usage_family_pending,
            census_window_end,
            &duplicate_census,
            true,
        );
    }
    // Keep the pre-existing ownership mask; the broader negative query above
    // never grants ownership, changes attribution or enters a money path.
    let detected_duplicate_request_owners = if duplicate_census_invalid {
        BTreeMap::new()
    } else {
        native_duplicate_request_owners
    };
    let duplicated_request_hashes = index
        .claude_duplicate_request_owners
        .keys()
        .chain(detected_duplicate_request_owners.keys())
        .cloned()
        .collect::<BTreeSet<_>>();
    if census_complete {
        let current_members = complete_families
            .values()
            .flatten()
            .cloned()
            .collect::<BTreeSet<_>>();
        index
            .claude_owned_start_census
            .retain(|source_session_id, _| current_members.contains(source_session_id));
    }
    if census_complete
        && !duplicate_census_invalid
        && !index.claude_duplicate_request_witness_overflowed
    {
        let verified = index
            .claude_owned_start_census
            .iter()
            .filter_map(|(source_session_id, witness)| {
                let (root_session_id, _) = complete_families
                    .iter()
                    .find(|(_, members)| members.contains(source_session_id))?;
                if uncertified_roots.contains(root_session_id) {
                    return None;
                }
                let pending = index.claude_usage_family_pending.get(root_session_id)?;
                if pending.invalid || pending.census_window_end != census_window_end {
                    return None;
                }
                let request_hashes = pending.member_request_id_hashes.get(source_session_id)?;
                if !request_hashes.is_disjoint(&duplicated_request_hashes) {
                    return None;
                }
                let indexed_fingerprint = index.files.iter().find_map(|(index_key, entry)| {
                    claude_index_path_family_member(Path::new(index_key))
                        .filter(|(_, member)| member == source_session_id)
                        .map(|_| entry.source_file_fingerprint.clone())
                })?;
                (indexed_fingerprint == witness.marker_source_file_fingerprint)
                    .then_some((source_session_id.clone(), indexed_fingerprint))
            })
            .collect::<Vec<_>>();
        for (source_session_id, fingerprint) in verified {
            if let Some(witness) = index.claude_owned_start_census.get_mut(&source_session_id) {
                witness.verified_source_file_fingerprint = Some(fingerprint);
            }
        }
    }
    // Design E: an item without a provider-proven start keeps its own-only
    // scalars by the file birth rule. Loaded telemetry only vetoes them; the
    // census fence and family pending are no longer consulted for scalars.
    let file_birth_tripwire = claude_context_file_birth::ClaudeTelemetryTripwire::build(
        snapshots,
        max_pending_occurrences,
        api_report,
        trace_report,
        veto_api_rows,
    );
    let multi_file_members = claude_context_file_birth::claude_multi_file_members(snapshots, index);
    let mut context_file_birth = ClaudeContextFileBirthCounts::default();
    #[cfg(test)]
    let mut posture_admissions = BTreeMap::new();
    for item in snapshots.iter_mut() {
        let root_session_id = claude_snapshot_family_root(item);
        let family = proven
            .get(&root_session_id)
            .or_else(|| reconstructed.get(&root_session_id));
        let excluded_request_hashes = family
            .and_then(|family| {
                family
                    .witness
                    .legacy_excluded_request_id_hashes
                    .get(&item.source_session_id)
            })
            .cloned()
            .unwrap_or_default();
        let unresolved_duplicate = duplicate_census_invalid
            || index.claude_duplicate_request_witness_overflowed
            || item.claude_usage_request_ids.iter().any(|request_id| {
                let request_hash = format!("{:x}", Sha256::digest(request_id.as_bytes()));
                duplicated_request_hashes.contains(&request_hash)
                    && !excluded_request_hashes.contains(&request_hash)
            });
        let provider_owned_start = !excluded_request_hashes.is_empty()
            || item.usage_accounting_contract.as_deref()
                == Some("session_exclusive_reported_usage:v1");
        let explicit_owned_start = item.claude_context_curve_owned_start_proven;
        let source_certified = !uncertified_roots.contains(&root_session_id);
        let posture_owned = source_certified
            && (explicit_owned_start || provider_owned_start)
            && !unresolved_duplicate;
        if posture_owned {
            item.claude_file_birth_verdict = None;
            context_file_birth.record_proof(item);
            // Design E's first own request time rides the birth rule only.
            item.first_own_request_at = None;
            #[cfg(test)]
            posture_admissions.insert(
                item.source_session_id.clone(),
                ClaudePostureAdmission::Strict,
            );
        } else if !source_certified {
            clear_claude_context_posture(item);
        } else {
            // Cache observations and the curve below still read the strict
            // `posture_owned`: only the scalar tuple and session start move.
            let multi_file = multi_file_members.contains(&item.source_session_id);
            let verdict = claude_context_file_birth::admit_claude_file_birth_posture(
                item,
                &root_session_id,
                &file_birth_tripwire,
                &mut claude_context_file_birth::remembered_tripwire(),
                multi_file,
                &mut context_file_birth,
            );
            #[cfg(test)]
            posture_admissions.insert(
                item.source_session_id.clone(),
                ClaudePostureAdmission::FileBirth(verdict),
            );
            #[cfg(not(test))]
            let _ = verdict;
        }
        if posture_owned && item.claude_context_curve_identity_complete {
            let mut owned_occurrences = item
                .claude_usage_occurrences
                .iter()
                .filter_map(|(request_id, occurrence)| {
                    let request_hash = format!("{:x}", Sha256::digest(request_id.as_bytes()));
                    (!excluded_request_hashes.contains(&request_hash)).then_some(occurrence.clone())
                })
                .collect::<Vec<_>>();
            owned_occurrences.sort_by_key(|occurrence| occurrence.sequence);
            let copied_prefix_end = if excluded_request_hashes.is_empty() {
                None
            } else {
                owned_occurrences
                    .first()
                    .map(|occurrence| occurrence.sequence)
            };
            if excluded_request_hashes.is_empty() || copied_prefix_end.is_some() {
                if copied_prefix_end.is_some() {
                    // Request 1 belongs to the copied prefix, not this session.
                    item.session_start = item
                        .session_start
                        .take()
                        .and_then(|start| (*start).inherited())
                        .map(Box::new);
                }
                rebuild_claude_context_posture(item, &owned_occurrences, copied_prefix_end);
            } else {
                clear_claude_context_posture(item);
            }
        } else if posture_owned {
            // Without a complete request index the occurrences cannot rebuild
            // the tuple; ship the parser's own-only values, never raw ones.
            if item.claude_file_birth.observed() {
                claude_context_file_birth::apply_own_context_scalars(item, &mut context_file_birth);
            } else {
                clear_claude_context_posture(item);
            }
        }
        if posture_owned
            && item.claude_context_curve_identity_complete
            && item.claude_context_curve_request_index_complete
            && (census_complete || claude_owned_start_was_census_verified(item, index))
            && !index
                .claude_usage_family_pending
                .get(&root_session_id)
                .is_some_and(|pending| {
                    pending.invalid || pending.census_window_end != census_window_end
                })
        {
            let owned = item
                .cache_requests
                .iter()
                .filter(|request| {
                    let hash = format!("{:x}", Sha256::digest(request.slot.request_ref.as_bytes()));
                    !excluded_request_hashes.contains(&hash)
                })
                .map(|request| {
                    let mut request = request.clone();
                    if request.slot.effort.is_none() {
                        let efforts = family
                            .and_then(|family| family.rows_by_member.get(&item.source_session_id))
                            .into_iter()
                            .flatten()
                            .filter(|row| {
                                row.request_id == request.slot.request_ref
                                    && CLAUDE_EFFORT_TIERS.contains(&row.effort.as_str())
                            })
                            .map(|row| row.effort.clone())
                            .collect::<BTreeSet<_>>();
                        if efforts.len() == 1 {
                            request.slot.effort = efforts.into_iter().next();
                        }
                    }
                    request
                })
                .collect::<Vec<_>>();
            item.cache_observations = cache_wire_for_requests(&item.source_session_id, &owned);
            if !item.cache_requests_complete {
                item.cache_observations = Some(CacheObservations {
                    schema_version: 1,
                    operations: Vec::new(),
                    coverage: "partial".into(),
                    omitted_observation_count: None,
                });
            }
        } else {
            item.cache_observations = None;
        }
        // Context posture participates in semantic identity. Recompute after
        // the ownership fold even when curve admission is disabled.
        item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::ClaudeCode, item);

        if item.context_curve.is_none() {
            // Activity hint did not advertise durable curve admission for this
            // cycle. Do not mint additive evidence that cannot be settled.
            continue;
        }
        let unavailable_coverage = if !item.claude_context_curve_request_index_complete {
            "parser_unsupported"
        } else if item.claude_file_birth_verdict() == Some(ClaudeFileBirthVerdict::Admitted) {
            // File birth admits the scalar tuple, never the strict curve.
            "scalars_file_birth_only"
        } else {
            "ownership_unresolved"
        };
        item.context_curve = Some(unavailable_context_curve(
            CLAUDE_CODE_SNAPSHOT_PARSER_VERSION,
            CLAUDE_CONTEXT_CURVE_OWNERSHIP_REVISION,
            unavailable_coverage,
            0,
            0,
        ));
        let owned_start_census_verified = claude_owned_start_was_census_verified(item, index);
        if !source_certified
            || !(census_complete || owned_start_census_verified)
            || !item.claude_context_curve_identity_complete
            || !item.claude_context_curve_request_index_complete
        {
            continue;
        }
        if index
            .claude_usage_family_pending
            .get(&root_session_id)
            .is_some_and(|pending| {
                pending.invalid || pending.census_window_end != census_window_end
            })
        {
            continue;
        }
        let owned_start_proven = item.claude_context_curve_owned_start_proven
            || !excluded_request_hashes.is_empty()
            || item.usage_accounting_contract.as_deref()
                == Some("session_exclusive_reported_usage:v1");
        if !owned_start_proven {
            // Unique request ids in the bounded census do not prove ownership:
            // a missing/deleted/out-of-window predecessor can leave a Fable or
            // takeover transcript's copied prefix looking unique. Require an
            // explicit provider fork boundary, an exactly excluded copied
            // prefix, or complete provider-reported ownership evidence.
            continue;
        }
        if unresolved_duplicate {
            continue;
        }
        #[cfg(test)]
        eprintln!("claude_curve_native_predicate: sid8={:.8x} census_complete={census_complete} owned_start_census_verified={owned_start_census_verified} native_identity_complete={} native_request_index_complete={} owned_start_proven={owned_start_proven} same_window_pending_valid=true unresolved_duplicate=false", Sha256::digest(item.source_session_id.as_bytes()), item.claude_context_curve_identity_complete, item.claude_context_curve_request_index_complete);

        let mut owned_occurrences = item
            .claude_usage_occurrences
            .iter()
            .filter_map(|(request_id, occurrence)| {
                let request_hash = format!("{:x}", Sha256::digest(request_id.as_bytes()));
                (!excluded_request_hashes.contains(&request_hash)).then_some(occurrence)
            })
            .collect::<Vec<_>>();
        owned_occurrences.sort_by_key(|occurrence| occurrence.sequence);
        let candidates = owned_occurrences
            .iter()
            .map(|occurrence| ContextCurveCandidatePoint {
                observed_at: occurrence.timestamp.clone(),
                effective_input_tokens: occurrence.effective_input_context,
                model: occurrence.model.clone(),
                context_window_tokens: None,
            })
            .collect::<Vec<_>>();
        let first_owned_sequence = owned_occurrences
            .first()
            .map(|occurrence| occurrence.sequence)
            .unwrap_or(u64::MAX);
        let boundaries = canonical_claude_curve_boundaries(&item.claude_context_curve_boundaries)
            .into_iter()
            // A copied-prefix compaction belongs to the predecessor, just like the
            // copied responses before the first owned request.
            .filter(|boundary| boundary.response_count_before > first_owned_sequence)
            .map(|boundary| ContextCurveCandidateBoundary {
                observed_at: boundary.timestamp,
                point_count_before: owned_occurrences
                    .iter()
                    .filter(|occurrence| occurrence.sequence < boundary.response_count_before)
                    .count() as u64,
            })
            .collect::<Vec<_>>();
        item.context_curve = Some(build_context_curve(
            CLAUDE_CODE_SNAPSHOT_PARSER_VERSION,
            CLAUDE_CONTEXT_CURVE_OWNERSHIP_REVISION,
            CLAUDE_CONTEXT_CURVE_MODEL_EVIDENCE_REVISION,
            &candidates,
            &boundaries,
            "parser_unsupported",
        ));
        if item
            .context_curve
            .as_ref()
            .is_some_and(|curve| matches!(curve.coverage.as_str(), "complete" | "sampled"))
        {
            if let Some(fingerprint) = item.source_file_fingerprint.as_ref() {
                if let Some(witness) = index
                    .claude_owned_start_census
                    .get_mut(&item.source_session_id)
                    .filter(|witness| {
                        witness.verified_source_file_fingerprint.as_ref() == Some(fingerprint)
                    })
                {
                    witness.emitted_source_file_fingerprint = Some(fingerprint.clone());
                }
            }
        }
    }
    for item in snapshots.iter() {
        match item
            .context_curve
            .as_ref()
            .map(|curve| curve.coverage.as_str())
        {
            Some("scalars_file_birth_only") => {
                context_file_birth.curve_scalars_file_birth_only_session_count += 1;
            }
            Some("ownership_unresolved") => {
                context_file_birth.curve_ownership_unresolved_session_count += 1;
            }
            _ => {}
        }
    }
    claude_context_file_birth::alarm_first_resource_withhold(&context_file_birth);
    note_claude_reemission_stop(&context_file_birth, file_birth_tripwire.over_bound_roots());

    let owned_start_reparse_ids = index
        .claude_owned_start_census
        .iter()
        .filter_map(|(source_session_id, witness)| {
            witness
                .verified_source_file_fingerprint
                .as_ref()
                .filter(|verified| {
                    witness.emitted_source_file_fingerprint.as_ref() != Some(*verified)
                })
                .map(|_| source_session_id.clone())
        })
        .collect::<BTreeSet<_>>();
    if !owned_start_reparse_ids.is_empty() {
        for (index_key, entry) in &mut index.files {
            if claude_index_path_family_member(Path::new(index_key)).is_some_and(
                |(_, source_session_id)| owned_start_reparse_ids.contains(&source_session_id),
            ) {
                crate::local_resource_diagnostics::claude_reread::clear(
                    crate::local_resource_diagnostics::claude_reread::ClearSite::OwnedStart,
                    !entry.source_file_fingerprint.is_empty(),
                );
                entry.source_file_fingerprint.clear();
            }
        }
    }

    let mut disposition = ClaudeUsageAuthorityDisposition {
        request_groupings,
        #[cfg(test)]
        posture_admissions,
        context_file_birth,
        ..ClaudeUsageAuthorityDisposition::default()
    };
    let mut demoting_members_by_root = BTreeMap::<String, BTreeSet<String>>::new();
    for item in snapshots.iter() {
        let root_session_id = claude_snapshot_family_root(item);
        let contractless = item.usage_accounting_contract.as_deref()
            != Some("session_exclusive_reported_usage:v1");
        if contractless {
            disposition
                .context_file_birth
                .record_contractless(item, witness_roots_before.contains(&root_session_id));
        }
        // E2 (gate on): a request-owned body replaces the family's exclusive
        // reported body as a contract of its own (its literal is installed by
        // `e2::finish_page` after this fold), so it is not a demotion. Account,
        // security and E2 twin holds are separate and still apply.
        let request_owned = claude_request_money::e2::enabled() && item.claude_money.is_some();
        if witness_roots_before.contains(&root_session_id) && contractless && !request_owned {
            demoting_members_by_root
                .entry(root_session_id)
                .or_default()
                .insert(item.source_session_id.clone());
            if disposition
                .quarantined_source_session_ids
                .insert(item.source_session_id.clone())
            {
                // R7: the demotion hold stays; its sessions upload no
                // scalars this pass whatever their basis. Counted locally.
                disposition
                    .context_file_birth
                    .demotion_quarantined_session_count += 1;
            }
        }
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or_default();
    for root_session_id in demoting_members_by_root.keys() {
        let correction_failed = index
            .claude_usage_authority_quarantine
            .get(root_session_id)
            .is_some_and(|record| record.proof_correction.is_some());
        let current_witness = index.claude_usage_family_witnesses.get(root_session_id);
        let proven_witness_fingerprint = current_witness
            .map(claude_usage_family_witness_fingerprint)
            .or_else(|| witness_fingerprints_before.get(root_session_id).cloned());
        let Some(proven_witness_fingerprint) = proven_witness_fingerprint.as_ref() else {
            continue;
        };
        // SOURCE U3: a prior digest cannot bind a new record after census
        // pruning. Count it and keep the page's demotion hold; the family
        // stays unproven residue. Save and load drop any existing orphan.
        if current_witness.is_none() {
            count_claude_authority_unwitnessed_demotion();
            continue;
        }
        let mut member_source_file_fingerprints = index
            .files
            .iter()
            .filter_map(|(index_key, entry)| {
                let (root, member) = claude_index_path_family_member(Path::new(index_key))?;
                (root == *root_session_id && !entry.source_file_fingerprint.is_empty())
                    .then(|| (member, entry.source_file_fingerprint.clone()))
            })
            .collect::<BTreeMap<_, _>>();
        for item in snapshots
            .iter()
            .filter(|item| claude_snapshot_family_root(item) == *root_session_id)
        {
            // File-backed Claude snapshots always have a source fingerprint.
            // The body fingerprint is a fail-closed fallback for a malformed
            // legacy entry: it deliberately cannot match the next file
            // candidate, which makes that family reparse every pass instead
            // of silently settling a held revision without durable retry
            // state.
            let revision_fingerprint = item
                .source_file_fingerprint
                .as_ref()
                .unwrap_or(&item.snapshot_fingerprint);
            member_source_file_fingerprints
                .insert(item.source_session_id.clone(), revision_fingerprint.clone());
        }
        let existing = index.claude_usage_authority_quarantine.get(root_session_id);
        let same_binding = existing.is_some_and(|existing| {
            claude_usage_authority_deadline_is_bounded(existing)
                && existing.proven_witness_fingerprint == *proven_witness_fingerprint
                && existing.member_source_file_fingerprints == member_source_file_fingerprints
        });
        let retain_existing = existing.is_some_and(|existing| {
            !correction_failed
                && same_binding
                && (existing.disposition
                    == ClaudeUsageAuthorityQuarantineDisposition::UnprovenTerminal
                    || existing.retry_after_unix_seconds > now)
        });
        if !retain_existing {
            let failed_reconstruction_count = existing
                .map(|existing| existing.failed_reconstruction_count.saturating_add(1))
                .unwrap_or_else(initial_claude_usage_authority_failure_count)
                .min(MAX_CLAUDE_USAGE_AUTHORITY_FAILURES);
            let disposition = if failed_reconstruction_count == MAX_CLAUDE_USAGE_AUTHORITY_FAILURES
            {
                ClaudeUsageAuthorityQuarantineDisposition::UnprovenTerminal
            } else {
                ClaudeUsageAuthorityQuarantineDisposition::RetryPending
            };
            let retry_after_unix_seconds = if correction_failed {
                existing
                    .expect("correction record exists")
                    .retry_after_unix_seconds
            } else {
                claude_usage_authority_retry_deadline(root_session_id, proven_witness_fingerprint)
            };
            index.claude_usage_authority_quarantine.insert(
                root_session_id.clone(),
                ClaudeUsageAuthorityQuarantineRecord {
                    proof_correction: None,
                    contract: CLAUDE_USAGE_AUTHORITY_QUARANTINE_CONTRACT_VERSION.to_string(),
                    proven_witness_fingerprint: proven_witness_fingerprint.clone(),
                    member_source_file_fingerprints,
                    failed_reconstruction_count,
                    disposition,
                    retry_after_unix_seconds,
                },
            );
        }
    }

    if census_complete && reports_healthy {
        index.settle_known_empty_claude_proof_corrections(current_files, snapshots);
    }

    if census_complete {
        let duplicate_witnesses_before = index.claude_duplicate_request_owners.clone();
        let mut duplicate_witnesses_after = duplicate_witnesses_before.clone();
        if !duplicate_census_invalid {
            let current_owner_universe = complete_families
                .iter()
                .flat_map(|(root_session_id, source_session_ids)| {
                    source_session_ids.iter().map(|source_session_id| {
                        claude_duplicate_request_owner(root_session_id, source_session_id)
                    })
                })
                .collect::<BTreeSet<_>>();
            for owners in duplicate_witnesses_after.values_mut() {
                owners.retain(|owner| current_owner_universe.contains(owner));
            }
        }
        for (root_session_id, pending) in &index.claude_usage_family_pending {
            if pending.invalid || pending.census_window_end != census_window_end {
                if pending.invalid && pending.census_window_end == census_window_end {
                    duplicate_census.invalid_current_window_family_count = duplicate_census
                        .invalid_current_window_family_count
                        .saturating_add(1);
                }
                continue;
            }
            for (source_session_id, current_request_hashes) in &pending.member_request_id_hashes {
                let owner = claude_duplicate_request_owner(root_session_id, source_session_id);
                for (request_hash, owners) in &mut duplicate_witnesses_after {
                    if owners.contains(&owner) && !current_request_hashes.contains(request_hash) {
                        owners.remove(&owner);
                    }
                }
            }
        }
        for (request_hash, owners) in &detected_duplicate_request_owners {
            duplicate_witnesses_after
                .entry(request_hash.clone())
                .or_default()
                .extend(owners.iter().cloned());
        }
        duplicate_witnesses_after.retain(|_, owners| owners.len() > 1);
        let overflowed_before = index.claude_duplicate_request_witness_overflowed;
        let changed_duplicate_request_hashes = duplicate_witnesses_before
            .keys()
            .chain(duplicate_witnesses_after.keys())
            .filter(|request_hash| {
                duplicate_witnesses_before.get(*request_hash)
                    != duplicate_witnesses_after.get(*request_hash)
            })
            .cloned()
            .collect::<BTreeSet<_>>();
        let changed_duplicate_owners = duplicate_witnesses_before
            .iter()
            .chain(duplicate_witnesses_after.iter())
            .filter(|(request_hash, _)| {
                duplicate_witnesses_before.get(*request_hash)
                    != duplicate_witnesses_after.get(*request_hash)
            })
            .flat_map(|(_, owners)| owners.iter().cloned())
            .collect::<BTreeSet<_>>();
        let coverage_missing_member_count =
            claude_duplicate_fence_coverage_missing_member_count(index, census_window_end);
        duplicate_census.coverage_complete = coverage_missing_member_count == 0;
        duplicate_census.coverage_missing_member_count = coverage_missing_member_count;
        disposition.transcript_ownership_complete =
            claude_family_members_unobserved_count(index, census_window_end, false) == 0;
        // Only witnessed families left unread keep this closed fence closed.
        let closed_only_by_witnessed_families = overflowed_before
            && coverage_missing_member_count > 0
            && claude_duplicate_request_witness_within_bound(
                &duplicate_witnesses_after,
                max_duplicate_owners,
            )
            && claude_fence_held_only_by_witnessed_families(index, census_window_end);
        let owners_within_bound = claude_duplicate_request_witness_within_bound(
            &duplicate_witnesses_after,
            max_duplicate_owners,
        );
        if duplicate_census_invalid
            || !claude_duplicate_request_witness_within_bound(
                &duplicate_witnesses_after,
                max_duplicate_owners,
            )
            // A closed fence reopens only after a census that observed every
            // indexed family member in this window. Unchanged files skipped by
            // an incremental, reset, or partially undone pass carry no current
            // request evidence, so their absence from pending proves nothing.
            || (overflowed_before && coverage_missing_member_count > 0)
        {
            index.claude_duplicate_request_owners.clear();
            index.claude_duplicate_request_witness_overflowed = true;
        } else {
            index.claude_duplicate_request_owners = duplicate_witnesses_after;
            index.claude_duplicate_request_witness_overflowed = false;
        }
        let census_unix_seconds = rfc3339_unix_seconds(census_window_end);
        let full_rearm_due = claude_duplicate_fence_full_rearm_due(
            index,
            overflowed_before,
            index.claude_duplicate_request_witness_overflowed,
            census_unix_seconds,
        );
        // Fix 1: a due liveness re-arm that provably cannot open the fence is
        // skipped. It never touches the contract-5 latch or its own re-arms.
        // A held first proof waits on exactly this due re-arm (C1a's dormant
        // owner successor), so it vetoes the skip.
        let first_proof_hold = legacy_request_owners.as_ref().map(|request_owners| {
            claude_dormant_owner_successors(
                index,
                &proven,
                &complete_families,
                census_window_end,
                request_owners,
                api_report,
            )
        });
        let first_proof_held =
            first_proof_hold.is_some_and(|counts| counts.dormant_owner_successor_family_count > 0);
        let first_proof_veto = first_proof_held
            || index
                .claude_full_rearm_progress
                .first_proof_hold_since_full_rearm;
        let stays_closed = overflowed_before && index.claude_duplicate_request_witness_overflowed;
        // Lead A ruling (a): the cutover's latch re-arms at one terminal under
        // the recorded contract; its baseline carries over (no full re-arm).
        let cutover = index.claude_full_rearm_progress.contract_cutover;
        let contract = claude_request_identity::cycle_contract(identity.is_some());
        let cutover_terminal = cutover == CLAUDE_CONTRACT_CUTOVER_OWED
            && index.claude_request_identity_contract.as_deref() == Some(contract);
        let latch_rearms = index.claude_request_identity_contract_changed
            && cutover != CLAUDE_CONTRACT_CUTOVER_SPENT;
        if let Some(record) = (index.claude_full_rearm_progress.structural_record.as_mut())
            .filter(|record| cutover_terminal && record.basis == claude_full_rearm_record_basis(""))
        {
            record.basis = claude_full_rearm_record_basis(contract);
        }
        let full_rearm_suppressed = claude_full_rearm_structural_terminal(
            index,
            census_window_end,
            &indexed_claude_family_ids,
            owners_within_bound,
            stays_closed,
            full_rearm_due,
            first_proof_veto,
            census_unix_seconds,
            claude_request_identity::cycle_contract(identity.is_some()),
        );
        let post_rebuild_skipped = full_rearm_due
            && !overflowed_before
            && index.claude_duplicate_request_witness_overflowed
            && complete_rebuild_read
            && owners_within_bound
            && !disposition.context_file_birth.resource_withheld()
            && !first_proof_veto
            && !latch_rearms
            && index.claude_request_identity_contract.as_deref()
                == Some(claude_request_identity::cycle_contract(identity.is_some()))
            && !index.claude_full_rearm_progress.other_invalidation_observed;
        let full_rearm = full_rearm_due && !full_rearm_suppressed && !post_rebuild_skipped;
        if !index.claude_duplicate_request_witness_overflowed {
            index.claude_duplicate_fence_rearm_attempt = 0;
            index.claude_duplicate_fence_next_full_rearm_unix_seconds = None;
        } else if full_rearm || post_rebuild_skipped {
            let attempt = index
                .claude_duplicate_fence_rearm_attempt
                .min(CLAUDE_DUPLICATE_FENCE_REARM_MAX_ATTEMPT);
            // An unparsable census clock leaves no deadline, which makes the
            // next closed census re-arm again: cost only, never an opening.
            index.claude_duplicate_fence_next_full_rearm_unix_seconds = census_unix_seconds
                .map(|now| now.saturating_add(claude_duplicate_fence_rearm_delay_seconds(attempt)));
            index.claude_duplicate_fence_rearm_attempt = attempt
                .saturating_add(1)
                .min(CLAUDE_DUPLICATE_FENCE_REARM_MAX_ATTEMPT);
        }
        let next_window = if full_rearm && index.claude_duplicate_request_witness_overflowed {
            index
                .claude_full_rearm_progress
                .traversal_origin
                .as_ref()
                .filter(|origin| {
                    origin.process == claude_full_rearm_process()
                        && origin.window_ends.contains(census_window_end)
                })
                .cloned()
                .map(|mut origin| {
                    origin.window_ends.clear();
                    origin
                })
        } else {
            None
        };
        let progress = &mut index.claude_full_rearm_progress;
        if !index.claude_duplicate_request_witness_overflowed {
            // An open fence needs no suppression or window memory.
            progress.structural_record = None;
            progress.structural_rearm_owed = false;
            progress.full_rearm_window_next = false;
            progress.stale_rearm_fence_deadline = None;
            progress.stale_rearms_at_deadline = 0;
            progress.first_proof_hold_since_full_rearm = false;
        } else if full_rearm {
            // Fix 2: the next traversal start opens a full-rearm window.
            progress.full_rearm_window_next = true;
            progress.first_proof_hold_since_full_rearm = false;
            if let Some(record) = progress.structural_record.as_mut() {
                record.suppressed_since_unix_seconds = None;
                record.skipped_full_rearms = 0;
            }
        } else if first_proof_held {
            progress.first_proof_hold_since_full_rearm = true;
        }
        // Retire the completed window; a full re-arm records the next one's
        // origin now so a restart before its first start still means BASE.
        progress.full_rearm_window = next_window;
        duplicate_census.full_rearm = full_rearm;
        duplicate_census.rearm_attempt = index.claude_duplicate_fence_rearm_attempt;
        duplicate_census.full_rearm_deferred_until =
            index.claude_duplicate_fence_next_full_rearm_unix_seconds;
        disposition.full_rearm_suppression.full_rearm_suppressed = full_rearm_suppressed;
        disposition
            .full_rearm_suppression
            .full_rearm_post_rebuild_skipped = u64::from(post_rebuild_skipped);
        if let Some(record) = index
            .claude_full_rearm_progress
            .structural_record
            .as_ref()
            .filter(|record| record.skipped_full_rearms > 0)
        {
            let counts = &mut disposition.full_rearm_suppression;
            counts.full_rearm_skipped_invalid_unchanged = record.skipped_full_rearms;
            counts.structural_invalid_family_count = record.families.len();
            counts.suppressed_since_unix_seconds = record.suppressed_since_unix_seconds;
        }
        let invalidated_witness_roots = witness_roots_before
            .difference(
                &index
                    .claude_usage_family_witnesses
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>(),
            )
            .cloned()
            .collect::<BTreeSet<_>>();
        let current_ids = snapshots
            .iter()
            .map(|item| item.source_session_id.as_str())
            .collect::<BTreeSet<_>>();
        // Final proof and demotion state, not the preflight's possible owners.
        // Every other rearm disjunct below remains authoritative.
        let negative_keys =
            if !duplicate_census_invalid && !index.claude_duplicate_request_witness_overflowed {
                negatives
                    .as_ref()
                    .map(|view| view.keys(index, &demoting_members_by_root, &complete_families))
                    .unwrap_or_default()
            } else {
                BTreeSet::new()
            };
        // Contract-5 identity latch: after a contract change nothing skips.
        // A complete closed-fence terminal under the recorded contract
        // re-arms every family file, including members a skip left unread.
        // Only a settled terminal with no authority debt can also clear the
        // latch below; its independent corrective re-arm does not wait.
        let identity_contract = claude_request_identity::cycle_contract(identity.is_some());
        let identity_contract_recorded =
            index.claude_request_identity_contract.as_deref() == Some(identity_contract);
        let fence_stays_closed =
            overflowed_before && index.claude_duplicate_request_witness_overflowed;
        // Path-(a) bridge: RetryPending authority debt no longer marks the
        // sweep, so the latch also requires that no such debt remains.
        let sweep_fully_settled = !index.bounded_sweep_had_unsettled_upload
            && index.claude_usage_authority_pending_count() == 0;
        // E2's revision-3 adoption is the identity upgrade's ONE paced
        // pass. The contract latch must not clear fingerprints and arm a
        // second, unpaced full replay after that pass.
        let e2_identity_upgrade = claude_request_money::e2::enabled()
            && identity_contract == claude_request_identity::E2_GROUPING
            && index.active_effective_upload_body_witness_revision == 3;
        let e2_identity_owed = e2_identity_upgrade
            && index.files.iter().any(|(key, entry)| {
                claude_index_path_member_ref(Path::new(key)).is_some()
                    && entry.effective_upload_body_witness_revision < 3
                    && !index.claude_family_listed(key)
            });
        let identity_contract_rearm = latch_rearms
            && !e2_identity_upgrade
            && fence_stays_closed
            && census_complete
            && identity_contract_recorded;
        // Partial settlement keeps the latch below, but cannot suppress its
        // independent corrective re-arm while the liveness deadline waits.
        // Fence recovery: members an earlier skip left unread stay unobserved,
        // and their families' pending goes stale. When witnessed families
        // this window did not read, which the BASE re-arm would have re-read,
        // are all that keeps the fence closed, re-arm every family file once,
        // so the next census can observe all of them in one window.
        let fence_recovery_rearm = closed_only_by_witnessed_families && fence_stays_closed;
        // An unchanged settled proof owes no replay only while the fence was
        // closed before and stays closed after this census, nothing re-arms
        // every file, the identity contract is unchanged, the sweep settled,
        // and the accepted ledger is current and not being rebuilt. Authority
        // debt alone does not unsettle the sweep; `claude_unchanged_proof_roots`
        // still excludes every quarantined or demoting root.
        // Option A: when the sweep's only unsettled cause is scoped
        // `CompletedBlockingHolds`, only the held families lose the skip below;
        // they stay held, re-offered and unproven residue. Any other cause, or
        // a stamp that could not name its families, keeps the sweep-wide veto.
        let unsettled_families = index.unchanged_proof_unsettled_families();
        let unchanged_proof_gate = fence_stays_closed
            && !full_rearm
            && !latch_rearms
            && identity_contract_recorded
            && unsettled_families.is_some()
            && claude_accepted_ledger_is_current(index)
            && index.upload_context_fingerprint == index.active_upload_context_fingerprint;
        // A partially settled page earlier in this traversal (shed, lost ACK
        // or refused CAS) keeps the latch; so does a partial save of this one,
        // and so does any RetryPending authority family.
        if census_complete
            && (full_rearm
                || identity_contract_rearm
                || !latch_rearms
                || fence_recovery_rearm
                || (e2_identity_upgrade && !e2_identity_owed))
            && identity_contract_recorded
            && sweep_fully_settled
        {
            claude_contract::note(|counts| {
                counts.identity_contract_latch.cleared +=
                    u64::from(index.claude_request_identity_contract_changed)
            });
            index.claude_request_identity_contract_changed = false;
        }
        let mut unchanged_proof_roots = if unchanged_proof_gate && !proven.is_empty() {
            claude_unchanged_proof_roots(
                index,
                &proven,
                &complete_families,
                &witness_fingerprints_before,
                &demoting_members_by_root,
                &current_ids,
                census_window_end,
                &invalidated_witness_roots,
                (
                    &changed_duplicate_owners,
                    &changed_duplicate_request_hashes,
                    &duplicated_request_hashes,
                ),
                legacy_request_owners.as_ref(),
            )
        } else {
            None
        };
        if let (Some(roots), Some(held)) = (
            unchanged_proof_roots.as_mut(),
            unsettled_families.as_ref().filter(|held| !held.is_empty()),
        ) {
            let mut held_with_retained_witness = 0_usize;
            for (root_session_id, unchanged) in roots.iter_mut() {
                if held.contains(&claude_full_rearm_root_digest(root_session_id)) {
                    *unchanged = false;
                    held_with_retained_witness += 1;
                }
            }
            eprintln!(
                "local snapshot census kept the proof re-arm of {} held Claude family/families \
                 ({held_with_retained_witness} with a retained witness, none settled) as \
                 unsettled residue; other settled unchanged families keep their \
                 unchanged-proof skip",
                held.len()
            );
        }
        if let Some(first_proof_hold) = first_proof_hold {
            disposition.first_proof_hold = first_proof_hold;
        }
        let mut rearmed_bytes = 0_u64;
        let mut rearm = crate::local_resource_diagnostics::NativeRearm {
            negative_keys: negative_keys.len(),
            ..Default::default()
        };
        let mut preserved = 0;
        for (index_key, entry) in &mut index.files {
            let Some((root_session_id, source_session_id)) =
                claude_index_path_family_member(Path::new(index_key))
            else {
                continue;
            };
            let duplicate_owner =
                claude_duplicate_request_owner(&root_session_id, &source_session_id);
            // A fence that stays closed keeps no duplicate witness (it is
            // cleared above), so every duplicate this census detects compares
            // as changed against nothing, and re-arming its owners re-read
            // them on every complete walk. While the fence stays closed,
            // `unresolved_duplicate` keeps the strict duplicate-dependent
            // ownership outputs (posture and curve ownership) unresolved: a
            // strict ownership gate, not an upload hold. This guard changes
            // neither that gate nor any money or account gate. A real append
            // or edit still re-reads through its own changed size or
            // fingerprint, and the fence's liveness full re-arm re-reads every
            // family to reopen it, so only an open or opening fence re-arms
            // changed duplicate owners.
            let changed_duplicate_owner =
                !fence_stays_closed && changed_duplicate_owners.contains(&duplicate_owner);
            let current_member_owns_changed_request = !fence_stays_closed
                && index
                    .claude_usage_family_pending
                    .get(&root_session_id)
                    .and_then(|pending| pending.member_request_id_hashes.get(&source_session_id))
                    .is_some_and(|request_hashes| {
                        !request_hashes.is_disjoint(&changed_duplicate_request_hashes)
                    });
            let proof_candidate = proven.contains_key(&root_session_id)
                && !current_ids.contains(source_session_id.as_str());
            let negative = negative_keys.contains(index_key.as_str());
            let settled_unchanged_proof = proof_candidate
                && unchanged_proof_roots
                    .as_ref()
                    .is_some_and(|roots| roots.get(root_session_id.as_str()) == Some(&true));
            let other_rearm = full_rearm
                || identity_contract_rearm
                || fence_recovery_rearm
                || invalidated_witness_roots.contains(&root_session_id)
                || changed_duplicate_owner
                || current_member_owns_changed_request;
            rearm.proof_candidates = rearm
                .proof_candidates
                .saturating_add(usize::from(proof_candidate));
            rearm.other_rearm_matches = rearm
                .other_rearm_matches
                .saturating_add(usize::from(other_rearm));
            let rearmed = full_rearm
                || identity_contract_rearm
                || fence_recovery_rearm
                || {
                    let proof_rearm = proof_candidate && !negative && !settled_unchanged_proof;
                    #[cfg(test)]
                    {
                        proof_rearm
                            && !envelope_selection_experiment::suppress_certified_negative_rearm(
                                &root_session_id,
                                index_key,
                            )
                    }
                    #[cfg(not(test))]
                    {
                        proof_rearm
                    }
                }
                || invalidated_witness_roots.contains(&root_session_id)
                || changed_duplicate_owner
                || current_member_owns_changed_request;
            if rearmed {
                // Reparse earlier-page members of every proven family unless
                // its proof is unchanged and settled behind a fence that was
                // closed before and stays closed: a first or changed proof, an
                // open or moving fence, a quarantined, demoted, held,
                // legacy-linked, duplicate-touching or unaccepted family, and
                // any family with a member on this page or re-armed by another
                // rule all re-arm. A contract-5 change re-arms every family
                // file once, and so do members left unread by an earlier skip
                // when they alone keep the fence closed. Also reparse
                // when a later page reveals a cross-family request duplicate.
                // Changed hash-only witnesses re-arm every affected owner
                // once; stable duplicates remain fail-closed without an
                // unbounded corrective replay loop.
                rearm.clear_calls = rearm.clear_calls.saturating_add(1);
                entry.source_file_fingerprint.clear();
                rearmed_bytes = rearmed_bytes.saturating_add(entry.size_bytes);
            } else if proof_candidate && negative {
                rearm.suppressed = rearm.suppressed.saturating_add(1);
            }
            preserved += u64::from(!rearmed && !entry.source_file_fingerprint.is_empty());
        }
        crate::local_resource_diagnostics::claude_reread::terminal_rearm(
            if full_rearm_suppressed || post_rebuild_skipped {
                index.claude_full_rearm_progress.ignored_vetoes
            } else {
                0
            },
            preserved,
            full_rearm_due && stays_closed && native_duplicate_veto,
        );
        // Spent only where the latch's re-arm causes ran (a closed fence).
        if cutover_terminal && fence_stays_closed {
            index.claude_full_rearm_progress.contract_cutover = CLAUDE_CONTRACT_CUTOVER_SPENT;
            claude_contract::note(|counts| {
                let cutover = &mut counts.contract_cutover_rearm;
                cutover.runs += 1;
                cutover.files += rearm.clear_calls as u64;
                cutover.bytes = cutover.bytes.saturating_add(rearmed_bytes);
            });
        }
        if let Some(diagnostic) = diagnostic {
            diagnostic.update(|d| d.terminal_rearm = Some(rearm));
        }

        index
            .claude_usage_family_pending
            .retain(|root_session_id, _| {
                index
                    .claude_usage_authority_quarantine
                    .contains_key(root_session_id)
            });
        let progress = &mut index.claude_full_rearm_progress;
        progress.observed_window = None;
        progress.ignored_vetoes = 0;
        progress.structural_roots.clear();
        progress.other_invalidation_observed = false;
    }

    if census_complete && reports_healthy {
        index.retire_absent_claude_proof_corrections(&complete_families);
    }

    // E2 (gate on): a request-owned body settles its family's authority like
    // a reported one (it is not a demotion, above), so a legacy record or
    // tombstone clears on the family's first E2 page, never staying red.
    let current_authority_by_root = snapshots.iter().fold(
        BTreeMap::<String, BTreeMap<String, bool>>::new(),
        |mut by_root, item| {
            by_root
                .entry(claude_snapshot_family_root(item))
                .or_default()
                .insert(
                    item.source_session_id.clone(),
                    item.usage_accounting_contract.as_deref()
                        == Some("session_exclusive_reported_usage:v1")
                        || (claude_request_money::e2::enabled() && item.claude_money.is_some()),
                );
            by_root
        },
    );
    let resolved_quarantines = index
        .claude_usage_authority_quarantine
        .keys()
        .filter(|root_session_id| {
            if demoting_members_by_root.contains_key(*root_session_id) {
                return false;
            }
            // A returning member of a tombstoned family is unindexed while it
            // is held, so the complete census never lists its family. Its
            // record stays until the member re-proves or the family is
            // retired again as absent (Round 12).
            let returning = index.claude_root_tombstoned(root_session_id);
            // Preserve the existing whole-family disappearance rule even
            // when provider reports are unavailable. Its witness was pruned
            // by the same complete filesystem census above.
            if census_complete && !complete_families.contains_key(*root_session_id) && !returning {
                return true;
            }
            // Only exact durable body settlement may drain a correction grant.
            if index
                .claude_usage_authority_quarantine
                .get(*root_session_id)
                .is_some_and(|record| record.proof_correction.is_some())
            {
                return false;
            }
            let expected_members =
                if let Some(complete_members) = complete_families.get(*root_session_id) {
                    complete_members.clone()
                } else if !census_complete || returning {
                    let Some(witness) = index.claude_usage_family_witnesses.get(*root_session_id)
                    else {
                        return false;
                    };
                    witness
                        .member_request_id_fingerprints
                        .keys()
                        .cloned()
                        .collect::<BTreeSet<_>>()
                } else {
                    // Only a complete census proves that the old family vanished.
                    return true;
                };
            let empty_members = confirmed_empty_claude_family_members(index, root_session_id);
            let current = current_authority_by_root
                .get(*root_session_id)
                .cloned()
                .unwrap_or_default();
            expected_members.iter().all(|member| {
                empty_members.contains(member) || current.get(member).copied() == Some(true)
            })
        })
        .cloned()
        .collect::<BTreeSet<_>>();
    for root_session_id in resolved_quarantines {
        index
            .claude_usage_authority_quarantine
            .remove(&root_session_id);
        index.claude_usage_family_pending.remove(&root_session_id);
    }
    // SOURCE/COST/SI Round 12: a returning family's tombstone clears once its
    // proof settles, on the page whose members all carry the reported-usage
    // contract with no authority record left. Its bodies commit with this
    // page. Never earlier: a returning member is indexed on the page that
    // reads it, before this fold demotes it and re-forms its record.
    if !index.claude_retired_family_tombstones.is_empty() {
        let mut cleared = 0_u64;
        for (root_session_id, members) in &current_authority_by_root {
            if members.values().all(|reported| *reported)
                && !index
                    .claude_usage_authority_quarantine
                    .contains_key(root_session_id)
                && index
                    .claude_retired_family_tombstones
                    .remove(&claude_retired_family_digest(root_session_id))
                    .is_some()
            {
                cleared += 1;
            }
        }
        if cleared > 0 {
            with_claude_absence_counters(|counters| {
                counters.tombstones_cleared = counters.tombstones_cleared.saturating_add(cleared);
            });
        }
    }
    duplicate_census.fence_after = index.claude_duplicate_request_witness_overflowed;
    disposition.duplicate_census = duplicate_census;
    #[cfg(test)]
    CLAUDE_FIRST_PROOF_HOLD_FOR_TEST.with(|cell| cell.set(disposition.first_proof_hold));
    disposition
}

/// Whether pending from an older census window keeps this census invalid.
fn claude_stale_pending_keeps_census_invalid(
    index: &ScanIndex,
    root_session_id: &str,
    pending: &ClaudeUsageFamilyPending,
    census_complete: bool,
    indexed_claude_family_ids: &BTreeSet<String>,
) -> bool {
    // Only a complete census proves that a family vanished. Old pending whose
    // root and members have no indexed file left cannot hide a current
    // request; any remaining file keeps it fail closed below.
    if census_complete
        && !indexed_claude_family_ids.contains(root_session_id)
        && pending
            .member_request_id_hashes
            .keys()
            .chain(pending.member_occurrences.keys())
            .all(|member| !indexed_claude_family_ids.contains(member))
    {
        return false;
    }
    // A demoted family retains its prior pending proof while bounded
    // quarantine retries reconstruct the durable witness. That old window is
    // not part of this census and must not globally poison unrelated Claude
    // posture. Ignore it only while the quarantine is well formed and bound to
    // the exact retained witness; every other stale or invalid pending shape
    // remains fail closed.
    !index
        .claude_usage_authority_quarantine
        .get(root_session_id)
        .zip(index.claude_usage_family_witnesses.get(root_session_id))
        .is_some_and(|(quarantine, witness)| {
            claude_usage_authority_preserves_pending(quarantine, witness)
        })
}

fn accumulate_claude_usage_family_pending_with_limit(
    snapshots: &[SnapshotItem],
    pending_by_root: &mut BTreeMap<String, ClaudeUsageFamilyPending>,
    census_window_end: &str,
    max_occurrences: usize,
) -> ClaudeDuplicateCensusCounts {
    accumulate_claude_usage_family_pending_with_credit(
        snapshots,
        pending_by_root,
        census_window_end,
        max_occurrences,
        None,
    )
    .expect("ordinary observation accumulation has no optional credit")
}

fn accumulate_claude_usage_family_pending_with_credit(
    snapshots: &[SnapshotItem],
    pending_by_root: &mut BTreeMap<String, ClaudeUsageFamilyPending>,
    census_window_end: &str,
    max_occurrences: usize,
    mut credit: Option<&mut claude_native_comparison::NativeBodyBudget<'_>>,
) -> Result<ClaudeDuplicateCensusCounts, crate::source_rotation::LocalRefusal> {
    let mut counts = ClaudeDuplicateCensusCounts::default();
    let mut retained_occurrence_count = pending_by_root
        .values()
        .flat_map(|pending| pending.member_occurrences.values())
        .map(BTreeMap::len)
        .fold(0_usize, usize::saturating_add);
    for item in snapshots {
        let construction = match credit.as_deref_mut() {
            Some(credit) => {
                credit.before_native_observation(item, pending_by_root, census_window_end)?
            }
            None => None,
        };
        (|| {
            let root_session_id = claude_snapshot_family_root(item);
            let prior_family_occurrence_count = pending_by_root
                .get(&root_session_id)
                .map(|pending| {
                    pending
                        .member_occurrences
                        .values()
                        .map(BTreeMap::len)
                        .fold(0_usize, usize::saturating_add)
                })
                .unwrap_or_default();
            let pending = pending_by_root.entry(root_session_id).or_insert_with(|| {
                ClaudeUsageFamilyPending {
                    census_window_end: census_window_end.to_string(),
                    member_request_id_hashes: BTreeMap::new(),
                    member_occurrences: BTreeMap::new(),
                    invalid: false,
                    idless_revision: None,
                }
            });
            if pending.census_window_end != census_window_end {
                retained_occurrence_count =
                    retained_occurrence_count.saturating_sub(prior_family_occurrence_count);
                *pending = ClaudeUsageFamilyPending {
                    census_window_end: census_window_end.to_string(),
                    member_request_id_hashes: BTreeMap::new(),
                    member_occurrences: BTreeMap::new(),
                    invalid: false,
                    idless_revision: None,
                };
            }
            let idless_revision = (item.source_session_id == claude_snapshot_family_root_ref(item)
                && item.request_count > 0
                && item.claude_usage_request_ids.is_empty()
                && item.claude_usage_occurrences.is_empty()
                && item.claude_context_curve_request_index_complete)
                .then(|| {
                    item.source_file_fingerprint
                        .as_deref()
                        .map(claude_idless_revision)
                })
                .flatten();
            if pending.invalid {
                // Invalid evidence normally stops accumulation. Preserve the
                // exception only for the identical singleton observation;
                // another member/revision or another cause revokes it.
                if pending.idless_revision != idless_revision || idless_revision.is_none() {
                    pending.idless_revision = None;
                }
                return;
            }
            let Some(hashes) = claude_snapshot_request_id_hashes(item).filter(|_| {
                item.claude_usage_occurrences.len() == item.claude_usage_request_ids.len()
            }) else {
                counts.page_invalidated_identity_count =
                    counts.page_invalidated_identity_count.saturating_add(1);
                let only_idless = pending.member_request_id_hashes.is_empty()
                    && pending.member_occurrences.is_empty();
                invalidate_claude_usage_family_pending(pending, &mut retained_occurrence_count);
                if only_idless {
                    pending.idless_revision = idless_revision;
                }
                return;
            };
            let occurrences = item
                .claude_usage_occurrences
                .iter()
                .map(|(request_id, occurrence)| {
                    (
                        format!("{:x}", Sha256::digest(request_id.as_bytes())),
                        ClaudeTranscriptUsageOccurrenceWitness::from(occurrence),
                    )
                })
                .collect::<BTreeMap<_, _>>();
            if occurrences.keys().cloned().collect::<BTreeSet<_>>() != hashes {
                counts.page_invalidated_occurrence_mismatch_count = counts
                    .page_invalidated_occurrence_mismatch_count
                    .saturating_add(1);
                invalidate_claude_usage_family_pending(pending, &mut retained_occurrence_count);
                return;
            }
            let replaced_occurrence_count = pending
                .member_occurrences
                .get(&item.source_session_id)
                .map(BTreeMap::len)
                .unwrap_or_default();
            let Some(next_retained_occurrence_count) =
                claude_pending_occurrence_count_after_replace(
                    retained_occurrence_count,
                    replaced_occurrence_count,
                    occurrences.len(),
                    max_occurrences,
                )
            else {
                counts.page_invalidated_cap_count =
                    counts.page_invalidated_cap_count.saturating_add(1);
                invalidate_claude_usage_family_pending(pending, &mut retained_occurrence_count);
                return;
            };
            if pending
                .member_request_id_hashes
                .insert(item.source_session_id.clone(), hashes.clone())
                .is_some_and(|previous| previous != hashes)
            {
                counts.page_invalidated_member_changed_count = counts
                    .page_invalidated_member_changed_count
                    .saturating_add(1);
                invalidate_claude_usage_family_pending(pending, &mut retained_occurrence_count);
                return;
            }
            if pending
                .member_occurrences
                .insert(item.source_session_id.clone(), occurrences.clone())
                .is_some_and(|previous| previous != occurrences)
            {
                counts.page_invalidated_member_changed_count = counts
                    .page_invalidated_member_changed_count
                    .saturating_add(1);
                invalidate_claude_usage_family_pending(pending, &mut retained_occurrence_count);
                return;
            }
            retained_occurrence_count = next_retained_occurrence_count;
        })();
        if let Some(construction) = construction {
            construction.finish()?;
        }
    }
    counts.pending_occurrence_count = retained_occurrence_count;
    Ok(counts)
}

fn invalidate_claude_usage_family_pending(
    pending: &mut ClaudeUsageFamilyPending,
    retained_occurrence_count: &mut usize,
) {
    *retained_occurrence_count = retained_occurrence_count.saturating_sub(
        pending
            .member_occurrences
            .values()
            .map(BTreeMap::len)
            .fold(0_usize, usize::saturating_add),
    );
    pending.member_request_id_hashes.clear();
    pending.member_occurrences.clear();
    pending.invalid = true;
    pending.idless_revision = None;
}

fn claude_pending_occurrence_count_after_replace(
    retained: usize,
    replaced: usize,
    incoming: usize,
    max_occurrences: usize,
) -> Option<usize> {
    let next = retained.saturating_sub(replaced).saturating_add(incoming);
    (next <= max_occurrences).then_some(next)
}

/// Indexed Claude family members a terminal pass did not observe in this exact
/// census window. Pending is reset whenever its window changes, so a
/// current-window, non-invalid member entry exists only if that member was
/// parsed in this window. Confirmed-empty files carry no request, and members
/// of a root held by a bound quarantine are excluded exactly as
/// `duplicate_census_invalid` excludes that root's retained pending.
fn claude_duplicate_fence_coverage_missing_member_count(
    index: &ScanIndex,
    census_window_end: &str,
) -> usize {
    claude_family_members_unobserved_count(index, census_window_end, true)
}

/// Indexed Claude family members whose current requests this census window did
/// not observe. Confirmed-empty files hold none. The fence also excuses a
/// family held by a bound authority quarantine (`quarantine_excused`), whose
/// retained pending the census excludes; transcript ownership does not.
fn claude_family_members_unobserved_count(
    index: &ScanIndex,
    census_window_end: &str,
    quarantine_excused: bool,
) -> usize {
    claude_family_members_unobserved_where(index, census_window_end, quarantine_excused, |_| false)
}

/// `claude_family_members_unobserved_count`, also excusing members of the
/// roots `excused_root` names.
fn claude_family_members_unobserved_where(
    index: &ScanIndex,
    census_window_end: &str,
    quarantine_excused: bool,
    excused_root: impl Fn(&str) -> bool,
) -> usize {
    let covered = index
        .claude_usage_family_pending
        .values()
        .filter(|pending| !pending.invalid && pending.census_window_end == census_window_end)
        .flat_map(|pending| {
            pending
                .member_request_id_hashes
                .keys()
                .filter(move |member| pending.member_occurrences.contains_key(*member))
        })
        .collect::<BTreeSet<_>>();
    index
        .files
        .keys()
        .filter(|index_key| {
            let Some((root_session_id, member)) =
                claude_index_path_family_member(Path::new(index_key.as_str()))
            else {
                return false;
            };
            !(covered.contains(&member)
                || index.confirmed_empty_files.contains(*index_key)
                || excused_root(&root_session_id)
                || (quarantine_excused
                    && index
                        .claude_usage_authority_quarantine
                        .get(&root_session_id)
                        .zip(index.claude_usage_family_witnesses.get(&root_session_id))
                        .is_some_and(|(quarantine, witness)| {
                            claude_usage_authority_preserves_pending(quarantine, witness)
                        })))
        })
        .count()
}

/// Fix 1 at a complete terminal (full-rearm investigation, SI and COST
/// rulings 2026-10-23). Returns whether this terminal's due full re-arm is
/// skipped because it cannot open the fence, and maintains the structural
/// record. Cost only: the fence decision above is final, this changes only
/// whether every family file is re-read.
///
/// The census must stay closed (closed before and after) for no reason but
/// structurally invalid families: no other invalidation in this window, no
/// owner-bound overflow, no stale pending that keeps the census invalid, and
/// every current-window invalid family with a structural member. A window
/// that observed every indexed member except those of its structural
/// families records them, digested with their members' fingerprints. A due
/// re-arm is skipped only when that record exists under the same basis (D1
/// derivation, scan identity, record version, identity contract), the
/// recorded contract is this cycle's, every recorded family is still indexed
/// with unchanged member fingerprints, and no other structural family
/// appeared. The basis names the contract, so a real contract change
/// re-arms once and records the new baseline; the contract-5 latch alone
/// never repeats a due re-arm (its re-read is the identity contract re-arm
/// or E2's paced debt), and a mid-traversal placeholder matches no contract.
/// Then re-reading every file reproduces each recorded family's invalidity,
/// so the next census is invalid again and the fence cannot open. Any change
/// re-arms once; that window records the new set. A census closed only by
/// coverage in an incremental window is held closed by the same unchanged
/// families, so it is skipped too.
#[allow(clippy::too_many_arguments)]
fn claude_full_rearm_structural_terminal(
    index: &mut ScanIndex,
    census_window_end: &str,
    indexed_claude_family_ids: &BTreeSet<String>,
    owners_within_bound: bool,
    fence_stays_closed: bool,
    full_rearm_due: bool,
    first_proof_veto: bool,
    census_unix_seconds: Option<u64>,
    identity_contract: &str,
) -> bool {
    if !fence_stays_closed {
        return false;
    }
    let progress = &index.claude_full_rearm_progress;
    let observed = progress.observed_window.as_deref() == Some(census_window_end);
    let mut current = BTreeSet::new();
    let mut other = (observed && progress.other_invalidation_observed) || !owners_within_bound;
    for (root_session_id, pending) in &index.claude_usage_family_pending {
        if other {
            break;
        }
        if pending.census_window_end == census_window_end {
            if pending.invalid {
                let root_digest = claude_full_rearm_root_digest(root_session_id);
                if observed && progress.structural_roots.contains(&root_digest) {
                    current.insert(root_digest);
                } else {
                    other = true;
                }
            }
        } else if claude_stale_pending_keeps_census_invalid(
            index,
            root_session_id,
            pending,
            true,
            indexed_claude_family_ids,
        ) {
            other = true;
        }
    }
    if other {
        return false;
    }
    let basis = claude_full_rearm_record_basis(identity_contract);
    let contract_current =
        index.claude_request_identity_contract.as_deref() == Some(identity_contract);
    let mut roots = current.clone();
    if let Some(record) = progress.structural_record.as_ref() {
        roots.extend(record.families.keys().cloned());
    }
    let digests = claude_full_rearm_member_digests(index, &roots);
    // Coverage-only skips must explain every omission by a recorded
    // structural family; a bound quarantine is not own-byte evidence.
    let coverage_explained =
        claude_family_members_unobserved_where(index, census_window_end, false, |root| {
            roots.contains(&claude_full_rearm_root_digest(root))
        }) == 0;
    let observed_every_other_member = !current.is_empty()
        && claude_family_members_unobserved_where(index, census_window_end, false, |root| {
            current.contains(&claude_full_rearm_root_digest(root))
        }) == 0;
    let observed_families = observed_every_other_member
        .then(|| {
            current
                .iter()
                .map(|root| Some((root.clone(), digests.get(root)?.clone()?)))
                .collect::<Option<BTreeMap<_, _>>>()
        })
        .flatten();
    let baseline_matches = progress.structural_record.as_ref().is_some_and(|record| {
        record.basis == basis
            && !record.families.is_empty()
            && record.families.iter().all(|(root, member_digest)| {
                digests.get(root).and_then(Option::as_ref) == Some(member_digest)
            })
            && current
                .iter()
                .all(|root| record.families.contains_key(root))
            && observed_families
                .as_ref()
                .map_or(true, |families| families == &record.families)
    });
    let suppressed = full_rearm_due
        && !first_proof_veto
        && contract_current
        && coverage_explained
        && baseline_matches
        && !progress.structural_rearm_owed;
    let progress = &mut index.claude_full_rearm_progress;
    progress.structural_rearm_owed |= !baseline_matches;
    // Observations may dirty a baseline at any terminal, but only a real
    // due whole-index re-arm can promote the candidate and settle the debt.
    if let Some(families) =
        observed_families.filter(|_| contract_current && full_rearm_due && !suppressed)
    {
        let same = progress
            .structural_record
            .as_ref()
            .is_some_and(|record| record.basis == basis && record.families == families);
        if !same {
            progress.structural_record = Some(ClaudeStructuralInvalidRecord {
                basis,
                families,
                suppressed_since_unix_seconds: None,
                skipped_full_rearms: 0,
            });
        }
        progress.structural_rearm_owed = false;
    }
    if suppressed {
        if let Some(record) = progress.structural_record.as_mut() {
            record.skipped_full_rearms = record.skipped_full_rearms.saturating_add(1);
            record.suppressed_since_unix_seconds =
                record.suppressed_since_unix_seconds.or(census_unix_seconds);
        }
    }
    suppressed
}

/// Whether a terminal pass clears every Claude source fingerprint. Opening the
/// fence re-emits posture once. A newly closed fence replays at once; a fence
/// that stays closed replays again only once its backoff deadline passes. A
/// missing, unreadable, or implausibly distant deadline is due, so losing the
/// scheduling fields costs one replay and never opens the fence.
fn claude_duplicate_fence_full_rearm_due(
    index: &ScanIndex,
    overflowed_before: bool,
    overflowed_after: bool,
    census_unix_seconds: Option<u64>,
) -> bool {
    if !overflowed_after {
        return overflowed_before;
    }
    if !overflowed_before {
        return true;
    }
    match (
        census_unix_seconds,
        index.claude_duplicate_fence_next_full_rearm_unix_seconds,
    ) {
        (Some(now), Some(next)) => {
            now >= next || next > now.saturating_add(CLAUDE_DUPLICATE_FENCE_REARM_MAX_SECONDS)
        }
        _ => true,
    }
}

fn claude_duplicate_fence_rearm_delay_seconds(attempt: u8) -> u64 {
    CLAUDE_DUPLICATE_FENCE_REARM_BASE_SECONDS
        .saturating_mul(1_u64 << u32::from(attempt.min(16)))
        .min(CLAUDE_DUPLICATE_FENCE_REARM_MAX_SECONDS)
}

/// Content-free count of complete terminals that kept every proof re-arm
/// because the unchanged-proof check was not admitted under its scratch budget.
static CLAUDE_UNCHANGED_PROOF_BUDGET_FALLBACKS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

#[cfg(test)]
thread_local! {
    static REFUSE_CLAUDE_UNCHANGED_PROOF_BUDGET_FOR_TEST: std::cell::Cell<bool> =
        const { std::cell::Cell::new(false) };
    static CLAUDE_UNCHANGED_PROOF_BUDGET_FALLBACKS_FOR_TEST: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

/// While alive, this thread refuses the unchanged-proof scratch budget, so
/// every complete terminal takes the BASE proof re-arm.
#[cfg(test)]
pub(crate) struct RefuseClaudeUnchangedProofBudgetForTest(bool);

#[cfg(test)]
impl RefuseClaudeUnchangedProofBudgetForTest {
    pub(crate) fn new() -> Self {
        Self(REFUSE_CLAUDE_UNCHANGED_PROOF_BUDGET_FOR_TEST.with(|cell| cell.replace(true)))
    }
}

#[cfg(test)]
impl Drop for RefuseClaudeUnchangedProofBudgetForTest {
    fn drop(&mut self) {
        REFUSE_CLAUDE_UNCHANGED_PROOF_BUDGET_FOR_TEST.with(|cell| cell.set(self.0));
    }
}

#[cfg(test)]
pub(crate) fn claude_unchanged_proof_budget_fallbacks_for_test() -> usize {
    CLAUDE_UNCHANGED_PROOF_BUDGET_FALLBACKS_FOR_TEST.with(std::cell::Cell::get)
}

/// Price the unchanged-proof scratch before allocating it, against the
/// existing parked overlap budget and with the same full-node pricing as the
/// reported-usage construction peak. The family map borrows its keys from the
/// terminal's proven families, and the prefix set borrows hashes from retained
/// witnesses. An unsupported layout or a refused price keeps BASE.
fn claude_unchanged_proof_scratch_admitted(families: usize, legacy_prefix_hashes: usize) -> bool {
    #[cfg(test)]
    if REFUSE_CLAUDE_UNCHANGED_PROOF_BUDGET_FOR_TEST.with(std::cell::Cell::get) {
        return false;
    }
    if !crate::heap_layout_bound::layout_supported() {
        return false;
    }
    let mut cost = crate::heap_layout_bound::Counter::new(crate::source_rotation::PARKED_BUDGET);
    crate::heap_layout_bound::tree_nodes::<&str, bool>(families, &mut cost).is_some()
        && crate::heap_layout_bound::tree_nodes::<&str, ()>(legacy_prefix_hashes, &mut cost)
            .is_some()
}

#[cfg(test)]
thread_local! {
    static REFUSE_CLAUDE_ABSENT_FAMILY_SCRATCH_FOR_TEST: std::cell::Cell<bool> =
        const { std::cell::Cell::new(false) };
}

/// While alive, this thread refuses the absent-family retirement scratch, so
/// a raw-complete census retires no RetryPending family.
#[cfg(test)]
pub(crate) struct RefuseClaudeAbsentFamilyScratchForTest(bool);

#[cfg(test)]
impl RefuseClaudeAbsentFamilyScratchForTest {
    pub(crate) fn new() -> Self {
        Self(REFUSE_CLAUDE_ABSENT_FAMILY_SCRATCH_FOR_TEST.with(|cell| cell.replace(true)))
    }
}

#[cfg(test)]
impl Drop for RefuseClaudeAbsentFamilyScratchForTest {
    fn drop(&mut self) {
        REFUSE_CLAUDE_ABSENT_FAMILY_SCRATCH_FOR_TEST.with(|cell| cell.set(self.0));
    }
}

/// Price the absent-family retirement scratch (one borrowed root per
/// RetryPending record) against the existing parked overlap budget, with the
/// same full-node pricing as the unchanged-proof scratch. An unsupported
/// layout or a refused price retires nothing.
fn claude_absent_family_scratch_admitted(retry_pending_roots: usize) -> bool {
    #[cfg(test)]
    if REFUSE_CLAUDE_ABSENT_FAMILY_SCRATCH_FOR_TEST.with(std::cell::Cell::get) {
        return false;
    }
    if !crate::heap_layout_bound::layout_supported() {
        return false;
    }
    let mut cost = crate::heap_layout_bound::Counter::new(crate::source_rotation::PARKED_BUDGET);
    crate::heap_layout_bound::tree_nodes::<&str, ()>(retry_pending_roots, &mut cost).is_some()
}

/// Most RetryPending roots one raw-complete Claude census checks on the
/// allocation-free absent-family fallback, used whenever the fast path's
/// scratch is not admitted (an unsupported heap layout, which also disables
/// native comparison, or a price over the parked budget). Retirement is a
/// liveness repair, so it cannot depend on that optional fast path alone.
/// With P RetryPending roots in one index, every root is checked within
/// ceil(P / 16) raw-complete censuses of that index, assuming its RetryPending
/// population changes only by these retirements, the process does not
/// restart, and at most `MAX_CLAUDE_ABSENT_FAMILY_FALLBACK_CURSORS` indexes
/// alternate in the process.
const MAX_CLAUDE_ABSENT_FAMILY_FALLBACK_ROOTS: usize = 16;

/// Most indexes whose fallback cursors one process keeps, comfortably above
/// the sources times upload destinations a daemon scans.
const MAX_CLAUDE_ABSENT_FAMILY_FALLBACK_CURSORS: usize = 32;

/// Runtime-only resume positions of the fallback, one per index. Each cursor
/// is the ordinal, in root order among that index's RetryPending records, at
/// which its next raw-complete census starts checking. The cursors are never
/// persisted or serialized and live in no index field: a restart starts every
/// index again at its first root, and progress resumes from there. An
/// ordinal rather than a root key keeps a cursor free of any owned copy; the
/// only owned allocation is the index's scope key, once per new index.
///
/// Cursors are scoped per index because indexes order different root sets:
/// one shared position alternating between two indexes can keep handing each
/// the same half of its roots forever. At the cap, a new index evicts the
/// least recently used cursor (that index restarts at its first root), so
/// coverage is guaranteed while at most the cap of indexes alternate.
struct ClaudeAbsentFamilyFallbackCursors {
    /// Index scope key to (cursor, last-use tick).
    by_index: BTreeMap<String, (usize, u64)>,
    tick: u64,
}

impl ClaudeAbsentFamilyFallbackCursors {
    const fn new() -> Self {
        Self {
            by_index: BTreeMap::new(),
            tick: 0,
        }
    }

    fn next_tick(&mut self) -> u64 {
        self.tick = self.tick.saturating_add(1);
        self.tick
    }

    fn cursor(&mut self, scope: &str) -> usize {
        let tick = self.next_tick();
        self.by_index.get_mut(scope).map_or(0, |(cursor, used)| {
            *used = tick;
            *cursor
        })
    }

    fn set(&mut self, scope: &str, cursor: usize) {
        let tick = self.next_tick();
        if let Some(entry) = self.by_index.get_mut(scope) {
            *entry = (cursor, tick);
            return;
        }
        if self.by_index.len() >= MAX_CLAUDE_ABSENT_FAMILY_FALLBACK_CURSORS {
            // Ticks are unique, so this evicts exactly the least recently
            // used cursor without copying its key.
            if let Some(oldest) = self.by_index.values().map(|(_, used)| *used).min() {
                self.by_index.retain(|_, (_, used)| *used != oldest);
            }
        }
        self.by_index.insert(scope.to_owned(), (cursor, tick));
    }
}

#[cfg(not(test))]
