#[allow(clippy::too_many_arguments)]
fn scan_source_roots_with_limit_and_attribution(
    source: SnapshotSource,
    roots: &[PathBuf],
    index: &mut ScanIndex,
    collected_at: &str,
    requested_backfill_window_days: u64,
    file_limit: usize,
    artifacts_enabled: bool,
    attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
    claude_effort_support_dir: Option<&Path>,
    hinted_paths: &[PathBuf],
    watcher_overflowed: bool,
) -> Result<SourceScanResult> {
    scan_source_roots_with_limit_and_attribution_and_curve(
        source,
        roots,
        index,
        collected_at,
        requested_backfill_window_days,
        file_limit,
        artifacts_enabled,
        attribution_context,
        claude_effort_support_dir,
        hinted_paths,
        watcher_overflowed,
        true,
    )
}

#[allow(clippy::too_many_arguments)]
fn scan_source_roots_with_limit_and_attribution_and_curve(
    source: SnapshotSource,
    roots: &[PathBuf],
    index: &mut ScanIndex,
    collected_at: &str,
    requested_backfill_window_days: u64,
    file_limit: usize,
    artifacts_enabled: bool,
    attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
    claude_effort_support_dir: Option<&Path>,
    hinted_paths: &[PathBuf],
    watcher_overflowed: bool,
    context_curve_enabled: bool,
) -> Result<SourceScanResult> {
    let mut state = OwnedSourceScan::new(
        source,
        roots,
        std::mem::take(index),
        collected_at,
        requested_backfill_window_days,
        file_limit,
        artifacts_enabled,
        claude_effort_support_dir,
        hinted_paths,
        watcher_overflowed,
        context_curve_enabled,
    );
    loop {
        match state.step(attribution_context) {
            OwnedSourceScanStep::Pending(next) => state = next,
            OwnedSourceScanStep::Complete {
                index: complete_index,
                scan,
                ..
            } => {
                *index = complete_index;
                return Ok(scan);
            }
        }
    }
}

fn prepare_owned_scan_candidate(
    source: SnapshotSource,
    candidate: &mut CandidateFile,
    codex_title_metadata: &CodexTitleMetadata,
    claude_title_metadata: &ClaudeTitleMetadata,
    claude_effort_support_dir: Option<&Path>,
) {
    // Sidecar contribution is path-derived and can be computed before the
    // transcript opens. Transcript identity itself is filled from the
    // exact opened object below, never from discovery metadata.
    let legacy_sidecar_fingerprint = match source {
        SnapshotSource::Codex => codex_title_metadata.legacy_sidecar_fingerprint.as_str(),
        SnapshotSource::ClaudeCode => claude_title_metadata.legacy_sidecar_fingerprint.as_str(),
        SnapshotSource::Pi => "",
    };
    candidate.legacy_source_file_fingerprint = source_file_fingerprint_with_context(
        &candidate.path,
        candidate.size_bytes,
        candidate.modified_unix_seconds,
        source.parser_version(),
        legacy_sidecar_fingerprint,
    );
    candidate.legacy_config_reconciliation_required =
        source == SnapshotSource::Codex && codex_title_metadata.legacy_config_file_present;
    let sidecar_fingerprint = match source {
        SnapshotSource::Codex => codex_title_metadata.path_sidecar_fingerprint(&candidate.path),
        SnapshotSource::ClaudeCode => {
            // A subagent transcript at any depth under `subagents/` has no
            // desktop-store entry of its own: its file stem is an agent id,
            // never a session id, so looking one up would either miss or
            // (worse) collide with an unrelated session. Its NAMING
            // material lives elsewhere — the `meta.json` sidecar and the
            // Workflow run manifest — so those feed the scan fingerprint
            // instead: a label arriving AFTER the transcript was indexed
            // must still re-select the unchanged transcript for a title re-emit
            // (same late-sidecar rationale as claude_code v14).
            if let Some(identity) = claude_subagent_identity(&candidate.path) {
                claude_subagent_sidecar_fingerprint(
                    &candidate.path,
                    &identity,
                    claude_effort_support_dir,
                )
            } else {
                candidate
                    .path
                    .file_stem()
                    .and_then(|value| value.to_str())
                    .map(|session_id| {
                        let desktop_fingerprint =
                            claude_title_metadata.session_sidecar_fingerprint(session_id);
                        let effort_fingerprint = claude_effort_support_dir
                            .map(|support_dir| {
                                claude_usage_sidecars_fingerprint(support_dir, session_id)
                            })
                            .unwrap_or_default();
                        if effort_fingerprint.is_empty() {
                            desktop_fingerprint
                        } else {
                            sha256_hex(&[
                                // v2 re-selects roots alongside children
                                // once when family account attribution is
                                // introduced. Without the version change an
                                // already-complete sidecar would only move
                                // the child fingerprint on upgrade.
                                "claude_session_sidecars:v2",
                                desktop_fingerprint.as_str(),
                                effort_fingerprint.as_str(),
                            ])
                        }
                    })
                    .unwrap_or_default()
            }
        }
        SnapshotSource::Pi => String::new(),
    };
    // Temporarily retain the sidecar digest in the source fingerprint slot;
    // the exact opened-object fingerprint replaces it immediately before
    // candidate comparison and parsing.
    candidate.source_file_fingerprint = sidecar_fingerprint;
}

pub(crate) mod claude_native_comparison;

pub(crate) struct OwnedSourceScan {
    native_comparison: Option<claude_native_comparison::NativePhase>,
    resource_probe: crate::local_resource_diagnostics::Probe,
    sampling: Option<sampled_scan::Context>,
    durable_guard: Option<std::sync::Weak<sampled_scan::SharedCache>>,
    source: SnapshotSource,
    /// Configured scan roots, for a Codex census close that starts the next
    /// generation in the same page (G1 carry).
    roots: Vec<PathBuf>,
    index: ScanIndex,
    collected_at: String,
    backfill_window_days: u64,
    file_limit: usize,
    artifacts_enabled: bool,
    context_curve_enabled: bool,
    /// This scan's sync cycle holds a contract-5 permit.
    claude_request_identity_capture: bool,
    claude_effort_support_dir: Option<PathBuf>,
    codex_title_metadata: CodexTitleMetadata,
    claude_title_metadata: ClaudeTitleMetadata,
    state_census_complete: bool,
    sidecar_census_complete: bool,
    codex_turn_traces: Option<Arc<CodexTurnTraceMap>>,
    codex_parent_identities: CodexParentIdentities,
    codex_parent_ownership_ledgers:
        Option<Arc<Mutex<BTreeMap<String, CodexParentOwnershipLedger>>>>,
    census_window_end: String,
    discovered_file_count: usize,
    census_unix_seconds: Option<u64>,
    census: ScanCensus,
    snapshots: Vec<SnapshotItem>,
    scanned_file_count: usize,
    scanned_session_count: usize,
    semantic_noop_count: usize,
    /// This page's history-upgrade budget and count-only gate diagnostics.
    history_upgrade: HistoryPage,
    codex_state_only_blocked_session_ids: BTreeSet<String>,
    codex_parent_resolution_retry_required: bool,
    residue_index_keys: BTreeSet<String>,
    settled_residue_index_keys: BTreeSet<String>,
    residue_blocked_session_ids: BTreeSet<String>,
    pending_finalization: Vec<PendingIndexFinalization>,
    claude_authority_preflight: bool,
    forced_claude_family_reparses: BTreeSet<String>,
    /// E2: forced roots selected only for path-twin co-scheduling. Their
    /// owed adoption-only members keep the history gate (both or neither).
    claude_twin_only_family_reparses: BTreeSet<String>,
    identified_candidates: VecDeque<CandidateFile>,
    /// The active file and, while it is a paged cursor job, its slot lease.
    /// A dropped frame returns an intact job to the slot.
    active_file: sampled_scan::codex_cursor::ActiveFrame,
    codex_join_inventory: Option<codex_file_join::HeaderInventory>,
    codex_join_prepared: bool,
    codex_join_groups: VecDeque<codex_file_join::Group>,
    codex_join_active: Option<Box<codex_file_join::GroupBoot>>,
    codex_join_completed: Vec<codex_file_join::Group>,
    codex_legacy_join_baselines: Vec<codex_file_join::LegacyBaseline>,
    /// Decoded bytes this page consumed; the cursor job and ordinary Codex
    /// singleton reads have separate budgets.
    codex_page: sampled_scan::codex_cursor::PageBudget,
    /// Selection flags of this page's Codex candidates, so a budget deferral
    /// returns a file to `pending_candidates` with its original priority.
    codex_selected_flags: BTreeMap<String, (bool, bool)>,
    /// U1a-2a: this Codex pass's side-ledger namespace and gate (C14).
    codex_side_pass: Option<CodexSidePass>,
    /// Stage 1 hunk A: the ticket this page's pause minted, carried across
    /// `step` calls into the result.
    continuation_ticket: Option<sampled_scan::codex_cursor::CodexCursorTicket>,
    /// LD: this pass's line observer, if one is registered.
    line_delivery: Option<line_delivery::LineDelivery>,
    codex_versions: Option<Arc<codex_version::CodexVersionFeed>>,
}
struct OwnedActiveFile {
    comparison_target: bool,
    sampling: Option<sampled_scan::Active>,
    // Survives paging and missing preparation; only source verification retires it.
    recovered_audit_due: Option<u64>,
    candidate: CandidateFile,
    decision: CandidateDecision,
    previous_snapshot_fingerprint: Option<String>,
    previous_upload_body_witness: Option<String>,
    projection_adoption_required: bool,
    source_file_fingerprint: String,
    parser: OwnedJsonlParser,
    aliases: Vec<CandidateFile>,
    applied_receipts: BTreeMap<String, Option<codex_file_join::AppliedTierReceipt>>,
    /// Present while this file is read as a paged cursor job.
    cursor: Option<sampled_scan::codex_cursor::JobMeta>,
    /// Reader bytes already charged to this page's budgets.
    charged_bytes: u64,
    /// End of the record after which a hold no append can cure first held.
    hold_offset: Option<u64>,
    /// Present while this job replays a Codex file group (P2).
    group: Option<Box<codex_file_join::GroupJob>>,
    /// U1a-2a (row 16): present while this file is P's side read. Every
    /// main write on its path is gated; it ends at the side exit.
    side_origin: Option<SideOrigin>,
}
#[allow(clippy::large_enum_variant)] // One active context moves between native collection steps.
pub(crate) enum OwnedSourceScanStep {
    Pending(OwnedSourceScan),
    Complete {
        index: ScanIndex,
        scan: SourceScanResult,
        terminal_native_traversal: Option<Box<claude_native_comparison::TerminalTraversal>>,
    },
}
// E2 can defer paths from the priority prefix. Stable removal keeps every
// surviving priority path within the old prefix bound; clamp it to the page's
// new length. Any ordinary suffix included was actually offered too, and the
// recorder credits only contiguous owed paths. Its membership scan stays no
// larger than the original prefix, including when the whole prefix deferred.
fn finish_claude_retry_selection(
    index: &mut ScanIndex,
    pending_paths: &mut Vec<ScanTraversalPath>,
    retry_service_end: usize,
    census_window_end: &str,
) {
    if claude_request_money::e2::enabled() {
        claude_request_money::e2::defer_roots_of_queued_families(
            pending_paths,
            index.traversal.as_mut().expect("traversal initialized"),
        );
    }
    let offered_end = retry_service_end.min(pending_paths.len());
    if offered_end > 0 {
        claude_retry_note_offered(index, &pending_paths[..offered_end], census_window_end);
    }
}

impl OwnedSourceScan {
    pub(crate) fn native_ordinary_body_frontier(&self) -> usize {
        // The Claude producer only extends snapshots until it returns Complete.
        // This index is consumed into owned receipts BEFORE the final fold.
        self.snapshots.len()
    }

    pub(crate) fn native_early_evidence_roots(&self) -> impl Iterator<Item = &str> + Clone {
        self.native_comparison
            .as_ref()
            .into_iter()
            .flat_map(move |phase| phase.early_evidence_roots(&self.snapshots))
    }
    pub(crate) fn native_capture_active(&self) -> bool {
        self.native_comparison
            .as_ref()
            .is_some_and(|phase| phase.capture_active())
    }

    pub(crate) fn native_capture_disabled(&self) -> bool {
        self.native_comparison
            .as_ref()
            .is_some_and(|phase| !phase.capture_active())
    }

    pub(crate) fn native_capture_bytes(&self) -> Option<usize> {
        self.native_comparison
            .as_ref()
            .map_or(Some(0), |phase| phase.owned_capture_bytes())
    }
    pub(crate) fn enable_native_comparison(&mut self) {
        if self.source == SnapshotSource::ClaudeCode {
            self.native_comparison = Some(claude_native_comparison::NativePhase::default());
        }
    }

    pub(crate) fn native_comparison_ready(&self) -> bool {
        self.native_comparison
            .as_ref()
            .is_some_and(|phase| phase.ready())
    }

    pub(crate) fn native_comparison_support_dir(&self) -> Option<&Path> {
        self.claude_effort_support_dir.as_deref()
    }

    pub(crate) fn native_comparison_context(&self) -> Option<&str> {
        self.index
            .traversal
            .as_ref()
            .map(|traversal| traversal.context_fingerprint.as_str())
    }

    pub(crate) fn resume_native_comparison_base(&mut self) {
        if let Some(phase) = self.native_comparison.as_mut() {
            phase.resume();
        }
    }

    pub(crate) fn disable_native_comparison(&mut self) {
        if let Some(phase) = self.native_comparison.as_mut() {
            phase.disable();
        }
    }

    pub(crate) fn native_comparison_inputs(&self) -> (&ScanIndex, &[SnapshotItem]) {
        (&self.index, &self.snapshots)
    }

    #[cfg(test)]
    pub(crate) fn prepare_native_comparison(
        &mut self,
        rows: claude_native_comparison::PairedRows<'_>,
    ) -> claude_native_comparison::Qualification {
        self.prepare_native_comparison_with_window(rows, None)
            .unwrap_or_default()
    }

    #[cfg(test)]
    pub(crate) fn prepare_native_comparison_with_window(
        &mut self,
        rows: claude_native_comparison::PairedRows<'_>,
        previous: Option<Box<claude_native_comparison::WindowEligibility>>,
    ) -> Option<claude_native_comparison::Qualification> {
        self.prepare_native_comparison_credit(rows, previous, None)
            .expect("logical qualification has no paid workspace refusal")
    }
    pub(crate) fn prepare_native_comparison_paid(
        &mut self,
        rows: claude_native_comparison::PairedRows<'_>,
        previous: Option<Box<claude_native_comparison::WindowEligibility>>,
        credit: &mut Option<crate::source_rotation::PaidReservation>,
    ) -> Result<Option<claude_native_comparison::Qualification>, crate::source_rotation::LocalRefusal>
    {
        self.prepare_native_comparison_credit(rows, previous, Some(credit))
    }
    fn prepare_native_comparison_credit(
        &mut self,
        rows: claude_native_comparison::PairedRows<'_>,
        previous: Option<Box<claude_native_comparison::WindowEligibility>>,
        mut credit: Option<&mut Option<crate::source_rotation::PaidReservation>>,
    ) -> Result<Option<claude_native_comparison::Qualification>, crate::source_rotation::LocalRefusal>
    {
        let healthy = self.native_comparison_is_healthy();
        let phase = self
            .native_comparison
            .as_mut()
            .expect("native comparison opted in");
        let imported = healthy
            && match credit.as_deref_mut() {
                Some(credit) => {
                    phase.import_window_paid(previous, &self.index, &self.census_window_end, credit)
                }
                None => phase.import_window(previous, &self.index, &self.census_window_end),
            };
        let external = credit.as_deref().and_then(|slot| {
            slot.as_ref()?
                .allocated()
                .checked_sub(phase.owned_capture_bytes()?)
        });
        let workspace = imported
            .then(|| match credit.as_deref_mut() {
                Some(credit) => {
                    phase.prepay_qualification_workspace(&self.index, &self.snapshots, credit)
                }
                None => Some(0), // Logical fixtures carry no admission claim.
            })
            .flatten();
        if imported && workspace.is_none() {
            phase.disable();
            phase.resume();
            return Err(crate::source_rotation::LocalRefusal(
                "native comparison qualification workspace cannot be prepaid",
            ));
        }
        let mut qualification = if let Some(workspace) = workspace {
            let qualification = phase.qualify_with_credit(
                &self.index,
                &self.snapshots,
                &self.census_window_end,
                rows,
                credit.as_deref_mut(),
                workspace,
            );
            phase.capture_active().then_some(qualification)
        } else {
            None
        };
        phase.resume();
        if let Some(slot) = credit {
            // All root-local temporaries and the old moved certificate buffer
            // are gone. Replace their future reservation with actual retained
            // qualification + current phase custody exactly once.
            use crate::heap_layout_bound::{Counter, HeapLayoutBound};
            let owned = (|| {
                let mut cost = Counter::new(crate::source_rotation::PARKED_BUDGET);
                if let Some(q) = qualification.as_ref() {
                    q.completed_heap_bound(&mut cost)?;
                }
                external?
                    .checked_add(phase.owned_capture_bytes()?)?
                    .checked_add(cost.bytes)
            })();
            let recorded = slot
                .as_mut()
                .zip(owned)
                .is_some_and(|(paid, bytes)| paid.record_allocated(bytes));
            if !recorded {
                drop(qualification.take());
                phase.disable();
                return Err(crate::source_rotation::LocalRefusal(
                    "native comparison retained qualification cannot be reconciled",
                ));
            }
            if let Some(paid) = slot.as_mut() {
                paid.retire_speculation();
            }
        }
        Ok(qualification)
    }

    fn native_comparison_is_healthy(&self) -> bool {
        // Before census counters are folded into traversal, require no local
        // read/parser loss and a healthy retained traversal. Unknown is base.
        let local = &self.census;
        self.state_census_complete
            && self.sidecar_census_complete
            && local.directory_entry_cap_exceeded_count == 0
            && local.symlink_rejected_count == 0
            && local.unreadable_path_count == 0
            && local.oversized_file_count == 0
            && local.disappeared_file_count == 0
            && local.malformed_json_line_count == 0
            && local.invalid_utf8_line_count == 0
            && local.over_line_cap_count == 0
            && local.recognized_usage_drop_count == 0
            && local.ownership_incomplete_file_count == 0
            && local.zero_snapshot_usage_evidence_count == 0
            && local.dropped_usage_record_count == 0
            && self
                .index
                .traversal
                .as_ref()
                .is_some_and(|traversal| !traversal.counts.has_errors())
    }

    pub(crate) fn take_native_comparison_acquisition(
        &self,
        qualification: &mut claude_native_comparison::Qualification,
    ) -> claude_native_comparison::TargetAcquisition {
        assert!(self.active_file.is_none() && self.identified_candidates.is_empty());
        qualification.take_native_acquisition(
            &self.snapshots,
            &self.pending_finalization,
            self.native_comparison_is_healthy(),
        )
    }

    #[cfg(test)]
    pub(crate) fn acquire_native_comparison_targets(
        &mut self,
        qualification: &mut claude_native_comparison::Qualification,
    ) -> claude_native_comparison::TargetSelection {
        self.acquire_native_comparison_targets_after(qualification, 0, None, &[])
            .expect("logical target selection adapter")
    }

    fn acquire_native_comparison_targets_after(
        &mut self,
        qualification: &mut claude_native_comparison::Qualification,
        frontier: usize,
        mut recovery: Option<claude_native_comparison::RecoveryBudget<'_>>,
        already_targets: &[CandidateFile],
    ) -> Result<claude_native_comparison::TargetSelection, crate::source_rotation::LocalRefusal>
    {
        assert!(self.active_file.is_none() && self.identified_candidates.is_empty());
        let (candidates, selection) = qualification.take_target_candidates_after(
            &self.snapshots,
            frontier,
            self.file_limit.saturating_sub(self.scanned_file_count),
            &self.pending_finalization,
            self.file_limit,
            recovery.as_mut(),
        )?;
        if selection.matched_roots > 0 || !selection.unresolved_sources.is_empty() {
            if let Some(recovery) = recovery.as_mut() {
                let reason = || {
                    crate::source_rotation::LocalRefusal(
                    "native comparison selected recovery cannot be prepaid before target or deferral",
                )
                };
                let paid = recovery.credit.as_mut().ok_or_else(reason)?;
                let targets = qualification
                    .recovery_targets()
                    .chain(already_targets.iter());
                let peak = claude_native_comparison::SelectedFallback::recovery_peak(
                    &self.index,
                    recovery.previous,
                    &self.pending_finalization,
                    targets,
                    paid,
                )
                .ok_or_else(reason)?;
                if !paid.reserve_recovery(peak) {
                    return Err(reason());
                }
            }
        }
        if !candidates.is_empty() {
            let phase = self
                .native_comparison
                .as_mut()
                .expect("native comparison opted in");
            if let Some(recovery) = recovery {
                phase.start_targets_paid(
                    &candidates,
                    &mut self.identified_candidates,
                    recovery.credit,
                )?;
            } else {
                phase.start_targets(&candidates);
            }
            self.identified_candidates.extend(candidates);
        }
        Ok(selection)
    }

    #[cfg(test)]
    pub(crate) fn test_active_physical_lines(&self) -> usize {
        self.active_file
            .as_ref()
            .map(|file| file.parser.reader.report.physical_line_count)
            .unwrap_or(0)
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new(
        source: SnapshotSource,
        roots: &[PathBuf],
        owned_index: ScanIndex,
        collected_at: &str,
        requested_backfill_window_days: u64,
        file_limit: usize,
        artifacts_enabled: bool,
        claude_effort_support_dir: Option<&Path>,
        hinted_paths: &[PathBuf],
        watcher_overflowed: bool,
        context_curve_enabled: bool,
    ) -> Self {
        Self::new_with_identity_capture(
            source,
            roots,
            owned_index,
            collected_at,
            requested_backfill_window_days,
            file_limit,
            artifacts_enabled,
            claude_effort_support_dir,
            hinted_paths,
            watcher_overflowed,
            context_curve_enabled,
            cfg!(test) || claude_request_identity::captures(source),
        )
    }

    /// `claude_request_identity_capture`: this scan captures transcript
    /// markers and keeps the Desktop census witness (every Claude sync cycle;
    /// `claude_request_identity::captures`). Without it it does neither.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new_with_identity_capture(
        source: SnapshotSource,
        roots: &[PathBuf],
        owned_index: ScanIndex,
        collected_at: &str,
        requested_backfill_window_days: u64,
        file_limit: usize,
        artifacts_enabled: bool,
        claude_effort_support_dir: Option<&Path>,
        hinted_paths: &[PathBuf],
        watcher_overflowed: bool,
        context_curve_enabled: bool,
        claude_request_identity_capture: bool,
    ) -> Self {
        Self::new_with_identity_capture_and_recovery_priority(
            source,
            roots,
            owned_index,
            collected_at,
            requested_backfill_window_days,
            file_limit,
            artifacts_enabled,
            claude_effort_support_dir,
            hinted_paths,
            watcher_overflowed,
            context_curve_enabled,
            claude_request_identity_capture,
            &[],
        )
    }

    /// Inactive source seam for already queued, durably rearmed recovery paths.
    /// This only changes native selection order, never ownership or settlement.
    /// The controller must still bind its process/source/destination scope and
    /// prove selected-save/restart liveness before using it.
    #[allow(dead_code, clippy::too_many_arguments)]
    pub(crate) fn new_with_identity_capture_and_recovery_priority(
        source: SnapshotSource,
        roots: &[PathBuf],
        owned_index: ScanIndex,
        collected_at: &str,
        requested_backfill_window_days: u64,
        file_limit: usize,
        artifacts_enabled: bool,
        claude_effort_support_dir: Option<&Path>,
        hinted_paths: &[PathBuf],
        watcher_overflowed: bool,
        context_curve_enabled: bool,
        claude_request_identity_capture: bool,
        recovery_priority: &[PathBuf],
    ) -> Self {
        Self::new_selecting(
            source,
            roots,
            owned_index,
            collected_at,
            requested_backfill_window_days,
            file_limit,
            artifacts_enabled,
            claude_effort_support_dir,
            hinted_paths,
            watcher_overflowed,
            context_curve_enabled,
            claude_request_identity_capture,
            recovery_priority,
        )
    }

    /// Performs no selection, inventory read or traversal update.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new_continuation(
        roots: &[PathBuf],
        owned_index: ScanIndex,
        collected_at: &str,
        requested_backfill_window_days: u64,
        file_limit: usize,
        artifacts_enabled: bool,
        context_curve_enabled: bool,
        ordinary_equivalent: Option<std::time::Duration>,
        mut evidence: Option<CodexContinuationEvidence>,
    ) -> Self {
        let codex_title_metadata = evidence
            .as_mut()
            .map(|e| std::mem::take(&mut e.codex))
            .unwrap_or_default();
        let codex_parent_identities =
            CodexParentIdentities::new(SnapshotSource::Codex, owned_index.traversal.as_ref());
        let census_window_end = owned_index
            .traversal
            .as_ref()
            .map_or_else(|| collected_at.to_owned(), |t| t.census_window_end.clone());
        let mut codex_page = sampled_scan::codex_cursor::PageBudget::default();
        codex_page.set_continuation(ordinary_equivalent);
        Self {
            native_comparison: None,
            resource_probe: crate::local_resource_diagnostics::Probe::start(),
            sampling: None,
            durable_guard: None,
            source: SnapshotSource::Codex,
            roots: roots.to_vec(),
            index: owned_index,
            collected_at: collected_at.to_owned(),
            backfill_window_days: effective_backfill_window_days(requested_backfill_window_days),
            file_limit,
            artifacts_enabled,
            context_curve_enabled,
            claude_request_identity_capture: false,
            claude_effort_support_dir: None,
            claude_title_metadata: Default::default(),
            state_census_complete: !codex_title_metadata.state_census_incomplete,
            sidecar_census_complete: !codex_title_metadata.sidecar_census_incomplete,
            codex_title_metadata,
            codex_turn_traces: evidence.as_mut().and_then(|e| e.traces.take()),
            codex_parent_identities,
            codex_parent_ownership_ledgers: evidence.as_mut().and_then(|e| e.ledgers.take()),
            census_window_end,
            discovered_file_count: 0,
            census_unix_seconds: rfc3339_unix_seconds(collected_at),
            census: Default::default(),
            snapshots: Vec::new(),
            scanned_file_count: 0,
            scanned_session_count: 0,
            semantic_noop_count: 0,
            history_upgrade: HistoryPage::with_twin_groups(Default::default()),
            codex_state_only_blocked_session_ids: Default::default(),
            codex_parent_resolution_retry_required: false,
            residue_index_keys: Default::default(),
            settled_residue_index_keys: Default::default(),
            residue_blocked_session_ids: Default::default(),
            pending_finalization: Vec::new(),
            claude_authority_preflight: false,
            forced_claude_family_reparses: Default::default(),
            claude_twin_only_family_reparses: Default::default(),
            identified_candidates: Default::default(),
            active_file: Default::default(),
            codex_join_inventory: evidence.map(|e| e.inventory),
            codex_join_prepared: true,
            codex_join_groups: Default::default(),
            codex_join_active: None,
            codex_join_completed: Vec::new(),
            codex_legacy_join_baselines: Vec::new(),
            codex_page,
            codex_selected_flags: Default::default(),
            codex_side_pass: None,
            continuation_ticket: None,
            line_delivery: None,
            codex_versions: None,
        }
    }

    /// Stage 1 (K6): the cooperative deadline of a continuation page, on the
    /// pace clock; ignored on an ordinary page. Past it the page pauses its
    /// job at the next `step()` return without minting a ticket.
    pub(crate) fn with_continuation_deadline(mut self, deadline: std::time::Instant) -> Self {
        self.codex_page.set_continuation_deadline(deadline);
        self
    }

    #[allow(clippy::too_many_arguments)]
    fn new_selecting(
        source: SnapshotSource,
        roots: &[PathBuf],
        mut owned_index: ScanIndex,
        collected_at: &str,
        requested_backfill_window_days: u64,
        file_limit: usize,
        artifacts_enabled: bool,
        claude_effort_support_dir: Option<&Path>,
        hinted_paths: &[PathBuf],
        watcher_overflowed: bool,
        context_curve_enabled: bool,
        claude_request_identity_capture: bool,
        recovery_priority: &[PathBuf],
    ) -> Self {
        let diagnostics = crate::local_resource_diagnostics::claude_reread::Scope::begin(
            source == SnapshotSource::ClaudeCode,
        );
        let mut resource_probe = crate::local_resource_diagnostics::Probe::start();
        let index = &mut owned_index;
        index.activate_quarantine_witness(source);
        let backfill_window_days = effective_backfill_window_days(requested_backfill_window_days);
        let codex_title_metadata = if source == SnapshotSource::Codex {
            let mut metadata = CodexTitleMetadata::load_from_roots(roots);
            metadata.count_prior_state_only_conflicts(index);
            metadata
        } else {
            CodexTitleMetadata::default()
        };
        let claude_identity_census_was_complete = index.claude_desktop_identity_census_complete;
        let claude_sidecar_was_incomplete = source == SnapshotSource::ClaudeCode
            && (index.claude_desktop_store_cursor.is_some()
                || index.claude_desktop_store_sweep_had_errors
                || (index
                    .claude_desktop_store_retry_not_before_unix_seconds
                    .is_some()
                    && (!index.claude_desktop_identity_census_complete
                        || !index.claude_desktop_lineage_census_complete)));
        let mut claude_title_metadata = if source == SnapshotSource::ClaudeCode {
            ClaudeTitleMetadata::load_from_roots_with_index(
                roots,
                index,
                collected_at,
                claude_request_identity_capture,
            )
        } else {
            ClaudeTitleMetadata::default()
        };
        if source == SnapshotSource::ClaudeCode
            && !claude_identity_census_was_complete
            && !claude_title_metadata.original_identity_census_incomplete
        {
            // Attribute the existing account-held retry reads to their recovered
            // metadata proof. This does not select, rearm or authorize any file.
            claude_title_metadata.note_completed_account_holds(index);
        }
        let state_census_complete =
            source != SnapshotSource::Codex || !codex_title_metadata.state_census_incomplete;
        let sidecar_census_complete = match source {
            SnapshotSource::Codex => !codex_title_metadata.sidecar_census_incomplete,
            SnapshotSource::ClaudeCode => !claude_title_metadata.sidecar_census_incomplete,
            SnapshotSource::Pi => true,
        };
        if (claude_sidecar_was_incomplete && sidecar_census_complete)
            || (source == SnapshotSource::ClaudeCode
                && claude_identity_census_was_complete
                && claude_title_metadata.original_identity_census_incomplete)
        {
            // The prior transcript generation was intentionally held red while
            // title discovery was partial. Start a fresh bounded transcript walk
            // now so sidecar additions/removals are folded into each affected
            // file fingerprint before a terminal manifest can publish. Actual identity
            // census loss also revisits consumed pages once to retract completeness.
            index.traversal = None;
        }
        // Read the per-turn fast-mode signal once per cycle (logs_2 is large); share
        // it read-only across every session file via Arc.
        let codex_turn_traces = (source == SnapshotSource::Codex).then(|| {
            Arc::new(CodexTurnTraceMap::load_from_roots(
                roots,
                backfill_window_days,
            ))
        });
        if source == SnapshotSource::ClaudeCode {
            index.observe_claude_request_identity_contract(claude_request_identity_capture);
        }
        let progress =
            ensure_bounded_traversal(source, roots, index, collected_at, backfill_window_days);
        if source == SnapshotSource::ClaudeCode && progress == TraversalProgress::Started {
            index.record_started_claude_request_identity_contract(claude_request_identity_capture);
        }
        let next_generation_hints;
        {
            let traversal = index.traversal.as_mut().expect("traversal initialized");
            refresh_retained_codex_roster(source, traversal, backfill_window_days, &index.files);
            next_generation_hints =
                enqueue_watcher_hints(source, traversal, hinted_paths, watcher_overflowed);
            advance_bounded_directory_traversal(
                source,
                traversal,
                backfill_window_days,
                &index.files,
            );
            release_codex_inventory_hold(source, traversal);
        }
        if source == SnapshotSource::Codex {
            // L-SB: an index from before blocked-set attribution moves its
            // whole blocked set to `legacy` once.
            index.migrate_codex_blocked_attribution();
        }
        // L-5: no census copy; parent lookups borrow the index's own census,
        // which this page no longer writes until it finishes.
        let codex_parent_identities = CodexParentIdentities::new(source, index.traversal.as_ref());
        let codex_parent_ownership_ledgers = (source == SnapshotSource::Codex).then(|| {
            let (validated, rewitnessed) = validate_codex_parent_ownership_ledgers(
                index,
                codex_parent_identities.census(index),
            );
            index.codex_parent_ownership_ledgers.extend(rewitnessed);
            Arc::new(Mutex::new(validated))
        });
        if source == SnapshotSource::ClaudeCode {
            claude_retry_queue_due_families(index, collected_at);
        }
        let traversal = index.traversal.as_mut().expect("traversal initialized");
        let census_window_end = traversal.census_window_end.clone();
        let discovered_file_count = traversal.counts.discovered_file_count;
        let mut pending_paths = Vec::new();
        // Watcher freshness must not starve the durable census when callers use a
        // small page size. Production reserves almost the whole 10k page already,
        // but the explicit slot also makes liveness independent of that ratio.
        let ordinary_census_pending = !index.claude_stale_family_carry.replay.is_empty()
            || traversal
                .pending_candidates
                .iter()
                .any(|candidate| candidate.census_member && !candidate.watcher_hint);
        let selection_limit =
            if source == SnapshotSource::Codex && !traversal.pending_directories.is_empty() {
                0
            } else {
                file_limit
            };
        // Fresh data gets a bounded page of its own, at most every other
        // ordinary page. Mixing it behind 64 MiB of census revalidation
        // starves it; always putting it first can starve the census instead.
        // Continuations never select new work. A hint alone does not trigger
        // a read: all selected paths still pass the unchanged candidate gate.
        let freshness_page = source == SnapshotSource::Codex
            && selection_limit > 0
            && !traversal.codex_freshness_yield
            && traversal
                .pending_candidates
                .iter()
                .any(|candidate| codex_fresh_data_pending(candidate, &index.files))
            && codex_selection_may_exhaust_page(traversal, selection_limit, &index.files);
        let census_page = source == SnapshotSource::Codex
            && selection_limit > 0
            && traversal.codex_freshness_yield
            && traversal
                .pending_candidates
                .iter()
                .any(|candidate| candidate.census_member);
        if source == SnapshotSource::Codex && selection_limit > 0 {
            traversal.codex_freshness_yield = freshness_page;
        }
        if freshness_page || census_page {
            let limit = if freshness_page {
                selection_limit.min(MAX_WATCHER_HINTED_FILES_PER_TICK)
            } else {
                selection_limit
            };
            // Rotate the original queue once without allocating another
            // backlog-sized container. Keep unselected paths in FIFO order.
            for _ in 0..traversal.pending_candidates.len() {
                let Some(candidate) = traversal.pending_candidates.pop_front() else {
                    break;
                };
                let eligible = pending_paths.len() < limit
                    && if freshness_page {
                        codex_fresh_data_pending(&candidate, &index.files)
                    } else {
                        candidate.census_member
                            && !codex_fresh_data_pending(&candidate, &index.files)
                    };
                if eligible {
                    pending_paths.push(candidate);
                } else {
                    traversal.pending_candidates.push_back(candidate);
                }
            }
            // If every remaining member has fresh bytes, service those
            // members in FIFO order rather than wasting their census turn.
            if census_page && pending_paths.is_empty() {
                for _ in 0..traversal.pending_candidates.len() {
                    let Some(candidate) = traversal.pending_candidates.pop_front() else {
                        break;
                    };
                    if pending_paths.len() < limit && candidate.census_member {
                        pending_paths.push(candidate);
                    } else {
                        traversal.pending_candidates.push_back(candidate);
                    }
                }
            }
        }
        // Dedicated turns select only their own work: new hinted members,
        // audits or old groups cannot consume the other turn's allowance.
        let selection_limit = if freshness_page || census_page {
            pending_paths.len()
        } else {
            selection_limit
        };
        let hinted_budget = selection_limit
            .min(MAX_WATCHER_HINTED_FILES_PER_TICK)
            .saturating_sub(usize::from(ordinary_census_pending && file_limit > 0));
        // Recovery must be selected before audits consume the page. Only
        // existing queued paths with durable rearm debt are eligible here.
        // Unknown/outside-page paths are not injected, and no deadline, source
        // fingerprint, census flag or budget is changed by selection.
        if source == SnapshotSource::ClaudeCode && claude_native_comparison::enabled() {
            if recovery_priority.is_empty() {
                // Selected fallback persists A at the front of this SAME
                // queue with existing empty-fp debt. A restarted process has
                // no lease/certificate or separate recovery path list. Honor
                // only that queued debt prefix before audits; never inject a
                // path, scan for missing members or mint native eligibility.
                while pending_paths.len() < selection_limit {
                    let known_debt =
                        traversal
                            .pending_candidates
                            .front()
                            .is_some_and(|candidate| {
                                index
                                    .files
                                    .get(&local_index_key(&candidate.path))
                                    .is_some_and(|entry| entry.source_file_fingerprint.is_empty())
                            });
                    if !known_debt {
                        break;
                    }
                    if let Some(candidate) = traversal.pending_candidates.pop_front() {
                        pending_paths.push(candidate);
                    }
                }
            } else {
                claude_native_comparison::select_recovery_before_audits(
                    &mut traversal.pending_candidates,
                    &mut pending_paths,
                    &index.files,
                    recovery_priority,
                    selection_limit,
                );
            }
        }
        // Nonshipping candidate: exercise target priority at the actual
        // selection boundary, before audits, with the unchanged page cap.
        #[cfg(test)]
        envelope_selection_experiment::before_audit_selection(
            source,
            &mut traversal.pending_candidates,
            &mut pending_paths,
            &mut index.files,
            selection_limit,
        );
        // Authority deadlines are serviced independently of history admission,
        // before audits can consume the existing per-page selection allowance.
        if source == SnapshotSource::ClaudeCode {
            if let Some(state) = index
                .claude_stale_family_carry
                .origin
                .as_ref()
                .and_then(|origin| origin.admission.as_ref())
            {
                claude_retry_select_due_paths(
                    state,
                    &index.claude_usage_authority_quarantine,
                    &mut traversal.pending_candidates,
                    &mut pending_paths,
                    rfc3339_unix_seconds(collected_at).unwrap_or_default(),
                    selection_limit,
                );
            }
        }
        let retry_service_end = pending_paths.len();
        let audit_now = sampled_scan::now_seconds();
        while pending_paths.len() < selection_limit {
            let Some(position) = traversal.pending_candidates.iter().position(|candidate| {
                index
                    .files
                    .get(&local_index_key(&candidate.path))
                    .is_some_and(|entry| entry.audit_requires_full(audit_now))
            }) else {
                break;
            };
            if let Some(candidate) = traversal.pending_candidates.remove(position) {
                pending_paths.push(candidate);
            }
        }
        let audited = pending_paths.len();
        for _ in pending_paths.len()..hinted_budget {
            let Some(position) = traversal
                .pending_candidates
                .iter()
                .position(|candidate| candidate.watcher_hint)
            else {
                break;
            };
            if let Some(candidate) = traversal.pending_candidates.remove(position) {
                pending_paths.push(candidate);
            }
        }
        // C1b: members a carry cancellation queued again, drained from the
        // replay buffer the carry funded, ahead of the ordinary census
        // candidates and within the same page limit. Draining keeps the
        // buffer's capacity.
        let carry_replay = &mut index.claude_stale_family_carry.replay;
        let replayed = selection_limit
            .saturating_sub(pending_paths.len())
            .min(carry_replay.len());
        pending_paths.extend(carry_replay.drain(..replayed));
        // Context catch-up consumes ordinary page slots only after queued new
        // or grown native files. Keep recovery/deadline reservations above.
        while matches!(source, SnapshotSource::ClaudeCode | SnapshotSource::Codex)
            && pending_paths.len() < selection_limit
        {
            let Some(position) = traversal.pending_candidates.iter().position(|candidate| {
                !index.files.contains_key(&local_index_key(&candidate.path))
                    || codex_fresh_data_pending(candidate, &index.files)
            }) else {
                break;
            };
            if let Some(candidate) = traversal.pending_candidates.remove(position) {
                pending_paths.push(candidate);
            }
        }
        while pending_paths.len() < selection_limit {
            let Some(position) = traversal
                .pending_candidates
                .iter()
                .position(|candidate| candidate.census_member && !candidate.watcher_hint)
            else {
                break;
            };
            if let Some(candidate) = traversal.pending_candidates.remove(position) {
                pending_paths.push(candidate);
            }
        }
        while pending_paths.len() < selection_limit {
            let Some(candidate) = traversal.pending_candidates.pop_front() else {
                break;
            };
            pending_paths.push(candidate);
        }
        if source == SnapshotSource::Codex {
            // G1 (fix 2): the same selection, read census members first. The
            // reserved census member and every other first read are charged
            // to the page's singleton budget before any re-read (a watcher
            // hint for a path this generation already processed), so each
            // page completes a first read and re-reads cannot starve one.
            // Audits keep their place; the order is otherwise unchanged.
            let (members, rereads): (Vec<_>, Vec<_>) = pending_paths
                .split_off(audited)
                .into_iter()
                .partition(|candidate| candidate.census_member);
            pending_paths.extend(members);
            pending_paths.extend(rereads);
        }
        let census_unix_seconds = rfc3339_unix_seconds(&census_window_end);
        let causes = traversal.counts.causes.page(census_unix_seconds);
        if source == SnapshotSource::ClaudeCode {
            finish_claude_retry_selection(
                index,
                &mut pending_paths,
                retry_service_end,
                &census_window_end,
            );
        }
        index.resume_census_window_end = Some(census_window_end.clone());
        let mut census = ScanCensus {
            causes,
            ..ScanCensus::default()
        };
        let codex_selected_flags = if source == SnapshotSource::Codex {
            pending_paths
                .iter()
                .map(|pending| {
                    (
                        local_index_key(&pending.path),
                        (pending.census_member, pending.watcher_hint),
                    )
                })
                .collect()
        } else {
            BTreeMap::new()
        };
        let mut files = pending_paths
            .into_iter()
            .filter_map(|pending| {
                candidate_from_traversal_path(
                    source,
                    pending,
                    &mut census,
                    census_unix_seconds,
                    backfill_window_days,
                    &index.files,
                )
            })
            .collect::<Vec<_>>();

        let prepare_candidate_context = |candidate: &mut CandidateFile| {
            prepare_owned_scan_candidate(
                source,
                candidate,
                &codex_title_metadata,
                &claude_title_metadata,
                claude_effort_support_dir,
            );
        };
        for candidate in &mut files {
            prepare_candidate_context(candidate);
        }
        let snapshots = Vec::new();
        let scanned_file_count = 0;
        let scanned_session_count = 0;
        let semantic_noop_count = 0;
        let codex_state_only_blocked_session_ids = BTreeSet::new();
        let codex_parent_resolution_retry_required = false;
        let residue_index_keys = BTreeSet::new();
        let settled_residue_index_keys = BTreeSet::new();
        let residue_blocked_session_ids = BTreeSet::new();
        let pending_finalization = Vec::new();
        let claude_authority_preflight = source == SnapshotSource::ClaudeCode
            && !index.claude_usage_authority_quarantine.is_empty();
        let mut identified_candidates = if claude_authority_preflight {
            files
                .into_iter()
                .filter_map(|candidate| {
                    open_and_identify_scan_candidate(
                        source,
                        candidate,
                        &mut census,
                        census_unix_seconds,
                        backfill_window_days,
                        &index.files,
                    )
                    .map(|(candidate, _)| candidate)
                })
                .collect::<Vec<_>>()
        } else {
            files
        };
        let mut forced_claude_family_reparses = if source == SnapshotSource::ClaudeCode {
            identified_candidates
                .iter()
                .filter_map(|candidate| {
                    index.claude_usage_authority_candidate_requires_family_reparse(candidate)
                })
                .collect::<BTreeSet<_>>()
        } else {
            BTreeSet::new()
        };
        let claude_family_membership_is_authoritative = source == SnapshotSource::ClaudeCode
            && index.traversal.as_ref().is_some_and(|traversal| {
                traversal.pending_directories.is_empty()
                    && traversal.counts.directory_entry_cap_exceeded_count == 0
                    && traversal.counts.symlink_rejected_count == 0
                    && traversal.counts.unreadable_path_count == 0
                    && traversal.counts.disappeared_file_count == 0
            });
        if claude_family_membership_is_authoritative {
            let current_members_by_root = index
                .traversal
                .as_ref()
                .into_iter()
                .flat_map(|traversal| traversal.observed_index_keys.iter())
                .filter_map(|index_key| claude_index_path_family_member(Path::new(index_key)))
                .fold(
                    BTreeMap::<String, BTreeSet<String>>::new(),
                    |mut by_root, (root_session_id, source_session_id)| {
                        by_root
                            .entry(root_session_id)
                            .or_default()
                            .insert(source_session_id);
                        by_root
                    },
                );
            for (root_session_id, record) in &index.claude_usage_authority_quarantine {
                let current_members = current_members_by_root
                    .get(root_session_id)
                    .cloned()
                    .unwrap_or_default();
                if current_members
                    != record
                        .member_source_file_fingerprints
                        .keys()
                        .cloned()
                        .collect()
                {
                    forced_claude_family_reparses.insert(root_session_id.clone());
                }
            }
        }
        let mut claude_twin_only_family_reparses = BTreeSet::new();
        // E2: the page's path-twin groups, built at most once per page and
        // shared with twin staging and the parse-time birth context.
        let claude_twin_groups = std::cell::OnceCell::new();
        if source == SnapshotSource::ClaudeCode && claude_request_money::e2::enabled() {
            let twin_groups = claude_twin_groups.get_or_init(|| {
                // A page file not known yet (a new copy) keeps its member's
                // single known path as its twin.
                let page_members = identified_candidates
                    .iter()
                    .filter_map(|candidate| claude_index_path_family_member(&candidate.path))
                    .map(|(_, member)| member)
                    .collect::<BTreeSet<_>>();
                claude_history_upgrade::claude_path_twin_groups(index, &page_members)
            });
            // Only a twin this page reads pulls its family in: every walk meets
            // each settled twin too, and pulling its family then re-read the
            // family on every walk (R1 probe: 8 files and one upload batch per
            // walk). Outside the authority preflight a candidate still carries
            // its sidecar digest in the scan fingerprint slot, so each twin is
            // identified on a copy first: one more open per twin candidate. A
            // twin that cannot be identified pulls its family in, as before.
            let read_twins = identified_candidates
                .iter()
                .filter(|candidate| {
                    !claude_request_money::e2::selected_twin_roots(
                        std::iter::once(candidate.path.as_path()),
                        twin_groups,
                    )
                    .is_empty()
                })
                .filter(|candidate| {
                    let mut twin = (*candidate).clone();
                    prepare_candidate_context(&mut twin);
                    match open_and_identify_scan_candidate(
                        source,
                        twin,
                        &mut ScanCensus::default(),
                        census_unix_seconds,
                        backfill_window_days,
                        &index.files,
                    ) {
                        Some((twin, _)) => {
                            index.candidate_decision(&twin) == CandidateDecision::Parse
                        }
                        None => true,
                    }
                })
                .map(|candidate| candidate.path.as_path())
                .collect::<Vec<_>>();
            for root in
                claude_request_money::e2::selected_twin_roots(read_twins.into_iter(), twin_groups)
            {
                if forced_claude_family_reparses.insert(root.clone()) {
                    claude_twin_only_family_reparses.insert(root);
                }
            }
        }
        if !forced_claude_family_reparses.is_empty() {
            let already_identified = identified_candidates
                .iter()
                .map(|candidate| local_index_key(&candidate.path))
                .collect::<BTreeSet<_>>();
            let family_index_keys = if claude_family_membership_is_authoritative {
                index
                    .traversal
                    .as_ref()
                    .map(|traversal| traversal.observed_index_keys.clone())
                    .unwrap_or_default()
            } else {
                index.files.keys().cloned().collect()
            };
            let scan_roots = index
                .traversal
                .as_ref()
                .map(|traversal| traversal.scan_roots.clone())
                .unwrap_or_default();
            let missing_family_paths = family_index_keys
                .into_iter()
                .filter(|index_key| !already_identified.contains(index_key))
                .filter_map(|index_key| {
                    let path = PathBuf::from(&index_key);
                    let (root_session_id, _) = claude_index_path_family_member(&path)?;
                    forced_claude_family_reparses
                        .contains(&root_session_id)
                        .then_some(path)
                })
                .collect::<BTreeSet<_>>();
            if let Some(traversal) = index.traversal.as_mut() {
                traversal
                    .pending_candidates
                    .retain(|pending| !missing_family_paths.contains(&pending.path));
            }
            index
                .claude_stale_family_carry
                .replay
                .retain(|pending| !missing_family_paths.contains(&pending.path));
            for path in missing_family_paths {
                let Some(scan_root) = scan_roots
                    .iter()
                    .filter(|root| path.starts_with(root))
                    .max_by_key(|root| root.components().count())
                    .cloned()
                else {
                    continue;
                };
                let Some(mut candidate) = candidate_from_traversal_path_at(
                    source,
                    disappearance_diagnostics::Site::CandidateForcedIndex,
                    ScanTraversalPath {
                        scan_root,
                        path,
                        census_member: true,
                        watcher_hint: false,
                    },
                    &mut census,
                    census_unix_seconds,
                    backfill_window_days,
                    &index.files,
                ) else {
                    continue;
                };
                prepare_candidate_context(&mut candidate);
                if let Some(opened) = open_and_identify_scan_candidate(
                    source,
                    candidate,
                    &mut census,
                    census_unix_seconds,
                    backfill_window_days,
                    &index.files,
                ) {
                    identified_candidates.push(opened.0);
                }
            }
        }

        let codex_join_inventory =
            (source == SnapshotSource::Codex && !identified_candidates.is_empty()).then(|| {
                let traversal = index
                    .traversal
                    .as_ref()
                    .expect("Codex traversal initialized");
                let mut inventory = codex_file_join::HeaderInventory::new(
                    &traversal.scan_roots,
                    &traversal.codex_rollout_paths,
                    traversal.codex_join_directory_census.as_ref(),
                );
                inventory.complete &= traversal.pending_directories.is_empty();
                inventory
            });
        resource_probe.page_events.merge(diagnostics.finish());
        Self {
            native_comparison: None,
            resource_probe,
            sampling: None,
            durable_guard: None,
            source,
            roots: roots.to_vec(),
            index: owned_index,
            collected_at: collected_at.to_owned(),
            backfill_window_days,
            file_limit,
            artifacts_enabled,
            context_curve_enabled,
            claude_request_identity_capture,
            claude_effort_support_dir: claude_effort_support_dir.map(Path::to_path_buf),
            codex_title_metadata,
            claude_title_metadata,
            state_census_complete,
            sidecar_census_complete,
            codex_turn_traces,
            codex_parent_identities,
            codex_parent_ownership_ledgers,
            census_window_end,
            discovered_file_count,
            census_unix_seconds,
            census,
            snapshots,
            scanned_file_count,
            scanned_session_count,
            semantic_noop_count,
            history_upgrade: HistoryPage::with_twin_groups(claude_twin_groups),
            codex_state_only_blocked_session_ids,
            codex_parent_resolution_retry_required,
            residue_index_keys,
            settled_residue_index_keys,
            residue_blocked_session_ids,
            pending_finalization,
            claude_authority_preflight,
            forced_claude_family_reparses,
            claude_twin_only_family_reparses,
            identified_candidates: identified_candidates.into(),
            active_file: Default::default(),
            codex_join_inventory,
            codex_join_prepared: false,
            codex_join_groups: VecDeque::new(),
            codex_join_active: None,
            codex_join_completed: Vec::new(),
            codex_legacy_join_baselines: Vec::new(),
            codex_page: sampled_scan::codex_cursor::PageBudget::with_next_generation_hints(
                next_generation_hints,
            ),
            codex_selected_flags,
            codex_side_pass: None,
            continuation_ticket: None,
            line_delivery: None,
            codex_versions: None,
        }
    }
    pub(crate) fn with_codex_versions(
        mut self,
        feed: Arc<codex_version::CodexVersionFeed>,
    ) -> Self {
        self.codex_versions = Some(feed);
        self
    }
    /// U1a-2a: the pass's C14 namespace and gate (`None` for other sources).
    pub(crate) fn with_codex_side_pass(mut self, pass: Option<CodexSidePass>) -> Self {
        self.codex_side_pass = pass;
        self
    }
    pub(crate) fn step(
        self,
        attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
    ) -> OwnedSourceScanStep {
        self.step_with_capture_credit(attribution_context, None)
            .expect("ordinary serial collection has no paid target retention")
    }

    pub(crate) fn step_paid(
        self,
        attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
        credit: &mut Option<crate::source_rotation::PaidReservation>,
    ) -> Result<OwnedSourceScanStep, crate::source_rotation::LocalRefusal> {
        self.step_with_capture_credit(attribution_context, Some(credit))
    }

    fn step_with_capture_credit(
        self,
        attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
        capture_credit: Option<&mut Option<crate::source_rotation::PaidReservation>>,
    ) -> Result<OwnedSourceScanStep, crate::source_rotation::LocalRefusal> {
        let diagnostics = crate::local_resource_diagnostics::claude_reread::Scope::begin(
            self.source == SnapshotSource::ClaudeCode,
        );
        let mut result = self.step_with_capture_credit_inner(attribution_context, capture_credit);
        let counts = diagnostics.finish();
        if let Ok(OwnedSourceScanStep::Pending(scan)) = &mut result {
            scan.resource_probe.page_events.merge(counts);
        }
        result
    }

    fn step_with_capture_credit_inner(
        mut self,
        attribution_context: Option<&crate::session_attribution::SessionAttributionContext>,
        mut capture_credit: Option<&mut Option<crate::source_rotation::PaidReservation>>,
    ) -> Result<OwnedSourceScanStep, crate::source_rotation::LocalRefusal> {
        // Prepare one demand batch through bounded native continuations. Group
        // owners come from the completed header census, never arbitrary names.
        if self.active_file.is_none()
            && self.codex_join_active.is_none()
            && (self.source != SnapshotSource::Codex || self.codex_join_prepared)
        {
            if let Some(context) = attribution_context {
                let first = self
                    .codex_join_groups
                    .front()
                    .map(|group| vec![group.owner.clone()])
                    .or_else(|| {
                        self.identified_candidates.front().map(|candidate| {
                            launch_workers_for_candidate(
                                self.source,
                                candidate,
                                self.codex_join_inventory.as_ref(),
                            )
                        })
                    })
                    .unwrap_or_default();
                // A completed batch covers its remaining members. Looking at
                // a sliding window here would add one new worker after every
                // file and repeat the complete retained-store sweep per file.
                if !context.launches_prepared(&first) {
                    let mut workers = BTreeSet::new();
                    for worker in self
                        .codex_join_groups
                        .iter()
                        .map(|group| group.owner.clone())
                        .chain(self.identified_candidates.iter().flat_map(|candidate| {
                            launch_workers_for_candidate(
                                self.source,
                                candidate,
                                self.codex_join_inventory.as_ref(),
                            )
                        }))
                        .take(crate::launch_events::MAX_DEMANDED_WORKERS)
                    {
                        if crate::launch_events::valid_worker(&worker) {
                            workers.insert(worker.to_ascii_lowercase());
                        }
                        if workers.len() == crate::launch_events::MAX_DEMANDED_WORKERS {
                            break;
                        }
                    }
                    let workers = workers.into_iter().collect::<Vec<_>>();
                    match context.prepare_launch_step(&workers) {
                        Ok(false) => return Ok(OwnedSourceScanStep::Pending(self)),
                        Err(()) => {} // Candidate handling keeps unreadable evidence owed.
                        Ok(true) => {}
                    }
                }
            }
        }
        let (copy_budget, step_measure) = self.sampled_copy_step();
        if copy_budget == 0 {
            // U1a-2a G15a: a side read wants no copy. It ends (a charged
            // attempt), and main's release then runs as it would with no
            // active file, since main never started P.
            if self
                .active_file
                .as_deref()
                .is_some_and(|active| active.side_origin.is_some())
            {
                if let Some(side) = self
                    .active_file
                    .take()
                    .and_then(|mut active| active.side_origin.take())
                {
                    side.end();
                }
            }
            // L-A1, M1: the resident bound and active charge from this same
            // walk, before any parse progress, admission or await; never
            // carried to another step.
            sampled_scan::release_cache_to_fit(
                self.sampling.as_ref(),
                self.active_file.as_deref(),
                step_measure,
            );
        }
        let Self {
            mut native_comparison,
            mut resource_probe,
            mut sampling,
            durable_guard,
            index: mut index_storage,
            source,
            roots,
            collected_at,
            backfill_window_days,
            file_limit,
            artifacts_enabled,
            context_curve_enabled,
            claude_request_identity_capture,
            claude_effort_support_dir,
            codex_title_metadata,
            mut claude_title_metadata,
            state_census_complete,
            sidecar_census_complete,
            codex_turn_traces,
            mut codex_parent_identities,
            codex_parent_ownership_ledgers,
            census_window_end,
            discovered_file_count,
            census_unix_seconds,
            mut census,
            mut snapshots,
            mut scanned_file_count,
            mut scanned_session_count,
            mut semantic_noop_count,
            mut history_upgrade,
            mut codex_state_only_blocked_session_ids,
            mut codex_parent_resolution_retry_required,
            mut residue_index_keys,
            mut settled_residue_index_keys,
            mut residue_blocked_session_ids,
            mut pending_finalization,
            claude_authority_preflight,
            mut forced_claude_family_reparses,
            claude_twin_only_family_reparses,
            mut identified_candidates,
            active_file: active_frame,
            mut codex_join_inventory,
            mut codex_join_prepared,
            mut codex_join_groups,
            mut codex_join_active,
            mut codex_join_completed,
            mut codex_legacy_join_baselines,
            mut codex_page,
            codex_selected_flags,
            codex_side_pass,
            mut continuation_ticket,
            mut line_delivery,
            codex_versions,
        } = self;
        // Held while this scan object runs the shared cursor job.
        let (mut active_file, mut codex_cursor_lease) = active_frame.into_parts();
        let index = &mut index_storage;
        // L-5: a resumed step re-probes everything it needs.
        codex_parent_identities.begin_step();
        // PR-P: once per page, on a selecting page (discovery done), before any
        // candidate is classified: apply the namespace's parent witnesses and
        // decide the restart budget.
        if source == SnapshotSource::Codex
            && !codex_page.continuation()
            && !codex_parent_identities.parents_applied
            && index
                .traversal
                .as_ref()
                .is_some_and(|traversal| traversal.pending_directories.is_empty())
        {
            if let Some(context) = sampling.as_ref() {
                codex_parent_step_start(
                    index,
                    context,
                    &mut codex_parent_identities,
                    &mut codex_page,
                    codex_parent_ownership_ledgers.as_ref(),
                    census_unix_seconds,
                    backfill_window_days,
                );
            }
            codex_parent_identities.parents_applied = true;
        }
        let claude_effort_support_dir_ref = claude_effort_support_dir.as_deref();
        // Construct the large continuation once. Repeating it in every yield
        // branch multiplies debug-build stack slots and can overflow native
        // callers even though the retained scanner state is unchanged.
        'scan_step: {
            macro_rules! pending {
                () => {
                    break 'scan_step
                };
            }
            if source == SnapshotSource::Codex && !codex_join_prepared {
                if let Some(inventory) = codex_join_inventory.as_mut() {
                    if !inventory.step_cached(
                        &codex_title_metadata,
                        sampling.as_ref().map(|context| context.cache.as_ref()),
                    ) {
                        pending!();
                    }
                    let selected = identified_candidates
                        .iter()
                        .map(|candidate| local_index_key(&candidate.path))
                        .collect::<BTreeSet<_>>();
                    let inventoried = inventory
                        .headers
                        .iter()
                        .map(|header| local_index_key(&header.candidate.path))
                        .collect::<BTreeSet<_>>();
                    inventory.complete &= selected.is_subset(&inventoried);
                    let mut owners = BTreeMap::<String, BTreeSet<PathBuf>>::new();
                    for header in &inventory.headers {
                        owners
                            .entry(header.owner.clone())
                            .or_default()
                            .insert(header.home.clone());
                    }
                    let current_owners = inventory
                        .headers
                        .iter()
                        .map(|header| {
                            (
                                local_index_key(&header.candidate.path),
                                codex_protected_owner(&header.owner),
                            )
                        })
                        .collect::<BTreeMap<_, _>>();
                    let absence_coverage =
                        codex_counting_version::absence_coverage_complete(index, inventory);
                    codex_counting_version::note_inventory_created(index, inventory);
                    codex_counting_version::prepare_moved_evidence(
                        index,
                        &current_owners,
                        absence_coverage,
                    );
                    let mut repurposed_protected_paths = BTreeSet::new();
                    let mut missing_protected_owners = BTreeSet::new();
                    let mut missing_unknown_owner = false;
                    for owner in index.decode_held_codex_owners() {
                        match owner {
                            Some(owner) => {
                                missing_protected_owners.insert(owner.to_owned());
                            }
                            None => missing_unknown_owner = true,
                        }
                    }
                    for (key, entry) in &index.files {
                        let repurposed = entry.codex_history_is_protected()
                            && entry
                                .codex_protected_owner
                                .as_ref()
                                .is_some_and(|previous| {
                                    current_owners
                                        .get(key)
                                        .is_some_and(|current| current != previous)
                                });
                        if repurposed {
                            repurposed_protected_paths.insert(key.clone());
                        }
                        if entry.codex_history_is_protected()
                            && (!inventoried.contains(key) || repurposed)
                        {
                            if let Some(owner) = entry
                                .codex_protected_owner
                                .as_ref()
                                .filter(|owner| valid_codex_protected_owner(owner))
                            {
                                missing_protected_owners.insert(owner.clone());
                            } else {
                                missing_unknown_owner = true;
                            }
                        }
                    }
                    let mut grouped_paths = BTreeSet::new();
                    let mut used = 0usize;
                    // R2-N6: a group with more members than the page's file
                    // limit is never excluded; it goes first and takes a page
                    // of its own (it pages through the cursor like any group).
                    // Round 3: so does a group whose probes outran a page's
                    // remaining singleton budget (`ProbeBudgetOrder`).
                    let fence = sampled_scan::codex_cursor::census_token(index);
                    let own_page = |group: &codex_file_join::Group| {
                        group.members.len() > file_limit
                            || sampling.as_ref().is_some_and(|context| {
                                context.cache.group_own_page(
                                    &context.namespace,
                                    &codex_file_join::job_key(group),
                                    fence.as_deref(),
                                )
                            })
                    };
                    let mut groups = inventory
                        .groups()
                        .into_values()
                        .map(|group| (own_page(&group), group))
                        .collect::<Vec<_>>();
                    // G1: after own-page groups, census members' groups go
                    // ahead of groups whose selected members are re-reads.
                    groups.sort_by_key(|(own, group)| {
                        (
                            !*own,
                            !sampled_scan::codex_cursor::census_member(
                                &codex_selected_flags,
                                group.members.iter().map(|member| member.path.as_path()),
                            ),
                        )
                    });
                    for (own, group) in groups {
                        if group
                            .members
                            .iter()
                            .any(|member| index.decode_holds_file(&local_index_key(&member.path)))
                        {
                            grouped_paths.extend(
                                group
                                    .members
                                    .iter()
                                    .map(|member| local_index_key(&member.path)),
                            );
                            index.mark_bounded_sweep_unsettled();
                            continue;
                        }
                        let protected_history_missing = missing_unknown_owner
                            || missing_protected_owners
                                .contains(&codex_protected_owner(&group.owner));
                        let previously_joined = group.members.iter().any(|member| {
                            index
                                .files
                                .get(&local_index_key(&member.path))
                                .is_some_and(|entry| {
                                    entry.codex_joined_member_set.is_some()
                                        || entry.codex_captured_joined_member_set.is_some()
                                })
                        });
                        if (group.members.len() < 2
                            && !previously_joined
                            && !protected_history_missing
                            && owners
                                .get(&group.owner)
                                .map_or(true, |homes| homes.len() <= 1))
                            || !group
                                .members
                                .iter()
                                .any(|member| selected.contains(&local_index_key(&member.path)))
                        {
                            continue;
                        }
                        grouped_paths.extend(
                            group
                                .members
                                .iter()
                                .map(|member| local_index_key(&member.path)),
                        );
                        // §d.1.2 c: a paused or active cursor job owns a
                        // member. Its selected members stay pending (holding
                        // the census) and are not read again while it lives.
                        if let Some(context) = sampling.as_ref().filter(|context| {
                            group.members.iter().any(|member| {
                                context
                                    .cache
                                    .cursor_job_owns(&local_index_key(&member.path))
                            })
                        }) {
                            let owned = group
                                .members
                                .iter()
                                .filter(|member| selected.contains(&local_index_key(&member.path)))
                                .collect::<Vec<_>>();
                            for _ in &owned {
                                context.cache.note_join_in_progress();
                            }
                            sampled_scan::codex_cursor::requeue_members(
                                index,
                                &codex_selected_flags,
                                owned,
                            );
                            continue;
                        }
                        let malformed_pending = group.members.iter().any(|member| {
                            index
                                .files
                                .get(&local_index_key(&member.path))
                                .is_some_and(|entry| {
                                    entry
                                        .codex_captured_joined_member_set
                                        .as_deref()
                                        .is_some_and(|marker| {
                                            !codex_file_join::valid_captured_join(marker)
                                        })
                                })
                        });
                        if !inventory.complete
                            || malformed_pending
                            || protected_history_missing
                            || group.members.iter().any(|member| {
                                repurposed_protected_paths.contains(&local_index_key(&member.path))
                            })
                            || owners
                                .get(&group.owner)
                                .is_some_and(|homes| homes.len() > 1)
                            || group.members.len() < 2
                        {
                            census.ownership_incomplete_file_count += group.members.len();
                            census.causes.add(ownership::INVENTORY, group.members.len());
                            census.record_unreadable(UnreadableCause::AliasParser, 1);
                            residue_index_keys.extend(
                                group
                                    .members
                                    .iter()
                                    .map(|member| local_index_key(&member.path)),
                            );
                            residue_blocked_session_ids.insert(group.owner.clone());
                            codex_state_only_blocked_session_ids.insert(group.owner.clone());
                            continue;
                        }
                        // G1: a group whose attempt already ended in this
                        // generation is fenced at its pop (M-5 b) and reads
                        // nothing. Decide it here, so it takes no file
                        // allowance a waiting census member needs.
                        let fenced = sampling.as_ref().is_some_and(|context| {
                            context.cache.group_fenced(
                                &context.namespace,
                                &codex_file_join::job_key(&group),
                                fence.as_deref(),
                            )
                        });
                        // G1: a group whose selected members are all re-reads
                        // never takes file allowance a waiting census-member
                        // singleton needs (own page or not). It waits for a
                        // page without one; its members stay pending as
                        // re-reads.
                        let rereads_crowd_members = !fenced
                            && !sampled_scan::codex_cursor::census_member(
                                &codex_selected_flags,
                                group.members.iter().map(|member| member.path.as_path()),
                            )
                            && {
                                let waiting = identified_candidates
                                    .iter()
                                    .filter(|candidate| {
                                        let key = local_index_key(&candidate.path);
                                        !grouped_paths.contains(&key)
                                            && sampled_scan::codex_cursor::selected_census_member(
                                                &codex_selected_flags,
                                                &candidate.path,
                                            )
                                    })
                                    .count();
                                waiting > 0
                                    && (own || used + group.members.len() + waiting > file_limit)
                            };
                        if rereads_crowd_members
                            || (!fenced
                                && used > 0
                                && (own || used + group.members.len() > file_limit))
                        {
                            // Keep the existing traversal as the only queue. A whole
                            // group is selected on a subsequent ordinary page.
                            if let Some(traversal) = index.traversal.as_mut() {
                                for member in &group.members {
                                    if selected.contains(&local_index_key(&member.path)) {
                                        traversal.pending_candidates.push_back(ScanTraversalPath {
                                            scan_root: member.scan_root.clone(),
                                            path: member.path.clone(),
                                            // G1: a re-read is not re-enrolled.
                                            census_member:
                                                sampled_scan::codex_cursor::selected_census_member(
                                                    &codex_selected_flags,
                                                    &member.path,
                                                ),
                                            watcher_hint: false,
                                        });
                                    }
                                }
                            }
                            continue;
                        }
                        if !fenced {
                            used += group.members.len();
                            if own {
                                // Nothing else joins its page.
                                used = used.max(file_limit);
                            }
                        }
                        if let Some(traversal) = index.traversal.as_mut() {
                            // R2-L3: one set per group, not a member scan per
                            // pending path.
                            let paths = group
                                .members
                                .iter()
                                .map(|member| member.path.as_path())
                                .collect::<std::collections::HashSet<_>>();
                            traversal
                                .pending_candidates
                                .retain(|pending| !paths.contains(pending.path.as_path()));
                        }
                        // F8 (§d.1.3): a queued group's owner has no state-only
                        // body in this scan object or across a restart until
                        // its exclusive body is accepted; B records the
                        // provenance for the L-1 release.
                        codex_state_only_blocked_session_ids.insert(group.owner.clone());
                        index
                            .codex_state_only_blocked_session_ids
                            .insert(group.owner.clone());
                        index
                            .codex_state_only_blocked_unattributed
                            .insert(group.owner.clone());
                        if let Some(context) = sampling.as_ref() {
                            context
                                .cache
                                .record_join_owner(&group.owner, &group.members);
                        }
                        if !fenced {
                            codex_join_groups.push_back(group);
                        }
                    }
                    // F8: the paused group job's owner, in every scan object.
                    if let Some(owner) = sampling
                        .as_ref()
                        .and_then(|context| context.cache.cursor_group_owner())
                    {
                        codex_state_only_blocked_session_ids.insert(owner.clone());
                        index
                            .codex_state_only_blocked_unattributed
                            .insert(owner.clone());
                        index.codex_state_only_blocked_session_ids.insert(owner);
                    }
                    identified_candidates.retain(|candidate| {
                        !grouped_paths.contains(&local_index_key(&candidate.path))
                    });
                    if !inventory.complete {
                        census.record_unreadable(UnreadableCause::AliasParser, 1);
                        census.ownership_incomplete_file_count += identified_candidates.len();
                        census
                            .causes
                            .add(ownership::INVENTORY, identified_candidates.len());
                        residue_index_keys.extend(
                            identified_candidates
                                .iter()
                                .map(|candidate| local_index_key(&candidate.path)),
                        );
                        let held_owners = inventory
                            .headers
                            .iter()
                            .filter(|header| {
                                selected.contains(&local_index_key(&header.candidate.path))
                            })
                            .map(|header| header.owner.clone())
                            .collect::<BTreeSet<_>>();
                        residue_blocked_session_ids.extend(held_owners.iter().cloned());
                        codex_state_only_blocked_session_ids.extend(held_owners);
                        identified_candidates.clear();
                    }
                    while !identified_candidates.is_empty()
                        && used + identified_candidates.len() > file_limit
                    {
                        // G1: re-reads leave before any census member.
                        let evict = identified_candidates
                            .iter()
                            .rposition(|candidate| {
                                !sampled_scan::codex_cursor::selected_census_member(
                                    &codex_selected_flags,
                                    &candidate.path,
                                )
                            })
                            .unwrap_or(identified_candidates.len() - 1);
                        if let Some(candidate) = identified_candidates.remove(evict) {
                            if let Some(traversal) = index.traversal.as_mut() {
                                // G1: a re-read is not re-enrolled.
                                let census_member =
                                    sampled_scan::codex_cursor::selected_census_member(
                                        &codex_selected_flags,
                                        &candidate.path,
                                    );
                                traversal.pending_candidates.push_front(ScanTraversalPath {
                                    scan_root: candidate.scan_root,
                                    path: candidate.path,
                                    census_member,
                                    watcher_hint: false,
                                });
                            }
                        }
                    }
                }
                codex_join_prepared = true;
                pending!();
            }
            if let Some(mut boot) = codex_join_active.take() {
                // R2-N2: a group larger than the singleton budget asks for
                // the cursor before its first header read; one that would
                // wait (or is fenced) reads no header or probe this page.
                // Round 3 (R2-M1): only after the unchanged decision, and
                // never for a group with a memo entry or parked record: those
                // reach their lookups first and leave without the slot.
                if let Some(context) = sampling.as_ref().filter(|context| {
                    boot.awaits_read()
                        && crate::heap_layout_bound::layout_supported()
                        && boot.expected_bytes()
                            > sampled_scan::codex_cursor::Limits::current().singleton()
                        && !context.cache.group_recorded(&context.namespace, &boot.key)
                }) {
                    match context.cache.cursor_plan(
                        &mut codex_page,
                        sampled_scan::codex_cursor::Limits::current(),
                        boot.expected_bytes(),
                        codex_cursor_lease.is_none() && context.cache.cursor_slot_free(),
                        true,
                        &context.namespace,
                        &boot.key,
                        sampled_scan::codex_cursor::census_token(index).as_deref(),
                        sampled_scan::codex_cursor::census_member(
                            &codex_selected_flags,
                            boot.group
                                .members
                                .iter()
                                .map(|member| member.path.as_path()),
                        ),
                    ) {
                        sampled_scan::codex_cursor::StartPlan::Defer => {
                            context.cache.cursor_note_deferred();
                            if boot.own_page {
                                context
                                    .cache
                                    .request_group_own_page(&context.namespace, &boot.key);
                            }
                            scanned_file_count =
                                scanned_file_count.saturating_sub(boot.group.members.len());
                            sampled_scan::codex_cursor::requeue_members(
                                index,
                                &codex_selected_flags,
                                &boot.group.members,
                            );
                            pending!();
                        }
                        sampled_scan::codex_cursor::StartPlan::Fenced => {
                            scanned_file_count =
                                scanned_file_count.saturating_sub(boot.group.members.len());
                            pending!();
                        }
                        _ => {}
                    }
                }
                boot.allow_probe_bytes(
                    codex_page.singleton_remaining(sampled_scan::codex_cursor::Limits::current()),
                );
                let outcome = boot.step_with_cache(
                    attribution_context,
                    index,
                    sampling.as_ref().map(|context| context.cache.as_ref()),
                );
                // Header and probe bytes are singleton-budget reads (§d.2).
                codex_page.charge(false, boot.take_charge());
                let members = boot.group.members.len();
                match outcome {
                    codex_file_join::Boot::Pending => {
                        codex_join_active = Some(boot);
                        pending!();
                    }
                    codex_file_join::Boot::Unchanged => {
                        // R1-L3: the accepted joined body is current, with no
                        // job or debt: the persisted block F8 (or a previous
                        // process) set is released, as an accepted exclusive
                        // body releases it, unless this scan holds the owner
                        // as residue.
                        if !residue_blocked_session_ids.contains(&boot.group.owner) {
                            // L-SB: the accepted joined body supersedes the
                            // members' own block on the owner; any other key
                            // still blocking it keeps it.
                            index.accept_codex_block(
                                boot.group
                                    .members
                                    .iter()
                                    .map(|member| local_index_key(&member.path)),
                                &boot.group.owner,
                            );
                        }
                        // R2-M1: nothing read for a job; it does not wait.
                        if let Some(context) = sampling.as_ref() {
                            context.cache.cursor_unwait(&context.namespace, &boot.key);
                        }
                        semantic_noop_count += members;
                        census.note_codex_group(CodexSelection::GroupUnchanged, members);
                        codex_join_completed.push(boot.group);
                        pending!();
                    }
                    codex_file_join::Boot::Strict => {
                        if let Some(context) = sampling.as_ref() {
                            context.cache.cursor_unwait(&context.namespace, &boot.key);
                        }
                        codex_file_join::disclose_strict(
                            &boot.group.owner,
                            &boot.group.members,
                            sampled_scan::codex_cursor::DisclosureTargets {
                                census: &mut census,
                                residue_index_keys: &mut residue_index_keys,
                                residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                codex_state_only_blocked_session_ids:
                                    &mut codex_state_only_blocked_session_ids,
                                pending_finalization: &mut pending_finalization,
                            },
                        );
                        pending!();
                    }
                    codex_file_join::Boot::Refused(reason) => {
                        // Decided from headers at no replay cost: terminal
                        // debt (outcome R), fenced, never memoized.
                        if let Some(context) = sampling.as_ref() {
                            context.cache.note_join_refusal(reason);
                            context.cache.group_attempted(
                                &context.namespace,
                                &boot.key,
                                sampled_scan::codex_cursor::census_token(index).as_deref(),
                            );
                        }
                        codex_file_join::disclose_members(
                            &codex_file_join::refusal_disclosure(&boot.group.owner),
                            &boot.group.members,
                            index,
                            sampled_scan::codex_cursor::DisclosureTargets {
                                census: &mut census,
                                residue_index_keys: &mut residue_index_keys,
                                residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                codex_state_only_blocked_session_ids:
                                    &mut codex_state_only_blocked_session_ids,
                                pending_finalization: &mut pending_finalization,
                            },
                        );
                        pending!();
                    }
                    codex_file_join::Boot::Ready => {
                        census.note_codex_group(CodexSelection::GroupSelected, members);
                    }
                }
                let expected = boot.expected_bytes();
                let dependencies = boot.dependencies(&codex_title_metadata);
                let mut paged = false;
                if let Some(context) = sampling.as_ref() {
                    if boot.probe_bound {
                        context.cache.note_probe_bound();
                    }
                    let live_file = boot.live().and_then(|(live, _)| {
                        open_candidate_file_stat_retained(
                            SnapshotSource::Codex,
                            &mut live.clone(),
                            Some(&context.cache),
                        )
                        .ok()
                        .map(|(file, _)| file)
                    });
                    let wake_stamp =
                        boot.live()
                            .zip(live_file.as_ref())
                            .and_then(|((live, _), file)| {
                                sampled_scan::codex_cursor::OpenStamp::capture(file)
                                    .ok()
                                    .map(|stamp| context.cache.retained_stamp(&live.path, stamp))
                            });
                    let memo_key =
                        sampled_scan::codex_cursor::memo_key(&context.namespace, &boot.key);
                    if let Some(entry) = context.cache.memo_lookup(&memo_key) {
                        // The match re-reads two samples of the live member (M3).
                        codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                        let hit = boot
                            .memo_digest(index, &codex_title_metadata)
                            .zip(live_file.as_ref())
                            .and_then(|(digest, file)| {
                                entry.matches_stamp(
                                    &boot.live()?.0.path,
                                    &digest,
                                    file,
                                    None,
                                    "",
                                    wake_stamp.clone()?,
                                )
                            });
                        if let Some(stamp) = hit {
                            // No wake dependency changed: the same terminal
                            // debt again, per member, at zero replay bytes.
                            context.cache.memo_hit(&memo_key, stamp);
                            context.cache.note_group_memo_hit();
                            context.cache.cursor_unwait(&context.namespace, &boot.key);
                            codex_file_join::disclose_members(
                                entry.disclosure(),
                                &boot.group.members,
                                index,
                                sampled_scan::codex_cursor::DisclosureTargets {
                                    census: &mut census,
                                    residue_index_keys: &mut residue_index_keys,
                                    residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                    codex_state_only_blocked_session_ids:
                                        &mut codex_state_only_blocked_session_ids,
                                    pending_finalization: &mut pending_finalization,
                                },
                            );
                            pending!();
                        }
                        context.cache.memo_forget(&memo_key);
                    }
                    let parked = context.cache.cursor_parked_stamp(
                        &boot.key,
                        wake_stamp,
                        dependencies.as_deref(),
                    );
                    if let Some(disclosure) = parked {
                        context.cache.cursor_unwait(&context.namespace, &boot.key);
                        codex_file_join::disclose_members(
                            &disclosure,
                            &boot.group.members,
                            index,
                            sampled_scan::codex_cursor::DisclosureTargets {
                                census: &mut census,
                                residue_index_keys: &mut residue_index_keys,
                                residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                codex_state_only_blocked_session_ids:
                                    &mut codex_state_only_blocked_session_ids,
                                pending_finalization: &mut pending_finalization,
                            },
                        );
                        pending!();
                    }
                    match context.cache.cursor_plan(
                        &mut codex_page,
                        sampled_scan::codex_cursor::Limits::current(),
                        expected,
                        codex_cursor_lease.is_none() && context.cache.cursor_slot_free(),
                        crate::heap_layout_bound::layout_supported(),
                        &context.namespace,
                        &boot.key,
                        sampled_scan::codex_cursor::census_token(index).as_deref(),
                        sampled_scan::codex_cursor::census_member(
                            &codex_selected_flags,
                            boot.group
                                .members
                                .iter()
                                .map(|member| member.path.as_path()),
                        ),
                    ) {
                        sampled_scan::codex_cursor::StartPlan::Singleton => {}
                        sampled_scan::codex_cursor::StartPlan::Cursor => paged = true,
                        sampled_scan::codex_cursor::StartPlan::Unpaged => {
                            codex_page.disclose_disabled(&context.cache);
                        }
                        sampled_scan::codex_cursor::StartPlan::Defer => {
                            // The whole group waits its turn on a later page.
                            context.cache.cursor_note_deferred();
                            if boot.own_page {
                                context
                                    .cache
                                    .request_group_own_page(&context.namespace, &boot.key);
                            }
                            scanned_file_count = scanned_file_count.saturating_sub(members);
                            sampled_scan::codex_cursor::requeue_members(
                                index,
                                &codex_selected_flags,
                                &boot.group.members,
                            );
                            pending!();
                        }
                        // Processed for this generation (K7 fence).
                        sampled_scan::codex_cursor::StartPlan::Fenced => {
                            scanned_file_count = scanned_file_count.saturating_sub(members);
                            pending!();
                        }
                    }
                }
                // No group byte or member cap (R1-M4): a group larger than
                // the singleton budget pages through the cursor; without one
                // (unsupported layout, uncached scan) it is read in one page
                // like main's unpaged read: each member at most
                // `MAX_CODEX_JSONL_FILE_BYTES`, the group's total uncapped
                // (R2-N7, disclosed).
                let active_dependencies = boot.live().map(|(live, _)| {
                    sampled_scan::codex_cursor::group_dependencies(
                        &boot.group.members,
                        &live.path,
                        &codex_title_metadata,
                        |member| member.opened_object_identity.clone(),
                    )
                });
                let owner = boot.group.owner.clone();
                let group_members = boot.group.members.clone();
                let boot_key = boot.key.clone();
                let job = boot.into_job(codex_file_join::JobInputs {
                    metadata: &codex_title_metadata,
                    traces: codex_turn_traces.clone(),
                    ledgers: codex_parent_ownership_ledgers.clone(),
                    artifacts: artifacts_enabled,
                    context_curve: context_curve_enabled,
                    index,
                });
                let Ok(mut job) = job else {
                    // Round 4 (L1): no lease exists yet; a waiter it left is
                    // dropped like the boot-`Strict` exit's.
                    if let Some(context) = sampling.as_ref() {
                        context.cache.cursor_unwait(&context.namespace, &boot_key);
                    }
                    codex_file_join::disclose_strict(
                        &owner,
                        &group_members,
                        sampled_scan::codex_cursor::DisclosureTargets {
                            census: &mut census,
                            residue_index_keys: &mut residue_index_keys,
                            residue_blocked_session_ids: &mut residue_blocked_session_ids,
                            codex_state_only_blocked_session_ids:
                                &mut codex_state_only_blocked_session_ids,
                            pending_finalization: &mut pending_finalization,
                        },
                    );
                    pending!();
                };
                if let Some(context) = sampling.as_ref().filter(|_| paged) {
                    match context.cache.cursor_start_group(
                        &mut job,
                        &context.namespace,
                        active_dependencies,
                        state_census_complete && sidecar_census_complete,
                        index,
                    ) {
                        Ok(lease) => {
                            // The members hold the strict census until the
                            // job's attempt ends (accepted or debt).
                            sampled_scan::codex_cursor::requeue_members(
                                index,
                                &codex_selected_flags,
                                &group_members,
                            );
                            codex_cursor_lease = Some(lease);
                        }
                        Err(sampled_scan::codex_cursor::StartRefusal::Busy) => {
                            context.cache.cursor_note_deferred();
                            scanned_file_count = scanned_file_count.saturating_sub(members);
                            sampled_scan::codex_cursor::requeue_members(
                                index,
                                &codex_selected_flags,
                                &group_members,
                            );
                            pending!();
                        }
                        // Never an unbounded in-page read of a group larger
                        // than the singleton budget (compressed members > B
                        // keep refusing, named debt).
                        Err(_) => {
                            census.record_unreadable(UnreadableCause::OpenRead, 1);
                            codex_state_only_blocked_session_ids.insert(owner);
                            pending!();
                        }
                    }
                }
                #[cfg(unix)]
                if let (Some(cache), Some(group)) = (
                    durable_guard.as_ref().and_then(std::sync::Weak::upgrade),
                    job.group.as_mut(),
                ) {
                    // Each member's missing-carrier deadline rides with the
                    // job across pause and defer to its own native entry.
                    if let Some((member, reason)) = group_members.iter().find_map(|member| {
                        let mut due = None;
                        let key = local_index_key(&member.path);
                        let held = cache.durable_member_hold(source, &key, index, &mut due);
                        if let Some(at) = group.members.iter().position(|m| m.path == member.path) {
                            group.recovered[at] = due;
                        }
                        held.map(|reason| (member, reason))
                    }) {
                        cache.durable_hold_exit(source, reason, index, member, &mut census);
                        pending!();
                    }
                }
                active_file = Some(job);
                pending!();
            }
            if source == SnapshotSource::Codex
                && active_file.is_none()
                && codex_join_active.is_none()
            {
                // A lease without an active file means this scan lost its job
                // on an error path; dropping the lease frees the slot.
                codex_cursor_lease = None;
                if let Some(context) = sampling.as_ref() {
                    codex_page.note_page(&context.cache, &context.namespace);
                }
                // E2: at most one resume attempt per page, and none on a page
                // that selected no candidates (no header inventory: no
                // evidence for the job this page). A deferred job therefore
                // never spins within a page.
                if let Some(context) = sampling.as_ref().filter(|_| {
                    !codex_page.cursor_exhausted(sampled_scan::codex_cursor::Limits::current())
                        && codex_join_inventory.is_some()
                        && (!codex_page.continuation() || codex_parent_identities.census_valid())
                        && codex_page.claim_resume()
                }) {
                    // Continuing the paused job is the highest scheduling class.
                    match sampled_scan::codex_cursor::resume_paused_job(
                        sampled_scan::codex_cursor::ResumeContext {
                            source,
                            sampling: context,
                            codex: &codex_title_metadata,
                            claude: &claude_title_metadata,
                            support: claude_effort_support_dir_ref,
                            context_curve_enabled,
                            traces: codex_turn_traces.clone(),
                            parents: codex_parent_ownership_ledgers.clone(),
                            inventory: codex_join_inventory.as_ref(),
                            flags: &codex_selected_flags,
                            census_complete: state_census_complete && sidecar_census_complete,
                            continuation: codex_page.continuation(),
                            ordinary_equivalent: codex_page.ordinary_equivalent(),
                        },
                        index,
                        &mut identified_candidates,
                        sampled_scan::codex_cursor::DisclosureTargets {
                            census: &mut census,
                            residue_index_keys: &mut residue_index_keys,
                            residue_blocked_session_ids: &mut residue_blocked_session_ids,
                            codex_state_only_blocked_session_ids:
                                &mut codex_state_only_blocked_session_ids,
                            pending_finalization: &mut pending_finalization,
                        },
                    ) {
                        sampled_scan::codex_cursor::Resumed::Active(job, lease) => {
                            codex_cursor_lease = Some(lease);
                            active_file = Some(job);
                            pending!();
                        }
                        // Deferred, invalidated or ended as strict debt: this
                        // page is spent; a pending path resumes or restarts.
                        sampled_scan::codex_cursor::Resumed::Spent => pending!(),
                        sampled_scan::codex_cursor::Resumed::Idle => {}
                    }
                }
                // Stage 1 hunk D: a continuation page only resumes. Without
                // an active job it plans and starts nothing: every path it
                // identified, and every group it prepared, goes back to the
                // queue untouched, and the page finishes.
                if codex_page.continuation() {
                    for candidate in identified_candidates.drain(..) {
                        sampled_scan::codex_cursor::requeue(
                            index,
                            &codex_selected_flags,
                            &candidate,
                        );
                    }
                    for group in codex_join_groups.drain(..) {
                        sampled_scan::codex_cursor::requeue_members(
                            index,
                            &codex_selected_flags,
                            &group.members,
                        );
                    }
                }
            }
            // G1 (fix 2): a group whose selected members are all re-reads
            // waits until this page's census singletons are read, so its
            // replay cannot spend the singleton budget a first read needs.
            // Evaluated between files only, and the candidate scan only when
            // the next group is a re-read.
            let rereads_wait = || {
                codex_join_groups.front().is_some_and(|group| {
                    !sampled_scan::codex_cursor::census_member(
                        &codex_selected_flags,
                        group.members.iter().map(|member| member.path.as_path()),
                    )
                }) && identified_candidates.iter().any(|candidate| {
                    sampled_scan::codex_cursor::selected_census_member(
                        &codex_selected_flags,
                        &candidate.path,
                    )
                })
            };
            if active_file.is_none() && !rereads_wait() {
                if let Some(group) = codex_join_groups.pop_front() {
                    if group
                        .members
                        .iter()
                        .any(|member| index.decode_holds_file(&local_index_key(&member.path)))
                    {
                        index.mark_bounded_sweep_unsettled();
                        pending!();
                    }
                    // Grouped members bypass the per-candidate guard: one held member holds the group.
                    #[cfg(unix)]
                    if let Some(cache) = durable_guard.as_ref().and_then(std::sync::Weak::upgrade) {
                        if let Some((member, reason)) = group.members.iter().find_map(|member| {
                            Some((
                                member,
                                cache.durable_full_hold(
                                    source,
                                    &local_index_key(&member.path),
                                    false,
                                )?,
                            ))
                        }) {
                            cache.durable_hold_exit(source, reason, index, member, &mut census);
                            pending!();
                        }
                    }
                    // M-5 (b): a group whose attempt already ended as terminal
                    // debt in this generation is not attempted again; its
                    // members were disclosed then.
                    let fenced = sampling.as_ref().is_some_and(|context| {
                        context.cache.group_fenced(
                            &context.namespace,
                            &codex_file_join::job_key(&group),
                            sampled_scan::codex_cursor::census_token(index).as_deref(),
                        )
                    });
                    if !fenced {
                        scanned_file_count += group.members.len();
                        let mut boot = Box::new(codex_file_join::GroupBoot::new(group, index));
                        if let Some(context) = sampling.as_ref() {
                            boot.own_page = context
                                .cache
                                .take_group_own_page(&context.namespace, &boot.key);
                        }
                        codex_join_active = Some(boot);
                    }
                    pending!();
                }
            }
            if let Some(mut active) = active_file.take() {
                let before_body_read = active.parser.reader.consumed_bytes();
                if let Some(delivery) = line_delivery.as_mut() {
                    delivery.begin_armed(&active, &roots);
                }
                let mut group_end = None;
                let stepped = if active.group.is_some() {
                    // A group job: one record of the current member, or one
                    // member transition (P2).
                    let live_scope = |member: &CandidateFile| {
                        let context = sampling.as_ref()?;
                        let dependency = sampled_scan::reduction_dependencies(
                            source,
                            member,
                            &codex_title_metadata,
                            &claude_title_metadata,
                            claude_effort_support_dir_ref,
                        )?;
                        Some(context.file_scope(
                            source,
                            member,
                            &dependency,
                            true,
                            context_curve_enabled,
                            index,
                        ))
                    };
                    match codex_file_join::step_group(
                        &mut active,
                        &codex_file_join::StepInputs {
                            metadata: &codex_title_metadata,
                            attribution: attribution_context,
                            artifacts: artifacts_enabled,
                            context_curve: context_curve_enabled,
                            live_scope: &live_scope,
                        },
                    ) {
                        codex_file_join::GroupStep::Read(result) => result,
                        codex_file_join::GroupStep::End(end) => {
                            group_end = Some(end);
                            Ok(false)
                        }
                    }
                } else if let Some(delivery) = line_delivery.as_mut() {
                    delivery.step(&mut active.parser)
                } else {
                    active.parser.step()
                };
                if source == SnapshotSource::ClaudeCode
                    && before_body_read == 0
                    && active.parser.reader.consumed_bytes() > 0
                {
                    // Count only the first actual body bytes. SourceChanged
                    // includes Desktop/usage sidecar and object revisions;
                    // ScopeChanged also catches a metadata change concurrent
                    // with growth (whose selection reason is TranscriptChanged).
                    // LegacyIdentity is the separate one-time legacy upgrade.
                    if claude_title_metadata
                        .recovered_account_holds
                        .contains(&local_index_key(&active.candidate.path))
                    {
                        crate::local_resource_diagnostics::claude_reread::desktop_recovered_hold_body_read();
                    } else {
                        match index.candidate_decision_with_reason(&active.candidate).1 {
                            Some(CandidateParseReason::LegacyIdentity) => {
                                crate::local_resource_diagnostics::claude_reread::desktop_revision_body_read(true);
                            }
                            reason if reason == Some(CandidateParseReason::SourceChanged)
                                || active.sampling.as_ref().is_some_and(|read| matches!(read.mode,
                                    crate::transcript_acquisition::ReadMode::Full(crate::transcript_acquisition::FullReason::ScopeChanged))) => {
                                crate::local_resource_diagnostics::claude_reread::desktop_revision_body_read(false);
                            }
                            _ => {}
                        }
                    }
                }
                if source == SnapshotSource::Codex {
                    let consumed = active.parser.reader.consumed_bytes();
                    let moved = codex_file_join::take_charge(&mut active);
                    codex_page.charge(
                        active.cursor.is_some(),
                        consumed
                            .saturating_sub(active.charged_bytes)
                            .saturating_add(moved),
                    );
                    active.charged_bytes = consumed;
                    if active.hold_offset.is_none()
                        && sampled_scan::codex_cursor::held_monotone(&active.parser.accumulator)
                    {
                        // File offset: a tail's reader counts from its start.
                        let start = active
                            .parser
                            .reader
                            .acquisition
                            .as_ref()
                            .map_or(0, crate::transcript_acquisition::ReadPlan::start_offset);
                        active.hold_offset =
                            Some(start + active.parser.reader.last_complete_line_end());
                    }
                }
                if let Some(end) = group_end {
                    codex_file_join::end_group(
                        active,
                        end,
                        codex_cursor_lease.take(),
                        codex_file_join::EndInputs {
                            sampling: sampling.as_ref(),
                            index,
                            targets: sampled_scan::codex_cursor::DisclosureTargets {
                                census: &mut census,
                                residue_index_keys: &mut residue_index_keys,
                                residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                codex_state_only_blocked_session_ids:
                                    &mut codex_state_only_blocked_session_ids,
                                pending_finalization: &mut pending_finalization,
                            },
                        },
                    );
                    pending!();
                }
                match stepped {
                    Ok(false) => {
                        // Stage 1 (K6): or a continuation page past its
                        // deadline, which pauses without a ticket.
                        if active.cursor.is_some()
                            && codex_page.cursor_stop(sampled_scan::codex_cursor::Limits::current())
                        {
                            if let Some(lease) = codex_cursor_lease.take() {
                                // Stage 1 hunk A: minted before the pause
                                // consumes the job, kept only if it pauses.
                                let ticket = sampling.as_ref().and_then(|context| {
                                    context.cache.continuation_ticket(&active, &codex_page)
                                });
                                continuation_ticket = None;
                                if let sampled_scan::codex_cursor::PauseEnd::StateBound(
                                    job,
                                    disclosure,
                                ) = lease.pause(active)
                                {
                                    // No unbounded fallback: `JoinStateBound`
                                    // debt, prior body kept, file parked.
                                    sampled_scan::codex_cursor::disclose_job_debt(
                                        &job,
                                        &disclosure,
                                        index,
                                        sampled_scan::codex_cursor::DisclosureTargets {
                                            census: &mut census,
                                            residue_index_keys: &mut residue_index_keys,
                                            residue_blocked_session_ids:
                                                &mut residue_blocked_session_ids,
                                            codex_state_only_blocked_session_ids:
                                                &mut codex_state_only_blocked_session_ids,
                                            pending_finalization: &mut pending_finalization,
                                        },
                                    );
                                    sampled_scan::codex_cursor::dequeue_members(
                                        index,
                                        sampled_scan::codex_cursor::job_files(&job),
                                    );
                                } else {
                                    continuation_ticket = ticket;
                                }
                                pending!();
                            }
                            // A job without its lease is dropped, never
                            // continued in-page past the budget; its pending
                            // path restarts it (L2).
                            if let Some(context) = sampling.as_ref() {
                                context.cache.cursor_note_lost();
                            }
                            pending!();
                        }
                        active_file = Some(active);
                        pending!();
                    }
                    Err(error) => {
                        // U1a-2a G14a: a side read error is its charged
                        // attempt; no census line, no dequeue.
                        if let Some(side) = active.side_origin.take() {
                            side.end();
                            pending!();
                        }
                        // Static reader text only, never a path or content. A
                        // live rollout appended while it is read reports
                        // "acquisition exceeds stable source"; that file is
                        // retried when its next write is hinted.
                        eprintln!(
                            "local snapshot scan: {} transcript read failed: {error}",
                            source.api_slug()
                        );
                        if let Some(lease) = codex_cursor_lease.take() {
                            lease.release();
                        }
                        if let Some(group) = active.group.as_ref() {
                            // A member read failure: strict, as before P2.
                            codex_file_join::disclose_strict(
                                &group.owner,
                                &group.members,
                                sampled_scan::codex_cursor::DisclosureTargets {
                                    census: &mut census,
                                    residue_index_keys: &mut residue_index_keys,
                                    residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                    codex_state_only_blocked_session_ids:
                                        &mut codex_state_only_blocked_session_ids,
                                    pending_finalization: &mut pending_finalization,
                                },
                            );
                            sampled_scan::codex_cursor::dequeue_members(index, &group.members);
                            pending!();
                        }
                        if active.cursor.is_some() {
                            sampled_scan::codex_cursor::dequeue(index, &active.candidate);
                        }
                        if source == SnapshotSource::ClaudeCode {
                            claude_request_census::invalidate_claude_request_census(
                                index,
                                &active.candidate.path,
                            );
                        }
                        census.record_unreadable(UnreadableCause::OpenRead, 1);
                        pending!();
                    }
                    Ok(true) if codex_page.continuation() => {
                        continuation_ticket = None;
                        if let Some(lease) = codex_cursor_lease.take() {
                            #[cfg(test)]
                            sampled_scan::codex_cursor::tests::constrain_eof_park(&mut active);
                            drop(lease.pause(active)); // StateBound: ordinary disclosure only.
                        }
                        pending!();
                    }
                    Ok(true) => {}
                }
                #[cfg(test)]
                AFTER_READER_EOF.with(|slot| {
                    if let Some(hook) = slot.borrow_mut().as_mut() {
                        hook(&active);
                    }
                });
                // H2c/E1: retain native trailing-line behavior at a genuine
                // unchanged EOF. A grown read keeps this fragment withheld.
                if source == SnapshotSource::ClaudeCode
                    && active.cursor.is_none()
                    && active.parser.reader.sealed_fragment()
                    && active
                        .parser
                        .reader
                        .acquisition
                        .as_ref()
                        .is_some_and(|plan| {
                            plan.start_offset()
                                .checked_add(active.parser.reader.consumed_bytes())
                                == Some(plan.frozen_length())
                                && active
                                    .parser
                                    .reader
                                    .reader
                                    .get_ref()
                                    .metadata()
                                    .is_ok_and(|held| held.len() == plan.frozen_length())
                        })
                {
                    active.parser.apply_sealed_fragment();
                }
                if active.cursor.is_some() && active.group.is_none() {
                    // E1 before the protected-tier gate below (R1-H1). A group
                    // job applies it to its live member in `member_eof`, before
                    // that member's proof ends (R2-N1).
                    sampled_scan::codex_cursor::apply_eof_record(&mut active);
                }
                // Consumer-only: publish retained native state at primary EOF.
                if active.is_primary_for(SnapshotSource::Codex) {
                    if let Some(feed) = codex_versions.as_ref() {
                        feed.observe(&active);
                    }
                }
                // U1a-2a B8′: a side read demands no launch workers (its
                // finish takes no attribution context), so G14b cannot fire.
                if let Some(context) = attribution_context.filter(|_| active.side_origin.is_none())
                {
                    let workers = launch_workers_for_parsed(
                        source,
                        active.parser.accumulator.source_session_id.as_deref(),
                        &active.candidate.path,
                    );
                    match context.prepare_launch_step(&workers) {
                        Ok(false) => {
                            active_file = Some(active);
                            pending!();
                        }
                        Err(()) => {
                            if source == SnapshotSource::ClaudeCode {
                                claude_request_census::invalidate_claude_request_census(
                                    index,
                                    &active.candidate.path,
                                );
                            }
                            census.record_unreadable(UnreadableCause::Reduction, 1);
                            pending!();
                        }
                        Ok(true) => {}
                    }
                }
                // U1a-2a G10b: a side read is not main's input.
                if let Some(context) = sampling.as_mut().filter(|_| active.side_origin.is_none()) {
                    if let Some(plan) = active.parser.reader.acquisition.as_ref() {
                        context.record_input(plan.metrics());
                        resource_probe.rearm_full_completed(
                            &local_index_key(&active.candidate.path),
                            plan.mode(),
                            plan.metrics().native_bytes,
                        );
                    }
                }
                if active.sampling.as_ref().is_some_and(|acquisition| {
                    !matches!(
                        acquisition.mode,
                        crate::transcript_acquisition::ReadMode::Full(_)
                    ) && active
                        .parser
                        .accumulator
                        .codex_tier_replay
                        .as_ref()
                        .is_some_and(codex_file_join::TierReplay::has_protected_tiers)
                }) {
                    // Native finish compares the reopened descriptor to the captured
                    // identity, so replacement during fallback cannot publish.
                    let reopened =
                        reopen_for_replay(source, &active.candidate, &active.parser.reader.reader);
                    let Ok(file) = reopened else {
                        census.record_unreadable(UnreadableCause::OpenRead, 1);
                        pending!();
                    };
                    let Ok(mut parser) = sampled_scan::new_source_parser(
                        file,
                        &active.candidate,
                        source,
                        &codex_title_metadata,
                        codex_turn_traces.clone(),
                        codex_parent_ownership_ledgers.clone(),
                        source != SnapshotSource::ClaudeCode || artifacts_enabled,
                        context_curve_enabled,
                        claude_request_identity_capture,
                        index,
                    ) else {
                        census.record_unreadable(UnreadableCause::Reduction, 1);
                        pending!();
                    };
                    // U1a-2a (D6(a)): the replacement parser gets the same
                    // P-fenced install (never on a side read).
                    if source == SnapshotSource::Codex && active.side_origin.is_none() {
                        let side = sampling
                            .as_ref()
                            .zip(codex_side_pass.as_ref())
                            .map(|(context, pass)| (&*context.cache, pass.ns));
                        if install_codex_parent_proof(
                            &mut parser,
                            &active.candidate,
                            index,
                            &codex_parent_identities,
                            side,
                            sampled_scan::now_seconds(),
                        ) {
                            // R1-M1: P's side fence and the proof seal.
                            codex_page.charge(false, PROOF_FENCE_READ_BYTES);
                        }
                    }
                    let acquisition = active.sampling.as_mut().expect("sampled acquisition");
                    let debt = sampled_audit::debt_for_key(
                        index,
                        &acquisition.key,
                        sampled_scan::now_seconds(),
                    );
                    let Ok(mode) = parser.prepare_acquisition(
                        None,
                        &acquisition.scope,
                        debt,
                        sampled_scan::now_seconds(),
                    ) else {
                        census.record_unreadable(UnreadableCause::Reduction, 1);
                        pending!();
                    };
                    acquisition.mode = mode;
                    if let Some(context) = sampling.as_mut() {
                        context.priority_replays += 1;
                        context.record_mode(mode, acquisition.audit_due);
                    }
                    active.parser = parser;
                    active.charged_bytes = 0;
                    active.hold_offset = None;
                    if active.cursor.is_some()
                        && !sampled_scan::codex_cursor::restart_in_place(&mut active)
                    {
                        // The full replay cannot be frozen: end this attempt
                        // (a retryable failure), never an unpaged read.
                        active.cursor = None;
                        if let Some(lease) = codex_cursor_lease.take() {
                            lease.release();
                        }
                        sampled_scan::codex_cursor::dequeue(index, &active.candidate);
                        census.record_unreadable(UnreadableCause::Reduction, 1);
                        pending!();
                    }
                    // LD: the replay is a fresh Full delivery from 0.
                    if let Some(delivery) = line_delivery.as_mut() {
                        delivery.arm();
                    }
                    active_file = Some(active);
                    pending!();
                }
                // E3: the completion step walks the finished job exactly,
                // once, for the budget its retention consumes below. A group
                // and an unsampled read keep the step-start budget. Any other
                // sampled singleton is measured exactly at completion
                // (P1-RETAIN R0, Q-PR13b; `try_lock`, so contention gives 0).
                // A Tail/Unchanged singleton (shape F) also decides whether a
                // release of lower-ranked residents would make its copy
                // fit; that release is deferred into its retention, after
                // every non-budget gate. Nothing is evicted here. Each branch
                // also returns the walk behind its budget (`copy_measure`, for
                // `retire_proof_beside_copy`); `copy_budget` is the
                // pre-release budget, which main's proof retirement and decode
                // peak reserve against (U1a-2a, #667).
                let (retain_budget, copy_measure, release_proof) = if active.cursor.is_some() {
                    let (budget, measure) =
                        sampled_scan::completion_copy_budget(sampling.as_ref(), &mut active);
                    (
                        sampled_scan::RetainBudget::granted_unclassified(budget),
                        measure,
                        None,
                    )
                } else if active.sampling.is_some()
                    && sampled_scan::codex_cursor::byte_charged(&active)
                {
                    (
                        sampled_scan::RetainBudget::granted_unclassified(copy_budget),
                        step_measure,
                        None,
                    )
                } else if active.sampling.is_some() {
                    if sampled_scan::borrows_only_retained_reduction(&active) {
                        sampled_scan::tail_completion_budget(sampling.as_ref(), &mut active)
                    } else {
                        let (budget, measure) = sampled_scan::copy_budget_step(
                            sampling.as_ref(),
                            Some(&mut *active),
                            true,
                        );
                        (
                            sampled_scan::RetainBudget::from((budget, measure)),
                            measure,
                            None,
                        )
                    }
                } else {
                    (
                        sampled_scan::RetainBudget::granted_unclassified(copy_budget),
                        step_measure,
                        None,
                    )
                };
                let copy_budget = retain_budget.raw();
                // A deferred release's peak-reserved `budget_after`, set where
                // its retention is attempted; the finalization limit only
                // where that release actually ran.
                let mut released_finalization_budget = None;
                // #631 review M1: the bytes this attempt read, taken before
                // `finish_job` consumes the acquisition's start offset. An
                // exact-stamp memo below must not cover anything past them.
                let attempt_read_end = sampled_scan::codex_cursor::read_end(&active);
                // S6: a cursor job commits only through its sealed-prefix
                // certificate; an invalidated attempt publishes nothing.
                let mut cursor_certificate = None;
                let mut cursor_publication = None;
                let mut cursor_fragment = None;
                // U1a-2a (row 39a): a certified job's unsealed bit for P's side
                // record (row 8), captured before `cursor_published`.
                let mut cursor_side_unsealed = None;
                // U1a-2a (row 8, group live member): a certified group job's
                // side seal for its live member, minted before the checkpoint
                // is dropped (a group job retains no reduction).
                let mut cursor_side_group_seal = None;
                if let Some(context) = sampling.as_ref().filter(|_| active.cursor.is_some()) {
                    let current_scope = sampled_scan::reduction_dependencies(
                        source,
                        &active.candidate,
                        &codex_title_metadata,
                        &claude_title_metadata,
                        claude_effort_support_dir_ref,
                    )
                    .map(|dependency| {
                        context.file_scope(
                            source,
                            &active.candidate,
                            &dependency,
                            true,
                            context_curve_enabled,
                            index,
                        )
                    });
                    let counting_now =
                        sampled_scan::codex_cursor::job_counting_view(&active, index);
                    let group_scope_now = sampled_scan::codex_cursor::group_scope(index);
                    let census_trusted = state_census_complete
                        && sidecar_census_complete
                        && active
                            .cursor
                            .as_ref()
                            .is_some_and(sampled_scan::codex_cursor::JobMeta::census_trusted);
                    // G1: growth past a job's frozen extent is next-generation
                    // evidence when the job started in this census generation.
                    let job_in_generation = active
                        .cursor
                        .as_ref()
                        .is_some_and(|meta| meta.in_generation(index));
                    // The certificate re-reads two samples from the held FD (M3).
                    codex_page.charge(true, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                    match sampled_scan::codex_cursor::finish_job(
                        &context.cache,
                        codex_cursor_lease.take(),
                        &mut active,
                        current_scope.as_ref(),
                        &counting_now,
                        &group_scope_now,
                        census_trusted,
                    ) {
                        sampled_scan::codex_cursor::JobEnd::Certified {
                            checkpoint,
                            grown,
                            publication,
                            fragment,
                        } => {
                            // N2: a withheld record keeps the path pending, so
                            // the next page tails it from `s`.
                            let next_generation = grown && fragment.is_none() && job_in_generation;
                            sampled_scan::codex_cursor::release_path(
                                index,
                                &active.candidate,
                                grown || fragment.is_some(),
                                next_generation,
                            );
                            context
                                .cache
                                .cursor_note_next_generation(u64::from(next_generation));
                            // N1: a cursor-only job (census incomplete at start
                            // or now) publishes like main's unsampled read: the
                            // certificate fenced the object, but no checkpoint,
                            // copy or verification is kept. A group job retains
                            // no reduction (its replay is joined).
                            cursor_side_unsealed =
                                Some(publication.eof_applied() || fragment.is_some());
                            if active.group.is_some() {
                                cursor_side_group_seal = Some(checkpoint.seal_as(
                                    sampled_scan::now_seconds(),
                                    &codex_parent_side_scope(),
                                ));
                            }
                            cursor_certificate = Some(
                                Some(checkpoint)
                                    .filter(|_| census_trusted && active.group.is_none()),
                            );
                            cursor_publication = Some(publication);
                            cursor_fragment = fragment;
                        }
                        sampled_scan::codex_cursor::JobEnd::Uncertified {
                            grown,
                            publication,
                            fragment,
                        } => {
                            // N2: a withheld record keeps the path pending, so
                            // the next page tails it from `s`.
                            let next_generation = grown && fragment.is_none() && job_in_generation;
                            sampled_scan::codex_cursor::release_path(
                                index,
                                &active.candidate,
                                grown || fragment.is_some(),
                                next_generation,
                            );
                            context
                                .cache
                                .cursor_note_next_generation(u64::from(next_generation));
                            cursor_certificate = Some(None);
                            cursor_publication = Some(publication);
                            cursor_fragment = fragment;
                        }
                        // Its path is still pending: the next page re-bootstraps.
                        sampled_scan::codex_cursor::JobEnd::Restart => pending!(),
                        sampled_scan::codex_cursor::JobEnd::MemberChanged(disclosure) => {
                            sampled_scan::codex_cursor::disclose_job_debt(
                                &active,
                                &disclosure,
                                index,
                                sampled_scan::codex_cursor::DisclosureTargets {
                                    census: &mut census,
                                    residue_index_keys: &mut residue_index_keys,
                                    residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                    codex_state_only_blocked_session_ids:
                                        &mut codex_state_only_blocked_session_ids,
                                    pending_finalization: &mut pending_finalization,
                                },
                            );
                            sampled_scan::codex_cursor::dequeue_members(
                                index,
                                sampled_scan::codex_cursor::job_files(&active),
                            );
                            pending!();
                        }
                    }
                    // A group's sealed members ended with the job; only its
                    // live member's path follows `release_path` above.
                    if let Some(group) = active.group.as_ref() {
                        sampled_scan::codex_cursor::dequeue_members(
                            index,
                            group
                                .members
                                .iter()
                                .filter(|member| member.path != active.candidate.path),
                        );
                    }
                }
                // S12: the live member's certified grant reaches validation.
                let group_live = active
                    .group
                    .as_ref()
                    .and_then(|_| sampled_scan::codex_cursor::certified_prefix(&active))
                    .map(|prefix| (local_index_key(&active.candidate.path), prefix));
                // PR-1 class 3: a non-monotone held file is memoized too, at the
                // read end; the record gate decides. Only a file the accumulator
                // already holds, and that is not parent-pending (the gate refuses
                // those), pays the two samples.
                let accumulator = &active.parser.accumulator;
                let memo_offset = active
                    .hold_offset
                    .or_else(|| {
                        (!accumulator.codex_usage_accounting_complete()
                            && !accumulator.codex_parent_resolution_pending()
                            && !sampled_scan::codex_cursor::held_monotone(accumulator))
                        .then_some(attempt_read_end)
                    })
                    .filter(|_| {
                        source == SnapshotSource::Codex
                            && active.aliases.is_empty()
                            && sampling.is_some()
                            // U1a-2a G17a: a side read keeps no memo.
                            && active.side_origin.is_none()
                    });
                if memo_offset.is_some() {
                    // The live witness reads two samples of the held file (M3).
                    codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                }
                let memo_candidate = memo_offset.and_then(|offset| {
                    let file = active.parser.reader.reader.get_ref();
                    let live = sampled_scan::codex_cursor::LiveWitness::read(
                        &active.candidate.path,
                        file,
                        offset,
                    )?;
                    let stamp = sampled_scan::codex_cursor::OpenStamp::capture(file).ok()?;
                    // PR-1: every singleton entry is exact until a counted tail
                    // makes growth replayable, so the stamp must cover exactly
                    // the bytes read (#631 review M1: captured after
                    // `finish_job`'s check).
                    if stamp.extent() != attempt_read_end {
                        return None;
                    }
                    // L-6: a curable hold is stamped only at the length its bind saw.
                    if sampled_scan::codex_cursor::growth_may_cure(&active.parser.accumulator)
                        && active.parser.accumulator.codex_bind_seed_len != Some(attempt_read_end)
                    {
                        return None;
                    }
                    let dependencies = sampled_scan::reduction_dependencies(
                        source,
                        &active.candidate,
                        &codex_title_metadata,
                        &claude_title_metadata,
                        claude_effort_support_dir_ref,
                    )?;
                    let digest = sampled_scan::codex_cursor::memo_digest(
                        index,
                        &active.candidate,
                        file,
                        &dependencies,
                        &codex_title_metadata,
                        sampled_scan::codex_cursor::owner_members(
                            codex_join_inventory.as_ref(),
                            &active.candidate.path,
                        ),
                        &sampled_scan::codex_cursor::counting_view(&active.candidate, index),
                    )?;
                    let sidecar = sampled_scan::codex_cursor::sidecar_wakes(
                        &active.parser.accumulator,
                    )
                    .then(|| {
                        sampled_scan::codex_cursor::sidecar_fingerprint(
                            &codex_title_metadata,
                            &active.candidate.path,
                        )
                    });
                    Some((digest, live, stamp, sidecar))
                });
                if source == SnapshotSource::ClaudeCode {
                    claude_title_metadata.resolve_deferred_lineage(index);
                }
                let OwnedActiveFile {
                    comparison_target,
                    sampling: file_sampling,
                    recovered_audit_due,
                    candidate,
                    decision,
                    previous_snapshot_fingerprint,
                    previous_upload_body_witness,
                    projection_adoption_required,
                    source_file_fingerprint,
                    parser,
                    aliases,
                    mut applied_receipts,
                    cursor: _,
                    charged_bytes: _,
                    hold_offset: _,
                    group,
                    side_origin,
                } = *active;
                let member_dues = group.map_or_else(Vec::new, |mut group| {
                    codex_legacy_join_baselines.extend(group.take_legacy_baselines());
                    std::mem::take(&mut group.recovered)
                });
                #[cfg(unix)]
                let paged = cursor_certificate.is_some();
                let mut parser = parser;
                // The repository identity X_out measured, if any (#665 U3).
                let mut measured_repository_identity = None;
                if let Some(replay) = parser.accumulator.codex_tier_replay.take() {
                    match replay.finish() {
                        Ok(receipt) => {
                            applied_receipts.insert(local_index_key(&candidate.path), receipt);
                        }
                        // U1a-2a G17a: the side read's charged attempt.
                        Err(_) if side_origin.is_some() => {
                            if let Some(side) = side_origin {
                                side.end();
                            }
                            pending!();
                        }
                        Err(_) => {
                            if let Some((context, publication)) =
                                sampling.as_ref().zip(cursor_publication.take())
                            {
                                context.cache.cursor_published(publication, false);
                            }
                            census.ownership_incomplete_file_count += 1;
                            census.causes.add(ownership::GROUP, 1);
                            census.record_unreadable(UnreadableCause::AliasParser, 1);
                            residue_index_keys.insert(local_index_key(&candidate.path));
                            if let Some(owner) = parser.accumulator.source_session_id.as_ref() {
                                residue_blocked_session_ids.insert(resolve_codex_identity(owner));
                                codex_state_only_blocked_session_ids
                                    .insert(resolve_codex_identity(owner));
                            }
                            pending!();
                        }
                    }
                }
                let retained_bytes = index
                    .files
                    .iter()
                    .filter(|(key, _)| !applied_receipts.contains_key(*key))
                    .filter_map(|(_, entry)| entry.codex_applied_tier_receipt.as_ref())
                    .map(|receipt| receipt.retained_bytes())
                    .sum::<usize>();
                let incoming_bytes = applied_receipts
                    .values()
                    .flatten()
                    .map(|receipt| receipt.retained_bytes())
                    .sum::<usize>();
                // U1a-2a G17a: a side read's receipts are never retained.
                if side_origin.is_none()
                    && retained_bytes.saturating_add(incoming_bytes)
                        > codex_file_join::MAX_RECEIPT_BYTES
                {
                    if let Some((context, publication)) =
                        sampling.as_ref().zip(cursor_publication.take())
                    {
                        context.cache.cursor_published(publication, false);
                    }
                    census.ownership_incomplete_file_count += aliases.len().max(1);
                    census.causes.add(ownership::GROUP, aliases.len().max(1));
                    census.record_unreadable(UnreadableCause::AliasParser, 1);
                    residue_index_keys.insert(local_index_key(&candidate.path));
                    residue_index_keys
                        .extend(aliases.iter().map(|member| local_index_key(&member.path)));
                    if let Some(owner) = parser.accumulator.source_session_id.as_ref() {
                        residue_blocked_session_ids.insert(resolve_codex_identity(owner));
                        codex_state_only_blocked_session_ids.insert(resolve_codex_identity(owner));
                    }
                    codex_state_only_blocked_session_ids.extend(
                        aliases
                            .iter()
                            .flat_map(|member| codex_session_id_candidates_from_path(&member.path)),
                    );
                    pending!();
                }
                // The existing copy budget funds two simultaneous allocations:
                // retained reduction and native finish/output. Reserve the extra
                // decoded response peak BEFORE either clone or decode. Active
                // compact records and their selector table were already charged
                // by copy_budget_step. A refusal disables retention, preserving
                // the ordinary native finish and its loss/output semantics.
                let cache_compatible = sampled_scan::compatible_reduction(&parser.accumulator)
                    && aliases.is_empty()
                    && applied_receipts.values().all(Option::is_none);
                // Retain the reduction only when every applied byte is in
                // the certified prefix `[0, s)`; a lossy job publishes
                // uncertified with its prepared debt, like a lossy full read.
                let sealed_only = parser.reader.sealed_fragment()
                    || parser.reader.consumed_bytes() == parser.reader.last_complete_line_end();
                // N4 (fe-seam-ack §5): the file branch decides its H3c route
                // before the retire below. A grown Claude prefix retains
                // nothing, so it must not retire a suspended proof.
                let file_acquisition = file_sampling
                    .as_ref()
                    .filter(|_| cursor_certificate.is_none() && side_origin.is_none());
                let (current_scope, prefix) = match file_acquisition {
                    Some(acquisition) => {
                        // Known dependencies and the current path are separate from the
                        // sampled prefix promise. Neither may be stale at completion.
                        let current_scope = sampled_scan::reduction_dependencies(
                            source,
                            &candidate,
                            &codex_title_metadata,
                            &claude_title_metadata,
                            claude_effort_support_dir_ref,
                        )
                        .zip(sampling.as_ref())
                        .map(|(dependency, context)| {
                            context.file_scope(
                                source,
                                &candidate,
                                &dependency,
                                source != SnapshotSource::ClaudeCode || artifacts_enabled,
                                context_curve_enabled,
                                index,
                            )
                        });
                        // H3c: a passed certificate permits native finish of
                        // this prefix only. Discard its checkpoint: no cache copy,
                        // audit credit or source verification can follow it.
                        let prefix = current_scope
                            .as_ref()
                            .filter(|scope| *scope == &acquisition.scope)
                            .filter(|_| {
                                acquisition.audit_due.is_some()
                                    && sampled_audit::progress_debt(
                                        index,
                                        &acquisition.key,
                                        sampled_scan::now_seconds(),
                                    )
                                    .is_none()
                                    && sampling.as_ref().is_some_and(|context| {
                                        context.audit_metadata_supported
                                            && (context.audit_slots > 0
                                                || index.files.get(&acquisition.key).is_some_and(
                                                    ScanIndexEntry::has_unverified_source,
                                                ))
                                    })
                            })
                            .and_then(|scope| {
                                parser.commit_claude_grown_prefix(
                                    &candidate.path,
                                    scope,
                                    index
                                        .files
                                        .get(&acquisition.key)
                                        .map_or(0, |entry| entry.size_bytes),
                                )
                            });
                        (current_scope, prefix)
                    }
                    None => (None, None),
                };
                let h3c_route = prefix.is_some();
                // U1a-2a (R2-B3, fix round 2 DB1; fix round 3 DM3): a suspended
                // proof that the copy and finish/output shares would overrun is
                // retired first, before either clone, and only where a copy can
                // be retained (the predicates of the two clones below); a
                // completion that retains nothing retires no proof.
                let retaining = cache_compatible
                    && match cursor_certificate.as_ref() {
                        Some(certificate) => certificate.is_some() && sealed_only,
                        None => file_sampling.is_some() && side_origin.is_none(),
                    };
                sampled_scan::retire_proof_beside_copy(
                    sampling.as_ref(),
                    if retaining && !h3c_route {
                        copy_budget
                    } else {
                        0
                    },
                    copy_measure,
                );
                // An H3c completion retains nothing: reserve no copy/decode
                // peak, just as it retires no proof and releases no resident.
                let finish_copy_budget = if retaining && !h3c_route {
                    parser
                        .accumulator
                        .claude_responses
                        .finish_copy_budget(copy_budget)
                } else {
                    None
                };
                let copy_budget = finish_copy_budget.unwrap_or(0);
                let mut completed_acquisition = if let Some(certificate) = cursor_certificate {
                    certificate.map(|checkpoint| {
                        parser.retain_sealed_prefix(
                            checkpoint,
                            // Never a release on a sealed prefix: excluded and
                            // unsealed keep the pre-release budget for the
                            // packet only; a retainable job is admitted
                            // against main's peak-reserved `copy_budget`.
                            if !cache_compatible {
                                retain_budget.excluded()
                            } else if !sealed_only {
                                retain_budget.unsealed()
                            } else {
                                sampled_scan::RetainBudget::granted_unclassified(copy_budget)
                            },
                        )
                    })
                } else if let Some(acquisition) =
                    file_sampling.as_ref().filter(|_| side_origin.is_none())
                {
                    if let Some(prefix) = prefix {
                        match prefix {
                            Ok(grant) => parser.reader.sealed_prefix = Some(grant),
                            Err(refusal) => {
                                claude_request_census::invalidate_claude_request_census(
                                    index,
                                    &candidate.path,
                                );
                                let cause = match refusal {
                                    crate::transcript_acquisition::PrefixRefusal::AuditDue => {
                                        UnreadableCause::Reduction
                                    }
                                    _ => UnreadableCause::ScopeObject,
                                };
                                census.record_unreadable(cause, 1);
                                pending!();
                            }
                        }
                        None
                    } else {
                        let mut current_path = candidate.clone();
                        if let Some(cause) = sampled_revalidation_cause(
                            current_scope.as_ref() == Some(&acquisition.scope),
                            || {
                                drop(open_candidate_file(source, &mut current_path)?);
                                Ok(current_path.opened_object_identity
                                    == candidate.opened_object_identity)
                            },
                        ) {
                            if source == SnapshotSource::ClaudeCode {
                                claude_request_census::invalidate_claude_request_census(
                                    index,
                                    &candidate.path,
                                );
                            }
                            census.record_unreadable(cause, 1);
                            pending!();
                        }
                        // #665 second-lander condition: only a retaining,
                        // non-H3c completion may measure X_out, reserve a peak,
                        // or prove a deferred release. Excluded reads keep none.
                        let retain_budget = if retaining && !h3c_route {
                            // #667: the decode peak is reserved from the budget the
                            // copy is admitted against: main's `copy_budget` above for
                            // a granted one. M-a (S-a): only now, after main's proof
                            // retirement and that reservation, may a shape-F release be
                            // proven; its `budget_after` is peak-reserved the same way.
                            // X_out (#665): Claude's finish-output bound, only for a
                            // proof. The repository identity it measured (U3) is the
                            // one `finish` takes below; a miss refuses.
                            let x_out = sampled_scan::x_out_for(source, || {
                                release_proof.as_ref()?;
                                measured_repository_identity = parser
                                    .accumulator
                                    .workspace_path
                                    .as_deref()
                                    .and_then(peek_repository_identity);
                                parser.finish_output_bound(
                                    FinishOutputInput {
                                        path: &candidate.path,
                                        collected_at: collected_at.as_str(),
                                        source_file_fingerprint: &source_file_fingerprint,
                                        opened_object_identity: &candidate.opened_object_identity,
                                        title_metadata: Some(&claude_title_metadata),
                                        attribution: attribution_context.is_some(),
                                        repository_identity: measured_repository_identity.as_ref(),
                                    },
                                    // `proven_release` checks it against `remaining'`.
                                    usize::MAX,
                                )
                            });
                            sampled_scan::prove_release(
                                retain_budget.reserve_peak(copy_budget, |budget| {
                                    parser
                                        .accumulator
                                        .claude_responses
                                        .finish_copy_budget(budget)
                                }),
                                release_proof,
                                sampling.as_ref(),
                                x_out,
                                |budget| {
                                    parser
                                        .accumulator
                                        .claude_responses
                                        .finish_copy_budget(budget)
                                },
                                |limit| {
                                    parser.accumulator.claude_responses.decode_peak_bound(limit)
                                },
                            )
                        } else {
                            retain_budget.excluded()
                        };
                        released_finalization_budget = retain_budget.released_budget();
                        #[cfg(test)]
                        sampled_scan::test_hooks::fire(
                            sampled_scan::test_hooks::Point::BeforeRetain,
                        );
                        match parser.retain_reduction(
                            &acquisition.scope,
                            sampled_scan::now_seconds(),
                            if cache_compatible {
                                retain_budget
                            } else {
                                retain_budget.excluded()
                            },
                        ) {
                            Ok(completed) => completed,
                            Err(_) => {
                                if source == SnapshotSource::ClaudeCode {
                                    claude_request_census::invalidate_claude_request_census(
                                        index,
                                        &candidate.path,
                                    );
                                }
                                census.record_unreadable(UnreadableCause::Reduction, 1);
                                pending!();
                            }
                        }
                    }
                } else {
                    None
                };
                #[cfg(test)]
                sampled_scan::test_hooks::fire(sampled_scan::test_hooks::Point::AfterRetain);
                // U1a-2a G17b + C9′: a side read's certificate, without
                // retention or any cache event; the same path must still name
                // the object. Its failures are its charged attempt.
                let mut side_certificate = None;
                if let Some(acquisition) = file_sampling.as_ref().filter(|_| side_origin.is_some())
                {
                    let mut current_path = candidate.clone();
                    let same_object =
                        open_candidate_file(source, &mut current_path).is_ok_and(|_| {
                            current_path.opened_object_identity == candidate.opened_object_identity
                        });
                    let certified = same_object
                        .then(|| {
                            parser
                                .certify_without_retention(
                                    &acquisition.scope,
                                    sampled_scan::now_seconds(),
                                )
                                .ok()
                        })
                        .flatten();
                    let Some(certified) = certified else {
                        if let Some(side) = side_origin {
                            side.end();
                        }
                        pending!();
                    };
                    let stamp = sampled_scan::codex_cursor::OpenStamp::capture(
                        parser.reader.reader.get_ref(),
                    )
                    .ok();
                    side_certificate = Some((certified, stamp));
                }
                // U1a-2a (row 8): the held FD's stamp for P's side record, at or
                // after the commit.
                let side_parsed_stamp = completed_acquisition
                    .as_ref()
                    .filter(|_| source == SnapshotSource::Codex && aliases.is_empty())
                    .and_then(|_| {
                        sampled_scan::codex_cursor::OpenStamp::capture(
                            parser.reader.reader.get_ref(),
                        )
                        .ok()
                    });
                // U1a-2a (row 8, group live member): the live member's seal and
                // held-FD stamp.
                let side_group_parse = cursor_side_group_seal
                    .filter(|_| source == SnapshotSource::Codex && !aliases.is_empty())
                    .zip(
                        sampled_scan::codex_cursor::OpenStamp::capture(
                            parser.reader.reader.get_ref(),
                        )
                        .ok(),
                    );
                let joined_owner = if aliases.is_empty() {
                    None
                } else {
                    parser
                        .accumulator
                        .source_session_id
                        .as_deref()
                        .map(resolve_codex_identity)
                };
                let codex_counting_v2 = parser.accumulator.codex_counting_v2();
                let evicted_legacy_v2_owner = parser
                    .accumulator
                    .source_session_id
                    .as_deref()
                    .filter(|_| {
                        codex_counting_version::evicted_legacy_selected_v2(
                            &parser.accumulator,
                            index,
                        )
                    })
                    .map(codex_protected_owner);
                // Counting receipts reach the scan's local diagnostics only
                // when this parse finishes: once per finished active file (a
                // joined group is one).
                let codex_counting_receipts =
                    parser
                        .accumulator
                        .codex_counting
                        .as_deref()
                        .map(|counting| {
                            let mut receipts = census.codex_counting_v2.clone().unwrap_or_default();
                            counting.fold_receipts(&mut receipts);
                            if evicted_legacy_v2_owner.is_some() {
                                receipts.legacy_to_v2_after_tombstone_eviction = receipts
                                    .legacy_to_v2_after_tombstone_eviction
                                    .saturating_add(1);
                            }
                            receipts
                        });
                // Slice D1: before `finish` consumes the parser. P1 ledger
                // birth: `created()` and identity of the descriptor this parse
                // opened, taken at open (never a path); unknown is None.
                let claude_opened_birth = (source == SnapshotSource::ClaudeCode
                    && !comparison_target
                    && claude_index_path_family_member(&candidate.path).is_some())
                .then_some(parser.claude_opened_birth)
                .flatten();
                let claude_itemless_request_hashes = if source == SnapshotSource::ClaudeCode
                    && !comparison_target
                    && !parser.positive_usage_evidence
                {
                    claude_request_census::claude_buffered_request_hashes(&parser)
                } else {
                    Vec::new()
                };
                let claude_grown_prefix =
                    source == SnapshotSource::ClaudeCode && parser.reader.sealed_prefix.is_some();
                let parsed_file = parser.finish_with_repository_identity(
                    &candidate.opened_object_identity,
                    &candidate.path,
                    collected_at.as_str(),
                    source_file_fingerprint.clone(),
                    (source == SnapshotSource::Codex).then_some(&codex_title_metadata),
                    (source == SnapshotSource::ClaudeCode).then_some(&claude_title_metadata),
                    // U1a-2a B8′: a side read takes no attribution context.
                    attribution_context.filter(|_| side_origin.is_none()),
                    measured_repository_identity,
                    Some(claude_request_money::e2::ReadContext {
                        index,
                        path: &candidate.path,
                        twins: history_upgrade.twin_groups(),
                    }),
                );
                // A committed cursor attempt counts as published only now (M4).
                if let Some((context, publication)) =
                    sampling.as_ref().zip(cursor_publication.take())
                {
                    context
                        .cache
                        .cursor_published(publication, parsed_file.is_ok());
                }
                if let Ok(parsed) = &parsed_file {
                    if source == SnapshotSource::ClaudeCode && !comparison_target {
                        for item in &parsed.snapshots {
                            if let Some(fold) = item.claude_money.as_deref() {
                                claude_request_money::e2::remember_birth(
                                    index,
                                    &candidate.path,
                                    fold,
                                );
                            }
                        }
                    }
                }
                let mut parsed_file = match parsed_file {
                    Ok(parsed) => parsed,
                    // U1a-2a G17b: the side read's charged attempt.
                    Err(_) if side_origin.is_some() => {
                        if let Some(side) = side_origin {
                            side.end();
                        }
                        pending!();
                    }
                    Err(_error) => {
                        #[cfg(test)]
                        sampled_scan::test_hooks::record_finish_error(&_error);
                        if source == SnapshotSource::ClaudeCode {
                            claude_request_census::invalidate_claude_request_census(
                                index,
                                &candidate.path,
                            );
                        }
                        census.record_unreadable(UnreadableCause::Reduction, 1);
                        pending!();
                    }
                };
                // U1a-2a (row 29) side exit, before any main write of the
                // completion: P's record or request only, from the first
                // matching outcome row; then the read's end line.
                if let Some(side) = side_origin {
                    use sampled_jsonl::SideCertificate;
                    let end = match side_certificate {
                        Some((SideCertificate::Certified { completed, len }, Some(parsed))) => {
                            SideReadEnd::Certified {
                                parse: Box::new(SideMainParse {
                                    seal: completed.checkpoint.seal_as(
                                        sampled_scan::now_seconds(),
                                        &codex_parent_side_scope(),
                                    ),
                                    parsed,
                                    verdict: codex_parent_side_verdict(&parsed_file),
                                    unsealed: completed.unsealed,
                                }),
                                len,
                            }
                        }
                        Some((SideCertificate::Lossy, _)) => SideReadEnd::Lossy,
                        _ => SideReadEnd::Failed,
                    };
                    let ledger = sampling
                        .as_ref()
                        .zip(codex_side_pass.as_ref())
                        .map(|(context, pass)| (&*context.cache, pass.ns));
                    index.finish_codex_parent_side_read(
                        &local_index_key(&candidate.path),
                        side.dev_ino,
                        end,
                        ledger,
                    );
                    side.end();
                    pending!();
                }
                if let Some(receipts) = codex_counting_receipts {
                    if let Some(owner) = evicted_legacy_v2_owner {
                        codex_counting_version::note_evicted_legacy_v2_selection(index, &owner);
                    }
                    census.codex_counting_v2 = Some(receipts);
                }
                let target_finalization_credit = if comparison_target {
                    if source != SnapshotSource::ClaudeCode || !aliases.is_empty() {
                        return Err(crate::source_rotation::LocalRefusal(
                            "native comparison target metadata source mismatch",
                        ));
                    }
                    if let Some(credit) = capture_credit.as_deref_mut() {
                        let admitted = native_comparison
                            .as_mut()
                            .ok_or(crate::source_rotation::LocalRefusal(
                                "native comparison target owner missing",
                            ))
                            .and_then(|phase| {
                                phase.retain_target_output(&parsed_file, &mut snapshots, credit)
                            });
                        // Error abandons collection; it is never finalized as
                        // an empty census or offered. Prior durable state stays.
                        admitted?;
                        let path_set_entries = index
                            .files
                            .len()
                            .checked_add(residue_index_keys.len())
                            .and_then(|n| n.checked_add(settled_residue_index_keys.len()))
                            .and_then(|n| n.checked_add(census.observed_index_keys.len()))
                            .and_then(|n| n.checked_add(index.confirmed_empty_files.len()))
                            .and_then(|n| {
                                n.checked_add(
                                    index
                                        .traversal
                                        .as_ref()
                                        .map_or(0, |t| t.observed_index_keys.len()),
                                )
                            })
                            .and_then(|n| {
                                n.checked_add(
                                    index
                                        .traversal
                                        .as_ref()
                                        .map_or(0, |t| t.residue.index_keys.len()),
                                )
                            })
                            .ok_or(crate::source_rotation::LocalRefusal(
                                "native target metadata path count overflow",
                            ))?;
                        Some(
                            native_comparison
                                .as_ref()
                                .expect("checked target phase")
                                .prepay_target_finalization_metadata(
                                    claude_native_comparison::TargetFinalizationInputs {
                                        candidate: &candidate,
                                        revision: &source_file_fingerprint,
                                        parsed: &parsed_file,
                                        index,
                                        pending: &mut pending_finalization,
                                        path_set_entries,
                                    },
                                    credit,
                                )?,
                        )
                    } else {
                        None
                    } // logical test adapter only
                } else {
                    None
                };
                // #667's peak-reserved finalization limit: from `budget_after`
                // where this completion's deferred release actually ran (and
                // its peak was reserved there), otherwise main's. `None`
                // refuses the copy; never 0 or `F_prev` in its place.
                let finalization_budget = if completed_acquisition
                    .as_ref()
                    .is_some_and(|completed| completed.released.is_some())
                {
                    released_finalization_budget
                } else {
                    finish_copy_budget
                };
                let finalization_charge = finalization_budget.and_then(|budget| {
                    crate::heap_layout_bound::completed_bound(&parsed_file, budget)
                });
                if finalization_charge.is_none() {
                    if let Some(completed) = completed_acquisition.as_mut() {
                        if completed.reduction.is_some() {
                            crate::local_resource_diagnostics::cache_lifecycle::record(
                                crate::local_resource_diagnostics::cache_lifecycle::Event::RetentionFinalizationBoundRefused,
                            );
                        }
                        completed.reduction = None;
                    }
                }
                let codex_parent_census = codex_parent_identities.census(index);
                // Fix round 5 (R2-N2): the proof re-fence's seal samples are
                // charged like every proof-side fence read.
                if codex_parent_proof_refenced(&parsed_file) {
                    codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                }
                invalidate_stale_codex_parent_resolution(
                    &mut parsed_file,
                    &mut codex_parent_identities,
                    codex_parent_census,
                );
                // PR-P: an overflowing ref is held `DeferredRef` debt, never a
                // restart. Once the scope's restart budget is spent, a pending
                // child holds `DeferredRestart` instead of restarting again.
                // Both are non-progressing held disclosure: nothing is admitted.
                // U1a-2a (fix round 6): whether this parse is `DeferredRef` here
                // with no ledger used and no step-map witness read. Together with
                // the guard's N1 conjuncts (`proof_used` and `proof_refusal` both
                // None) it identifies the parser's pending `_` arm, the one
                // deferral a later install's proof arm answers; the flag alone
                // does not. In-memory, this completion only.
                let mut deferred_ref_unwitnessed = false;
                if source == SnapshotSource::Codex && parsed_file.codex_parent_resolution_pending {
                    if parsed_file
                        .codex_parent_session_ref
                        .as_deref()
                        .is_some_and(|parent| !index.codex_parent_ref_fits(parent))
                    {
                        deferred_ref_unwitnessed =
                            parsed_file.codex_parent_ledger_identity_used.is_none();
                        parsed_file.defer_parent_resolution(CodexParentUnresolvable::DeferredRef);
                    } else if codex_parent_identities.restart_budget_spent {
                        parsed_file
                            .defer_parent_resolution(CodexParentUnresolvable::DeferredRestart);
                    }
                }
                // U1a-2a (D6(a), rev 3 §3.1–§3.2): a singleton settles its
                // proof entry from this parse in every mode; a budgeted held
                // singleton whose cause a proof cures owes one. Groups hold
                // no proof entries.
                if source == SnapshotSource::Codex {
                    let key = local_index_key(&candidate.path);
                    if aliases.is_empty() {
                        index.settle_codex_parent_proof_use(&key, &parsed_file);
                        if codex_parent_proofs_enabled(source, sampling.as_ref())
                            && !parsed_file.complete()
                        {
                            if let (Some(cause), Some(parent)) = (
                                parsed_file
                                    .codex_parent_unresolvable
                                    .filter(|cause| cause.proof_owed()),
                                parsed_file.codex_parent_session_ref.as_deref(),
                            ) {
                                index.owe_codex_parent_proof(
                                    &key,
                                    &resolve_codex_identity(parent),
                                    cause.index() as u8,
                                    OwedOrigin::Child,
                                    false,
                                );
                            }
                        }
                    } else {
                        index.remove_codex_parent_proof(&key);
                        for member in &aliases {
                            index.remove_codex_parent_proof(&local_index_key(&member.path));
                        }
                    }
                }
                codex_parent_resolution_retry_required |=
                    parsed_file.codex_parent_resolution_pending;
                // U1a-2a (row 8): main's certified parse of P (singleton, a P1
                // job's certified finish, or a certified group job's live
                // member) writes P's side record. A group member takes the
                // joined parse's verdict: the join publishes only a complete
                // union, so a held union holds every member.
                let side_seal = side_parsed_stamp
                    .zip(completed_acquisition.as_ref())
                    .map(|(parsed, completed)| {
                        (
                            completed
                                .checkpoint
                                .seal_as(sampled_scan::now_seconds(), &codex_parent_side_scope()),
                            parsed,
                            cursor_side_unsealed.unwrap_or(completed.unsealed),
                        )
                    })
                    .or_else(|| {
                        side_group_parse.map(|(seal, parsed)| {
                            (
                                seal,
                                parsed,
                                codex_group_side_unsealed(cursor_side_unsealed),
                            )
                        })
                    });
                if let Some((seal, parsed, unsealed)) = side_seal {
                    let p_ids = parsed_file
                        .codex_parent_ownership_ledger
                        .as_ref()
                        .map(|(session_id, _)| resolve_codex_identity(session_id))
                        .into_iter()
                        .chain(
                            codex_session_id_candidates_from_path(&candidate.path)
                                .iter()
                                .map(|id| resolve_codex_identity(id)),
                        )
                        .collect::<Vec<_>>();
                    let side = sampling
                        .as_ref()
                        .zip(codex_side_pass.as_ref())
                        .map(|(context, pass)| (&*context.cache, pass.ns));
                    index.write_codex_parent_side_from_main(
                        &local_index_key(&candidate.path),
                        &p_ids,
                        SideMainParse {
                            seal,
                            parsed,
                            verdict: codex_parent_side_verdict(&parsed_file),
                            unsealed,
                        },
                        side,
                    );
                }
                let parse_complete = parsed_file.complete();
                // Claude response conflicts may be discovered only by native
                // finalization. A prefix cannot publish that late loss: it
                // would have neither a committed audit marker nor necessarily
                // a D1 record when the record budget is exhausted.
                if claude_grown_prefix && !parse_complete {
                    claude_request_census::invalidate_claude_request_census(index, &candidate.path);
                    census.record_unreadable(UnreadableCause::ScopeObject, 1);
                    pending!();
                }
                if !aliases.is_empty() && !parse_complete {
                    // Joining authorizes a complete replacement only. Native
                    // ownership/parser loss cannot publish a partial union body.
                    census.ownership_incomplete_file_count += aliases.len();
                    census.causes.add(ownership::GROUP, aliases.len());
                    census.record_unreadable(UnreadableCause::AliasParser, 1);
                    residue_index_keys
                        .extend(aliases.iter().map(|member| local_index_key(&member.path)));
                    let owners = parsed_file
                        .snapshots
                        .iter()
                        .map(|item| resolve_codex_identity(&item.source_session_id));
                    codex_state_only_blocked_session_ids.extend(owners);
                    codex_state_only_blocked_session_ids
                        .extend(parsed_file.state_only_blocked_session_ids.iter().cloned());
                    pending!();
                }
                if !aliases.is_empty() {
                    codex_join_completed.push(codex_file_join::Group {
                        owner: joined_owner
                            .expect("joined replay owner was bound before native finish"),
                        home: codex_file_join::member_home(&candidate.scan_root),
                        members: aliases.clone(),
                        live: group_live.clone(),
                    });
                }
                let diagnostic_reason = if parse_complete {
                    FileReason::Complete
                } else if parsed_file.codex_parent_resolution_pending {
                    FileReason::ParentPending
                } else if parsed_file.ownership_incomplete_file_count > 0 {
                    FileReason::OwnershipIncomplete
                } else if parsed_file.recognized_usage_drop_count
                    > parsed_file.terminal_line_loss_count
                {
                    FileReason::RecognizedUsageDropped
                } else {
                    FileReason::ReadOrLineLoss
                };
                // PR-P: a fresh held child counted under its parent cause; the
                // memo replay counts the same (`disclose_terminal_codex_debt`).
                if let Some(cause) = parsed_file
                    .codex_parent_unresolvable
                    .filter(|_| !parse_complete)
                {
                    census.parent_unresolvable.record(cause.index(), 1);
                    cause.log_held_once();
                }
                let terminal_loss = parsed_file.terminal_loss();
                if let Some(parent_session_ref) = parsed_file
                    .codex_parent_session_ref
                    .as_ref()
                    .filter(|_| parsed_file.codex_parent_ledger_consulted)
                {
                    index.record_codex_parent_ref(parent_session_ref);
                }
                if source == SnapshotSource::Codex {
                    // PR-P: the parent-side identity of this parse: its own
                    // ledger object when a child asked for that id; otherwise a
                    // referenced path id at the opened object (no ledger object
                    // at all). A ledger under session id B while children ask
                    // for this path's id A can never serve them (the census and
                    // the classifier look parents up by path id), so A is
                    // witnessed `NoLedger` at this identity either way.
                    let parent_side = parsed_file
                        .codex_parent_ownership_ledger
                        .as_ref()
                        .map(|(session_id, ledger)| {
                            (
                                resolve_codex_identity(session_id.as_str()),
                                ledger.opened_object_identity.clone(),
                                ledger.scan_complete,
                                parsed_file.codex_parent_ledger_unusable,
                            )
                        })
                        .filter(|(session_id, ..)| {
                            index
                                .codex_parent_ownership_refs
                                .contains(session_id.as_str())
                        })
                        .or_else(|| {
                            codex_session_id_candidates_from_path(&candidate.path)
                                .iter()
                                .map(|id| resolve_codex_identity(id))
                                .find(|id| index.codex_parent_ownership_refs.contains(id))
                                .map(|id| {
                                    (
                                        id,
                                        candidate.opened_object_identity.clone(),
                                        false,
                                        Some(CodexParentUnresolvable::NoLedger),
                                    )
                                })
                        });
                    // The id the branch below settles, if any.
                    let settled_id = parent_side
                        .as_ref()
                        .map(|(session_id, ..)| session_id.clone());
                    if let Some((session_id, identity, scan_complete, cause)) = parent_side {
                        // L-5: a fresh open after the parent's own parse, only for
                        // a referenced parent (the only kind whose ledger is kept).
                        let at_current = codex_parent_identities
                            .reprobe(codex_parent_identities.census(index), &session_id)
                            .ok()
                            .as_deref()
                            == Some(identity.as_str());
                        let shared = codex_parent_ownership_ledgers.as_ref();
                        let scope = sampling
                            .as_ref()
                            .map(|_| sampled_scan::codex_cursor::group_scope(index));
                        let ram = sampling.as_ref().zip(scope.as_ref());
                        match (at_current, scan_complete, cause) {
                            (true, true, _) => {
                                // A usable ledger at the current object ends every
                                // witness for this parent, kept or not.
                                if let Some((context, scope)) = ram {
                                    context.cache.drop_parent_witnesses(
                                        &context.namespace,
                                        scope,
                                        std::slice::from_ref(&session_id),
                                    );
                                }
                                if let Some((_, ledger)) =
                                    parsed_file.codex_parent_ownership_ledger.as_ref()
                                {
                                    index
                                        .codex_parent_ownership_ledgers
                                        .insert(session_id.clone(), ledger.clone());
                                    if let Some(mut shared) =
                                        shared.and_then(|shared| shared.lock().ok())
                                    {
                                        // Replaces any step-map witness under this key.
                                        shared.insert(session_id.clone(), ledger.clone());
                                    }
                                }
                            }
                            (true, false, Some(cause)) => {
                                // Event (b): deterministic over these bytes and
                                // this classification; witness it so its children
                                // hold (RAM only; it admits nothing).
                                if let Some((context, scope)) = ram {
                                    context.cache.witness_parent(
                                        &context.namespace,
                                        scope,
                                        &session_id,
                                        sampled_scan::codex_cursor::ParentWitness {
                                            cause,
                                            identity: Some(
                                                context
                                                    .cache
                                                    .retained_stamp_identity(&candidate, &identity),
                                            ),
                                            waits_on: None,
                                        },
                                    );
                                }
                                witness_in_step_map(shared, &session_id, cause);
                            }
                            (true, false, None) => {
                                // Pending, or held `DeferredRestart`: no cause, so
                                // no earlier witness may keep holding its children.
                                // The wait record replaces it; it settles nothing
                                // (still owed) and only feeds cycle detection.
                                if let Some((context, scope)) = ram {
                                    context.cache.witness_parent(
                                        &context.namespace,
                                        scope,
                                        &session_id,
                                        sampled_scan::codex_cursor::ParentWitness {
                                            cause: CodexParentUnresolvable::DeferredRestart,
                                            identity: Some(
                                                context
                                                    .cache
                                                    .retained_stamp_identity(&candidate, &identity),
                                            ),
                                            waits_on: parsed_file.codex_parent_session_ref.clone(),
                                        },
                                    );
                                }
                                unwitness_in_step_map(shared, &session_id);
                            }
                            (false, ..) => {}
                        }
                    }
                    // A referenced path id other than the settled one (at most
                    // two path candidates) is never served by this parse. If
                    // the step map still owes it and this object is its current
                    // rollout, witness it `NoLedger` here, so it is not re-read
                    // every generation. Gated like `at_current`.
                    for path_id in codex_session_id_candidates_from_path(&candidate.path)
                        .iter()
                        .map(|id| resolve_codex_identity(id))
                        .filter(|id| settled_id.as_deref() != Some(id.as_str()))
                        .filter(|id| index.codex_parent_ownership_refs.contains(id))
                        .filter(|id| codex_parent_owed(codex_parent_ownership_ledgers.as_ref(), id))
                        .collect::<Vec<_>>()
                    {
                        let at_current = codex_parent_identities
                            .reprobe(codex_parent_identities.census(index), &path_id)
                            .ok()
                            .as_deref()
                            == Some(candidate.opened_object_identity.as_str());
                        if !at_current {
                            continue;
                        }
                        if let Some(context) = sampling.as_ref() {
                            let scope = sampled_scan::codex_cursor::group_scope(index);
                            context.cache.witness_parent(
                                &context.namespace,
                                &scope,
                                &path_id,
                                sampled_scan::codex_cursor::ParentWitness {
                                    cause: CodexParentUnresolvable::NoLedger,
                                    identity: Some(context.cache.retained_stamp_identity(
                                        &candidate,
                                        &candidate.opened_object_identity,
                                    )),
                                    waits_on: None,
                                },
                            );
                        }
                        witness_in_step_map(
                            codex_parent_ownership_ledgers.as_ref(),
                            &path_id,
                            CodexParentUnresolvable::NoLedger,
                        );
                    }
                }
                let index_key = local_index_key(&candidate.path);
                let non_progressing_residue = parsed_file.non_progressing_residue();
                if non_progressing_residue {
                    residue_index_keys.insert(index_key.clone());
                } else {
                    settled_residue_index_keys.insert(index_key.clone());
                }
                let blocked = parsed_file
                    .state_only_blocked_session_ids
                    .iter()
                    .map(|session_id| resolve_codex_identity(session_id.as_str()))
                    .collect::<BTreeSet<_>>();
                for session_id in &blocked {
                    if non_progressing_residue {
                        residue_blocked_session_ids.insert(session_id.clone());
                    }
                    codex_state_only_blocked_session_ids.insert(session_id.clone());
                    index
                        .codex_state_only_blocked_session_ids
                        .insert(session_id.clone());
                }
                if source == SnapshotSource::Codex {
                    // L-SB: this (settleable) parse is each member's whole
                    // contribution. `aliases` includes the candidate itself, so
                    // `index_key` repeats: intentional and idempotent.
                    for key in std::iter::once(index_key.clone())
                        .chain(aliases.iter().map(|member| local_index_key(&member.path)))
                    {
                        index.attribute_codex_blocked(&key, blocked.clone());
                    }
                }
                let report = parsed_file.report;
                let recognized_usage_drop_count = parsed_file.recognized_usage_drop_count;
                let ownership_incomplete_file_count = parsed_file.ownership_incomplete_file_count;
                let zero_snapshot_usage_evidence = parsed_file.zero_snapshot_usage_evidence;
                let dropped_usage_record_count = parsed_file.dropped_usage_record_count;
                let claude_compaction_unlinked_parent_count =
                    parsed_file.claude_compaction_unlinked_parent_count;
                if let Some(context) = sampling
                    .as_ref()
                    .filter(|_| source == SnapshotSource::Codex && aliases.is_empty())
                {
                    // PR-1: every settleable held singleton (usage-bearing and
                    // terminal over-line-cap included; `non_progressing_residue`
                    // already requires `complete_except_over_line_cap` and excludes
                    // parent-pending). Anything else, completion included, clears
                    // a stale entry.
                    let held = !parse_complete
                        && non_progressing_residue
                        && ownership_incomplete_file_count > 0;
                    // U1a-2a (fix round 5, N1; fix round 6): a hold built before
                    // its proof turned `Proven` is not memoized, so the next page
                    // parses and reaches the install.
                    let awaits_proof = held
                        && codex_held_memo_awaits_proof_install(
                            index,
                            codex_parent_identities.census(index),
                            &index_key,
                            &parsed_file,
                            deferred_ref_unwitnessed,
                        );
                    match memo_candidate.filter(|_| held && !awaits_proof) {
                        Some((digest, live, stamp, sidecar)) => {
                            // L4: the ledger identity the classification used, and
                            // the parent's opened identity. When a ledger was used,
                            // the after-parse fence just proved the parent is at
                            // it, so no second open. Otherwise the probe is a wake
                            // input only, charged when it opens.
                            let used = parsed_file.codex_parent_ledger_identity_used.clone();
                            let parent =
                                parsed_file
                                    .codex_parent_session_ref
                                    .as_deref()
                                    .map(|parent| {
                                        let (current, qualified) = retained_codex_parent(
                                            codex_parent_identities.census(index),
                                            parent,
                                            &context.cache,
                                        );
                                        codex_page.charge(
                                            false,
                                            sampled_scan::codex_cursor::SAMPLE_READ_BYTES,
                                        );
                                        sampled_scan::codex_cursor::ParentDep {
                                            id: parent.to_owned(),
                                            // An invalidation dependency only, never
                                            // proof of use: the ledger the parse used
                                            // takes precedence; with none, the indexed
                                            // identity (main's term), so its arrival,
                                            // change or removal misses once.
                                            ledger: retained_parent_ledger(
                                                used.clone().or_else(|| {
                                                    index
                                                        .codex_parent_ownership_ledgers
                                                        .get(
                                                            resolve_codex_identity(parent).as_str(),
                                                        )
                                                        .map(|ledger| {
                                                            ledger.opened_object_identity.clone()
                                                        })
                                                }),
                                                qualified.as_ref(),
                                            ),
                                            current: current.ok(),
                                            // PR-P: the step-map witness this
                                            // parse read, so its arrival, change
                                            // or removal misses once.
                                            witnessed: parsed_file.codex_parent_unresolvable,
                                        }
                                    });
                            let own_ledger = parsed_file
                                .codex_parent_ownership_ledger
                                .as_ref()
                                .is_some_and(|(_, ledger)| ledger.scan_complete);
                            context.cache.memo_record(
                                sampled_scan::codex_cursor::memo_key(
                                    &context.namespace,
                                    &index_key,
                                ),
                                sampled_scan::codex_cursor::MemoEntry::new(
                                    digest,
                                    live,
                                    context.cache.retained_stamp(&candidate.path, stamp),
                                    parent,
                                    sidecar,
                                    sampled_scan::codex_cursor::Disclosure {
                                        reason:
                                            sampled_scan::codex_cursor::DebtReason::HeldTerminal,
                                        ownership_incomplete_file_count,
                                        cause: parsed_file.cause,
                                        zero_snapshot_usage_evidence,
                                        state_only_blocked_session_ids: parsed_file
                                            .state_only_blocked_session_ids
                                            .iter()
                                            .cloned()
                                            .collect(),
                                        diagnostic_reason,
                                        parsed_snapshot_count: parsed_file.snapshots.len(),
                                        held: sampled_scan::codex_cursor::HeldCounts {
                                            over_line_cap: report.over_line_cap_count,
                                            recognized_usage_drop: recognized_usage_drop_count,
                                            dropped_usage_record: dropped_usage_record_count,
                                            terminal_line_loss: parsed_file
                                                .terminal_line_loss_count,
                                        },
                                        // PR-P: only a ledger-consulting
                                        // child requests its parent ref.
                                        parent_ref: parsed_file
                                            .codex_parent_session_ref
                                            .clone()
                                            .filter(|_| parsed_file.codex_parent_ledger_consulted),
                                        parent_unresolvable: parsed_file.codex_parent_unresolvable,
                                    },
                                )
                                // Every singleton entry is exact (PR-1).
                                .growth_may_cure(true)
                                .own_ledger(own_ledger),
                            )
                        }
                        None => context
                            .cache
                            .memo_forget(&sampled_scan::codex_cursor::memo_key(
                                &context.namespace,
                                &index_key,
                            )),
                    }
                }
                // N2: a withheld final record is owed, never verified.
                let held_progress_audit =
                    sampled_audit::progress_debt(index, &index_key, sampled_scan::now_seconds())
                        .is_some();
                let source_verified = cursor_fragment.is_none()
                    && completed_acquisition
                        .as_ref()
                        .is_some_and(|completed| completed.checkpoint.audit_debt().is_none())
                    || (file_sampling.is_none()
                        && state_census_complete
                        && sidecar_census_complete
                        && sampled_jsonl::loss_free_source_report(
                            &report,
                            recognized_usage_drop_count,
                            dropped_usage_record_count,
                        ));
                if source == SnapshotSource::ClaudeCode {
                    index.claude_full_rearm_progress.rebuild_read_full &= parse_complete
                        && source_verified
                        && file_sampling.as_ref().map_or(true, |active| {
                            matches!(
                                active.mode,
                                crate::transcript_acquisition::ReadMode::Full(_)
                            )
                        })
                        && sampled_jsonl::loss_free_source_report(
                            &report,
                            recognized_usage_drop_count,
                            dropped_usage_record_count,
                        );
                }
                let mut parsed = parsed_file.snapshots;
                if source == SnapshotSource::ClaudeCode && parse_complete {
                    if let Some((_, source_session_id)) =
                        claude_index_path_family_member(&candidate.path)
                    {
                        let marker_present = parsed.iter().any(|snapshot| {
                            snapshot.source_session_id == source_session_id
                                && snapshot.claude_context_curve_owned_start_proven
                        });
                        if !marker_present {
                            index.claude_owned_start_census.remove(&source_session_id);
                        } else {
                            let witness = index
                                .claude_owned_start_census
                                .entry(source_session_id)
                                .or_insert_with(|| ClaudeOwnedStartCensusWitness {
                                    marker_source_file_fingerprint: source_file_fingerprint.clone(),
                                    verified_source_file_fingerprint: None,
                                    emitted_source_file_fingerprint: None,
                                });
                            if witness.marker_source_file_fingerprint != source_file_fingerprint {
                                *witness = ClaudeOwnedStartCensusWitness {
                                    marker_source_file_fingerprint: source_file_fingerprint.clone(),
                                    verified_source_file_fingerprint: None,
                                    emitted_source_file_fingerprint: None,
                                };
                            }
                        }
                    }
                }
                if source == SnapshotSource::ClaudeCode {
                    // Slice D1: record only; no decision reads it. A #588
                    // comparison target prepays no record, so it has none.
                    if comparison_target {
                        claude_request_census::invalidate_claude_request_census(
                            index,
                            &candidate.path,
                        );
                    } else if !held_progress_audit || (source_verified && parse_complete) {
                        // An unsuccessful virtual audit keeps its old hold:
                        // it has no sampled marker carrying the obligation.
                        claude_request_census::record_claude_request_census(
                            index,
                            claude_request_census::ClaudeRequestCensusParse {
                                path: &candidate.path,
                                index_key: &index_key,
                                source_file_fingerprint: &source_file_fingerprint,
                                census_window_end: &census_window_end,
                                complete: parse_complete,
                                lossy: dropped_usage_record_count > 0
                                    || recognized_usage_drop_count > 0
                                    || report.over_line_cap_count > 0,
                                source_verified,
                                itemless_request_hashes: claude_itemless_request_hashes,
                                opened_birth: claude_opened_birth,
                                modified_unix_seconds: candidate.modified_unix_seconds,
                            },
                            &parsed,
                        );
                    }
                }
                if source == SnapshotSource::Codex {
                    for snapshot in parsed.iter_mut() {
                        apply_codex_state_evidence(
                            snapshot,
                            &codex_title_metadata,
                            &candidate.path,
                        );
                    }
                    for snapshot in &parsed {
                        if snapshot.usage_accounting_contract.as_deref()
                            == Some("session_exclusive_reported_usage:v1")
                        {
                            // L-SB: the accepted exclusive body supersedes this
                            // file's (and its aliases') own block; any other key
                            // still blocking the id keeps it. `aliases` includes
                            // the candidate, so `index_key` repeats: intentional,
                            // the second is a no-op.
                            index.accept_codex_block(
                                std::iter::once(index_key.clone()).chain(
                                    aliases.iter().map(|member| local_index_key(&member.path)),
                                ),
                                resolve_codex_identity(snapshot.source_session_id.as_str())
                                    .as_str(),
                            );
                        }
                    }
                }
                // R1: a paged job parked across a fresh index load captured
                // no due for a file now without an entry. Re-probe the same
                // live-context, clamped debt (read only) before recording;
                // no restart. A re-probed singleton miss counts here.
                #[cfg(unix)]
                let (member_dues, recovered_audit_due, reprobed_due) = {
                    let mut dues = (member_dues, recovered_audit_due, None);
                    if let Some(cache) = durable_guard
                        .as_ref()
                        .and_then(std::sync::Weak::upgrade)
                        .filter(|_| paged && parse_complete)
                    {
                        let absent = |key: &str| !index.files.contains_key(key);
                        for (member, due) in aliases.iter().zip(dues.0.iter_mut()) {
                            let key = local_index_key(&member.path);
                            if due.is_none() && absent(&key) {
                                *due = cache.durable_carrier_reprobe(source, &key, index);
                            }
                        }
                        if dues.0.is_empty() && dues.1.is_none() && absent(&index_key) {
                            dues.2 = cache.durable_carrier_reprobe(source, &index_key, index);
                            dues.1 = dues.2;
                            if dues.2.is_some() {
                                cache.durable_note_carrier("audit_carrier");
                            }
                        }
                    }
                    dues
                };
                #[cfg(not(unix))]
                let reprobed_due: Option<u64> = None;
                if parse_complete && !aliases.is_empty() {
                    for alias in &aliases {
                        if alias.path == candidate.path {
                            continue;
                        }
                        let alias_fingerprint = alias.source_file_fingerprint.clone();
                        pending_finalization.push(PendingIndexFinalization {
                            sampled_audit_verified: false,
                            codex_pending_recovery: index
                                .files
                                .get(&local_index_key(&alias.path))
                                .is_some_and(ScanIndexEntry::codex_recovery_is_pending),
                            index_key: local_index_key(&alias.path),
                            source_file_fingerprint: alias_fingerprint.clone(),
                            previous_snapshot_fingerprint: index.last_snapshot_fingerprint(alias),
                            previous_upload_body_witness: index.last_upload_body_witness(alias),
                            parse_complete,
                            diagnostic_reason,
                            parsed_snapshot_count: parsed.len(),
                            effective_upload_body_witness_revision: index
                                .active_effective_upload_body_witness_revision,
                        });
                        let alias_items = parsed
                            .iter()
                            .cloned()
                            .map(|mut item| {
                                item.source_file_fingerprint = Some(alias_fingerprint.clone());
                                item.snapshot_fingerprint = snapshot_fingerprint(source, &item);
                                item
                            })
                            .collect::<Vec<_>>();
                        index.record(
                            alias.clone(),
                            alias_items
                                .last()
                                .map(|item| item.snapshot_fingerprint.clone()),
                            ScanParseOutcome::Snapshot,
                        );
                        census
                            .observed_index_keys
                            .insert(local_index_key(&alias.path));
                        snapshots.extend(alias_items);
                    }
                }
                scanned_session_count += parsed.len();
                let last_snapshot_fingerprint = parsed
                    .last()
                    .map(|snapshot| snapshot.snapshot_fingerprint.clone());
                let parsed_snapshot_count = parsed.len();
                let sampled_audit_verified = parse_complete
                    && cursor_fragment.is_none()
                    && completed_acquisition
                        .as_ref()
                        .is_some_and(|completed| completed.checkpoint.audit_debt().is_none())
                    && file_sampling
                        .as_ref()
                        .is_some_and(|active| active.audit_due.is_some());
                if sampled_audit_verified {
                    if let Some(context) = sampling.as_mut() {
                        context.complete_audit(
                            file_sampling
                                .as_ref()
                                .and_then(|active| active.audit_due)
                                .expect("verified audit due"),
                        );
                    }
                }
                pending_finalization.push(PendingIndexFinalization {
                    sampled_audit_verified,
                    codex_pending_recovery: index
                        .files
                        .get(&index_key)
                        .is_some_and(ScanIndexEntry::codex_recovery_is_pending),
                    index_key: index_key.clone(),
                    source_file_fingerprint: source_file_fingerprint.clone(),
                    previous_snapshot_fingerprint: (decision != CandidateDecision::ReconcileLegacy
                        && !projection_adoption_required)
                        .then_some(previous_snapshot_fingerprint)
                        .flatten(),
                    previous_upload_body_witness: (decision != CandidateDecision::ReconcileLegacy
                        && !projection_adoption_required)
                        .then_some(previous_upload_body_witness)
                        .flatten(),
                    parse_complete,
                    diagnostic_reason,
                    parsed_snapshot_count,
                    effective_upload_body_witness_revision: index
                        .active_effective_upload_body_witness_revision,
                });
                if source == SnapshotSource::Codex
                    && parse_complete
                    && aliases.is_empty()
                    && applied_receipts.values().any(Option::is_some)
                {
                    if let Some(item) = parsed.first() {
                        codex_join_completed.push(codex_file_join::Group {
                            owner: resolve_codex_identity(&item.source_session_id),
                            home: codex_file_join::member_home(&candidate.scan_root),
                            members: vec![candidate.clone()],
                            live: None,
                        });
                    }
                }
                let counting_owner = parsed.first().and_then(|item| {
                    if source != SnapshotSource::Codex {
                        return None;
                    }
                    let owner = codex_join_inventory
                        .as_ref()?
                        .owner_for_path(&candidate.path)?;
                    let binding = codex_protected_owner(owner);
                    (binding == codex_protected_owner(&item.source_session_id)).then_some(binding)
                });
                let joined_marker =
                    (!aliases.is_empty()).then(|| codex_file_join::member_set_witness(&aliases));
                let protected_owner = (!aliases.is_empty()
                    || applied_receipts.values().any(Option::is_some))
                .then(|| {
                    parsed
                        .first()
                        .map(|item| codex_protected_owner(&item.source_session_id))
                })
                .flatten();
                let joined_keys = aliases
                    .iter()
                    .map(|member| local_index_key(&member.path))
                    .collect::<Vec<_>>();
                if parse_complete {
                    index.record_terminal_jsonl_disposition(&candidate, terminal_loss.clone());
                    let outcome = if last_snapshot_fingerprint.is_some() {
                        ScanParseOutcome::Snapshot
                    } else {
                        ScanParseOutcome::ConfirmedEmpty
                    };
                    // N2: with the certified prefix copy retained, the entry
                    // records only `[0, s)` as read, so the next page tails
                    // the withheld record with main's EOF behavior. Without a
                    // copy it records the length read and the staged debt
                    // re-selects it at the audit cadence.
                    let mut recorded = candidate;
                    if let Some(fragment) = cursor_fragment.filter(|_| {
                        completed_acquisition
                            .as_ref()
                            .is_some_and(|completed| completed.reduction.is_some())
                    }) {
                        recorded.size_bytes = fragment.offset;
                    }
                    index.record(recorded, last_snapshot_fingerprint, outcome);
                    // The counting version travels in the same entry as the
                    // fingerprint it describes; no separate save can split them.
                    if let Some(entry) = index.files.get_mut(&index_key) {
                        entry.codex_counting_v2 = codex_counting_v2;
                        entry.codex_counting_owner = counting_owner.clone();
                    }
                    // Each grouped member, aliases included, settles its own
                    // recovered debt on its native-created entry: unverified
                    // stages the existing marker; verified retires and counts.
                    for (member, &due) in aliases.iter().zip(&member_dues) {
                        let key = local_index_key(&member.path);
                        let marked = index
                            .files
                            .get(&key)
                            .and_then(ScanIndexEntry::unverified_deadline);
                        let staged = !source_verified
                            && due.is_some_and(|due_unix_seconds| {
                                index.stage_sampled_audit(
                                    &key,
                                    &member.source_file_fingerprint,
                                    crate::transcript_acquisition::AuditDebt { due_unix_seconds },
                                )
                            });
                        debug_assert!(staged || source_verified || due.is_none());
                        if let Some(context) = sampling.as_mut() {
                            if let Some(owed) = marked.or(due).filter(|_| source_verified) {
                                context.complete_audit(owed);
                            }
                            #[cfg(unix)]
                            for (counted, class) in [
                                (due.is_some(), "audit_carrier"),
                                (
                                    staged && marked.is_none(),
                                    "audit_carrier_staged_unverified",
                                ),
                            ] {
                                if counted {
                                    context.cache.durable_note_carrier(class);
                                }
                            }
                        }
                    }
                    // Native settlement accepts disclosed terminal row loss, even
                    // though that acquisition cannot certify a verified prefix.
                    // Its sampled publication still owes the prepared deadline;
                    // losing a completion certificate must never erase that debt.
                    let obligation = match completed_acquisition.as_ref() {
                        // Recovery debt stays in its bounded scheduling slot
                        // and census hold, including terminal loss. Never
                        // consume the last sampled slot on failed credit.
                        _ if held_progress_audit => None,
                        Some(completed) => completed.checkpoint.audit_debt(),
                        None => file_sampling
                            .as_ref()
                            .and_then(|active| active.audit_due)
                            .map(
                                |due_unix_seconds| crate::transcript_acquisition::AuditDebt {
                                    due_unix_seconds,
                                },
                            ),
                    }
                    .or(recovered_audit_due
                        .filter(|_| !source_verified)
                        .map(
                            |due_unix_seconds| crate::transcript_acquisition::AuditDebt {
                                due_unix_seconds,
                            },
                        ));
                    if let Some(debt) = obligation {
                        let was_pending = index
                            .files
                            .get(&index_key)
                            .is_some_and(ScanIndexEntry::has_unverified_source);
                        if index.stage_sampled_audit(&index_key, &source_file_fingerprint, debt)
                            && !was_pending
                        {
                            if let Some(context) = sampling.as_mut() {
                                context.audit_slots = context.audit_slots.saturating_sub(1);
                                #[cfg(unix)]
                                if recovered_audit_due.is_some() && !source_verified {
                                    context
                                        .cache
                                        .durable_note_carrier("audit_carrier_staged_unverified");
                                }
                            }
                        }
                    } else if source_verified {
                        index.complete_full_audit(&index_key, &source_file_fingerprint);
                        // A re-probed singleton due retires like a captured one, once.
                        if let Some((context, due)) = sampling
                            .as_mut()
                            .zip(reprobed_due.filter(|_| !sampled_audit_verified))
                        {
                            context.complete_audit(due);
                        }
                    }
                    if source == SnapshotSource::ClaudeCode {
                        if claude_grown_prefix {
                            index.mark_sealed_prefix(&index_key, &source_file_fingerprint);
                        } else if completed_acquisition.is_some()
                            && cursor_fragment.is_none()
                            && file_sampling.as_ref().is_some_and(|active| {
                                !matches!(
                                    active.mode,
                                    crate::transcript_acquisition::ReadMode::Unchanged
                                )
                            })
                            && state_census_complete
                            && sidecar_census_complete
                            && sampled_jsonl::loss_free_source_report(
                                &report,
                                recognized_usage_drop_count,
                                dropped_usage_record_count,
                            )
                        {
                            index.complete_native_recomposition(
                                &index_key,
                                &source_file_fingerprint,
                            );
                        }
                    }
                    if let Some(fragment) = cursor_fragment {
                        index.stage_sampled_audit(
                            &index_key,
                            &source_file_fingerprint,
                            fragment.debt,
                        );
                    }
                    if let Some(completed) = completed_acquisition {
                        if let Some(context) = sampling.as_ref() {
                            // A clone allocates exactly its length, and is the
                            // sampled key: R0's insert term assumes both.
                            let key = index_key.clone();
                            debug_assert_eq!(key.capacity(), key.len());
                            debug_assert!(file_sampling
                                .as_ref()
                                .map_or(true, |sampled| sampled.key.len() == key.len()));
                            let admitted = context.cache.insert_admitted(
                                key,
                                completed,
                                finalization_charge.unwrap_or(0),
                            );
                            if admitted {
                                if let Some(active) = file_sampling.as_ref() {
                                    active.reinsertion.admitted();
                                }
                                // M1 selection provenance (F2): the
                                // fingerprint this reduction was acquired for.
                                #[cfg(unix)]
                                context
                                    .cache
                                    .durable_note_selection(&index_key, &source_file_fingerprint);
                            }
                        }
                    }
                    for key in joined_keys {
                        if let Some(entry) = index.files.get_mut(&key) {
                            if source_verified {
                                entry.scan_identity_version =
                                    Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
                            }
                            entry.codex_joined_member_set = joined_marker.clone();
                            entry.codex_protected_owner = protected_owner.clone();
                            // Set only by a V2 decision; a Legacy group clears
                            // any stale mark with the ACK it rewrites.
                            entry.codex_counting_v2 = codex_counting_v2;
                            entry.codex_counting_owner = counting_owner.clone();
                        }
                    }
                }
                if parse_complete {
                    for (key, receipt) in applied_receipts {
                        if let Some(entry) = index.files.get_mut(&key) {
                            if receipt.is_some() {
                                entry.codex_protected_owner = protected_owner.clone();
                            }
                            entry.codex_applied_tier_receipt_required = receipt.is_some();
                            entry.codex_applied_tier_receipt = receipt;
                        }
                    }
                }
                census.malformed_json_line_count += report.malformed_json_line_count;
                census.invalid_utf8_line_count += report.invalid_utf8_line_count;
                census.over_line_cap_count += report.over_line_cap_count;
                census.recognized_usage_drop_count += recognized_usage_drop_count;
                census.ownership_incomplete_file_count += ownership_incomplete_file_count;
                census
                    .causes
                    .add(parsed_file.cause, ownership_incomplete_file_count);
                census.zero_snapshot_usage_evidence_count +=
                    usize::from(zero_snapshot_usage_evidence);
                census.dropped_usage_record_count = census
                    .dropped_usage_record_count
                    .saturating_add(dropped_usage_record_count);
                census.claude_compaction_unlinked_parent_count = census
                    .claude_compaction_unlinked_parent_count
                    .saturating_add(claude_compaction_unlinked_parent_count);
                if let Some(loss) = terminal_loss {
                    census.terminal_over_line_cap_count = census
                        .terminal_over_line_cap_count
                        .saturating_add(loss.over_line_cap_count);
                    census.terminal_recognized_usage_drop_count = census
                        .terminal_recognized_usage_drop_count
                        .saturating_add(loss.recognized_usage_drop_count);
                    census.terminal_dropped_usage_record_count = census
                        .terminal_dropped_usage_record_count
                        .saturating_add(loss.dropped_usage_record_count);
                }
                // Retryable parse loss still quarantines the whole derived entity.
                // A bounded oversized line is different: its loss is terminal and
                // disclosed, so independently parsed sibling records remain usable.
                if parse_complete {
                    snapshots.extend(parsed);
                }
                if let Some(bytes) = target_finalization_credit {
                    native_comparison
                        .as_mut()
                        .expect("checked target phase")
                        .retain_target_metadata(
                            bytes,
                            capture_credit
                                .as_deref_mut()
                                .expect("funded target metadata"),
                        )?;
                }
                pending!();
            }
            let Some(mut candidate) = identified_candidates.pop_front() else {
                if codex_page.continuation() {
                    let continuation_evidence = codex_join_inventory.map(|inventory| {
                        Arc::new(Mutex::new(Some(CodexContinuationEvidence {
                            inventory,
                            ledgers: codex_parent_ownership_ledgers,
                            codex: codex_title_metadata,
                            traces: codex_turn_traces,
                        })))
                    });
                    return Ok(OwnedSourceScanStep::Complete {
                        index: index_storage,
                        terminal_native_traversal: None,
                        scan: SourceScanResult {
                            continuation_ticket,
                            continuation_evidence,
                            ..SourceScanResult::empty(SnapshotSource::Codex)
                        },
                    });
                }
                // U1a-2a (row 31): the proof hook, once per page, after the
                // page's candidates, on the singleton budget main left.
                if codex_parent_proofs_enabled(source, sampling.as_ref())
                    && codex_page.claim_proof()
                {
                    if let Some((context, pass)) = sampling.as_ref().zip(codex_side_pass.as_ref()) {
                        codex_parent_proof_hook::codex_parent_proof_step(
                            index,
                            context,
                            pass,
                            &codex_parent_identities,
                            &mut codex_page,
                            sampled_scan::now_seconds(),
                        );
                    }
                }
                if native_comparison
                    .as_mut()
                    .is_some_and(|phase| phase.pause_before_finalization())
                {
                    pending!();
                }
                if let Some(traversal) = index.traversal.as_mut() {
                    traversal.codex_parent_resolution_retry_required |=
                        codex_parent_resolution_retry_required;
                    // A residue file that this page parsed to completion, or that a
                    // watcher hint proved absent, leaves the generation's residue set; a
                    // file that reproduced its residue (re)enters it.
                    for index_key in settled_residue_index_keys.iter().chain(
                        census.removed_index_keys.iter().filter(|key| {
                            !index
                                .files
                                .get(*key)
                                .is_some_and(ScanIndexEntry::codex_history_is_protected)
                        }),
                    ) {
                        traversal.residue.index_keys.remove(index_key);
                    }
                    if let Some(inventory) = codex_join_inventory
                        .as_ref()
                        .filter(|inventory| !inventory.complete)
                    {
                        record_codex_inventory_hold(traversal, inventory, &residue_index_keys);
                    }
                    traversal.residue.index_keys.extend(residue_index_keys);
                    traversal
                        .residue
                        .blocked_session_ids
                        .extend(residue_blocked_session_ids);
                    // Exact watcher remove/rename hints must amend the same durable
                    // observation set used by directory census reconciliation. Apply
                    // removals first so a valid observation later in this page wins.
                    for index_key in &census.removed_index_keys {
                        traversal.observed_index_keys.remove(index_key);
                    }
                    traversal
                        .observed_index_keys
                        .extend(census.observed_index_keys.iter().cloned());
                    traversal.counts.directory_entry_cap_exceeded_count +=
                        census.directory_entry_cap_exceeded_count;
                    traversal.counts.symlink_rejected_count += census.symlink_rejected_count;
                    traversal.counts.unreadable_path_count += census.unreadable_path_count;
                    traversal
                        .counts
                        .unreadable_causes
                        .merge(census.unreadable_causes);
                    traversal
                        .counts
                        .parent_unresolvable
                        .merge(census.parent_unresolvable);
                    traversal.counts.oversized_file_count += census.oversized_file_count;
                    oversized_discovery::merge(
                        &mut traversal.oversized_discovery,
                        std::mem::take(&mut census.oversized_discovery),
                    );
                    traversal.counts.disappeared_file_count += census.disappeared_file_count;
                    traversal.counts.malformed_json_line_count += census.malformed_json_line_count;
                    traversal.counts.invalid_utf8_line_count += census.invalid_utf8_line_count;
                    traversal.counts.over_line_cap_count += census.over_line_cap_count;
                    traversal.counts.recognized_usage_drop_count +=
                        census.recognized_usage_drop_count;
                    traversal.counts.ownership_incomplete_file_count +=
                        census.ownership_incomplete_file_count;
                    traversal.counts.causes.merge(&census.causes);
                    traversal.counts.zero_snapshot_usage_evidence_count +=
                        census.zero_snapshot_usage_evidence_count;
                    traversal.counts.dropped_usage_record_count = traversal
                        .counts
                        .dropped_usage_record_count
                        .saturating_add(census.dropped_usage_record_count);
                    traversal.counts.terminal_over_line_cap_count = traversal
                        .counts
                        .terminal_over_line_cap_count
                        .saturating_add(census.terminal_over_line_cap_count);
                    traversal.counts.terminal_recognized_usage_drop_count = traversal
                        .counts
                        .terminal_recognized_usage_drop_count
                        .saturating_add(census.terminal_recognized_usage_drop_count);
                    traversal.counts.terminal_dropped_usage_record_count = traversal
                        .counts
                        .terminal_dropped_usage_record_count
                        .saturating_add(census.terminal_dropped_usage_record_count);
                }
                if source == SnapshotSource::Codex {
                    // Count-only attribution of why Codex files were selected
                    // on this page. No path, session, or identifier is named.
                    if let Some(line) = census.codex_parse_reasons_line(
                        index.upload_context_fingerprint == index.active_upload_context_fingerprint,
                    ) {
                        eprintln!("{line}");
                        #[cfg(test)]
                        CODEX_PARSE_REASON_LINES.with(|lines| lines.borrow_mut().push(line));
                    }
                }
                if source == SnapshotSource::ClaudeCode
                    && (census.parse_reasons.iter().any(|count| *count > 0)
                        || census.claude_compaction_unlinked_parent_count > 0
                        || history_upgrade.any()
                        || index.claude_reemission_exclusions.pauses_adoption()
                        || claude_reemission_stop_latched())
                {
                    claude_history_upgrade::alarm_if_owed_without_list(
                        &history_upgrade,
                        index.claude_reemission_exclusions.state(),
                    );
                    // Count-only attribution of why Claude files were selected
                    // on this page. No path, session, or identifier is named.
                    eprintln!(
                        "local snapshot census claude parse reasons: upload_context_matches={} {} compaction_summary_unlinked_parent={} body_witness_adoption_deferred={} body_witness_adoption_excluded={} body_witness_adoption_held_no_list={} body_witness_adoption_exclusions_invalid={} body_witness_adoption_list={} body_witness_adoption_stop={} body_witness_adoption_stop_withheld_folds={} history_upgrade_owed={} history_upgrade_permitted={} history_emission_denied={} history_listed_literal_roots={} history_reowed={} history_activation_refused={} claude_reemission_family_closure_root_absent_excluded={} identity_incomplete_holds_entered_process_total={} identity_incomplete_holds_cleared_process_total={} identity_incomplete_hold_deadlines_restored_process_total={}",
                        index.upload_context_fingerprint == index.active_upload_context_fingerprint,
                        census_count_fields(&CANDIDATE_PARSE_REASON_NAMES, &census.parse_reasons),
                        census.claude_compaction_unlinked_parent_count,
                        history_upgrade.denied_for(&[
                            HistoryHold::UngatedRevision,
                            HistoryHold::ListPaused,
                            HistoryHold::Latched,
                            HistoryHold::Budget,
                        ]),
                        history_upgrade.denied_for(&[HistoryHold::Listed]),
                        history_upgrade
                            .denied_for(&[HistoryHold::NoListBirth, HistoryHold::MoveNotFull]),
                        u8::from(index.claude_reemission_exclusions.is_invalid()),
                        index.claude_reemission_exclusions.status(),
                        claude_reemission_stop_reason(),
                        claude_reemission_stop_withheld_folds(),
                        history_upgrade.owed,
                        history_upgrade.permitted,
                        history_upgrade.denied_summary(),
                        history_upgrade.listed_literal_roots.len(),
                        claude_history_upgrade::local_count(
                            claude_history_upgrade::LocalCount::Reowed
                        ),
                        claude_history_upgrade::local_count(
                            claude_history_upgrade::LocalCount::ActivationRefused
                        ),
                        history_upgrade.family_closure_root_absent_excluded,
                        claude_request_census::identity_incomplete_hold_totals().0,
                        claude_request_census::identity_incomplete_hold_totals().1,
                        claude_request_census::identity_incomplete_hold_deadlines_restored_total()
                    );
                    if history_upgrade.family_closure_root_absent_excluded > 0 {
                        crate::local_resource_diagnostics::claude_reemission_family_closure_root_absent_excluded(
                            history_upgrade.family_closure_root_absent_excluded,
                        );
                    }
                }
                // A remove/rename hint can arrive after bounded reconciliation has already
                // passed this key. Removing it only from `observed_index_keys` is then too
                // late: the reconciliation cursor will never revisit the stale entry and a
                // terminal manifest can still publish it. The hint was revalidated as
                // absent beneath the configured root above, so retire the corresponding
                // derived index state directly. Any recreation after this absence witness
                // belongs to the next generation.
                // U1a-2a (row 30): the side ledger's namespace for this pass.
                let codex_side_drop = sampling
                    .as_ref()
                    .zip(codex_side_pass.as_ref())
                    .map(|(context, pass)| (&*context.cache, pass.ns));
                for index_key in &census.removed_index_keys {
                    if !index
                        .files
                        .get(index_key)
                        .is_some_and(ScanIndexEntry::codex_history_is_protected)
                    {
                        // A Claude member that vanished beneath its present
                        // parent also drops its unverified audit debt (SOURCE
                        // N2); every other removal keeps that debt. Both
                        // retire its request-census record (SOURCE N1).
                        let vanished = census.claude_vanished_index_keys.contains(index_key);
                        let census_record =
                            vanished && index.claude_request_census.get(index_key).is_some();
                        if vanished && index.retire_vanished_claude_audit_debt_entry(index_key) {
                            disappearance_diagnostics::vanished(
                                source,
                                disappearance_diagnostics::Vanished::AuditDebtDropped,
                            );
                        } else if source != SnapshotSource::Codex
                            || codex_counting_version::tombstone_before_retire(index, index_key)
                        {
                            index.remove_file_entry_unless_held(index_key, vanished);
                        }
                        if census_record && index.claude_request_census.get(index_key).is_none() {
                            disappearance_diagnostics::vanished(
                                source,
                                disappearance_diagnostics::Vanished::RequestCensusRemoved,
                            );
                        }
                        if !index.files.contains_key(index_key) {
                            index.drop_codex_proof_items(index_key, codex_side_drop);
                        }
                    }
                }
                // G1: only census members hold discovery. A pending re-read
                // (growth after this generation processed its path) is
                // next-generation evidence; retiring drops it and the next
                // walk re-reads the file if it is stale.
                let traversal_discovery_done =
                    index.traversal.as_ref().is_some_and(|traversal| {
                        traversal.pending_directories.is_empty()
                            && !traversal
                                .pending_candidates
                                .iter()
                                .any(|candidate| candidate.census_member)
                    }) && index.claude_stale_family_carry.replay.is_empty();
                if traversal_discovery_done {
                    if source == SnapshotSource::Codex {
                        let missing = index
                            .files
                            .iter()
                            .filter(|(key, entry)| {
                                entry.codex_history_is_protected()
                                    && !index
                                        .traversal
                                        .as_ref()
                                        .expect("traversal")
                                        .codex_rollout_paths
                                        .contains(*key)
                            })
                            .map(|(key, _)| key.clone())
                            .collect::<BTreeSet<_>>();
                        if !missing.is_empty() {
                            let traversal = index.traversal.as_mut().expect("traversal");
                            // Quiet ticks reuse this generation's red witness. Count
                            // each absent protected source once, without rearming the
                            // retry latch or rescanning headers before its deadline.
                            let newly_missing =
                                missing.difference(&traversal.residue.index_keys).count();
                            traversal.counts.ownership_incomplete_file_count += newly_missing;
                            traversal
                                .counts
                                .causes
                                .add(ownership::ABSENT, newly_missing);
                            traversal.counts.record_unreadable(
                                UnreadableCause::ProtectedAbsence,
                                usize::from(newly_missing > 0),
                            );
                            traversal.residue.index_keys.extend(missing);
                        }
                    }
                    // Discovery has visited every directory and parsed every candidate,
                    // so the counts are the complete re-derivation for this generation.
                    // Loss that only a change to the corpus can move is settled now, so a
                    // machine whose only problem is an unresolvable rollout still reaches
                    // a terminal census instead of retrying the same bytes forever with
                    // every downstream gate (historical backfill, the legacy settlement
                    // sweep, the terminal manifest) held behind it. Retryable problems
                    // veto the settlement inside the helper.
                    if let Some(traversal) = index.traversal.as_mut() {
                        traversal.counts.settle_non_progressing_residue();
                    }
                    // L-1 (§d.1.3): on a clean completed walk, release every
                    // owner B blocked for a group whose members all left the
                    // rollout census, unless an inventoried header or a live,
                    // paused or queued group job still holds it.
                    let clean = index
                        .traversal
                        .as_ref()
                        .is_some_and(|traversal| !traversal.counts.has_retryable_problems());
                    let inventory = codex_join_inventory
                        .as_ref()
                        .filter(|inventory| inventory.complete);
                    if let (SnapshotSource::Codex, true, Some(context), Some(inventory)) =
                        (source, clean, sampling.as_ref(), inventory)
                    {
                        // Read before the release: `keep` runs under the cursor
                        // lock and must not take it again.
                        let paused = context.cache.cursor_group_owner();
                        release_departed_join_owners(index, &context.cache, |owner| {
                            inventory.headers.iter().any(|header| header.owner == owner)
                                || paused.as_deref() == Some(owner)
                                || codex_join_groups.iter().any(|group| group.owner == owner)
                                || codex_join_active
                                    .as_ref()
                                    .is_some_and(|boot| boot.group.owner == owner)
                        });
                    }
                }
                let traversal_snapshot = index
                    .traversal
                    .as_ref()
                    .cloned()
                    .expect("traversal remains active");
                let traversal_healthy = !traversal_snapshot.counts.has_errors()
                    && (source != SnapshotSource::ClaudeCode
                        || index
                            .claude_stale_family_carry
                            .origin
                            .as_ref()
                            .and_then(|origin| origin.admission.as_ref())
                            .is_none());
                let clean_frozen_generation = !traversal_snapshot.watcher_hint_seen;
                let reconciliation_complete = if traversal_discovery_done
                    && traversal_healthy
                    && clean_frozen_generation
                    && state_census_complete
                    && sidecar_census_complete
                {
                    reconcile_missing_index_entries_bounded(index, codex_side_drop)
                } else {
                    false
                };
                // Vanished paths are retired from `files` just above - by exact watcher
                // remove/rename hints and by bounded census reconciliation. Terminal
                // dispositions are keyed identically, so retire their orphans in the same
                // place instead of carrying a renamed or deleted file's record forever.
                // This keeps the map a subset of `files`, which is the whole bound it
                // needs.
                index.prune_terminal_jsonl_dispositions();
                // Retirements on this page can already have a moved header in
                // the inventory, even while that file's parse is deferred.
                if let Some(inventory) = codex_join_inventory.as_ref() {
                    codex_counting_version::note_inventory_created(index, inventory);
                }
                if source == SnapshotSource::Codex
                    && traversal_discovery_done
                    && traversal_healthy
                    && clean_frozen_generation
                    && state_census_complete
                    && sidecar_census_complete
                    && reconciliation_complete
                {
                    // Reconcile authoritative transcript deletions before deciding which
                    // state-database threads are file-backed. Otherwise a vanished rollout
                    // remains "covered" for this whole generation, the state-only fallback
                    // is delayed one cycle, and a complete terminal manifest can briefly
                    // omit a thread the local state database still proves exists.
                    let (state_only_scanned, state_only_noops) = append_codex_state_only_snapshots(
                        &mut snapshots,
                        &codex_title_metadata,
                        collected_at.as_str(),
                        index,
                        &codex_state_only_blocked_session_ids,
                    );
                    scanned_session_count += state_only_scanned;
                    semantic_noop_count += state_only_noops;
                }
                // G1: pending re-reads do not hold the restart either.
                let parent_resolution_restart = traversal_discovery_done
                    && !traversal_snapshot
                        .pending_candidates
                        .iter()
                        .any(|candidate| candidate.census_member)
                    && traversal_snapshot.codex_parent_resolution_retry_required;
                if parent_resolution_restart {
                    if let Some(context) = sampling.as_ref() {
                        // Inline table: never refused. The new count is what
                        // this page's diagnostics report; a poisoned cursor
                        // reports none (N1).
                        codex_parent_identities.parent_restarts =
                            context.cache.note_parent_restart(
                                &context.namespace,
                                &sampled_scan::codex_cursor::group_scope(index),
                            );
                    }
                }
                let raw_census_complete = traversal_discovery_done
                    && traversal_healthy
                    && clean_frozen_generation
                    && state_census_complete
                    && sidecar_census_complete
                    && reconciliation_complete
                    && !parent_resolution_restart;
                let needs_clean_followup =
                    raw_census_complete && index.bounded_sweep_had_unsettled_upload;
                // Path-(a) bridge: a raw-complete census first retires every
                // RetryPending family it proves wholly absent, so a vanished
                // family's debt cannot withhold the census below forever.
                if raw_census_complete && source == SnapshotSource::ClaudeCode {
                    // The fallback cursor's index scope: the sampled-acquisition
                    // namespace, a digest of this index's path, upload
                    // destination namespace and scan mode. A scan without one
                    // shares the empty scope.
                    let cursor_scope = sampling
                        .as_ref()
                        .map_or("", |context| context.namespace.0.as_str());
                    let outcome = index.retire_positively_absent_claude_families(
                        &traversal_snapshot,
                        cursor_scope,
                    );
                    match outcome {
                        Ok(0) => {}
                        Ok(retired) => eprintln!(
                            "local snapshot census retired {retired} wholly absent RetryPending \
                             Claude usage family/families on a raw-complete census"
                        ),
                        Err(refusal) => {
                            if index.claude_usage_authority_pending_count() > 0 {
                                eprintln!(
                                    "local snapshot census kept every RetryPending Claude usage \
                                     family: absence retirement refused ({})",
                                    refusal.as_str()
                                );
                            }
                        }
                    }
                    // SOURCE Round 15: only a complete healthy terminal lowers
                    // the tombstone uncertainty fence, before the census fold
                    // prunes any witness.
                    index.drain_claude_retired_family_tombstone_fence(&traversal_snapshot);
                }
                // Path-(a) bridge: RetryPending authority debt no longer marks
                // the sweep, but it still withholds the ordinary census (and so
                // its complete fold and upload-context adoption), as the mark
                // did. It owes no clean follow-up of its own.
                let authority_debt_withholds_census = raw_census_complete
                    && source == SnapshotSource::ClaudeCode
                    && index.claude_usage_authority_pending_count() > 0;
                let census_complete = raw_census_complete
                    && !needs_clean_followup
                    && !authority_debt_withholds_census;
                // Slice D1: prune and measure only, before any fold.
                let claude_request_census_shadow =
                    (source == SnapshotSource::ClaudeCode && census_complete).then(|| {
                        claude_request_census::settle_claude_request_census_terminal(
                            index,
                            &traversal_snapshot.observed_index_keys,
                            &traversal_snapshot.residue.index_keys,
                            &census_window_end,
                        )
                    });
                let reconciliation_pending = traversal_discovery_done
                    && traversal_healthy
                    && clean_frozen_generation
                    && state_census_complete
                    && sidecar_census_complete
                    && !reconciliation_complete;
                let pending_work_count = index
                    .traversal
                    .as_ref()
                    .map(|traversal| {
                        traversal
                            .pending_candidates
                            .len()
                            .saturating_add(traversal.pending_directories.len())
                            .saturating_add(usize::from(reconciliation_pending))
                    })
                    .unwrap_or_default()
                    .saturating_add(index.claude_stale_family_carry.replay.len());
                let skipped_file_count_due_to_limit = index
                    .traversal
                    .as_ref()
                    .map(|traversal| {
                        traversal
                            .pending_candidates
                            .iter()
                            .filter(|candidate| candidate.census_member)
                            .count()
                    })
                    .unwrap_or_default()
                    .saturating_add(index.claude_stale_family_carry.replay.len());
                let restart_after_hints =
                    traversal_discovery_done && traversal_healthy && !clean_frozen_generation;
                let terminal_unhealthy = traversal_discovery_done && !traversal_healthy;
                if terminal_unhealthy {
                    let now = rfc3339_unix_seconds(collected_at.as_str()).unwrap_or_default();
                    let traversal = index.traversal.as_mut().expect("traversal remains active");
                    if traversal.unhealthy_retry_not_before_unix_seconds.is_none() {
                        let previous_attempt = traversal.unhealthy_retry_attempt;
                        // The counter saturates at the attempt whose delay is already the
                        // hourly ceiling. A persistent problem therefore costs at most one
                        // bounded re-walk per hour and the persisted witness stays small.
                        traversal.unhealthy_retry_attempt = previous_attempt
                            .saturating_add(1)
                            .min(UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS);
                        traversal.unhealthy_retry_not_before_unix_seconds =
                            Some(now.saturating_add(unhealthy_scan_retry_delay_seconds(
                                traversal.unhealthy_retry_attempt,
                            )));
                        if previous_attempt < UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS
                            && traversal.unhealthy_retry_attempt
                                == UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS
                        {
                            eprintln!(
                    "ottto-service: bounded scan retry for {} reached attempt {}; the traversal \
                     stays a durable red witness and is re-walked at most hourly until the \
                     problem clears or the scan context changes",
                    source.api_slug(),
                    UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS
                );
                        }
                    }
                }
                let pending_work_count = pending_work_count
                    .saturating_add(usize::from(restart_after_hints))
                    .saturating_add(usize::from(terminal_unhealthy))
                    .saturating_add(usize::from(needs_clean_followup))
                    .saturating_add(usize::from(parent_resolution_restart));
                if raw_census_complete {
                    index.record_scan_residue_witness(source, &traversal_snapshot);
                    index.retain_observed_claude_account_deferred_holds(
                        &traversal_snapshot.observed_index_keys,
                    );
                }
                let mut terminal_native_traversal = None;
                let mut carried_next_generation = Vec::new();
                if (raw_census_complete
                    && codex_legacy_join_baselines.is_empty()
                    && !pending_finalization.iter().any(|pending| {
                        index.files.get(&pending.index_key).is_some_and(|entry| {
                            entry.codex_applied_tier_receipt.is_some()
                                || entry.codex_joined_member_set.is_some()
                        })
                    }))
                    || restart_after_hints
                    || parent_resolution_restart
                {
                    traversal_transition::retiring(
                        source,
                        index.generation,
                        &traversal_snapshot,
                        raw_census_complete,
                        index.unsettled_cause_bits(),
                        (source == SnapshotSource::ClaudeCode).then(|| {
                            (
                                with_claude_absence_counters(|counters| *counters),
                                index.claude_retired_family_tombstones_uncertain,
                            )
                        }),
                        CensusGates {
                            discovery_done: traversal_discovery_done,
                            traversal_healthy,
                            frozen_generation: clean_frozen_generation,
                            state_complete: state_census_complete,
                            sidecar_complete: sidecar_census_complete,
                            reconciliation_complete,
                            parent_restart: parent_resolution_restart,
                            clean_followup: needs_clean_followup,
                            census_complete,
                        },
                    );
                    terminal_native_traversal = claude_native_comparison::TerminalTraversal::take(
                        index,
                        source,
                        native_comparison.is_some(),
                        raw_census_complete,
                        &census_window_end,
                    );
                    // G1 carry: the closing generation's waiting re-reads
                    // (watcher hints, budget-deferred re-reads, growth past
                    // its window end) are next-generation evidence. Hand them
                    // to the next generation as members rather than dropping
                    // them; they never re-enter the generation closing here.
                    carried_next_generation = index
                        .traversal
                        .as_ref()
                        .filter(|_| source == SnapshotSource::Codex)
                        .map_or_else(Vec::new, |traversal| {
                            traversal
                                .pending_candidates
                                .iter()
                                .filter(|candidate| !candidate.census_member)
                                .map(|candidate| candidate.path.clone())
                                .collect::<Vec<_>>()
                        });
                    index.traversal = None;
                    index.resume_after_path = None;
                    index.resume_upper_bound_path = None;
                    index.resume_census_window_end = None;
                }
                let counts = traversal_snapshot.counts;
                let zero_snapshot_confirmed_count = index.confirmed_empty_files.len();
                let zero_snapshot_usage_evidence_count = counts.zero_snapshot_usage_evidence_count;
                let dropped_usage_record_count = counts.dropped_usage_record_count;
                // The witness just recorded above describes THIS generation only when the
                // generation completed; otherwise the durable one is an earlier census's
                // and must not be reported as this scan's evidence. Counts only: the
                // witness's index keys and session ids never leave the local index.
                let (
                    census_residue_index_key_count,
                    census_residue_archived_rollout_count,
                    census_residue_blocked_session_count,
                ) = if raw_census_complete {
                    index
                        .scan_residue_witness
                        .as_ref()
                        .map(|witness| {
                            (
                                witness.index_keys.len(),
                                witness.archived_residue_file_count(),
                                witness.codex_state_only_blocked_session_ids.len(),
                            )
                        })
                        .unwrap_or_default()
                } else {
                    (0, 0, 0)
                };
                if !context_curve_enabled {
                    for snapshot in &mut snapshots {
                        snapshot.context_curve = None;
                    }
                }
                index.preserve_decode_held_files(source, &snapshots, &mut pending_finalization);
                snapshots.retain(|item| !index.decode_holds_snapshot(source, item));
                let census_complete = census_complete && index.decode_holds.is_empty();
                if census_complete {
                    // SOURCE/SI: only a healthy EFFECTIVE terminal can prove a
                    // carried file gone. A raw terminal, another file's census,
                    // or an unknown original association cannot retire its ACKs.
                    index.accepted_rebuild_incidence.retain(|key, _| {
                        key.is_empty()
                            || traversal_snapshot.observed_index_keys.contains(key)
                            || traversal_snapshot.residue.index_keys.contains(key)
                            || index.files.contains_key(key)
                    });
                    index.accepted_incidence_pending_census =
                        !index.accepted_rebuild_incidence.is_empty();
                }
                if !index.decode_holds.is_empty() {
                    index.mark_bounded_sweep_unsettled();
                }
                // Only a settled close starts the next generation in this
                // page. A partially settled sweep (including a decode hold
                // just marked) keeps its marker for the clean follow-up the
                // next page starts, and that walk re-reads the stale files.
                if !carried_next_generation.is_empty() && !index.bounded_sweep_had_unsettled_upload
                {
                    ensure_bounded_traversal(
                        source,
                        &roots,
                        index,
                        &collected_at,
                        backfill_window_days,
                    );
                    if let Some(next) = index.traversal.as_mut() {
                        enqueue_watcher_hints(source, next, &carried_next_generation, false);
                    }
                }
                if source == SnapshotSource::ClaudeCode {
                    seal_claude_complete_rebuild_read(
                        index,
                        &pending_finalization,
                        census_complete
                            && pending_work_count == 0
                            && !counts.has_errors()
                            && !index.bounded_sweep_had_unsettled_upload,
                    );
                }
                let local_diagnostics = codex_title_metadata.local_diagnostics;
                let continuation_evidence = (codex_join_completed.is_empty()
                    && continuation_ticket.is_some())
                .then(|| codex_join_inventory.take())
                .flatten()
                .filter(|inventory| inventory.complete)
                .map(|inventory| CodexContinuationEvidence {
                    inventory,
                    ledgers: codex_parent_ownership_ledgers,
                    codex: codex_title_metadata,
                    traces: codex_turn_traces,
                });
                if continuation_ticket.is_some() && continuation_evidence.is_none() {
                    crate::local_resource_diagnostics::codex_continuation_mint(
                        if codex_join_completed.is_empty() {
                            "inventory_incomplete"
                        } else {
                            "groups_completed"
                        },
                    );
                }
                let scan = SourceScanResult {
                    source,
                    backfill_window_days,
                    backfill_file_limit: file_limit,
                    discovered_file_count,
                    skipped_file_count_due_to_limit,
                    scan_cap_hit: pending_work_count > 0,
                    scanned_file_count,
                    scanned_session_count,
                    semantic_noop_count,
                    census_complete,
                    census_window_end,
                    state_census_complete,
                    sidecar_census_complete,
                    symlink_rejected_count: counts.symlink_rejected_count,
                    directory_entry_cap_exceeded_count: counts.directory_entry_cap_exceeded_count,
                    unreadable_path_count: counts.unreadable_path_count,
                    oversized_file_count: counts.oversized_file_count,
                    disappeared_file_count: counts.disappeared_file_count,
                    malformed_json_line_count: counts.malformed_json_line_count,
                    invalid_utf8_line_count: counts.invalid_utf8_line_count,
                    over_line_cap_count: counts.over_line_cap_count,
                    recognized_usage_drop_count: counts.recognized_usage_drop_count,
                    ownership_incomplete_file_count: counts.ownership_incomplete_file_count,
                    causes: counts.causes,
                    zero_snapshot_confirmed_count,
                    zero_snapshot_usage_evidence_count,
                    dropped_usage_record_count,
                    terminal_ownership_incomplete_file_count: counts
                        .terminal_ownership_incomplete_file_count,
                    terminal_zero_snapshot_usage_evidence_count: counts
                        .terminal_zero_snapshot_usage_evidence_count,
                    terminal_recognized_usage_drop_count: counts
                        .terminal_recognized_usage_drop_count,
                    terminal_dropped_usage_record_count: counts.terminal_dropped_usage_record_count,
                    terminal_over_line_cap_count: counts.terminal_over_line_cap_count,
                    census_residue_index_key_count,
                    census_residue_archived_rollout_count,
                    census_residue_blocked_session_count,
                    snapshots,
                    pending_finalization,
                    codex_legacy_join_baselines,
                    claude_request_census_shadow,
                    continuation_ticket,
                    continuation_evidence: continuation_evidence
                        .map(|e| Arc::new(Mutex::new(Some(e)))),
                    codex_join_validation: codex_join_inventory
                        .filter(|_| !codex_join_completed.is_empty())
                        .map(|inventory| codex_file_join::Validation {
                            inventory,
                            groups: codex_join_completed,
                        }),
                    // Moved, not copied: the box was charged with the census.
                    codex_counting_v2: if source == SnapshotSource::Codex {
                        codex_counting_version::take_local_receipts(
                            index,
                            census.codex_counting_v2.take(),
                        )
                    } else {
                        census.codex_counting_v2.take()
                    },
                    local_codex_diagnostics: (source == SnapshotSource::Codex).then_some(
                        CodexScanDiagnostics {
                            version: 1,
                            generation: index.generation,
                            unreadable_causes: counts.unreadable_causes,
                            // PR-P: traversal-cumulative per-page counts, as
                            // `unreadable_causes`.
                            parent_unresolvable: counts.parent_unresolvable,
                            // PR-P: omitted unless established on this page.
                            parent_restarts_in_scope: codex_parent_identities.parent_restarts,
                            gates: CensusGates {
                                discovery_done: traversal_discovery_done,
                                traversal_healthy,
                                frozen_generation: clean_frozen_generation,
                                state_complete: state_census_complete,
                                sidecar_complete: sidecar_census_complete,
                                reconciliation_complete,
                                parent_restart: parent_resolution_restart,
                                clean_followup: needs_clean_followup,
                                census_complete,
                            },
                            ..local_diagnostics
                        },
                    ),
                };
                if source == SnapshotSource::ClaudeCode {
                    rearm_cause::retain(index);
                }
                let sampled_acquisition = sampling.as_ref().map(|context| {
                    let audit_now = sampled_scan::now_seconds();
                    let pending = index
                        .files
                        .values()
                        .filter(|entry| entry.has_unverified_source())
                        .count();
                    let overdue = index
                        .files
                        .values()
                        .filter(|entry| entry.audit_requires_full(audit_now))
                        .count();
                    let oldest_due_age = index
                        .files
                        .values()
                        .filter_map(|entry| entry.audit_obligation(audit_now))
                        .map(|debt| audit_now.saturating_sub(debt.due_unix_seconds))
                        .max()
                        .unwrap_or(0);
                    crate::local_resource_diagnostics::ReadCounts {
                        full_selections: context.full_files,
                        tail_selections: context.tail_files,
                        unchanged_selections: context.unchanged_files,
                        completed_native_bytes: context.native_bytes,
                        completed_guard_bytes: context.sample_bytes,
                        acquisition_admission: context.admission,
                        page_events: crate::local_resource_diagnostics::PageEvents {
                            full_cause: resource_probe.rearm_fulls(),
                            full_reasons: crate::local_resource_diagnostics::FullReasons(
                                context.full_reasons,
                            ),
                            priority_full_replays: context.priority_replays,
                            audits_started: context.audits_started,
                            audits_completed: context.audits_completed,
                            max_start_overdue_seconds: context.start_overdue_seconds,
                            max_completion_overdue_seconds: context.completion_overdue_seconds,
                        },
                        index_state_at_page_end: crate::local_resource_diagnostics::IndexState {
                            pending_audits: pending,
                            overdue_audits: overdue,
                            oldest_due_age_seconds: oldest_due_age,
                        },
                        codex_cursor: context.cache.cursor_diagnostics(&codex_page),
                    }
                });
                if sampled_acquisition.is_some() {
                    crate::local_resource_diagnostics::cache_lifecycle_totals();
                    crate::local_resource_diagnostics::codex_memo_lifecycle_totals(
                        source.api_slug(),
                    );
                    crate::local_resource_diagnostics::codex_side_lifecycle_totals(
                        source.api_slug(),
                    );
                }
                if let Some(delivery) = line_delivery.as_mut() {
                    if active_file.is_none() {
                        delivery.left_active();
                    }
                    resource_probe.line_delivery = Some(delivery.take_page());
                }
                let full_causes = std::mem::take(&mut resource_probe.full_causes);
                resource_probe.collection_with_account_pending(
                    source.api_slug(),
                    crate::local_resource_diagnostics::CollectionCounts {
                        scanned_files: scanned_file_count,
                        semantic_noops: semantic_noop_count,
                        sampled_acquisition,
                        full_causes,
                    },
                    if source == SnapshotSource::ClaudeCode {
                        index.claude_account_retained_pending_resources()
                    } else {
                        None
                    },
                );
                return Ok(OwnedSourceScanStep::Complete {
                    index: index_storage,
                    scan,
                    terminal_native_traversal,
                });
            };
            if let Some(context) = sampling
                .as_ref()
                .filter(|_| source == SnapshotSource::Codex)
            {
                if context
                    .cache
                    .cursor_job_owns(&local_index_key(&candidate.path))
                {
                    // The paused or active cursor job owns this file (a group
                    // job owns every member); it stays pending (holding the
                    // census) until that job's attempt ends (§d.1.2 c).
                    context.cache.note_join_in_progress();
                    sampled_scan::codex_cursor::requeue(index, &codex_selected_flags, &candidate);
                    pending!();
                }
            }
            // Path-(a) tombstone: a returning, unindexed member of a family
            // this index retired as absent. It is never skipped forever and
            // never read as a fresh file: the candidate decision routes it
            // through the family's authority path (see
            // `candidate_decision_with_reason_gated`). Counted per sighting.
            if source == SnapshotSource::ClaudeCode
                && index.claude_retired_family_member(&candidate.path)
                && !index.files.contains_key(&local_index_key(&candidate.path))
            {
                with_claude_absence_counters(|counters| {
                    counters.tombstone_hits = counters.tombstone_hits.saturating_add(1);
                });
            }
            let preflight_source_file_fingerprint =
                claude_authority_preflight_fingerprint(index, &candidate);
            if let Some(context) = attribution_context {
                let workers =
                    launch_workers_for_candidate(source, &candidate, codex_join_inventory.as_ref());
                match context.prepare_launch_step(&workers) {
                    Ok(false) => {
                        identified_candidates.push_front(candidate);
                        pending!();
                    }
                    Err(()) => {
                        census.record_unreadable(UnreadableCause::Reduction, 1);
                        pending!();
                    }
                    Ok(true) => {}
                }
            }
            // Keep the prepass physical identity intact while lookup yields. Only
            // replace it with sidecar inputs immediately before the second open.
            prepare_owned_scan_candidate(
                source,
                &mut candidate,
                &codex_title_metadata,
                &claude_title_metadata,
                claude_effort_support_dir_ref,
            );
            let verification_rescue = sampled_audit::progress_debt(
                index,
                &local_index_key(&candidate.path),
                sampled_scan::now_seconds(),
            )
            .is_some();
            let Some((mut candidate, opened_file)) = open_and_identify_scan_candidate_with_rescue(
                source,
                candidate,
                &mut census,
                census_unix_seconds,
                backfill_window_days,
                &index.files,
                verification_rescue,
                sampling.as_ref().map(|context| context.cache.as_ref()),
            ) else {
                pending!();
            };
            if preflight_source_file_fingerprint
                .as_ref()
                .is_some_and(|fingerprint| fingerprint != &candidate.source_file_fingerprint)
            {
                // A quarantined candidate changed after the family prepass. Do not
                // parse a mixed family or refresh its retry record; keep this
                // generation non-terminal and retry the new exact object together.
                disappearance_diagnostics::increment(
                    &mut census.disappeared_file_count,
                    source,
                    disappearance_diagnostics::Cause::PreflightFingerprintChanged,
                );
                pending!();
            }
            // The preflight fences physical/sidecar identity. Local launcher facts
            // are semantic context and must not contaminate that two-open witness.
            if let Some(context) = attribution_context {
                let workers =
                    launch_workers_for_candidate(source, &candidate, codex_join_inventory.as_ref());
                if let Some(witness) = context.launch_witness(&workers) {
                    candidate.source_file_fingerprint = sha256_hex(&[
                        "launcher_worker_context:v1",
                        &candidate.source_file_fingerprint,
                        &witness,
                    ]);
                }
            }
            // Constructor preflight has only physical identities. Reconcile its
            // family retry decision once launcher context is prepared, while keeping
            // the two-open equality check above physical. Every family member must
            // match the retained revision before withdrawing a forced retry.
            if source == SnapshotSource::ClaudeCode {
                if let Some(context) = attribution_context {
                    if let Some((root, _)) = claude_index_path_family_member(&candidate.path) {
                        if forced_claude_family_reparses.contains(&root)
                            && claude_held_family_matches_launch_context(
                                index,
                                &root,
                                &candidate,
                                &identified_candidates,
                                context,
                            )
                        {
                            forced_claude_family_reparses.remove(&root);
                        }
                    }
                }
            }
            if index.decode_holds_file(&local_index_key(&candidate.path)) {
                index.mark_bounded_sweep_unsettled();
                pending!();
            }
            let (mut decision, parse_reason) =
                match claude_index_path_family_member(&candidate.path).filter(
                    |(root_session_id, _)| forced_claude_family_reparses.contains(root_session_id),
                ) {
                    // A twin-only forced member that owes only adoption keeps that
                    // reason, so the history gate can hold the whole twin group.
                    Some((root_session_id, _))
                        if claude_twin_only_family_reparses.contains(&root_session_id)
                            && index.candidate_decision_with_reason(&candidate)
                                == (
                                    CandidateDecision::Parse,
                                    Some(CandidateParseReason::BodyWitnessAdoption),
                                ) =>
                    {
                        (
                            CandidateDecision::Parse,
                            Some(CandidateParseReason::BodyWitnessAdoption),
                        )
                    }
                    Some(_) => (
                        CandidateDecision::Parse,
                        Some(CandidateParseReason::ForcedFamily),
                    ),
                    None => index.candidate_decision_with_reason(&candidate),
                };
            let target_match = native_comparison
                .as_ref()
                .and_then(|phase| phase.target_revision_matches(&candidate));
            if target_match == Some(false) {
                // Comparison requires this exact frozen object and sidecars.
                // The ordinary path may reparse replacements, but a target
                // cannot silently claim that it compared the frozen revision.
                disappearance_diagnostics::increment(
                    &mut census.disappeared_file_count,
                    source,
                    disappearance_diagnostics::Cause::ComparisonTargetRevisionChanged,
                );
                pending!();
            }
            let comparison_target = target_match == Some(true);
            if comparison_target {
                decision = CandidateDecision::Parse;
            }
            // History-upgrade gate (SOURCE P1), whatever selected the file:
            // unchanged Claude history that would carry a new body-witness
            // revision passes the list, the no-list birth hold, the family
            // skip, the stop latch and this page's budget (reserved once per
            // file). A held file that only owes the upgrade is skipped with
            // its old stamp. A held file selected for another reason (upload
            // context, re-arm, family, audit, authority, a rebuilt or replayed
            // index) still parses for its local work, but none of its bodies
            // is emitted and its upload tuple stays (`veto_claude_history_emission`).
            // A skipped Claude file held only by this page's budget is queued
            // again as a re-read for the next page of the walk. Codex and Pi
            // keep the adoption-only page budget.
            if decision == CandidateDecision::Parse {
                let adoption_only = parse_reason == Some(CandidateParseReason::BodyWitnessAdoption)
                    && index.candidate_requires_only_body_witness_adoption(&candidate);
                let history = if source == SnapshotSource::ClaudeCode {
                    index.claude_history_upgrade_decision(
                        &candidate,
                        opened_file
                            .metadata()
                            .and_then(|metadata| metadata.created())
                            .ok()
                            .and_then(unix_seconds),
                        &mut history_upgrade,
                    )
                } else if adoption_only
                    && !comparison_target
                    && !history_upgrade.reserve_admitting_first_file(
                        &local_index_key(&candidate.path),
                        candidate.size_bytes,
                    )
                {
                    history_upgrade.note_denied(
                        HistoryHold::Budget,
                        index.claude_reemission_exclusions.state(),
                    );
                    HistoryDecision::Held(HistoryHold::Budget)
                } else {
                    HistoryDecision::NotOwed
                };
                // A held, unchanged member owed only a proof correction is not
                // re-read every traversal either: its bodies would be vetoed,
                // and the correction waits for the gate (StateMissing M2).
                let correction_only = parse_reason
                    == Some(CandidateParseReason::AuthorityQuarantine)
                    && index.claude_authority_correction_only(&candidate);
                // A listed genuine change is never held (it is literal-only
                // denied), so a held correction-only member is unchanged.
                match history {
                    HistoryDecision::Held(hold)
                        if (adoption_only || correction_only) && !comparison_target =>
                    {
                        if source == SnapshotSource::ClaudeCode {
                            let carried = index
                                .accepted_rebuild_incidence
                                .get(&local_index_key(&candidate.path))
                                .map_or(0, BTreeSet::len);
                            index.claude_history_emission.skipped_carried_entries = index
                                .claude_history_emission
                                .skipped_carried_entries
                                .saturating_add(carried);
                            // A budget hold paces the upgrade page by page:
                            // the file goes back to the walk's queue as a
                            // re-read, so the next page of this walk continues
                            // the upgrade (Design E2 item 8, the switch-on
                            // re-read). A re-read is not a census member
                            // (G1): it never holds the census, and a walk
                            // that ends first drops it for the next walk to
                            // list again. Only once this page admitted
                            // history: a file that cannot fit an empty page
                            // waits for the next walk as before.
                            if hold == HistoryHold::Budget && history_upgrade.admitted_any() {
                                if let Some(traversal) = index.traversal.as_mut() {
                                    traversal.pending_candidates.push_back(ScanTraversalPath {
                                        scan_root: candidate.scan_root.clone(),
                                        path: candidate.path.clone(),
                                        census_member: false,
                                        watcher_hint: false,
                                    });
                                }
                            }
                        }
                        decision = CandidateDecision::Skip;
                    }
                    HistoryDecision::Held(hold) => {
                        index.gate_claude_history_candidate(&candidate, Some(hold));
                    }
                    HistoryDecision::Owed => index.gate_claude_history_candidate(&candidate, None),
                    HistoryDecision::LiteralDenied => {
                        index.deny_claude_history_literal(&candidate);
                    }
                    HistoryDecision::NotOwed => {}
                }
            }
            if source == SnapshotSource::ClaudeCode && decision == CandidateDecision::Parse {
                if let Some(reason) = parse_reason {
                    let count = &mut census.parse_reasons[reason as usize];
                    *count = count.saturating_add(1);
                }
            }
            index.note_reason_reoffer_cooldown_candidate(
                &candidate,
                decision == CandidateDecision::Skip && parse_reason.is_none(),
            );
            // U1a-2a (row 9): P's side read, when main skips an unchanged P
            // that owes no PR-P reparse and its side request is due. Every
            // main write on its path is gated (G2–G17); it ends at the side
            // exit.
            let mut side_plan = None;
            let mut codex_selected_by = None;
            if source == SnapshotSource::Codex && decision == CandidateDecision::Skip {
                let shared = codex_parent_ownership_ledgers.as_ref();
                let owed = codex_parent_reparse_owed_ids(index, shared, &candidate.path);
                if owed.is_empty()
                    && index
                        .codex_parent_side_requests
                        .contains_key(&local_index_key(&candidate.path))
                    && index.terminal_jsonl_loss(&candidate).is_none()
                {
                    if let Some(((context, pass), at)) = sampling
                        .as_ref()
                        .zip(codex_side_pass.as_ref())
                        .zip(side_now(&opened_file))
                    {
                        let terms = || SideDueTerms {
                            census_complete: state_census_complete && sidecar_census_complete,
                            header_current: codex_join_inventory.as_ref().is_some_and(
                                |inventory| {
                                    inventory.complete
                                        && inventory
                                            .headers
                                            .iter()
                                            .any(|header| header.candidate.path == candidate.path)
                                },
                            ),
                            owner_members: sampled_scan::codex_cursor::owner_members(
                                codex_join_inventory.as_ref(),
                                &candidate.path,
                            ),
                            dependencies: sampled_scan::reduction_dependencies(
                                source,
                                &candidate,
                                &codex_title_metadata,
                                &claude_title_metadata,
                                claude_effort_support_dir_ref,
                            )
                            .is_some(),
                        };
                        if index.codex_parent_side_request_due(
                            &local_index_key(&candidate.path),
                            at,
                            sampled_scan::now_seconds(),
                            &context.cache,
                            pass,
                            terms,
                        ) {
                            side_plan = Some(at);
                            decision = CandidateDecision::Parse;
                            codex_selected_by = Some(CodexSelection::SideRead);
                        }
                    }
                } else if !owed.is_empty() && index.terminal_jsonl_loss(&candidate).is_none() {
                    // An unresolved child requested this unchanged parent after
                    // its earlier page had already passed. Reparse only that
                    // parent to populate bounded structural evidence.
                    decision = CandidateDecision::Parse;
                    codex_selected_by = Some(CodexSelection::OwedParent);
                } else if let Some(context) = sampling.as_ref().filter(|_| !owed.is_empty()) {
                    // A terminal disposition at this exact file fingerprint and
                    // parser generation means the previous traversal already
                    // parsed this object to completion and disclosed its loss.
                    // Parsing is deterministic over unchanged bytes, so a
                    // reparse would rebuild the same lossy ledger, be rejected
                    // again, and re-arm this override forever - an unbounded
                    // full reread of a multi-hundred-MB parent every cycle.
                    // PR-P event (c): witness it instead, gated on this object
                    // being the parent's unique current rollout. The child
                    // stays held; only a new fingerprint or generation
                    // re-opens the file (`candidate_decision`,
                    // `terminal_jsonl_loss`).
                    let scope = sampled_scan::codex_cursor::group_scope(index);
                    for parent in &owed {
                        let (current, fresh) = codex_parent_identities
                            .probe(codex_parent_identities.census(index), parent);
                        if fresh {
                            codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                        }
                        if current.ok().as_deref()
                            == Some(candidate.opened_object_identity.as_str())
                        {
                            context.cache.witness_parent(
                                &context.namespace,
                                &scope,
                                parent,
                                sampled_scan::codex_cursor::ParentWitness {
                                    cause: CodexParentUnresolvable::ParentLossy,
                                    identity: Some(context.cache.retained_stamp_identity(
                                        &candidate,
                                        &candidate.opened_object_identity,
                                    )),
                                    waits_on: None,
                                },
                            );
                            witness_in_step_map(
                                shared,
                                parent,
                                CodexParentUnresolvable::ParentLossy,
                            );
                        }
                    }
                }
            }
            if source == SnapshotSource::Codex {
                census.note_codex_selection(decision, parse_reason, codex_selected_by);
            }
            // A parse of a carried family's member cancels that family's
            // carry, so the family is co-observed in this window as BASE's
            // re-arm would observe it. A re-armed member is no new change.
            if source == SnapshotSource::ClaudeCode
                && decision == CandidateDecision::Parse
                && parse_reason != Some(CandidateParseReason::Rearmed)
            {
                cancel_claude_family_carry_for_member_parse(
                    index,
                    &census_window_end,
                    &candidate.path,
                    &snapshots,
                    &identified_candidates,
                );
            }
            match decision {
                CandidateDecision::Skip => {
                    #[cfg(feature = "replay-harness")]
                    resource_probe.index_reuse_skip();
                    if let Some(phase) = native_comparison.as_mut() {
                        if let Some(credit) = capture_credit.as_deref_mut() {
                            phase.record_actual_skip_paid(
                                index,
                                &candidate,
                                &census_window_end,
                                credit,
                            );
                        } else {
                            phase.record_actual_skip(index, &candidate, &census_window_end);
                        }
                    }
                    if let Some(loss) = index.terminal_jsonl_loss(&candidate) {
                        census.add_terminal_jsonl_loss(loss);
                    }
                    pending!();
                }
                CandidateDecision::Migrate => {
                    index.migrate(candidate);
                    pending!();
                }
                CandidateDecision::ReconcileLegacy | CandidateDecision::Parse => {}
            }
            #[cfg(unix)]
            let mut recovered_audit_due = None;
            #[cfg(not(unix))]
            let recovered_audit_due = None;
            #[cfg(unix)]
            if side_plan.is_none() {
                if let Some(cache) = durable_guard.as_ref().and_then(std::sync::Weak::upgrade) {
                    let key = local_index_key(&candidate.path);
                    if let Some(reason) =
                        cache.durable_hold(source, &key, index, &mut recovered_audit_due)
                    {
                        cache.durable_hold_exit(source, reason, index, &candidate, &mut census);
                        pending!();
                    }
                }
            }
            if let Some(context) = sampling
                .as_ref()
                .filter(|_| source == SnapshotSource::Codex)
            {
                let wake_stamp = sampled_scan::codex_cursor::OpenStamp::capture(&opened_file)
                    .ok()
                    .map(|stamp| context.cache.retained_stamp(&candidate.path, stamp));
                let key = local_index_key(&candidate.path);
                // Keyed per namespace (R1-M1): the digest carries the upload
                // context, so concurrent namespaces must not evict each other.
                let memo_key = sampled_scan::codex_cursor::memo_key(&context.namespace, &key);
                use crate::local_resource_diagnostics::codex_memo_lifecycle;
                // R1-M1 (PR-1) and PR-P: an owed parent must be parsed, so a
                // held memo hit cannot hide its own ledger (PR-1) or its
                // parent-side cause (event (b)). A parent that a settling
                // witness already explains is not owed; `DeferredRestart`
                // never settles, so quietness cannot hide a parent.
                let owed_parent = !codex_parent_reparse_owed_ids(
                    index,
                    codex_parent_ownership_ledgers.as_ref(),
                    &candidate.path,
                )
                .is_empty();
                // U1a-2a G2: a side read makes no memo lookup or event.
                let entry = if side_plan.is_some() {
                    None
                } else {
                    context.cache.memo_lookup(&memo_key)
                };
                // PR-P widens PR-1's `has_own_ledger()` condition to every
                // entry: a held parent without its own ledger must also fire
                // event (b).
                let bypass = owed_parent && entry.is_some();
                if bypass {
                    codex_memo_lifecycle::record(codex_memo_lifecycle::Event::MissOther);
                }
                if let Some(entry) = entry.filter(|_| !bypass) {
                    // The match re-reads two samples of the held file (M3).
                    codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                    let sidecar_now = sampled_scan::codex_cursor::sidecar_fingerprint(
                        &codex_title_metadata,
                        &candidate.path,
                    );
                    // L4 (PR-1): the parent's index ledger identity, and its
                    // current opened identity (L-5 probe; charged when it opens).
                    let parent_now = entry.parent_ref().map(|parent| {
                        let (current, qualified) = retained_codex_parent(
                            codex_parent_identities.census(index),
                            parent,
                            &context.cache,
                        );
                        codex_page.charge(false, sampled_scan::codex_cursor::SAMPLE_READ_BYTES);
                        sampled_scan::codex_cursor::ParentNow {
                            ledger: retained_parent_ledger(
                                index
                                    .codex_parent_ownership_ledgers
                                    .get(resolve_codex_identity(parent).as_str())
                                    .map(|ledger| ledger.opened_object_identity.clone()),
                                qualified.as_ref(),
                            ),
                            current: current.ok(),
                            // PR-P: the step map's witness, as the classifier
                            // would read it now; an overflowing ref is
                            // `DeferredRef` with no entry. Only for an entry
                            // whose parse consulted the step map (marked by
                            // `Disclosure.parent_ref`); any other child
                            // recorded `witnessed: None` and compares equal.
                            witnessed: entry.disclosure().parent_ref.as_ref().and_then(|_| {
                                step_map_witness(codex_parent_ownership_ledgers.as_ref(), parent)
                                    .or_else(|| {
                                        (!index.codex_parent_ref_fits(parent))
                                            .then_some(CodexParentUnresolvable::DeferredRef)
                                    })
                            }),
                        }
                    });
                    let digest = sampled_scan::reduction_dependencies(
                        source,
                        &candidate,
                        &codex_title_metadata,
                        &claude_title_metadata,
                        claude_effort_support_dir_ref,
                    )
                    .and_then(|dependencies| {
                        sampled_scan::codex_cursor::memo_digest(
                            index,
                            &candidate,
                            &opened_file,
                            &dependencies,
                            &codex_title_metadata,
                            sampled_scan::codex_cursor::owner_members(
                                codex_join_inventory.as_ref(),
                                &candidate.path,
                            ),
                            &sampled_scan::codex_cursor::counting_view(&candidate, index),
                        )
                    });
                    let hit = digest.as_deref().and_then(|digest| {
                        entry.matches_stamp(
                            &candidate.path,
                            digest,
                            &opened_file,
                            parent_now.as_ref(),
                            &sidecar_now,
                            wake_stamp.clone()?,
                        )
                    });
                    if let Some(stamp) = hit {
                        // An append cannot cure this hold and no wake
                        // dependency changed: disclose the same terminal
                        // debt again at zero transcript bytes.
                        codex_memo_lifecycle::add(
                            codex_memo_lifecycle::Event::HitEstimatedAvoidedParserBytes,
                            stamp.extent(),
                        );
                        context.cache.memo_hit(&memo_key, stamp);
                        let keep_previous = decision != CandidateDecision::ReconcileLegacy
                            && !index
                                .effective_upload_body_witness_revision_requires_adoption(&key);
                        let previous = (
                            keep_previous
                                .then(|| index.last_snapshot_fingerprint(&candidate))
                                .flatten(),
                            keep_previous
                                .then(|| index.last_upload_body_witness(&candidate))
                                .flatten(),
                        );
                        sampled_scan::codex_cursor::disclose_terminal_codex_debt(
                            entry.disclosure(),
                            &candidate,
                            previous,
                            index,
                            sampled_scan::codex_cursor::DisclosureTargets {
                                census: &mut census,
                                residue_index_keys: &mut residue_index_keys,
                                residue_blocked_session_ids: &mut residue_blocked_session_ids,
                                codex_state_only_blocked_session_ids:
                                    &mut codex_state_only_blocked_session_ids,
                                pending_finalization: &mut pending_finalization,
                            },
                        );
                        // R1-L6: the fresh path's session count, replayed.
                        scanned_session_count += entry.disclosure().parsed_snapshot_count;
                        pending!();
                    }
                    match digest.as_deref().and_then(|digest| {
                        entry.grew_past_exact(
                            &candidate.path,
                            digest,
                            &opened_file,
                            parent_now.as_ref(),
                            &sidecar_now,
                        )
                    }) {
                        Some(extent) => {
                            codex_memo_lifecycle::record(
                                codex_memo_lifecycle::Event::MissExactStamp,
                            );
                            codex_memo_lifecycle::add(
                                codex_memo_lifecycle::Event::MissExactStampBytes,
                                extent,
                            );
                        }
                        None => {
                            codex_memo_lifecycle::record(codex_memo_lifecycle::Event::MissOther)
                        }
                    }
                    context.cache.memo_forget(&memo_key);
                }
                // A parked `JoinStateBound` file is not read again until it
                // is replaced, shrunk or edited, or its reduction dependencies
                // change; growth cannot cure it (§c.2, M-2).
                // U1a-2a G3: a side read never touches the parked set.
                let parked = side_plan
                    .is_none()
                    .then(|| {
                        context.cache.cursor_parked_stamp(
                            &key,
                            wake_stamp.clone(),
                            sampled_scan::reduction_dependencies(
                                source,
                                &candidate,
                                &codex_title_metadata,
                                &claude_title_metadata,
                                claude_effort_support_dir_ref,
                            )
                            .as_deref(),
                        )
                    })
                    .flatten();
                if let Some(disclosure) = parked {
                    let keep_previous = decision != CandidateDecision::ReconcileLegacy
                        && !index.effective_upload_body_witness_revision_requires_adoption(&key);
                    let previous = (
                        keep_previous
                            .then(|| index.last_snapshot_fingerprint(&candidate))
                            .flatten(),
                        keep_previous
                            .then(|| index.last_upload_body_witness(&candidate))
                            .flatten(),
                    );
                    sampled_scan::codex_cursor::disclose_terminal_codex_debt(
                        &disclosure,
                        &candidate,
                        previous,
                        index,
                        sampled_scan::codex_cursor::DisclosureTargets {
                            census: &mut census,
                            residue_index_keys: &mut residue_index_keys,
                            residue_blocked_session_ids: &mut residue_blocked_session_ids,
                            codex_state_only_blocked_session_ids:
                                &mut codex_state_only_blocked_session_ids,
                            pending_finalization: &mut pending_finalization,
                        },
                    );
                    pending!();
                }
                #[cfg(test)]
                CODEX_BEFORE_PARSE.with(|slot| {
                    if let Some(hook) = slot.borrow_mut().as_mut() {
                        hook(&candidate.path);
                    }
                });
                // Fresh-first page budget, decided before any retained state is
                // consumed: the optimistic read is the tail extent when a
                // retained entry exists, the whole file otherwise.
                let extent = opened_file.metadata().map_or(0, |metadata| metadata.len());
                // U1a-2a G4a: a side read is a full read with no retained
                // state, and 2a reads only a singleton (otherwise main's Skip).
                let expected = if side_plan.is_some() {
                    extent
                } else {
                    extent.saturating_sub(context.cache.retained_sealed_offset(&key).unwrap_or(0))
                };
                if side_plan.is_some()
                    && expected > sampled_scan::codex_cursor::Limits::current().singleton()
                {
                    pending!();
                }
                match context.cache.cursor_plan_paced(
                    &mut codex_page,
                    sampled_scan::codex_cursor::Limits::current(),
                    expected,
                    codex_cursor_lease.is_none() && context.cache.cursor_slot_free(),
                    crate::heap_layout_bound::layout_supported(),
                    &context.namespace,
                    &key,
                    sampled_scan::codex_cursor::census_token(index).as_deref(),
                    sampled_scan::codex_cursor::census_member(
                        &codex_selected_flags,
                        [candidate.path.as_path()],
                    ),
                    // Stage 1 guard (§6): a side read is never paced.
                    side_plan
                        .is_none()
                        .then_some(sampled_scan::codex_cursor::PaceProbe {
                            file: &opened_file,
                            index,
                        }),
                ) {
                    // U1a-2a G4a: a side deferral writes nothing (uncharged).
                    sampled_scan::codex_cursor::StartPlan::Defer if side_plan.is_some() => {
                        pending!()
                    }
                    sampled_scan::codex_cursor::StartPlan::Defer => {
                        context.cache.cursor_note_deferred();
                        sampled_scan::codex_cursor::requeue(
                            index,
                            &codex_selected_flags,
                            &candidate,
                        );
                        pending!();
                    }
                    // Processed for this generation (K7 fence): not requeued,
                    // so the census can complete; the next generation reads it.
                    sampled_scan::codex_cursor::StartPlan::Fenced => pending!(),
                    sampled_scan::codex_cursor::StartPlan::Singleton
                    | sampled_scan::codex_cursor::StartPlan::Cursor
                    | sampled_scan::codex_cursor::StartPlan::Unpaged => {}
                }
            }
            if let Some(phase) = native_comparison.as_mut() {
                // This is an actual native acquisition attempt, before parser
                // construction can fail or complete with no emitted entity.
                if let Some(credit) = capture_credit.as_deref_mut() {
                    let captured = phase.record_parse_attempt_paid(&candidate, credit);
                    if !captured && comparison_target {
                        // The ordinary candidate was a Skip. Refuse this extra
                        // target before opening its parser or retaining bodies;
                        // the controller's existing fallback preserves debt.
                        pending!();
                    }
                } else {
                    phase.record_parse_attempt(&candidate);
                }
            }
            let target_input_credit = if comparison_target {
                match capture_credit.as_deref_mut() {
                    Some(credit) => Some(
                        native_comparison
                            .as_ref()
                            .expect("checked target phase")
                            .prepay_target_input_metadata(&candidate, index, credit)?,
                    ),
                    None => None, // logical test adapter only
                }
            } else {
                None
            };
            // U1a-2a G5: a side read is not a scanned file.
            if side_plan.is_none() {
                scanned_file_count += 1;
            }
            // U1a-2a G7 (row 15): the side read's charge and start line,
            // before the parser or any acquisition reads P. A refused charge
            // is main's Skip (nothing written).
            let mut side_origin = None;
            if let Some(at) = side_plan {
                let Some((context, pass)) = sampling.as_ref().zip(codex_side_pass.as_ref()) else {
                    pending!();
                };
                let Some(attempts) = index.charge_codex_parent_side_read(
                    &local_index_key(&candidate.path),
                    at,
                    sampled_scan::now_seconds(),
                    &context.cache,
                    pass,
                ) else {
                    pending!();
                };
                side_origin = Some(SideOrigin {
                    guard: crate::local_resource_diagnostics::codex_side_lifecycle::SideReadGuard::start(
                        attempts,
                    ),
                    dev_ino: at.dev_ino,
                });
            }
            let previous_snapshot_fingerprint = index.last_snapshot_fingerprint(&candidate);
            let previous_upload_body_witness = index.last_upload_body_witness(&candidate);
            let projection_adoption_required = index
                .effective_upload_body_witness_revision_requires_adoption(&local_index_key(
                    &candidate.path,
                ));
            let source_file_fingerprint = candidate.source_file_fingerprint.clone();
            if let Some(bytes) = target_input_credit {
                native_comparison
                    .as_mut()
                    .expect("checked target phase")
                    .retain_target_metadata(bytes, capture_credit.expect("funded target input"))?;
            }

            if side_origin.is_some() && check_parent_side_input(&candidate, None).is_err() {
                if let Some(side) = side_origin {
                    side.end();
                }
                pending!();
            }
            let mut parser = match sampled_scan::new_source_parser(
                opened_file,
                &candidate,
                source,
                &codex_title_metadata,
                codex_turn_traces.clone(),
                codex_parent_ownership_ledgers.clone(),
                source != SnapshotSource::ClaudeCode || artifacts_enabled,
                context_curve_enabled,
                claude_request_identity_capture,
                index,
            ) {
                Ok(parser) => parser,
                // U1a-2a G6: the side read's charged attempt; no census line.
                Err(_) if side_origin.is_some() => {
                    if let Some(side) = side_origin {
                        side.end();
                    }
                    pending!();
                }
                Err(_) => {
                    if source == SnapshotSource::ClaudeCode {
                        claude_request_census::invalidate_claude_request_census(
                            index,
                            &candidate.path,
                        );
                    }
                    census.record_unreadable(UnreadableCause::Reduction, 1);
                    pending!();
                }
            };
            // U1a-2a (D6(a)): this child's proof, P-fenced before its parse.
            // A side read is P's, never a proof consumer.
            if source == SnapshotSource::Codex && side_origin.is_none() {
                let side = sampling
                    .as_ref()
                    .zip(codex_side_pass.as_ref())
                    .map(|(context, pass)| (&*context.cache, pass.ns));
                if install_codex_parent_proof(
                    &mut parser,
                    &candidate,
                    index,
                    &codex_parent_identities,
                    side,
                    sampled_scan::now_seconds(),
                ) {
                    // R1-M1: P's side fence (its admission and at most one
                    // `samples_match`) and the proof seal's `admits`.
                    codex_page.charge(false, PROOF_FENCE_READ_BYTES);
                }
            }
            let mut file_sampling = None;
            let mut retained_offset = None;
            // Counted once the page actually reads the file (R2-M3): a fence
            // or deferral below does not inflate the read diagnostics.
            let mut planned_mode = None;
            // U1a-2a G7: a side read's acquisition is a fresh `Full` read
            // under the side scope: no retained take, no admission observes
            // or counters, no debt. Failures are its charged attempt.
            if side_origin.is_some() {
                // Defensive: a compressed input has no physical offsets or
                // samples (no production open builds one today).
                if check_parent_side_input(&candidate, Some(&parser.reader.reader)).is_err() {
                    if let Some(side) = side_origin {
                        side.end();
                    }
                    pending!();
                }
                let scope = codex_parent_side_scope();
                match parser.prepare_acquisition(None, &scope, None, sampled_scan::now_seconds()) {
                    Ok(mode) => {
                        sampled_scan::configure_tier_replay(&mut parser, &candidate, index);
                        file_sampling = Some(sampled_scan::Active {
                            key: local_index_key(&candidate.path),
                            scope,
                            mode,
                            audit_due: None,
                            retained_hint: None,
                            retained_finalization_charge: 0,
                            retained_usage: None,
                            reinsertion: Default::default(),
                        });
                    }
                    Err(_) => {
                        if let Some(side) = side_origin {
                            side.end();
                        }
                        pending!();
                    }
                }
            } else if let Some(context) = sampling.as_mut() {
                let key = local_index_key(&candidate.path);
                let taken = context.cache.take(&key);
                // Kept beside the moved copy for R0's completion decision.
                let taken_admission = taken.as_ref().map(|taken| {
                    (
                        taken.modified_hint,
                        taken.finalization_charge,
                        taken.retained.state.usage_witness(),
                    )
                });
                let e2_held_new_file = source == SnapshotSource::ClaudeCode
                    && taken.as_ref().is_some_and(|taken| taken.e2_held_new_file);
                let retained = taken.map(|taken| taken.retained);
                let retained_present = retained.is_some();
                let reinsertion =
                    crate::local_resource_diagnostics::claude_reread::Reinsertion::new(
                        retained_present,
                    );
                context.admission.attempts = context.admission.attempts.saturating_add(1);
                context.admission.retained_entry.observe(retained_present);
                if !retained_present {
                    // No historical expiry/eviction/clear/admission reason is
                    // carried by this lookup (including a failed cache lock).
                    context.admission.cache_lookup_miss_unknown_origin = context
                        .admission
                        .cache_lookup_miss_unknown_origin
                        .saturating_add(1);
                }
                retained_offset = retained
                    .as_ref()
                    .map(|retained| retained.checkpoint.sealed_offset());
                let owning_header_is_current = source != SnapshotSource::Codex
                    || codex_join_inventory.as_ref().is_some_and(|inventory| {
                        inventory.complete
                            && inventory
                                .headers
                                .iter()
                                .any(|header| header.candidate.path == candidate.path)
                    });
                context
                    .admission
                    .owning_header_current
                    .observe(owning_header_is_current);
                context
                    .admission
                    .state_census_complete
                    .observe(state_census_complete);
                context
                    .admission
                    .sidecar_census_complete
                    .observe(sidecar_census_complete);
                // Claude's retained reduction is captured before metadata is
                // applied in finish. Its exact per-session dependencies still
                // fence reuse; unrelated inventory coverage cannot force a Full
                // on growth. Coverage/identity/publication gates below remain
                // unchanged, and Codex still needs its closed-world sidecars.
                // Partial Desktop coverage permits continuing a known native
                // session, not admitting a new cold file to sampled acquisition.
                // Without an index entry or its own held-new certificate, keep
                // main's unsampled read and copy-refusal exemption.
                let scoped_claude_metadata = source == SnapshotSource::ClaudeCode
                    && !sidecar_census_complete
                    && (index.files.contains_key(&key) || e2_held_new_file);
                if owning_header_is_current
                    && state_census_complete
                    && (sidecar_census_complete || scoped_claude_metadata)
                {
                    if scoped_claude_metadata {
                        crate::local_resource_diagnostics::claude_reread::desktop_scoped_acquisition();
                    }
                    let reduction_sidecar = sampled_scan::reduction_dependencies(
                        source,
                        &candidate,
                        &codex_title_metadata,
                        &claude_title_metadata,
                        claude_effort_support_dir_ref,
                    );
                    context
                        .admission
                        .reduction_dependencies_available
                        .observe(reduction_sidecar.is_some());
                    if let Some(reduction_sidecar) = reduction_sidecar {
                        let debt =
                            sampled_audit::debt_for_key(index, &key, sampled_scan::now_seconds())
                                .or(recovered_audit_due.map(|due_unix_seconds| {
                                    crate::transcript_acquisition::AuditDebt { due_unix_seconds }
                                }));
                        let protected_entry = index.files.get(&key);
                        context
                            .admission
                            .index_entry_present
                            .observe(protected_entry.is_some());
                        let protected =
                            protected_entry.is_some_and(ScanIndexEntry::codex_history_is_protected);
                        let forced_family = claude_index_path_family_member(&candidate.path)
                            .is_some_and(|(root, _)| {
                                forced_claude_family_reparses.contains(&root)
                                    || index.claude_usage_authority_quarantine.contains_key(&root)
                            });
                        let parent_proof_required = source == SnapshotSource::Codex
                            && codex_session_id_candidates_from_path(&candidate.path)
                                .iter()
                                .any(|id| index.codex_parent_ownership_refs.contains(id));
                        let allow_sample = context.audit_metadata_supported
                        // A same-process E2-held native read may reuse its own
                        // certificate. It grants no persisted/index authority;
                        // scope, object, prefix and audit checks still apply.
                        && (index.files.contains_key(&key) || e2_held_new_file)
                        && !protected
                        && !forced_family
                        && !comparison_target
                        && !parent_proof_required
                        && (debt.is_some() || context.audit_slots > 0);
                        context
                            .admission
                            .audit_metadata_supported
                            .observe(context.audit_metadata_supported);
                        context.admission.protected_history.observe(protected);
                        context.admission.forced_family.observe(forced_family);
                        context
                            .admission
                            .comparison_target
                            .observe(comparison_target);
                        context
                            .admission
                            .parent_proof_required
                            .observe(parent_proof_required);
                        context.admission.audit_debt_present.observe(debt.is_some());
                        context
                            .admission
                            .audit_slot_available
                            .observe(context.audit_slots > 0);
                        context.admission.sampling_allowed.observe(allow_sample);
                        if retained_present && !allow_sample {
                            context.admission.retained_entry_rejected_by_eligibility = context
                                .admission
                                .retained_entry_rejected_by_eligibility
                                .saturating_add(1);
                        }
                        let scope = context.file_scope(
                            source,
                            &candidate,
                            &reduction_sidecar,
                            source != SnapshotSource::ClaudeCode || artifacts_enabled,
                            context_curve_enabled,
                            index,
                        );
                        // M1: on a RAM miss, a durable record may restore
                        // the copy (charged to the RAM cache, then taken as
                        // a retained copy); any refusal leaves the read Full.
                        // #814's E2 held-new flag is RAM-only in M1: a miss
                        // carries it false, and a restore needs the
                        // committed index entry, so it never widens reuse.
                        #[cfg(unix)]
                        context.cache.durable_note_scope(source, &key, &scope);
                        #[cfg(unix)]
                        let (retained, taken_admission, debt) = match retained {
                            None if allow_sample && !parser.reader.reader.is_compressed() => {
                                let interpretation = sampled_scan::durable_tail::Interpretation::of(
                                    source,
                                    &key,
                                    index,
                                    claude_request_identity_capture,
                                    &context.namespace,
                                );
                                let restore = context.cache.durable_restore(
                                    source,
                                    &key,
                                    &candidate.path,
                                    &scope,
                                    parser.reader.reader.get_mut(),
                                    index,
                                    &interpretation,
                                );
                                resource_probe.full_causes.restore_outcome.record(&restore);
                                match restore {
                                    sampled_scan::durable_tail::RestoreOutcome::Restored(taken) => {
                                        retained_offset =
                                            Some(taken.retained.checkpoint.sealed_offset());
                                        let admission = (
                                            taken.modified_hint,
                                            taken.finalization_charge,
                                            taken.retained.state.usage_witness(),
                                        );
                                        (Some(taken.retained), Some(admission), debt)
                                    }
                                    sampled_scan::durable_tail::RestoreOutcome::Miss(class) => {
                                        let rearmed = class.rearm_audit(
                                            index,
                                            &key,
                                            sampled_scan::now_seconds(),
                                        );
                                        if rearmed.is_some() && debt.is_none() {
                                            context.audit_slots =
                                                context.audit_slots.saturating_sub(1);
                                        }
                                        (None, taken_admission, rearmed.or(debt))
                                    }
                                    sampled_scan::durable_tail::RestoreOutcome::Held(reason) => {
                                        context.cache.durable_hold_exit(
                                            source,
                                            reason,
                                            index,
                                            &candidate,
                                            &mut census,
                                        );
                                        pending!();
                                    }
                                }
                            }
                            retained => (retained, taken_admission, debt),
                        };
                        let old = retained.filter(|_| allow_sample);
                        context.admission.prepare_started =
                            context.admission.prepare_started.saturating_add(1);
                        let mode = match parser.prepare_acquisition(
                            old,
                            &scope,
                            debt,
                            sampled_scan::now_seconds(),
                        ) {
                            Ok(mode) => mode,
                            Err(_) => {
                                context.admission.prepare_failed =
                                    context.admission.prepare_failed.saturating_add(1);
                                if source == SnapshotSource::ClaudeCode {
                                    claude_request_census::invalidate_claude_request_census(
                                        index,
                                        &candidate.path,
                                    );
                                }
                                census.record_unreadable(UnreadableCause::Reduction, 1);
                                pending!();
                            }
                        };
                        // H1c: the plan uses absolute offsets; the reader's
                        // extent is relative to its Full/Tail start.
                        if source == SnapshotSource::ClaudeCode
                            && allow_sample
                            && matches!(
                                mode,
                                crate::transcript_acquisition::ReadMode::Full(_)
                                    | crate::transcript_acquisition::ReadMode::Tail
                            )
                        {
                            if let Some(plan) = parser.reader.acquisition.as_ref() {
                                parser
                                    .reader
                                    .set_extent_limit(plan.frozen_length() - plan.start_offset());
                            }
                        }
                        // Restore does not restore/extend an exact-prefix pricing receipt.
                        // Any new priority contribution below forces a real full replay.
                        if source == SnapshotSource::Codex {
                            sampled_scan::configure_tier_replay(&mut parser, &candidate, index);
                        }
                        let audit_due = parser
                            .reader
                            .acquisition
                            .as_ref()
                            .and_then(|plan| plan.metrics().audit_due)
                            .or(recovered_audit_due)
                            .or_else(|| {
                                // A grown Full without an older obligation
                                // still owes a quiet audit. Prepare its bound
                                // now, never from the discarded checkpoint.
                                (source == SnapshotSource::ClaudeCode
                                    && allow_sample
                                    && matches!(
                                        mode,
                                        crate::transcript_acquisition::ReadMode::Full(_)
                                    ))
                                .then(|| {
                                    sampled_scan::now_seconds().saturating_add(
                                        crate::transcript_acquisition::AUDIT_INTERVAL_SECONDS,
                                    )
                                })
                            });
                        planned_mode = Some((mode, audit_due));
                        // Only a continued copy (Tail or Unchanged) carries
                        // its admission facts; `prepare` falls back to Full
                        // when the old copy is filtered.
                        let continued = taken_admission.filter(|_| {
                            !matches!(mode, crate::transcript_acquisition::ReadMode::Full(_))
                        });
                        file_sampling = Some(sampled_scan::Active {
                            key,
                            scope,
                            mode,
                            audit_due,
                            retained_hint: continued.map(|(hint, _, _)| hint),
                            retained_finalization_charge: continued
                                .map_or(0, |(_, charge, _)| charge),
                            retained_usage: continued.map(|(_, _, usage)| usage),
                            reinsertion,
                        });
                    }
                } else if source == SnapshotSource::Codex
                    && owning_header_is_current
                    && crate::heap_layout_bound::layout_supported()
                    && parser
                        .reader
                        .reader
                        .get_ref()
                        .metadata()
                        .is_ok_and(|metadata| {
                            metadata.len()
                                > sampled_scan::codex_cursor::Limits::current().singleton()
                        })
                {
                    // N1 (K9): the state or sidecar census is incomplete, so
                    // main's trust rule refuses verification and retention,
                    // yet main still reads and publishes this file. A file
                    // larger than the singleton budget therefore pages as a
                    // cursor-only job: a fresh `Full` acquisition with no
                    // retained state and no debt input, used only for the
                    // job's object certificate. Its completion keeps no
                    // checkpoint and no copy, so it is never source-verified.
                    let reduction_sidecar = sampled_scan::reduction_dependencies(
                        source,
                        &candidate,
                        &codex_title_metadata,
                        &claude_title_metadata,
                        claude_effort_support_dir_ref,
                    );
                    context
                        .admission
                        .reduction_dependencies_available
                        .observe(reduction_sidecar.is_some());
                    if let Some(reduction_sidecar) = reduction_sidecar {
                        let scope = context.file_scope(
                            source,
                            &candidate,
                            &reduction_sidecar,
                            true,
                            context_curve_enabled,
                            index,
                        );
                        context.admission.prepare_started =
                            context.admission.prepare_started.saturating_add(1);
                        let mode = match parser.prepare_acquisition(
                            None,
                            &scope,
                            None,
                            sampled_scan::now_seconds(),
                        ) {
                            Ok(mode) => mode,
                            Err(_) => {
                                context.admission.prepare_failed =
                                    context.admission.prepare_failed.saturating_add(1);
                                census.record_unreadable(UnreadableCause::Reduction, 1);
                                pending!();
                            }
                        };
                        sampled_scan::configure_tier_replay(&mut parser, &candidate, index);
                        planned_mode = Some((mode, recovered_audit_due));
                        file_sampling = Some(sampled_scan::Active {
                            key,
                            scope,
                            mode,
                            audit_due: recovered_audit_due,
                            retained_hint: None,
                            retained_finalization_charge: 0,
                            retained_usage: None,
                            reinsertion: Default::default(),
                        });
                    }
                }
            }
            let mut active = Box::new(OwnedActiveFile {
                comparison_target,
                sampling: file_sampling,
                recovered_audit_due,
                candidate,
                decision,
                previous_snapshot_fingerprint,
                previous_upload_body_witness,
                projection_adoption_required,
                source_file_fingerprint,
                parser,
                aliases: Vec::new(),
                applied_receipts: BTreeMap::new(),
                cursor: None,
                charged_bytes: 0,
                hold_offset: None,
                group: None,
                side_origin,
            });
            if let Some(context) = sampling
                .as_ref()
                .filter(|_| source == SnapshotSource::Codex)
            {
                let extent = active
                    .parser
                    .reader
                    .reader
                    .get_ref()
                    .metadata()
                    .map_or(0, |metadata| metadata.len());
                let expected = match active.sampling.as_ref().map(|acquisition| acquisition.mode) {
                    Some(crate::transcript_acquisition::ReadMode::Unchanged) => 0,
                    Some(crate::transcript_acquisition::ReadMode::Tail) => {
                        extent.saturating_sub(retained_offset.unwrap_or(0))
                    }
                    _ => extent,
                };
                // U1a-2a (row 18): a side read is a singleton read (2a); any
                // other plan is its charged attempt, with no counter,
                // requeue or census write (G4b, G5, G9, A20).
                if active.side_origin.is_some() {
                    let plan = (expected
                        <= sampled_scan::codex_cursor::Limits::current().singleton())
                    .then(|| {
                        context.cache.cursor_plan(
                            &mut codex_page,
                            sampled_scan::codex_cursor::Limits::current(),
                            expected,
                            false,
                            crate::heap_layout_bound::layout_supported(),
                            &context.namespace,
                            &local_index_key(&active.candidate.path),
                            sampled_scan::codex_cursor::census_token(index).as_deref(),
                            true,
                        )
                    });
                    if plan != Some(sampled_scan::codex_cursor::StartPlan::Singleton) {
                        if let Some(side) = active.side_origin.take() {
                            side.end();
                        }
                        pending!();
                    }
                    active_file = Some(active);
                    pending!();
                }
                let defer = match context.cache.cursor_plan_paced(
                    &mut codex_page,
                    sampled_scan::codex_cursor::Limits::current(),
                    expected,
                    codex_cursor_lease.is_none() && context.cache.cursor_slot_free(),
                    crate::heap_layout_bound::layout_supported(),
                    &context.namespace,
                    &local_index_key(&active.candidate.path),
                    sampled_scan::codex_cursor::census_token(index).as_deref(),
                    sampled_scan::codex_cursor::census_member(
                        &codex_selected_flags,
                        [active.candidate.path.as_path()],
                    ),
                    Some(sampled_scan::codex_cursor::PaceProbe {
                        file: active.parser.reader.reader.get_ref(),
                        index,
                    }),
                ) {
                    sampled_scan::codex_cursor::StartPlan::Singleton => false,
                    sampled_scan::codex_cursor::StartPlan::Unpaged => {
                        // Layout-unsupported build: the cursor is off as a
                        // whole and this file reads in its page, as before.
                        codex_page.disclose_disabled(&context.cache);
                        false
                    }
                    sampled_scan::codex_cursor::StartPlan::Cursor => {
                        let dependencies = sampled_scan::reduction_dependencies(
                            source,
                            &active.candidate,
                            &codex_title_metadata,
                            &claude_title_metadata,
                            claude_effort_support_dir_ref,
                        );
                        let owner = codex_join_inventory
                            .as_ref()
                            .and_then(|inventory| inventory.owner_for_path(&active.candidate.path))
                            .map(str::to_owned);
                        match context.cache.cursor_start(
                            &mut active,
                            &context.namespace,
                            dependencies,
                            owner,
                            state_census_complete && sidecar_census_complete,
                            index,
                        ) {
                            Ok(lease) => {
                                // The job's path holds the strict census until
                                // its attempt ends (accepted or debt).
                                sampled_scan::codex_cursor::requeue(
                                    index,
                                    &codex_selected_flags,
                                    &active.candidate,
                                );
                                codex_cursor_lease = Some(lease);
                                false
                            }
                            // The slot frees when its job ends: wait in turn.
                            Err(sampled_scan::codex_cursor::StartRefusal::Busy) => true,
                            // N1: no acquisition even cursor-only (no current
                            // owning header or no reduction dependencies, where
                            // main holds the file too). Never requeued: the
                            // path is processed for this generation with a
                            // retryable cause, so discovery finishes and the
                            // bounded unhealthy retry starts the next one.
                            Err(sampled_scan::codex_cursor::StartRefusal::InputsUnavailable) => {
                                census.record_unreadable(UnreadableCause::Reduction, 1);
                                pending!();
                            }
                            Err(sampled_scan::codex_cursor::StartRefusal::Unstartable) => {
                                // Never an unbounded in-page read of a file
                                // larger than the singleton budget.
                                census.record_unreadable(UnreadableCause::OpenRead, 1);
                                pending!();
                            }
                        }
                    }
                    sampled_scan::codex_cursor::StartPlan::Defer => true,
                    // Processed for this generation (K7 fence).
                    sampled_scan::codex_cursor::StartPlan::Fenced => {
                        scanned_file_count = scanned_file_count.saturating_sub(1);
                        pending!();
                    }
                };
                if defer {
                    // Only a full read reaches here (a tail was planned
                    // before its retained state was consumed).
                    context.cache.cursor_note_deferred();
                    scanned_file_count = scanned_file_count.saturating_sub(1);
                    sampled_scan::codex_cursor::requeue(
                        index,
                        &codex_selected_flags,
                        &active.candidate,
                    );
                    pending!();
                }
            }
            #[cfg(unix)]
            if active.side_origin.is_none()
                && active.sampling.as_ref().map_or(true, |a| {
                    matches!(a.mode, crate::transcript_acquisition::ReadMode::Full(_))
                })
            {
                if let Some(cache) = durable_guard.as_ref().and_then(std::sync::Weak::upgrade) {
                    if let Some(reason) = cache.durable_full_hold(
                        source,
                        &local_index_key(&active.candidate.path),
                        true,
                    ) {
                        cache.durable_hold_exit(
                            source,
                            reason,
                            index,
                            &active.candidate,
                            &mut census,
                        );
                        pending!();
                    }
                }
            }
            if let Some((context, (mode, audit_due))) = sampling.as_mut().zip(planned_mode) {
                context.record_mode(mode, audit_due);
                resource_probe.rearm_full_selected(&local_index_key(&active.candidate.path), mode);
            }
            if let Some(delivery) = line_delivery.as_mut() {
                delivery.arm();
            }
            active_file = Some(active);
            pending!();
        }
        if let (None, Some(delivery)) = (&active_file, line_delivery.as_mut()) {
            delivery.left_active();
        }
        Ok(OwnedSourceScanStep::Pending(Self {
            native_comparison,
            resource_probe,
            sampling,
            durable_guard,
            source,
            roots,
            index: index_storage,
            collected_at,
            backfill_window_days,
            file_limit,
            artifacts_enabled,
            context_curve_enabled,
            claude_request_identity_capture,
            claude_effort_support_dir,
            codex_title_metadata,
            claude_title_metadata,
            state_census_complete,
            sidecar_census_complete,
            codex_turn_traces,
            codex_parent_identities,
            codex_parent_ownership_ledgers,
            census_window_end,
            discovered_file_count,
            census_unix_seconds,
            census,
            snapshots,
            scanned_file_count,
            scanned_session_count,
            semantic_noop_count,
            history_upgrade,
            codex_state_only_blocked_session_ids,
            codex_parent_resolution_retry_required,
            residue_index_keys,
            settled_residue_index_keys,
            residue_blocked_session_ids,
            pending_finalization,
            claude_authority_preflight,
            forced_claude_family_reparses,
            claude_twin_only_family_reparses,
            identified_candidates,
            active_file: sampled_scan::codex_cursor::ActiveFrame::new(
                active_file,
                codex_cursor_lease,
            ),
            codex_join_inventory,
            codex_join_prepared,
            codex_join_groups,
            codex_join_active,
            codex_join_completed,
            codex_legacy_join_baselines,
            codex_page,
            codex_selected_flags,
            codex_side_pass,
            continuation_ticket,
            line_delivery,
            codex_versions,
        }))
    }
}

fn launch_workers_for_candidate(
    source: SnapshotSource,
    candidate: &CandidateFile,
    inventory: Option<&codex_file_join::HeaderInventory>,
) -> Vec<String> {
    if source == SnapshotSource::Codex {
        if let Some(owner) =
            inventory.and_then(|inventory| inventory.owner_for_path(&candidate.path))
        {
            return vec![owner.to_owned()];
        }
    }
    launch_workers_for_path(source, &candidate.path)
}

// Path hints authorize only lookup demand, never transcript ownership or facts.
fn launch_workers_for_path(source: SnapshotSource, path: &Path) -> Vec<String> {
    if claude_subagent_has_no_launch_worker(source, path) {
        return Vec::new();
    }
    match source {
        SnapshotSource::Codex => codex_session_id_candidates_from_path(path),
        SnapshotSource::ClaudeCode | SnapshotSource::Pi => path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .map(|stem| vec![stem.to_string()])
            .unwrap_or_default(),
    }
}

// Finish-time demand for the parsed file. A Claude subagent carries its
// parent's `sessionId`, but `into_items` re-keys it from the path before any
// launch fact lookup, so demanding that parent would only discard the prepared
// batch for a key no consumer reads.
fn launch_workers_for_parsed(
    source: SnapshotSource,
    parsed_session_id: Option<&str>,
    path: &Path,
) -> Vec<String> {
    match parsed_session_id {
        _ if claude_subagent_has_no_launch_worker(source, path) => Vec::new(),
        Some(id) if source == SnapshotSource::Codex => vec![resolve_codex_identity(id)],
        Some(id) => vec![id.to_owned()],
        None => launch_workers_for_path(source, path),
    }
}

// Same predicate as the `into_items` re-key: the re-keyed id is never a UUID,
// and launch workers are UUID-only, so no launch event can name this file.
fn claude_subagent_has_no_launch_worker(source: SnapshotSource, path: &Path) -> bool {
    source == SnapshotSource::ClaudeCode && claude_subagent_identity(path).is_some()
}

fn claude_held_family_matches_launch_context(
    index: &ScanIndex,
    root: &str,
    current: &CandidateFile,
    remaining: &VecDeque<CandidateFile>,
    context: &crate::session_attribution::SessionAttributionContext,
) -> bool {
    let Some(record) = index.claude_usage_authority_quarantine.get(root) else {
        return false;
    };
    let mut members = BTreeSet::new();
    for member in std::iter::once(current).chain(remaining.iter()) {
        let Some((family, id)) = claude_index_path_family_member(&member.path) else {
            continue;
        };
        if family != root {
            continue;
        }
        members.insert(id);
        let mut semantic = member.clone();
        if member.path != current.path {
            let workers = launch_workers_for_path(SnapshotSource::ClaudeCode, &member.path);
            if !context.launches_prepared(&workers) {
                return false;
            }
            if let Some(witness) = context.launch_witness(&workers) {
                semantic.source_file_fingerprint = sha256_hex(&[
                    "launcher_worker_context:v1",
                    &semantic.source_file_fingerprint,
                    &witness,
                ]);
            }
        }
        if index
            .claude_usage_authority_candidate_requires_family_reparse(&semantic)
            .is_some()
        {
            return false;
        }
    }
    members
        == record
            .member_source_file_fingerprints
            .keys()
            .cloned()
            .collect()
}

/// Preserve the two-open identity fence only for the Claude family whose
/// authority reconstruction actually requested the preflight.
///
/// A quarantine anywhere enables the source-wide prepass so the scanner can
/// discover every current member of that family. Unrelated healthy sessions
/// must not inherit its equality check: their transcript or shared OTEL
/// sidecars may advance between the prepass and the authoritative parse open.
/// The second open remains fully revalidated for those sessions; only the
/// quarantined family's cross-member snapshot must stay byte-identical across
/// both phases.
fn claude_authority_preflight_fingerprint(
    index: &ScanIndex,
    candidate: &CandidateFile,
) -> Option<String> {
    let (root_session_id, _) = claude_index_path_family_member(&candidate.path)?;
    index
        .claude_usage_authority_quarantine
        .contains_key(&root_session_id)
        .then(|| candidate.source_file_fingerprint.clone())
}

fn apply_codex_state_evidence(item: &mut SnapshotItem, metadata: &CodexTitleMetadata, path: &Path) {
    let source_session_id = resolve_codex_identity(item.source_session_id.as_str());
    if metadata
        .identity_conflicts
        .contains(source_session_id.as_str())
    {
        return;
    }
    // Parsed usage and its recorded state total must describe the same home.
    // A missing file in a stale home cannot inflate the parsed file's evidence.
    let Some(thread) = metadata
        .thread_extent_for_path(source_session_id.as_str(), path)
        .0
    else {
        return;
    };
    if thread.tokens_used == 0 {
        return;
    }
    item.provenance.state_total_tokens = Some(thread.tokens_used);
    item.provenance.state_archived = Some(thread.archived);
    item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::Codex, item);
}

fn append_codex_state_only_snapshots(
    snapshots: &mut Vec<SnapshotItem>,
    metadata: &CodexTitleMetadata,
    collected_at: &str,
    index: &mut ScanIndex,
    blocked_session_ids: &BTreeSet<String>,
) -> (usize, usize) {
    let snapshots_before = snapshots.len();
    let blocked_session_ids = blocked_session_ids
        .union(&index.codex_state_only_blocked_session_ids)
        .map(|session_id| resolve_codex_identity(session_id.as_str()))
        .collect::<BTreeSet<_>>();
    let covered_session_ids: BTreeSet<String> = snapshots
        .iter()
        .map(|snapshot| resolve_codex_identity(snapshot.source_session_id.as_str()))
        .collect();
    // Sessions whose rollout was parsed into a snapshot in a PRIOR scan run.
    // The incremental scan skips unchanged rollout files, so they are absent
    // from this run's `snapshots`, but their split snapshot already reached the
    // backend — re-emitting a state-only total would overwrite it with an
    // unattributed "Other". We recover those session ids from the persisted
    // scan index, and also cover accepted header owners when the filename is
    // ambiguous. Two correctness points:
    //   * Only entries that actually produced a snapshot count
    //     (`last_snapshot_fingerprint` is set). `index.record` runs for every
    //     scanned file, including a rollout that parsed to zero usage rows; such
    //     a session has no split snapshot, so it MUST still fall through to a
    //     state-only total or its tokens would be dropped entirely.
    //   * Session ids are derived from the rollout filename, so coverage does
    //     not depend on the state DB `rollout_path` matching the scan path
    //     byte-for-byte (home symlinks, relative paths, case differences).
    let mut covered_in_prior_runs = BTreeSet::new();
    let mut ambiguous_observations = 0_u64;
    let mut ambiguous_tokens = 0_u64;
    for (path, entry) in &index.files {
        if entry.last_snapshot_fingerprint.is_none() {
            continue; // No body was produced: preserve main's state-only fallback.
        }
        if let Some(identity) = metadata.identity_from_path_evidence(Path::new(path)) {
            covered_in_prior_runs.insert(identity);
        } else if !codex_index_file_body_accepted(index, path, entry) {
            let supported = codex_session_id_candidates_from_path(Path::new(path))
                .into_iter()
                .filter(|identity| metadata.has_identity_evidence(identity))
                .collect::<Vec<_>>();
            if supported.len() == 2 {
                for identity in &supported {
                    if let Some(thread) = metadata.state_threads.get(identity) {
                        ambiguous_tokens = ambiguous_tokens.saturating_add(thread.tokens_used);
                    }
                }
                covered_in_prior_runs.extend(supported);
                ambiguous_observations += 1;
            }
        }
    }
    crate::local_resource_diagnostics::codex_state_only_ambiguous_identity(
        ambiguous_observations,
        ambiguous_tokens,
    );
    let mut scanned_session_count = 0;
    let protected = index
        .files
        .values()
        .filter(|entry| entry.codex_history_is_protected())
        .collect::<Vec<_>>();
    let unknown_protected_owner = protected.iter().any(|entry| {
        entry
            .codex_protected_owner
            .as_ref()
            .map_or(true, |owner| !valid_codex_protected_owner(owner))
    });
    let protected_owners = protected
        .iter()
        .filter_map(|entry| entry.codex_protected_owner.as_ref())
        .chain(
            index
                .files
                .iter()
                .filter(|(key, entry)| codex_index_file_body_accepted(index, key, entry))
                .filter_map(|(_, entry)| entry.codex_counting_owner.as_ref()),
        )
        .collect::<BTreeSet<_>>();
    for (source_session_id, thread) in &metadata.state_threads {
        if thread.tokens_used == 0
            || unknown_protected_owner
            || protected_owners.contains(&codex_protected_owner(source_session_id))
            || covered_session_ids.contains(source_session_id)
            || covered_in_prior_runs.contains(source_session_id)
            || blocked_session_ids.contains(source_session_id)
            || metadata
                .family_position(source_session_id.as_str())
                .is_some()
        {
            continue;
        }
        let snapshot = codex_state_only_snapshot(source_session_id, thread, collected_at);
        scanned_session_count += 1;
        // The final fingerprint can still change during enrichment, privacy
        // policy application, or account-cutoff filtering. Always carry the
        // provisional item to `finalize_scan_after_policy`, which owns both
        // durable state and semantic no-op suppression.
        snapshots.push(snapshot);
    }
    crate::local_resource_diagnostics::codex_state_only(
        scanned_session_count,
        snapshots.len().saturating_sub(snapshots_before),
        0, // Semantic no-op suppression remains in finalize_scan_after_policy.
    );
    (scanned_session_count, 0)
}

fn codex_state_only_snapshot(
    source_session_id: &str,
    thread: &CodexStateThread,
    collected_at: &str,
) -> SnapshotItem {
    let model = thread
        .model
        .clone()
        .and_then(normalize_title)
        .unwrap_or_else(|| "unknown".to_string());
    let display_name = thread
        .title
        .clone()
        .and_then(|title| normalize_display_title(title, "session_index"));
    let row = SnapshotModelUsage {
        evidence_ref: None,
        identity_parts: None,
        model,
        input_tokens: 0,
        output_tokens: 0,
        cache_read_tokens: 0,
        cache_creation_5m_tokens: 0,
        cache_creation_1h_tokens: 0,
        reasoning_output_tokens: 0,
        reasoning_effort: None,
        unattributed_total_tokens: thread.tokens_used,
        request_count: 0,
        selector_context: BTreeMap::new(),
        selector_sources: BTreeMap::new(),
        auth_mode: None,
        billing_channel: None,
        billing_provider: None,
        gateway_provider: None,
        model_provider: None,
        subscription_product: None,
        account_identifier_hash: None,
        cost_usd: None,
        input_cost_usd: None,
        output_cost_usd: None,
        cache_read_cost_usd: None,
        cache_creation_cost_usd: None,
    };
    // v6 requires usage_buckets whenever the snapshot reports any usage.
    // State-only snapshots have no per-line activity to bucket on, so we
    // synthesize one bucket at the hour of the most recent state evidence
    // (updated_at), falling back to created_at, then collected_at. If even
    // that fails to parse, the snapshot is emitted without buckets — the
    // backend will then reject it, but that's strictly better than crashing
    // the daemon's snapshot scan.
    let bucket_seed = thread
        .updated_at
        .clone()
        .or_else(|| thread.created_at.clone())
        .unwrap_or_else(|| collected_at.to_string());
    let usage_buckets = match activity_bucket_from_timestamp(&bucket_seed) {
        Some((bucket_start, normalized_timestamp)) => vec![SnapshotUsageBucket {
            bucket_start,
            model_usage: vec![row.clone()],
            first_activity_at: Some(normalized_timestamp.clone()),
            last_activity_at: Some(normalized_timestamp),
        }],
        None => Vec::new(),
    };
    let model_usage = vec![row];
    let has_display_name = display_name.is_some();
    let mut item = SnapshotItem {
        request_evidence: Vec::new(),
        request_identity_refusals: 0,
        claude_org_markers: None,
        claude_account_withheld_reason: None,
        claude_account_display: None,
        source_session_id: source_session_id.to_string(),
        snapshot_fingerprint: String::new(),
        status: "final".to_string(),
        input_tokens: 0,
        output_tokens: 0,
        cache_read_tokens: 0,
        cache_creation_5m_tokens: 0,
        cache_creation_1h_tokens: 0,
        reasoning_output_tokens: 0,
        unattributed_total_tokens: thread.tokens_used,
        request_count: 0,
        usage_accounting_contract: None,
        removed_request_count: None,
        removed_usage: None,
        telemetry_owned_complete: None,
        resolver_conflict_count: None,
        claude_money: None,
        session_account_evidence: None,
        claude_usage_request_ids: BTreeSet::new(),
        claude_usage_occurrences: BTreeMap::new(),
        cache_observations: None,
        cache_observations_state: None,
        cache_base_head_etag: None,
        cache_requests: Vec::new(),
        cache_requests_complete: true,
        avg_duration_ms: None,
        avg_time_to_first_token_ms: None,
        max_duration_ms: None,
        max_time_to_first_token_ms: None,
        peak_context_fill_tokens: None,
        first_turn_context_tokens: None,
        last_turn_context_tokens: None,
        first_turn_context_window_tokens: None,
        peak_context_fill_window_tokens: None,
        last_turn_context_window_tokens: None,
        compaction_count: None,
        compaction_timestamps: Vec::new(),
        compaction_events: Vec::new(),
        first_own_request_at: None,
        local_context_points: Vec::new(),
        compaction_total_pre_tokens: None,
        compaction_total_post_tokens: None,
        compaction_total_cumulative_dropped_tokens: None,
        compaction_total_duration_ms: None,
        context_curve: Some(unavailable_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            CODEX_CONTEXT_CURVE_OWNERSHIP_REVISION,
            "pre_capture",
            0,
            0,
        )),
        claude_context_curve_boundaries: Vec::new(),
        claude_context_curve_identity_complete: false,
        claude_context_curve_request_index_complete: false,
        claude_context_curve_owned_start_proven: false,
        claude_file_birth: Default::default(),
        claude_file_birth_verdict: None,
        activity_summary: None,
        tool_usage: None,
        tool_usage_truncated: false,
        session_start: None,
        model_usage,
        usage_buckets,
        cost: None,
        session_display_name: display_name,
        session_display_name_source: has_display_name.then(|| "session_index".to_string()),
        source_started_at: thread.created_at.clone(),
        source_ended_at: None,
        source_last_activity_at: thread.updated_at.clone(),
        collected_at: collected_at.to_string(),
        workspace_hash: None,
        workspace_display_label: None,
        workspace_label_source: None,
        repository_hash: None,
        repository_label: None,
        repository_label_source: None,
        repository_identity_source: None,
        workspace_kind: None,
        source_file_fingerprint: None,
        session_artifacts: Vec::new(),
        provenance: SnapshotProvenance {
            collector: "codex_state_sqlite".to_string(),
            source_file_count: 1,
            input_token_scope: Some("total_only".to_string()),
            state_total_tokens: Some(thread.tokens_used),
            state_archived: Some(thread.archived),
        },
        // Codex state-index summaries carry no session_meta -> no raw origin.
        origin: None,
        originator: None,
        attribution_facts: Vec::new(),
    };
    item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::Codex, &item);
    item
}

