    #[test]
    fn compaction_timeline_keeps_newest_64_for_snapshot_upload() {
        let mut timestamps = (0..72)
            .map(|index| {
                let day = index / 24 + 1;
                let hour = index % 24;
                format!("2026-07-{day:02}T{hour:02}:00:00Z")
            })
            .collect::<Vec<_>>();
        timestamps.reverse();
        timestamps.push("2026-07-03T23:00:00Z".to_string());

        let bounded = bounded_compaction_timestamps(timestamps);

        assert_eq!(bounded.len(), MAX_COMPACTION_TIMESTAMPS);
        assert_eq!(
            bounded.first().map(String::as_str),
            Some("2026-07-01T08:00:00Z")
        );
        assert_eq!(
            bounded.last().map(String::as_str),
            Some("2026-07-03T23:00:00Z")
        );
    }

    #[test]
    fn codex_parser_derives_context_posture_watermarks() {
        // Codex reports each response's own usage in `last_token_usage`, so the
        // watermarks come from there. Shapes asserted, in file order:
        //   * turn 1 (22817) sets the first-turn baseline,
        //   * turn 2 (33205) raises the peak,
        //   * a DUPLICATE of turn 2 must be idempotent (max/first, not a sum),
        //   * turn 3 (45272) is the session peak,
        //   * the zero-usage event Codex emits at a compaction is ignored,
        //   * the post-compaction turn (25182) drops well below the peak, which
        //     must retain the pre-compaction high-water mark.
        let path = temp_file("codex-context-posture");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-17T03:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019f6d5f-abbf-7502-9448-a68952e2c988\"}}\n",
                "{\"timestamp\":\"2026-07-17T03:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":22817,\"cached_input_tokens\":9984,\"output_tokens\":440},\"last_token_usage\":{\"input_tokens\":22817,\"cached_input_tokens\":9984,\"output_tokens\":440},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T03:02:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":56022,\"cached_input_tokens\":32256,\"output_tokens\":921},\"last_token_usage\":{\"input_tokens\":33205,\"cached_input_tokens\":22272,\"output_tokens\":481},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T03:02:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":56022,\"cached_input_tokens\":32256,\"output_tokens\":921},\"last_token_usage\":{\"input_tokens\":33205,\"cached_input_tokens\":22272,\"output_tokens\":481},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T03:03:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":101294,\"cached_input_tokens\":75008,\"output_tokens\":1165},\"last_token_usage\":{\"input_tokens\":45272,\"cached_input_tokens\":42752,\"output_tokens\":244},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T03:04:00Z\",\"type\":\"compacted\",\"payload\":{\"message\":\"\",\"replacement_history\":[]}}\n",
                "{\"timestamp\":\"2026-07-17T03:04:01Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":101294,\"cached_input_tokens\":75008,\"output_tokens\":1165},\"last_token_usage\":{\"input_tokens\":0,\"cached_input_tokens\":0,\"output_tokens\":0},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T03:04:02Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"context_compacted\"}}\n",
                "{\"timestamp\":\"2026-07-17T03:05:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":126476,\"cached_input_tokens\":97280,\"output_tokens\":1300},\"last_token_usage\":{\"input_tokens\":25182,\"cached_input_tokens\":22272,\"output_tokens\":135},\"model_context_window\":258400,\"model\":\"gpt-5.5\"}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_codex_jsonl_file(
            &path,
            "2026-07-17T03:06:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(item.first_turn_context_tokens, Some(22817));
        assert_eq!(item.peak_context_fill_tokens, Some(45272));
        // The `compacted` rollout record and its paired `context_compacted` UI
        // event describe ONE compaction; counting both would report two.
        assert_eq!(item.compaction_count, Some(1));
        assert_eq!(
            item.compaction_timestamps,
            vec!["2026-07-17T03:04:00Z".to_string()]
        );
        let curve = item.context_curve.as_ref().expect("Codex curve");
        assert_eq!(curve.coverage, "complete");
        assert_eq!(curve.total_owned_request_count, 4);
        assert_eq!(curve.retained_point_count, 4);
        assert_eq!(
            curve
                .points
                .iter()
                .map(|point| point.effective_input_tokens)
                .collect::<Vec<_>>(),
            vec![22_817, 33_205, 45_272, 25_182]
        );
        assert_eq!(curve.boundaries.len(), 1);
        assert_eq!(curve.boundaries[0].boundary_index, 1);
        assert_eq!(curve.boundaries[0].before_owned_request_ordinal, 3);
        assert_eq!(curve.boundaries[0].after_owned_request_ordinal, 4);
        assert_eq!(
            curve.points[2].compaction_after_request_boundary_index,
            Some(1)
        );
        assert_eq!(
            curve.points[3].compaction_before_request_boundary_index,
            Some(1)
        );
        assert_eq!(curve.model_windows[0].model_window_index, 0);
        assert_eq!(curve.model_windows[0].context_window_tokens, Some(258_400));
        validate_context_curve(0, curve).expect("Codex curve is wire-valid");

        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_context_posture_reads_per_turn_usage_not_the_cumulative() {
        // Regression guard for the two ways the cumulative `total_token_usage`
        // misreports per-turn context, both taken from real rollouts:
        //   * the cumulative is a session-wide SUM, so on turn 2 it is 56022
        //     while the turn's actual context is 33205;
        //   * Codex `input_tokens` already includes `cached_input_tokens`, so
        //     adding cache reads (the Claude-side formula) would report
        //     33205 + 22272 = 55477 for a turn that saw 33205.
        // Either mistake inflates the peak, and the backend divides the peak by
        // the model's context window — so an inflated peak reads as a session
        // filling far more of its window than it did.
        let path = temp_file("codex-posture-not-cumulative");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-17T04:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019f6d5f-1111-7502-9448-bbbbbbbbbbbb\"}}\n",
                "{\"timestamp\":\"2026-07-17T04:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":22817,\"cached_input_tokens\":9984,\"output_tokens\":440},\"last_token_usage\":{\"input_tokens\":22817,\"cached_input_tokens\":9984,\"output_tokens\":440},\"model\":\"gpt-5.5\"}}}\n",
                "{\"timestamp\":\"2026-07-17T04:02:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":56022,\"cached_input_tokens\":32256,\"output_tokens\":921},\"last_token_usage\":{\"input_tokens\":33205,\"cached_input_tokens\":22272,\"output_tokens\":481},\"model\":\"gpt-5.5\"}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_codex_jsonl_file(
            &path,
            "2026-07-17T04:03:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(item.peak_context_fill_tokens, Some(33205));
        // The session-wide cumulative and the cache-additive figure must never
        // surface as a context reading.
        assert_ne!(item.peak_context_fill_tokens, Some(56022));
        assert_ne!(item.peak_context_fill_tokens, Some(55477));
        // Usage accounting still reconciles off the cumulative deltas, and
        // stays inclusive-scoped: `input_tokens` is the session-wide total with
        // `cache_read_tokens` as a SUBSET of it, not an addend (the backend
        // subtracts that subset exactly once, per `input_token_scope`). Summing
        // the two here would yield 88278 — the same double-count that must
        // never reach a context reading above.
        assert_eq!(item.input_tokens, 56022);
        assert_eq!(item.cache_read_tokens, 32256);
        assert_eq!(
            item.provenance.input_token_scope.as_deref(),
            Some("inclusive_cached")
        );

        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_sessions_without_per_turn_usage_claim_no_context() {
        // A rollout whose `token_count` events carry no `last_token_usage`
        // yields no context reading rather than a guess derived from the
        // cumulative. `compaction_count` is still Some(0): the parser DID read
        // this transcript's compaction records and saw none, which is an
        // observation, not a gap.
        let path = temp_file("codex-no-last-token-usage");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-01T12:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019e253c-7777-7000-9000-aaaaaaaaaaaa\"}}\n",
                "{\"timestamp\":\"2026-07-01T12:03:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":50,\"output_tokens\":9},\"model\":\"gpt-5.5\"}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_codex_jsonl_file(
            &path,
            "2026-07-01T12:04:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(item.peak_context_fill_tokens, None);
        assert_eq!(item.first_turn_context_tokens, None);
        assert_eq!(item.compaction_count, Some(0));
        let serialized = serde_json::to_value(&item).expect("serialize");
        assert!(serialized.get("peak_context_fill_tokens").is_none());
        assert!(serialized.get("first_turn_context_tokens").is_none());
        let curve = item
            .context_curve
            .as_ref()
            .expect("explicit curve coverage");
        assert_eq!(curve.coverage, "pre_capture");
        assert_eq!(curve.total_owned_request_count, 0);
        assert!(curve.points.is_empty());

        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_context_posture_fields_change_snapshot_fingerprint() {
        // Codex posture joins the fingerprint payload on purpose: that is what
        // re-uploads every already-collected Codex session once, so the backend
        // can backfill posture for history rather than only new sessions.
        let path = temp_file("codex-posture-fingerprint");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-07-01T12:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019e253c-8888-7000-9000-cccccccccccc\"}}\n",
                "{\"timestamp\":\"2026-07-01T12:03:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":5000,\"cached_input_tokens\":1000,\"output_tokens\":9},\"last_token_usage\":{\"input_tokens\":5000,\"cached_input_tokens\":1000,\"output_tokens\":9},\"model\":\"gpt-5.5\"}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_codex_jsonl_file(
            &path,
            "2026-07-01T12:04:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(item.peak_context_fill_tokens, Some(5000));
        let mut without_posture = item.clone();
        without_posture.peak_context_fill_tokens = None;
        without_posture.first_turn_context_tokens = None;
        without_posture.compaction_count = None;
        without_posture.compaction_timestamps.clear();
        assert_ne!(
            snapshot_fingerprint(SnapshotSource::Codex, &item),
            snapshot_fingerprint(SnapshotSource::Codex, &without_posture)
        );

        let _ = fs::remove_file(path);
    }

    #[test]
    fn pi_sessions_emit_no_context_posture_fields() {
        // Pi derives no posture, so all three fields stay None and serialize
        // away — and posture must not be a Pi fingerprint dimension, or every
        // Pi session would re-upload on upgrade carrying nothing new.
        let path = temp_file("pi-no-context-posture");
        fs::write(
            &path,
            concat!(
                "{\"type\":\"session\",\"session_id\":\"019e2700-eeee-7000-9000-444444444444\",\"cwd\":\"/Users/example/work\",\"timestamp\":\"2026-05-19T11:00:00Z\"}\n",
                "{\"type\":\"message_end\",\"message\":{\"provider\":\"openai\",\"model\":\"gpt-5.4\",\"api\":\"responses\",\"timestamp\":1779234002000,\"usage\":{\"input\":80,\"output\":20,\"cacheRead\":10,\"cacheWrite\":0}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_pi_jsonl_file(&path, "2026-05-19T11:05:00Z", "fp".to_string())
            .expect("parse")
            .into_iter()
            .next()
            .expect("snapshot");

        assert_eq!(item.peak_context_fill_tokens, None);
        assert_eq!(item.first_turn_context_tokens, None);
        assert_eq!(item.compaction_count, None);
        assert!(item.compaction_timestamps.is_empty());
        let serialized = serde_json::to_value(&item).expect("serialize");
        assert!(serialized.get("peak_context_fill_tokens").is_none());
        assert!(serialized.get("first_turn_context_tokens").is_none());
        assert!(serialized.get("compaction_count").is_none());
        assert!(serialized.get("compaction_timestamps").is_none());

        let fingerprint = snapshot_fingerprint(SnapshotSource::Pi, &item);
        let mut mutated = item.clone();
        mutated.peak_context_fill_tokens = Some(10);
        mutated.first_turn_context_tokens = Some(5);
        mutated.compaction_count = Some(1);
        assert_eq!(
            snapshot_fingerprint(SnapshotSource::Pi, &mutated),
            fingerprint
        );

        let _ = fs::remove_file(path);
    }

    /// Pins the `context_posture` semantic-envelope component.
    ///
    /// This component is one of `POLICY_NEUTRAL_COMPONENTS`, so `content_hash`
    /// is computed over everything in it. Adding a field therefore re-mints
    /// every session's content identity fleet-wide — which
    /// `SNAPSHOT_CONTENT_HASH_EPOCH` reserves for a deliberate, announced epoch
    /// move, never a side effect of shipping a field.
    ///
    /// That is easy to do by accident: a new watermark or metric naturally
    /// "belongs" next to the posture fields, and nothing at the call site says
    /// otherwise. It has already happened twice.
    ///
    /// If this test fails you are changing identity. Either carry the value as
    /// a plain `SnapshotItem` wire field — which is what almost every new
    /// signal actually wants, and costs nothing here — or move the epoch on
    /// purpose and re-pin this hash in the same change.
    #[test]
    fn context_posture_component_is_pinned_against_accidental_identity_churn() {
        let mut item = valid_v6_batch_request()
            .snapshots
            .into_iter()
            .next()
            .expect("fixture snapshot");
        item.peak_context_fill_tokens = Some(977_698);
        item.first_turn_context_tokens = Some(84_043);
        item.compaction_count = Some(3);
        item.compaction_timestamps = vec!["2026-08-14T09:00:00Z".to_string()];

        let hashes = snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &item);
        assert_eq!(
            hashes
                .get("context_posture")
                .map(String::as_str)
                .expect("claude sessions carry a context_posture component"),
            "e69a7dbf291f50c62e8298740c57e812d30ea41fadb888fb4d7cb438f699da0d",
            "context_posture feeds content_hash; read this test's docs before re-pinning"
        );
    }

    /// Compaction sizes and local context points are additive evidence: they
    /// must never move semantic identity, the content hash or the body
    /// witness, and the points must never reach the wire.
    #[test]
    fn compaction_events_and_local_context_points_are_identity_neutral() {
        let mut request = valid_v6_batch_request();
        let policy = request.upload_policy;
        let mut item = request.snapshots.remove(0);
        item.peak_context_fill_tokens = Some(250_000);
        item.first_turn_context_tokens = Some(40_000);
        item.compaction_count = Some(1);
        item.compaction_timestamps = vec!["2026-08-14T09:00:00Z".to_string()];
        let mut with = item.clone();
        with.compaction_events = vec![SnapshotCompactionEvent {
            at: "2026-08-14T09:00:00Z".to_string(),
            before: Some(250_000),
            after: Some(59_000),
            trigger: Some("manual".to_string()),
        }];
        with.local_context_points = vec![LocalContextPoint {
            at_unix_seconds: 1_786_000_000,
            prompt_tokens: 250_000,
        }];
        for source in [SnapshotSource::ClaudeCode, SnapshotSource::Codex] {
            assert_eq!(
                snapshot_semantic_component_hashes(source, &with),
                snapshot_semantic_component_hashes(source, &item),
                "{source:?}"
            );
            assert_eq!(
                snapshot_fingerprint(source, &with),
                snapshot_fingerprint(source, &item),
                "{source:?}"
            );
            // The whole envelope, so the lists can never slip into the
            // revision or revision v2 input either.
            assert_eq!(
                snapshot_semantic_envelope(source, &with, policy),
                snapshot_semantic_envelope(source, &item, policy),
                "{source:?}"
            );
        }
        assert_eq!(
            snapshot_upload_body_witness(&with),
            snapshot_upload_body_witness(&item)
        );
        assert_eq!(
            snapshot_upload_body_witness_version(&with),
            snapshot_upload_body_witness_version(&item)
        );
        let wire = serde_json::to_value(&with).expect("serialize");
        assert_eq!(
            wire["compaction_events"],
            json!([{"at": "2026-08-14T09:00:00Z", "before": 250_000, "after": 59_000, "trigger": "manual"}])
        );
        assert!(wire.get("local_context_points").is_none());
        let wire = serde_json::to_value(&item).expect("serialize");
        assert!(wire.get("compaction_events").is_none());
    }

    #[test]
    fn context_curve_is_hash_neutral_and_deterministically_bounded() {
        let first = max_fractional_context_curve_fixture();
        let second = max_fractional_context_curve_fixture();
        assert_eq!(first, second);
        assert_eq!(first.coverage, "sampled");
        assert_eq!(first.total_owned_request_count, 1_300);
        assert_eq!(first.total_compaction_boundary_count, 70);
        assert_eq!(first.retained_boundary_count, 64);
        assert_eq!(first.model_windows.len(), MAX_CONTEXT_CURVE_MODEL_WINDOWS);
        assert!(first
            .model_windows
            .iter()
            .all(|window| window.model.len() == 128));
        assert!(first.retained_point_count <= MAX_CONTEXT_CURVE_POINTS as u64);
        assert!(
            serde_json::to_vec(&first).expect("serialize").len() <= MAX_CONTEXT_CURVE_WIRE_BYTES
        );
        assert_eq!(
            first
                .boundaries
                .iter()
                .map(|boundary| boundary.boundary_index)
                .collect::<Vec<_>>(),
            (1..=32).chain(39..=70).collect::<Vec<_>>()
        );
        assert_eq!(
            first
                .points
                .iter()
                .filter(|point| {
                    point.compaction_before_request_boundary_index.is_some()
                        || point.compaction_after_request_boundary_index.is_some()
                })
                .count(),
            128,
            "all before/after points for 64 retained boundaries stay present"
        );
        for ordinal in [1_u64, 2, 5, 10, 20] {
            assert!(first.points.iter().any(|point| {
                point.owned_request_ordinal == ordinal
                    && point.retention_flags & CONTEXT_CURVE_RETENTION_ANCHOR != 0
            }));
        }
        assert!(first.points.iter().any(|point| {
            point.owned_request_ordinal == 1
                && point.retention_flags & CONTEXT_CURVE_RETENTION_PEAK != 0
        }));
        assert!(first.points.iter().any(|point| {
            point.owned_request_ordinal == 1_300
                && point.retention_flags & CONTEXT_CURVE_RETENTION_TAIL != 0
        }));
        validate_context_curve(0, &first).expect("sampled curve validates");

        let mut item = valid_v6_batch_request().snapshots.remove(0);
        let before = snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &item);
        item.context_curve = Some(first.clone());
        let after = snapshot_semantic_component_hashes(SnapshotSource::ClaudeCode, &item);
        assert_eq!(before, after, "curve stays out of semantic/content hashes");

        let mut request = valid_v6_batch_request();
        {
            let item = &mut request.snapshots[0];
            item.context_curve = Some(first.clone());
            item.compaction_timestamps = (0..MAX_COMPACTION_TIMESTAMPS)
                .map(|second| format!("2026-08-20T12:00:{:02}Z", second % 60))
                .collect();
            item.compaction_events = item
                .compaction_timestamps
                .iter()
                .map(|at| SnapshotCompactionEvent {
                    at: at.clone(),
                    before: Some(u64::MAX),
                    after: Some(u64::MAX),
                    trigger: Some("manual".to_string()),
                })
                .collect();
            item.tool_usage = Some(
                (0..MAX_TOOL_USAGE_NAMES)
                    .map(|index| SnapshotToolUsage {
                        name: format!("tool_{index:03}_{}", "x".repeat(119)),
                        count: u64::MAX,
                    })
                    .collect(),
            );
            item.tool_usage_truncated = true;
            item.session_artifacts = (0..MAX_SESSION_ARTIFACTS)
                .map(|index| SessionArtifact {
                    kind: "pull_request".to_string(),
                    value: format!("https://example.invalid/org/repository/pull/{index}"),
                })
                .collect();
            item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::ClaudeCode, item);
        }
        validate_snapshot_batch_request(&request).expect("max curve fits populated item");
        let item = &request.snapshots[0];
        let envelope =
            snapshot_semantic_envelope(SnapshotSource::ClaudeCode, item, request.upload_policy);
        let curve_bytes = serde_json::to_vec(item.context_curve.as_ref().expect("curve"))
            .expect("serialize curve")
            .len();
        let item_bytes = serde_json::to_vec(&SnapshotItemWire {
            snapshot: item,
            semantic_envelope: envelope,
        })
        .expect("serialize item")
        .len();
        let batch_bytes = serde_json::to_vec(&request).expect("serialize batch").len();
        eprintln!(
            "max context curve bytes={curve_bytes}; retained points={}; populated item bytes={item_bytes}; batch bytes={batch_bytes}",
            first.retained_point_count
        );
        assert!(curve_bytes <= MAX_CONTEXT_CURVE_WIRE_BYTES);
        assert!(item_bytes <= MAX_SNAPSHOT_ITEM_WIRE_BYTES);
        assert!(batch_bytes <= MAX_SNAPSHOT_BATCH_WIRE_BYTES);
    }

    #[test]
    fn context_curve_wire_is_content_free_and_field_allowlisted() {
        fn collect_keys(value: &Value, keys: &mut BTreeSet<String>) {
            match value {
                Value::Object(object) => {
                    for (key, child) in object {
                        keys.insert(key.clone());
                        collect_keys(child, keys);
                    }
                }
                Value::Array(values) => {
                    for child in values {
                        collect_keys(child, keys);
                    }
                }
                _ => {}
            }
        }

        let value =
            serde_json::to_value(max_fractional_context_curve_fixture()).expect("curve serializes");
        let mut keys = BTreeSet::new();
        collect_keys(&value, &mut keys);
        let expected = BTreeSet::from_iter(
            [
                "contract_version",
                "parser_revision",
                "ownership_revision",
                "sampling_revision",
                "coverage",
                "total_owned_request_count",
                "retained_point_count",
                "total_compaction_boundary_count",
                "retained_boundary_count",
                "points",
                "boundaries",
                "model_windows",
                "owned_request_ordinal",
                "observed_at",
                "effective_input_tokens",
                "model_window_index",
                "segment_ordinal",
                "retention_flags",
                "compaction_before_request_boundary_index",
                "compaction_after_request_boundary_index",
                "boundary_index",
                "before_owned_request_ordinal",
                "after_owned_request_ordinal",
                "segment_before_ordinal",
                "segment_after_ordinal",
                "model",
                "context_window_tokens",
                "evidence_kind",
                "evidence_revision",
            ]
            .into_iter()
            .map(str::to_string),
        );
        assert_eq!(keys, expected);
        let encoded = serde_json::to_string(&value).expect("curve encodes");
        for forbidden in [
            "http://",
            "https://",
            "/Users/",
            "prompt",
            "tool_result",
            "command",
            "screenshot",
            "reasoning",
        ] {
            assert!(!encoded.contains(forbidden), "curve leaked {forbidden}");
        }
    }

    #[test]
    fn context_curve_yields_to_the_whole_snapshot_item_budget() {
        let mut request = valid_v6_batch_request();
        let policy = request.upload_policy;
        let item = &mut request.snapshots[0];
        item.context_curve = Some(max_fractional_context_curve_fixture());
        item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::ClaudeCode, item);
        let original_points = item
            .context_curve
            .as_ref()
            .expect("curve")
            .retained_point_count;
        let current_size = snapshot_item_wire_size(SnapshotSource::ClaudeCode, item, policy);
        let synthetic_budget = current_size - 2_048;
        fit_context_curve_to_snapshot_item_budget(
            SnapshotSource::ClaudeCode,
            item,
            policy,
            synthetic_budget,
        );
        let fitted = item
            .context_curve
            .as_ref()
            .expect("fitted curve remains explicit");
        assert_eq!(fitted.coverage, "sampled");
        assert!(fitted.retained_point_count < original_points);
        assert!(
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, item, policy) <= synthetic_budget
        );
        validate_snapshot_batch_request(&request).expect("pruned curve keeps snapshot uploadable");

        let mut mandatory_request = valid_v6_batch_request();
        let policy = mandatory_request.upload_policy;
        let mandatory_item = &mut mandatory_request.snapshots[0];
        let mut mandatory_curve = max_fractional_context_curve_fixture();
        while prune_one_context_curve_fill_point(&mut mandatory_curve) {}
        mandatory_item.context_curve = Some(mandatory_curve);
        mandatory_item.snapshot_fingerprint =
            snapshot_fingerprint(SnapshotSource::ClaudeCode, mandatory_item);
        let mandatory_size =
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, mandatory_item, policy);
        let mut unavailable_probe = mandatory_item.clone();
        let mandatory_curve = unavailable_probe.context_curve.as_ref().expect("curve");
        unavailable_probe.context_curve = Some(unavailable_context_curve(
            &mandatory_curve.parser_revision,
            &mandatory_curve.ownership_revision,
            "payload_budget_exceeded",
            0,
            0,
        ));
        let unavailable_size =
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, &unavailable_probe, policy);
        assert!(mandatory_size > unavailable_size);
        fit_context_curve_to_snapshot_item_budget(
            SnapshotSource::ClaudeCode,
            mandatory_item,
            policy,
            unavailable_size,
        );
        let unavailable = mandatory_item
            .context_curve
            .as_ref()
            .expect("budget reason remains explicit");
        assert_eq!(unavailable.coverage, "payload_budget_exceeded");
        assert_eq!(unavailable.total_owned_request_count, 0);
        assert!(unavailable.points.is_empty());
        assert!(
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, mandatory_item, policy)
                <= unavailable_size
        );
        validate_snapshot_batch_request(&mandatory_request)
            .expect("unavailable curve never quarantines ordinary snapshot evidence");

        let mut reserve_item = unavailable_probe;
        let mut reserve_base = reserve_item.clone();
        reserve_base.context_curve = None;
        let reserve_base_size =
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, &reserve_base, policy);
        let near_limit_budget = reserve_base_size + 1;
        fit_context_curve_to_snapshot_item_budget(
            SnapshotSource::ClaudeCode,
            &mut reserve_item,
            policy,
            near_limit_budget,
        );
        assert_eq!(
            reserve_item
                .context_curve
                .as_ref()
                .expect("explicit clear is never omitted")
                .coverage,
            "payload_budget_exceeded"
        );
        let reserve_item_size =
            snapshot_item_wire_size(SnapshotSource::ClaudeCode, &reserve_item, policy);
        assert!(reserve_item_size > near_limit_budget);
        assert!(reserve_item_size <= near_limit_budget + 1_024);

        assert!(snapshot_item_wire_size_is_allowed(
            MAX_SNAPSHOT_ITEM_WIRE_BYTES + 1,
            MAX_SNAPSHOT_ITEM_WIRE_BYTES,
            Some("payload_budget_exceeded")
        ));
        assert!(!snapshot_item_wire_size_is_allowed(
            MAX_SNAPSHOT_ITEM_WIRE_BYTES + 1,
            MAX_SNAPSHOT_ITEM_WIRE_BYTES,
            Some("sampled")
        ));
        assert!(!snapshot_item_wire_size_is_allowed(
            MAX_SNAPSHOT_ITEM_CLEAR_WIRE_BYTES + 1,
            MAX_SNAPSHOT_ITEM_WIRE_BYTES,
            Some("payload_budget_exceeded")
        ));
    }

