    #[test]
    fn context_curve_fails_closed_on_unsafe_or_unbounded_model_evidence() {
        let hostile_path = "/Users/operator/private/repository/session.jsonl";
        let hostile = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &[ContextCurveCandidatePoint {
                observed_at: Some("2026-08-20T12:00:01Z".to_string()),
                effective_input_tokens: 10,
                model: Some(hostile_path.to_string()),
                context_window_tokens: None,
            }],
            &[],
            "parser_unsupported",
        );
        assert_eq!(hostile.coverage, "complete");
        assert_eq!(hostile.model_windows[0].model, "unknown");
        assert_eq!(hostile.model_windows[0].evidence_kind, "unavailable");
        assert!(!serde_json::to_string(&hostile)
            .expect("serialize hostile evidence")
            .contains(hostile_path));

        let window_without_safe_model = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &[ContextCurveCandidatePoint {
                observed_at: Some("2026-08-20T12:00:01Z".to_string()),
                effective_input_tokens: 10,
                model: Some(hostile_path.to_string()),
                context_window_tokens: Some(258_400),
            }],
            &[],
            "parser_unsupported",
        );
        assert_eq!(window_without_safe_model.coverage, "complete");
        assert_eq!(window_without_safe_model.model_windows[0].model, "unknown");
        assert_eq!(
            window_without_safe_model.model_windows[0].evidence_kind,
            "provider_reported_window"
        );

        let too_many_models = (0..17_u64)
            .map(|index| ContextCurveCandidatePoint {
                observed_at: Some(format!("2026-08-20T12:00:{:02}Z", index + 1)),
                effective_input_tokens: index + 1,
                model: Some(format!("model-{index}")),
                context_window_tokens: None,
            })
            .collect::<Vec<_>>();
        let unavailable = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &too_many_models,
            &[],
            "parser_unsupported",
        );
        assert_eq!(unavailable.coverage, "parser_unsupported");
        assert_eq!(unavailable.total_owned_request_count, 0);
        assert!(unavailable.points.is_empty());
    }

    #[test]
    fn context_curve_fails_closed_without_exact_boundary_adjacency() {
        let candidates = [1_u64, 2]
            .into_iter()
            .map(|ordinal| ContextCurveCandidatePoint {
                observed_at: Some(format!("2026-08-20T12:00:0{ordinal}Z")),
                effective_input_tokens: ordinal * 10,
                model: Some("gpt-5.5".to_string()),
                context_window_tokens: Some(258_400),
            })
            .collect::<Vec<_>>();
        for point_count_before in [0_u64, 2] {
            let curve = build_context_curve(
                CODEX_SNAPSHOT_PARSER_VERSION,
                "codex_owned_rollout_occurrences:v1",
                "codex_token_count_model_context_window:v1",
                &candidates,
                &[ContextCurveCandidateBoundary {
                    observed_at: Some("2026-08-20T12:00:01Z".to_string()),
                    point_count_before,
                }],
                "ownership_unresolved",
            );
            assert_eq!(curve.coverage, "ownership_unresolved");
            assert!(curve.boundaries.is_empty());
        }
        let out_of_interval = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &candidates,
            &[ContextCurveCandidateBoundary {
                observed_at: Some("2026-08-20T12:00:03Z".to_string()),
                point_count_before: 1,
            }],
            "ownership_unresolved",
        );
        assert_eq!(out_of_interval.coverage, "ownership_unresolved");
        assert!(out_of_interval.boundaries.is_empty());
    }

    #[test]
    fn context_curve_cross_language_golden_is_canonical_and_current() {
        let point = |timestamp: &str, tokens: u64, model: &str, window: Option<u64>| {
            ContextCurveCandidatePoint {
                observed_at: Some(timestamp.to_string()),
                effective_input_tokens: tokens,
                model: Some(model.to_string()),
                context_window_tokens: window,
            }
        };
        let codex = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &[
                point("2026-08-20T12:00:01Z", 18_000, "gpt-5.5", Some(258_400)),
                point("2026-08-20T12:00:02Z", 42_000, "gpt-5.5", Some(258_400)),
                point("2026-08-20T12:00:04Z", 21_000, "gpt-5.5", Some(258_400)),
            ],
            &[ContextCurveCandidateBoundary {
                observed_at: Some("2026-08-20T12:00:03Z".to_string()),
                point_count_before: 2,
            }],
            "parser_unsupported",
        );
        let claude = build_context_curve(
            CLAUDE_CODE_SNAPSHOT_PARSER_VERSION,
            "claude_owned_request_start_proof:v1",
            "claude_transcript_model:v1",
            &[
                point("2026-08-20T13:00:01Z", 115, "claude-opus-4-8", None),
                point("2026-08-20T13:00:03Z", 220, "claude-opus-4-8", None),
                point("2026-08-20T13:00:04Z", 337, "claude-opus-4-8", None),
            ],
            &[ContextCurveCandidateBoundary {
                observed_at: Some("2026-08-20T13:00:02Z".to_string()),
                point_count_before: 1,
            }],
            "parser_unsupported",
        );
        let witness = |curve: SnapshotContextCurve,
                       tool_usage: Option<Vec<SnapshotToolUsage>>,
                       tool_usage_truncated: bool| {
            let mut item = sample_session_artifact_item();
            item.context_curve = Some(curve);
            item.tool_usage = tool_usage;
            item.tool_usage_truncated = tool_usage_truncated;
            json!({
                "version": snapshot_upload_body_witness_version(&item),
                "digest": snapshot_upload_body_witness(&item),
            })
        };
        let body_witnesses = json!({
            "codex_curve_only_v11": witness(codex.clone(), None, false),
            "claude_curve_only_v11": witness(claude.clone(), None, false),
            "curve_with_empty_tool_usage_v11": witness(codex.clone(), Some(Vec::new()), false),
            "curve_with_truncated_only_v11": witness(codex.clone(), None, true),
            "curve_with_both_tool_fields_v11": witness(
                codex.clone(),
                Some(vec![SnapshotToolUsage { name: "Read".to_string(), count: 2 }]),
                true,
            ),
        });
        let fixture = json!({
            "fixture_version": "local_context_curve_wire:v1",
            "codex": codex,
            "claude_code": claude,
        });
        let canonical =
            crate::canonical_json::canonicalize(&fixture).expect("curve fixture canonicalizes");
        let fixture_hash = format!("{:x}", Sha256::digest(&canonical));
        let max_fractional_curve = max_fractional_context_curve_fixture();
        let max_fractional_canonical = crate::canonical_json::canonicalize(
            &serde_json::to_value(&max_fractional_curve).expect("max fractional curve serializes"),
        )
        .expect("max fractional curve canonicalizes");
        let max_fractional_hash = format!("{:x}", Sha256::digest(&max_fractional_canonical));
        let manifest = json!({
            "manifest_version": "local_context_curve_wire_manifest:v1",
            "contract_version": CONTEXT_CURVE_CONTRACT_VERSION,
            "canonicalization": crate::canonical_json::CANONICAL_JSON_CONTRACT_VERSION,
            "fixture_file": "context-curve-v1-golden.json",
            "fixture_trailing_newline": true,
            "fixture_canonical_sha256": fixture_hash,
            "max_fractional_fixture_file": "context-curve-v1-max-fractional.json",
            "max_fractional_fixture_trailing_newline": true,
            "max_fractional_fixture_canonical_sha256": max_fractional_hash,
            "max_fractional_fixture_wire_bytes": max_fractional_canonical.len(),
            "caps": {
                "points": MAX_CONTEXT_CURVE_POINTS,
                "boundaries": MAX_CONTEXT_CURVE_BOUNDARIES,
                "model_windows": MAX_CONTEXT_CURVE_MODEL_WINDOWS,
                "wire_bytes": MAX_CONTEXT_CURVE_WIRE_BYTES,
            },
            "retention_flags": {
                "anchor": CONTEXT_CURVE_RETENTION_ANCHOR,
                "compaction_before": CONTEXT_CURVE_RETENTION_COMPACTION_BEFORE,
                "compaction_after": CONTEXT_CURVE_RETENTION_COMPACTION_AFTER,
                "peak": CONTEXT_CURVE_RETENTION_PEAK,
                "tail": CONTEXT_CURVE_RETENTION_TAIL,
                "deterministic_fill": CONTEXT_CURVE_RETENTION_FILL,
            },
            "revisions": {
                "sampling": CONTEXT_CURVE_SAMPLING_REVISION,
                "codex_parser": CODEX_SNAPSHOT_PARSER_VERSION,
                "codex_ownership": CODEX_CONTEXT_CURVE_OWNERSHIP_REVISION,
                "codex_model_window_evidence": CODEX_CONTEXT_CURVE_MODEL_EVIDENCE_REVISION,
                "claude_parser": CLAUDE_CODE_SNAPSHOT_PARSER_VERSION,
                "claude_ownership": CLAUDE_CONTEXT_CURVE_OWNERSHIP_REVISION,
                "claude_model_window_evidence": CLAUDE_CONTEXT_CURVE_MODEL_EVIDENCE_REVISION,
            },
            "body_witnesses": body_witnesses,
        });
        let canonical_manifest =
            crate::canonical_json::canonicalize(&manifest).expect("curve manifest canonicalizes");
        let fixture_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/snapshot-audit/context-curve-v1-golden.json");
        let manifest_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/snapshot-audit/context-curve-v1-manifest.json");
        let max_fractional_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/snapshot-audit/context-curve-v1-max-fractional.json");
        if std::env::var_os("UPDATE_CONTEXT_CURVE_GOLDEN").is_some() {
            let mut fixture_file = canonical.clone();
            fixture_file.push(b'\n');
            fs::write(&fixture_path, fixture_file).expect("write curve fixture");
            let mut manifest_file = canonical_manifest.clone();
            manifest_file.push(b'\n');
            fs::write(&manifest_path, manifest_file).expect("write curve manifest");
            let mut max_fractional_file = max_fractional_canonical.clone();
            max_fractional_file.push(b'\n');
            fs::write(&max_fractional_path, max_fractional_file)
                .expect("write max fractional curve fixture");
        }
        let mut expected_fixture = canonical;
        expected_fixture.push(b'\n');
        let mut expected_manifest = canonical_manifest;
        expected_manifest.push(b'\n');
        let mut expected_max_fractional = max_fractional_canonical;
        expected_max_fractional.push(b'\n');
        assert_eq!(
            fs::read(&fixture_path).expect("read curve fixture"),
            expected_fixture,
            "run UPDATE_CONTEXT_CURVE_GOLDEN=1 cargo test -p ottto-service --lib context_curve_cross_language_golden_is_canonical_and_current"
        );
        assert_eq!(
            fs::read(&manifest_path).expect("read curve manifest"),
            expected_manifest,
            "run UPDATE_CONTEXT_CURVE_GOLDEN=1 cargo test -p ottto-service --lib context_curve_cross_language_golden_is_canonical_and_current"
        );
        assert_eq!(
            fs::read(&max_fractional_path).expect("read max fractional curve fixture"),
            expected_max_fractional,
            "run UPDATE_CONTEXT_CURVE_GOLDEN=1 cargo test -p ottto-service --lib context_curve_cross_language_golden_is_canonical_and_current"
        );
    }

    #[test]
    fn context_curve_requires_exact_durable_entity_ack_proof() {
        let curve = build_context_curve(
            CODEX_SNAPSHOT_PARSER_VERSION,
            "codex_owned_rollout_occurrences:v1",
            "codex_token_count_model_context_window:v1",
            &[ContextCurveCandidatePoint {
                observed_at: Some("2026-08-20T12:00:00.003Z".to_string()),
                effective_input_tokens: 42,
                model: Some("gpt-5.5".to_string()),
                context_window_tokens: Some(258_400),
            }],
            &[],
            "parser_unsupported",
        );
        let mut item = sample_session_artifact_item();
        item.context_curve = Some(curve);
        item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::ClaudeCode, &item);
        let request = SnapshotBatchRequest {
            schema_version: SNAPSHOT_SCHEMA_VERSION,
            source: "claude_code".to_string(),
            machine_id: "machine".to_string(),
            collector_version: None,
            snapshots: vec![item.clone()],
            upload_policy: SnapshotUploadPolicy::default(),
            client_report: crate::client_report::ClientReport::empty(),
        };
        let response = |version: Option<u64>, digest: Option<String>| {
            crate::snapshot_client::SnapshotBatchResponse {
                accepted: 1,
                sessions_reconciled: 0,
                session_ids: Vec::new(),
                disabled: false,
                disabled_reason: None,
                entity_ack_contract: Some(SNAPSHOT_ENTITY_ACK_CONTRACT.to_string()),
                accepted_entities: vec![crate::snapshot_client::SnapshotEntityRef {
                    source_session_id: item.source_session_id.clone(),
                    snapshot_fingerprint: item.snapshot_fingerprint.clone(),
                    occurrence_count: 1,
                    body_witness_version: version,
                    body_witness_digest: digest,
                    head_etag: None,
                    head_challenge: None,
                    unchanged_basis: None,
                }],
                unchanged_entities: Vec::new(),
                rejected_entities: Vec::new(),
                conflict_entities: Vec::new(),
            }
        };
        let legacy = crate::snapshot_client::SnapshotBatchResponse {
            accepted: 1,
            sessions_reconciled: 0,
            session_ids: Vec::new(),
            disabled: false,
            disabled_reason: None,
            entity_ack_contract: None,
            accepted_entities: Vec::new(),
            unchanged_entities: Vec::new(),
            rejected_entities: Vec::new(),
            conflict_entities: Vec::new(),
        };
        legacy
            .validate_entity_ack(&request)
            .expect_err("legacy/routing-off ACK cannot settle curve evidence");
        response(None, None)
            .validate_entity_ack(&request)
            .expect_err("generic entity ACK cannot settle curve evidence");
        response(Some(5), Some("0".repeat(64)))
            .validate_entity_ack(&request)
            .expect_err("mismatched durable proof cannot settle curve evidence");
        response(
            Some(SNAPSHOT_BODY_WITNESS_ENVELOPE_CONTEXT_CURVE_VERSION),
            Some(snapshot_upload_body_witness(&item)),
        )
        .validate_entity_ack(&request)
        .expect_err("internal envelope proof cannot replace the public ACK version");
        response(
            Some(crate::snapshot_client::SNAPSHOT_BODY_WITNESS_PUBLIC_CONTEXT_CURVE_VERSION),
            Some("0".repeat(64)),
        )
        .validate_entity_ack(&request)
        .expect_err("mismatched durable proof cannot settle curve evidence");
        response(
            Some(crate::snapshot_client::SNAPSHOT_BODY_WITNESS_PUBLIC_CONTEXT_CURVE_VERSION),
            Some(snapshot_upload_body_witness(&item)),
        )
        .validate_entity_ack(&request)
        .expect("exact released accepted-log proof settles curve evidence");

        let mut exclusive_item = item.clone();
        exclusive_item.usage_accounting_contract =
            Some("session_exclusive_reported_usage:v1".to_string());
        exclusive_item.snapshot_fingerprint =
            snapshot_fingerprint(SnapshotSource::ClaudeCode, &exclusive_item);
        let exclusive_request = SnapshotBatchRequest {
            snapshots: vec![exclusive_item.clone()],
            ..request
        };
        let exclusive_response = |version| crate::snapshot_client::SnapshotBatchResponse {
            accepted: 1,
            sessions_reconciled: 0,
            session_ids: Vec::new(),
            disabled: false,
            disabled_reason: None,
            entity_ack_contract: Some(SNAPSHOT_ENTITY_ACK_CONTRACT.to_string()),
            accepted_entities: vec![crate::snapshot_client::SnapshotEntityRef {
                source_session_id: exclusive_item.source_session_id.clone(),
                snapshot_fingerprint: exclusive_item.snapshot_fingerprint.clone(),
                occurrence_count: 1,
                body_witness_version: Some(version),
                body_witness_digest: Some(snapshot_upload_body_witness(&exclusive_item)),
                head_etag: None,
                head_challenge: None,
                unchanged_basis: None,
            }],
            unchanged_entities: Vec::new(),
            rejected_entities: Vec::new(),
            conflict_entities: Vec::new(),
        };
        exclusive_response(SNAPSHOT_BODY_WITNESS_ENVELOPE_EXCLUSIVE_CONTEXT_CURVE_VERSION)
            .validate_entity_ack(&exclusive_request)
            .expect_err("internal v12 alias cannot replace released v6 ACK proof");
        exclusive_response(6)
            .validate_entity_ack(&exclusive_request)
            .expect("released v6 accepted-log proof settles internal v12 curve evidence");
    }

    #[test]
    fn body_witness_ack_normalization_fixture_is_canonical_and_current() {
        let curve = build_context_curve(
            CLAUDE_CODE_SNAPSHOT_PARSER_VERSION,
            "claude_owned_request_start_proof:v1",
            "claude_transcript_model:v1",
            &[ContextCurveCandidatePoint {
                observed_at: Some("2026-08-30T12:00:00Z".to_string()),
                effective_input_tokens: 42,
                model: Some("claude-opus-4-8".to_string()),
                context_window_tokens: None,
            }],
            &[],
            "ownership_unresolved",
        );
        let mut nonexclusive = sample_session_artifact_item();
        nonexclusive.context_curve = Some(curve.clone());
        let mut exclusive = nonexclusive.clone();
        exclusive.usage_accounting_contract =
            Some("session_exclusive_reported_usage:v1".to_string());
        // Evidence-bearing legacy bodies reserve v21/v22. Envelope evidence
        // uses v23/v24, so public normalization must be an explicit mapping.
        let mappings = [
            (7_u64, 1_u64),
            (8, 2),
            (9, 3),
            (10, 4),
            (11, 5),
            (12, 6),
            (15, 13),
            (16, 14),
            (19, 17),
            (20, 18),
            (23, 7),
            (24, 8),
        ]
        .into_iter()
        .map(|(internal_version, released_ack_version)| {
            json!({
                "internal_version": internal_version,
                "released_ack_version": released_ack_version,
            })
        })
        .collect::<Vec<_>>();
        let header = codex_creator_header();
        let creator_case = |exclusive: bool, with_curve: bool| {
            // Exercise the actual original-session parser and its model/hourly
            // usage fold rather than a metadata-only item with positive totals.
            let mut item = codex_creator_item(
                std::slice::from_ref(&header),
                header["payload"]["id"].as_str().unwrap(),
            );
            item.cache_observations = None;
            item.cache_observations_state = None;
            if !exclusive {
                item.usage_accounting_contract = None;
            }
            if !with_curve {
                item.context_curve = None;
            }
            assert_eq!(
                (item.input_tokens, item.output_tokens, item.request_count),
                (100, 5, 1)
            );
            assert_eq!(item.model_usage.len(), 1);
            assert_eq!(item.usage_buckets.len(), 1);
            let bucket = &item.usage_buckets[0];
            assert_eq!(bucket.bucket_start, "2026-09-30T10:00:00Z");
            assert_eq!(bucket.model_usage, item.model_usage);
            assert_eq!(
                (
                    item.model_usage[0].input_tokens,
                    item.model_usage[0].output_tokens,
                    item.model_usage[0].request_count
                ),
                (100, 5, 1)
            );
            assert!(item
                .source_file_fingerprint
                .as_deref()
                .is_some_and(|fp| fp.len() == 64));
            let mut request = valid_v6_batch_request();
            request.source = "codex".into();
            request.snapshots = vec![item.clone()];
            apply_upload_policy(
                SnapshotSource::Codex,
                &mut request.snapshots,
                request.upload_policy,
            );
            let item = &mut request.snapshots[0];
            item.snapshot_fingerprint = snapshot_fingerprint(SnapshotSource::Codex, item);
            let wire = serde_json::to_value(&request).unwrap();
            let item = &request.snapshots[0];
            let envelope =
                snapshot_semantic_envelope(SnapshotSource::Codex, item, request.upload_policy);
            assert_eq!(
                wire["snapshots"][0]["semantic_envelope"],
                serde_json::to_value(&envelope).unwrap()
            );
            assert_eq!(
                item.snapshot_fingerprint,
                snapshot_fingerprint_from_component_hashes(
                    SnapshotSource::Codex,
                    &item.source_session_id,
                    &envelope.component_hashes
                )
            );
            let canonical =
                crate::canonical_json::canonicalize(&snapshot_upload_body_witness_payload(item))
                    .unwrap();
            assert_eq!(
                snapshot_upload_body_witness(item),
                format!("{:x}", Sha256::digest(canonical))
            );
            assert_eq!(
                wire["snapshots"][0]["usage_buckets"][0]["model_usage"],
                wire["snapshots"][0]["model_usage"]
            );
            json!({
                "wire": wire,
                "internal_version": snapshot_upload_body_witness_version(item),
                "released_ack_version": if exclusive { 8 } else { 7 },
                "digest": snapshot_upload_body_witness(item),
                "body_projection": snapshot_upload_body_witness_payload(item),
            })
        };
        let fixture = json!({
            "contract_version": "snapshot_body_witness_ack_normalization:v1",
            "session_account_omission_contract": {
                "session_account_evidence": "omitted when absent; never serialized as null",
                "source_created_at": "omitted when absent; never serialized as null",
                "source_created_at_spelling": "RFC3339 formatted original own-header time; fixture 2026-09-30T10:00:00Z",
                "requires_semantic_envelope_for_internal_versions_23_24": true,
                "reserved_legacy_session_account_witness_domain": [21, 22],
                "legacy_content_hash_epoch": SNAPSHOT_CONTENT_HASH_EPOCH,
            },
            "session_account_cases": {
                "nonexclusive": creator_case(false, false),
                "exclusive": creator_case(true, false),
                "exclusive_with_curve": creator_case(true, true),
            },
            "mappings": mappings,
            "declared_cache_session_account_ack_mappings": {"23": 13, "24": 14},
            "curve_cases": {
                "nonexclusive": {
                    "internal_version": snapshot_upload_body_witness_version(&nonexclusive),
                    "released_ack_version": 5,
                    "digest": snapshot_upload_body_witness(&nonexclusive),
                },
                "exclusive": {
                    "internal_version": snapshot_upload_body_witness_version(&exclusive),
                    "released_ack_version": 6,
                    "digest": snapshot_upload_body_witness(&exclusive),
                },
            },
        });
        let mut canonical = crate::canonical_json::canonicalize(&fixture)
            .expect("ACK normalization fixture canonicalizes");
        canonical.push(b'\n');
        let fixture_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/snapshot-audit/body-witness-ack-normalization-v1.json");
        if std::env::var_os("UPDATE_BODY_WITNESS_ACK_GOLDEN").is_some() {
            fs::write(&fixture_path, &canonical).expect("write ACK normalization fixture");
        }
        assert_eq!(
            fs::read(&fixture_path).expect("read ACK normalization fixture"),
            canonical,
            "run UPDATE_BODY_WITNESS_ACK_GOLDEN=1 cargo test -p ottto-service --lib body_witness_ack_normalization_fixture_is_canonical_and_current"
        );
    }

    #[test]
    fn cache_physical_record_loss_preserves_usage_and_accepted_observations() {
        use std::io::Write;
        let root = temp_dir("cache-physical-record-loss");
        let id = "00000000-0000-7000-8000-000000000001";
        let path = root.join(format!("rollout-{id}.jsonl"));
        let header =
            json!({"type":"session_meta","timestamp":"2026-09-30T10:00:00Z","payload":{"id":id}});
        let mut prefix = format!(
            "{header}\n{}\n",
            json!({"type":"turn_context","payload":{"model":"gpt-5.6-sol","effort":"high"}})
        );
        let mut suffix = String::new();
        let mut lost_request = String::new();
        let mut reads = 0;
        for (index, read) in [90_000, 0, 90_000].into_iter().enumerate() {
            reads += read;
            let timestamp = format!("2026-09-30T10:00:0{index}Z");
            let rows = [
                json!({"type":"token_usage_record","timestamp":timestamp,"payload":{"response_id":format!("resp_cache_fixture_{index}"),"usage":{"input_tokens":100_000,"cached_input_tokens":read,"cache_write_input_tokens":0,"output_tokens":1}}}),
                json!({"type":"event_msg","timestamp":timestamp,"payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":100_000*(index+1),"cached_input_tokens":reads,"output_tokens":index+1},"last_token_usage":{"input_tokens":100_000,"cached_input_tokens":read,"output_tokens":1}}}}),
            ];
            let text = rows
                .iter()
                .map(|row| format!("{row}\n"))
                .collect::<String>();
            if index == 0 {
                prefix.push_str(&text);
            } else if index == 1 {
                lost_request = rows[0].to_string();
                suffix.push_str(&format!("{}\n", rows[1]));
            } else {
                suffix.push_str(&text);
            }
        }
        fs::write(&path, format!("{prefix}{lost_request}\n{suffix}")).unwrap();
        let clean = parse_codex_test_with_ledgers(&path, BTreeMap::new());
        assert!(clean.complete());
        let mut prior_item = clean.snapshots[0].clone();
        prepare_cache_observations(&mut prior_item, None);
        let prior = prior_item.cache_observations_state.unwrap();
        assert_eq!(prior["observations"].as_array().unwrap().len(), 1);
        for loss in ["oversized", "malformed", "invalid_utf8"] {
            let mut file = File::create(&path).unwrap();
            file.write_all(prefix.as_bytes()).unwrap();
            match loss {
                "oversized" => {
                    file.write_all(lost_request.trim_end_matches('}').as_bytes())
                        .unwrap();
                    file.write_all(b",\"padding\":\"").unwrap();
                    file.seek(SeekFrom::Current((MAX_JSONL_LINE_BYTES + 1) as i64))
                        .unwrap();
                    file.write_all(b"\"}\n").unwrap();
                }
                "malformed" => file.write_all(b"{broken boundary\n").unwrap(),
                _ => file.write_all(b"\xff\n").unwrap(),
            }
            file.write_all(suffix.as_bytes()).unwrap();
            drop(file);
            let parsed = parse_codex_test_with_ledgers(&path, BTreeMap::new());
            assert!(!parsed.report.complete());
            assert_eq!(
                parsed.complete(),
                loss == "oversized",
                "terminal usage loss policy unchanged"
            );
            let mut item = parsed.snapshots[0].clone();
            assert_eq!((item.input_tokens, item.output_tokens), (300_000, 3));
            assert_eq!(item.model_usage, clean.snapshots[0].model_usage);
            assert_eq!(item.usage_buckets, clean.snapshots[0].usage_buckets);
            assert_eq!(
                item.cache_requests.len(),
                2,
                "the skipped owned response is absent"
            );
            // Without the read-completeness fence, the unchanged detector calls
            // these two surviving warm requests complete and retracts the
            // previously accepted loss anchored on the missing cold request.
            let mut unfenced = item.clone();
            unfenced.cache_observations = cache_wire_for_requests(id, &item.cache_requests);
            prepare_cache_observations(&mut unfenced, Some(&prior));
            assert!(matches!(
                unfenced
                    .cache_observations
                    .as_ref()
                    .unwrap()
                    .operations
                    .as_slice(),
                [cache_observations::Operation::Retract { .. }]
            ));
            assert_eq!(
                unfenced.cache_observations_state.unwrap()["observations"],
                json!([])
            );
            assert!(
                !item.cache_requests_complete,
                "{loss}: skipped physical boundary is unknown"
            );
            let patch = item.cache_observations.as_ref().unwrap();
            assert_eq!(patch.coverage, "partial");
            assert!(
                patch.operations.is_empty(),
                "no inferred requests across lost records"
            );
            prepare_cache_observations(&mut item, Some(&prior));
            assert!(item
                .cache_observations
                .as_ref()
                .unwrap()
                .operations
                .is_empty());
            assert_eq!(
                item.cache_observations_state.as_ref().unwrap()["observations"],
                prior["observations"],
                "loss cannot retract accepted evidence"
            );
        }
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn paired_creator_cache_wire_corpus_matches_exact_ack() {
        // One physical source stream supplies both creator and owned canonical
        // cache requests. No source identity is grafted onto another session.
        let header = codex_creator_header();
        let session = header["payload"]["id"].as_str().unwrap().to_string();
        let mut records = vec![
            header,
            json!({"type":"turn_context","payload":{"model":"gpt-5.6-sol","effort":"high","current_date":"2026-09-30"}}),
        ];
        let mut read_total = 0;
        for (index, read) in [90_000, 0, 90_000].into_iter().enumerate() {
            let timestamp = format!("2026-09-30T10:00:0{index}Z");
            read_total += read;
            records.push(json!({"type":"token_usage_record","timestamp":timestamp,"payload":{"response_id":format!("resp_paired_{index}"),"usage":{"input_tokens":100_000,"cached_input_tokens":read,"cache_write_input_tokens":0,"output_tokens":1}}}));
            records.push(json!({"type":"event_msg","timestamp":timestamp,"payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":100_000*(index+1),"cached_input_tokens":read_total,"output_tokens":index+1},"last_token_usage":{"input_tokens":100_000,"cached_input_tokens":read,"output_tokens":1}}}}));
        }
        let root = temp_dir("paired-creator-cache");
        let path = root.join(format!("rollout-2026-09-30T10-00-00-{session}.jsonl"));
        fs::write(
            &path,
            records
                .iter()
                .map(|row| format!("{row}\n"))
                .collect::<String>(),
        )
        .unwrap();
        let mut parsed = parse_codex_jsonl_file(&path, "2026-09-30T10:05:00Z", "f".repeat(64))
            .unwrap()
            .remove(0);
        fs::remove_dir_all(root).unwrap();
        prepare_cache_observations(&mut parsed, None);
        assert!(parsed.session_account_evidence.is_some());
        assert!(parsed.cache_observations.is_some());
        assert!(parsed.context_curve.is_some());
        assert_eq!((parsed.input_tokens, parsed.output_tokens), (300_000, 3));
        let mut cases = Vec::new();
        for capability in ["creator", "cache", "combined", "legacy"] {
            for exclusive in [false, true] {
                for curve in [false, true] {
                    for tools in [
                        "omitted",
                        "empty_default_only",
                        "nonempty",
                        "truncated_only",
                    ] {
                        let mut item = parsed.clone();
                        if capability == "cache" || capability == "legacy" {
                            item.session_account_evidence = None;
                        }
                        if capability == "creator" || capability == "legacy" {
                            item.cache_observations = None;
                            item.cache_observations_state = None;
                        }
                        if !exclusive {
                            item.usage_accounting_contract = None;
                        }
                        if !curve {
                            item.context_curve = None;
                        }
                        item.tool_usage = match tools {
                            "empty_default_only" => Some(vec![]),
                            "nonempty" => Some(vec![SnapshotToolUsage {
                                name: "Read".into(),
                                count: 2,
                            }]),
                            _ => None,
                        };
                        item.tool_usage_truncated = tools == "truncated_only";
                        let mut request = valid_v6_batch_request();
                        request.source = "codex".into();
                        request.snapshots = vec![item];
                        apply_upload_policy(
                            SnapshotSource::Codex,
                            &mut request.snapshots,
                            request.upload_policy,
                        );
                        request.snapshots[0].snapshot_fingerprint =
                            snapshot_fingerprint(SnapshotSource::Codex, &request.snapshots[0]);
                        let item = &request.snapshots[0];
                        // These are exact normal HTTP body bytes, not reconstructed
                        // canonical JSON or a mutation of the serialized leaves.
                        let wire_bytes = serde_json::to_vec(&request).unwrap();
                        let wire: Value = serde_json::from_slice(&wire_bytes).unwrap();
                        let projection = snapshot_upload_body_witness_payload(item);
                        let internal = snapshot_upload_body_witness_version(item);
                        let public = internal.map(|version| match version {
                            9 => 3,
                            10 => 4,
                            11 => 5,
                            12 => 6,
                            15 => 13,
                            16 => 14,
                            19 => 17,
                            20 => 18,
                            23 => {
                                if item.cache_observations.is_some() {
                                    13
                                } else {
                                    7
                                }
                            }
                            24 => {
                                if item.cache_observations.is_some() {
                                    14
                                } else {
                                    8
                                }
                            }
                            _ => panic!("unexpected paired domain"),
                        });
                        let digest = internal.map(|_| snapshot_upload_body_witness(item));
                        for field in [
                            "context_curve",
                            "tool_usage",
                            "tool_usage_truncated",
                            "session_account_evidence",
                        ] {
                            if let Some(declared) = wire["snapshots"][0].get(field) {
                                assert_eq!(projection.get(field), Some(declared));
                            } else if capability != "legacy" || curve || tools == "omitted" {
                                assert!(projection.get(field).is_none());
                            }
                        }
                        let response = |version, proof, unchanged| {
                            let reference = crate::snapshot_client::SnapshotEntityRef {
                                source_session_id: item.source_session_id.clone(),
                                snapshot_fingerprint: item.snapshot_fingerprint.clone(),
                                occurrence_count: 1,
                                body_witness_version: version,
                                body_witness_digest: proof,
                                head_etag: item.cache_observations.as_ref().map(|_| "a".repeat(64)),
                                head_challenge: None,
                                unchanged_basis: None,
                            };
                            crate::snapshot_client::SnapshotBatchResponse {
                                accepted: 1,
                                sessions_reconciled: 0,
                                session_ids: vec![],
                                disabled: false,
                                disabled_reason: None,
                                entity_ack_contract: Some(SNAPSHOT_ENTITY_ACK_CONTRACT.into()),
                                accepted_entities: if unchanged {
                                    vec![]
                                } else {
                                    vec![reference.clone()]
                                },
                                unchanged_entities: if unchanged {
                                    vec![reference]
                                } else {
                                    vec![]
                                },
                                rejected_entities: vec![],
                                conflict_entities: vec![],
                            }
                        };
                        for unchanged in [false, true] {
                            response(public, digest.clone(), unchanged)
                                .validate_entity_ack(&request)
                                .unwrap();
                            if capability != "legacy" || curve {
                                assert!(response(public, Some("0".repeat(64)), unchanged)
                                    .validate_entity_ack(&request)
                                    .is_err());
                                assert!(response(None, None, unchanged)
                                    .validate_entity_ack(&request)
                                    .is_err());
                                assert!(response(Some(99), digest.clone(), unchanged)
                                    .validate_entity_ack(&request)
                                    .is_err());
                            }
                        }
                        cases.push(json!({"admission":"first_admission","capability":capability,"exclusive":exclusive,"curve":curve,"tools":tools,
                            "provenance":"real Codex parser and normal SnapshotBatchRequest serializer",
                            "wire":wire,"wire_body_utf8":String::from_utf8(wire_bytes).unwrap(),
                            "internal_version":internal,"released_ack_version":public,"digest":digest,
                            "body_projection":projection,"cache_observations_state":item.cache_observations_state}));
                    }
                }
            }
        }
        assert_eq!(cases.len(), 64);
        let corpus =
            json!({"contract_version":"paired_creator_cache_wire_corpus:v1","cases":cases});
        if let Ok(output) = std::env::var("OTTTO_PAIRED_CREATOR_CACHE_CORPUS_OUT") {
            fs::write(output, serde_json::to_vec_pretty(&corpus).unwrap()).unwrap();
        }
    }

    fn projection_adoption_fixture(name: &str, count: usize) -> (PathBuf, PathBuf, ScanIndex) {
        let home = temp_dir(name);
        let root = home.join("transcripts");
        fs::create_dir_all(&root).unwrap();
        for slot in 0..count {
            let session = format!("00000000-0000-7000-8000-{slot:012x}");
            fs::write(
                root.join(format!("rollout-{session}.jsonl")),
                format!(
                    "{{\"type\":\"session_meta\",\"ordinal\":0,\"timestamp\":\"2026-07-22T08:00:00Z\",\"payload\":{{\"id\":\"{session}\"}}}}\n{}\n",
                    codex_test_token_line("2026-07-22T08:00:01Z", Some(1), (12, 0, 4, 0), Some((12, 0, 4, 0)))
                ),
            ).unwrap();
        }
        let mut index = ScanIndex::default();
        index.activate_upload_context("already-admitted-context".into());
        let baseline = scan_source_roots(
            SnapshotSource::Codex,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-22T08:02:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .unwrap();
        assert_eq!(baseline.snapshots.len(), count);
        index.record_accepted_snapshot_fingerprints(
            &baseline
                .snapshots
                .iter()
                .map(|item| item.snapshot_fingerprint.clone())
                .collect(),
        );
        index.save(&home.join("scan-index.json")).unwrap();
        let mut loaded = ScanIndex::load(&home.join("scan-index.json")).unwrap();
        loaded.activate_upload_context("already-admitted-context".into());
        assert_eq!(loaded.accepted_snapshot_fingerprints.len(), count);
        assert_eq!(
            loaded.accepted_snapshot_fingerprint_ledger_version,
            SNAPSHOT_ACCEPTED_LEDGER_VERSION
        );
        assert!(loaded.files.values().all(|entry| {
            entry.scan_identity_version.as_deref() == Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION)
                && entry.effective_upload_body_witness_revision == 0
                && entry.last_upload_body_witness.is_some()
        }));
        (home, root, loaded)
    }

    #[test]
    fn sampled_audit_diagnostics_distinguish_semantic_only_change() {
        for missing_previous_semantic in [false, true] {
            let (home, root, mut index) = projection_adoption_fixture("audit-comparison", 1);
            // Adoption intentionally omits previous witnesses. Select the
            // ordinary due-audit path instead, which retains both comparisons.
            let key = index.files.keys().next().unwrap().clone();
            let fingerprint = index.files[&key].source_file_fingerprint.clone();
            assert!(index.stage_sampled_audit(
                &key,
                &fingerprint,
                crate::transcript_acquisition::AuditDebt {
                    due_unix_seconds: 1
                },
            ));
            let mut scan =
                projection_adoption_scan(&root, &mut index, MAX_BACKFILL_FILES_PER_SOURCE);
            assert_eq!(scan.pending_finalization.len(), 1);
            assert!(scan.pending_finalization[0]
                .previous_snapshot_fingerprint
                .is_some());
            assert!(scan.pending_finalization[0]
                .previous_upload_body_witness
                .is_some());
            // Tokens change semantic identity, but not the canonical additive
            // witness (curve/tool/account/cache evidence). Use the real builder.
            let before_body = snapshot_upload_body_witness(&scan.snapshots[0]);
            scan.snapshots[0].output_tokens += 1;
            assert_eq!(
                snapshot_upload_body_witness(&scan.snapshots[0]),
                before_body
            );
            scan.pending_finalization[0].sampled_audit_verified = true;
            if missing_previous_semantic {
                scan.pending_finalization[0].previous_snapshot_fingerprint = None;
            }
            let mut control = scan.clone();
            control.pending_finalization[0].sampled_audit_verified = false;
            let mut control_index = index.clone();
            finalize_scan_after_policy(SnapshotSource::Codex, &mut control, &mut control_index);
            let (_, rows) = crate::local_resource_diagnostics::capture(|| {
                finalize_scan_after_policy(SnapshotSource::Codex, &mut scan, &mut index);
            });
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0]["stage"], "sampled_audit_comparison");
            assert_eq!(rows[0]["counts"]["body_comparison_available"], true);
            assert_eq!(rows[0]["counts"]["effective_body_changed"], false);
            assert_eq!(
                rows[0]["counts"]["semantic_comparison_available"],
                !missing_previous_semantic
            );
            assert_eq!(rows[0]["counts"]["semantic_changed"], true);
            assert!(rows[0]["observation"]["shared_process_cpu_delta_us"].is_null());
            assert_eq!(
                serde_json::to_value(&scan.snapshots).unwrap(),
                serde_json::to_value(&control.snapshots).unwrap()
            );
            assert_eq!(
                serde_json::to_value(&index).unwrap(),
                serde_json::to_value(&control_index).unwrap()
            );
            fs::remove_dir_all(home).unwrap();
        }
    }

    #[test]
    fn codex_local_diagnostics_distinguish_loader_faults_and_identity_conflicts() {
        use crate::codex_scan_diagnostics::LoaderReason;
        let home = temp_dir("codex-local-loader-diagnostics");
        let root = home.join("sessions");
        fs::create_dir_all(&root).unwrap();
        let roots = std::slice::from_ref(&root);
        let empty = CodexTitleMetadata::load_from_roots(roots);
        assert!(!empty.state_census_incomplete && !empty.sidecar_census_incomplete);
        assert_eq!(
            empty.local_diagnostics.state_titles.reason,
            LoaderReason::Complete
        );
        assert_eq!(empty.local_diagnostics.session_index.completed_roots, 1);
        let db = Connection::open(home.join("state_5.sqlite")).unwrap();
        db.execute_batch("CREATE TABLE threads (id TEXT, title, tokens_used INTEGER, thread_source TEXT, first_user_message TEXT); INSERT INTO threads VALUES ('session', X'01', 1, 'user', NULL);").unwrap();
        drop(db);
        let malformed_row = CodexTitleMetadata::load_from_roots(roots);
        assert_eq!(
            malformed_row.local_diagnostics.state_titles.reason,
            LoaderReason::SqliteRowDecode
        );
        assert_eq!(
            malformed_row.local_diagnostics.state_threads.reason,
            LoaderReason::SqliteRowDecode
        );
        assert_eq!(
            malformed_row.local_diagnostics.spawn_edges.reason,
            LoaderReason::Complete
        );
        assert!(malformed_row.state_census_incomplete);
        fs::remove_file(home.join("state_5.sqlite")).unwrap();
        let db = Connection::open(home.join("state_5.sqlite")).unwrap();
        db.execute_batch("CREATE TABLE threads (id TEXT, title TEXT);")
            .unwrap();
        drop(db);
        let schema = CodexTitleMetadata::load_from_roots(roots);
        assert_eq!(
            schema.local_diagnostics.state_threads.reason,
            LoaderReason::IncompleteShape
        );
        assert_eq!(
            schema.local_diagnostics.spawn_edges.reason,
            LoaderReason::IncompleteShape
        );
        fs::remove_file(home.join("state_5.sqlite")).unwrap();
        // Untitled cased aliases inside one state DB are an alias, not a row
        // conflict, and the threads loader is the first to see them.
        let db = Connection::open(home.join("state_5.sqlite")).unwrap();
        db.execute_batch(concat!(
            "CREATE TABLE threads (id TEXT, title TEXT, tokens_used INTEGER, ",
            "thread_source TEXT, first_user_message TEXT); INSERT INTO threads VALUES ",
            "('ABCDEF00-0000-7000-8000-000000000002', NULL, 1, 'user', NULL), ",
            "('abcdef00-0000-7000-8000-000000000002', NULL, 2, 'user', NULL);"
        ))
        .unwrap();
        drop(db);
        let alias = CodexTitleMetadata::load_from_roots(roots);
        assert!(alias.local_diagnostics.state_threads.identity_conflict);
        assert!(!alias.local_diagnostics.state_titles.identity_conflict);
        let taxonomy = alias.local_diagnostics.identity_conflict_taxonomy;
        assert_eq!(
            (
                taxonomy.state_alias_keys,
                taxonomy.state_intra_root_row_keys,
                taxonomy.state_cross_root_keys,
                taxonomy.conflict_keys_total,
            ),
            (1, 0, 0, 1)
        );
        fs::remove_file(home.join("state_5.sqlite")).unwrap();
        // Differently cased UUIDs collapse to the same comparison key.
        fs::write(
            home.join("session_index.jsonl"),
            concat!(
                "{\"id\":\"ABCDEF00-0000-7000-8000-000000000001\",\"title\":\"old\"}\n",
                "{\"id\":\"abcdef00-0000-7000-8000-000000000001\",\"title\":\"new\"}\n"
            ),
        )
        .unwrap();
        let conflict = CodexTitleMetadata::load_from_roots(roots);
        assert!(conflict.local_diagnostics.session_index.identity_conflict);
        assert_eq!(
            conflict.local_diagnostics.session_index.reason,
            LoaderReason::Complete
        );
        assert!(!conflict.state_census_incomplete && conflict.sidecar_census_incomplete);
        fs::remove_dir_all(home).unwrap();
    }

    #[test]
    fn codex_local_diagnostics_bind_failed_root_and_sqlite_operation() {
        let home = temp_dir("codex-local-root-fault");
        let good = home.join("good");
        let bad = home.join("bad");
        let roots = [good.join("sessions"), bad.join("sessions")];
        for root in &roots {
            fs::create_dir_all(root).unwrap();
        }
        fs::write(bad.join("state_5.sqlite"), b"not a SQLite database").unwrap();
        let metadata = CodexTitleMetadata::load_from_roots(&roots);
        assert!(metadata.state_census_incomplete && metadata.sidecar_census_incomplete);
        let diagnostics = serde_json::to_value(metadata.local_diagnostics).unwrap();
        for loader in ["state_titles", "state_threads", "spawn_edges"] {
            let evidence = &diagnostics[loader];
            assert_eq!(evidence["failed_roots"], 1);
            assert_eq!(evidence["completed_roots"], 1);
            assert_eq!(evidence["sqlite_extended_code"], 26);
            assert_eq!(evidence["first_failure_stage"], "prepare");
            assert_eq!(
                evidence["first_failure_root_digest"],
                serde_json::to_value(crate::codex_scan_diagnostics::digest(
                    local_index_key(&bad).as_str()
                ))
                .unwrap()
            );
        }
        let serialized = serde_json::to_string(&diagnostics).unwrap();
        assert!(!serialized.contains(home.to_str().unwrap()));
        assert!(!serialized.contains("not a SQLite database"));
        fs::remove_file(bad.join("state_5.sqlite")).unwrap();
        let recovered = CodexTitleMetadata::load_from_roots(&roots);
        assert!(!recovered.state_census_incomplete && !recovered.sidecar_census_incomplete);
        let diagnostics = serde_json::to_value(recovered.local_diagnostics).unwrap();
        for loader in ["state_titles", "state_threads", "spawn_edges"] {
            assert_eq!(diagnostics[loader]["failed_roots"], 0);
            assert!(diagnostics[loader]["first_failure_root_digest"].is_null());
            assert!(diagnostics[loader]["sqlite_extended_code"].is_null());
            assert!(diagnostics[loader]["first_failure_stage"].is_null());
        }

        // The same ids in two homes: `progress` differs only in tokens_used,
        // `locator` in rollout_path, and the 0-token copy of `idle` is never
        // loaded. `progress` is also created and the parent of a `bad` edge.
        let progress = "abcdef00-0000-7000-8000-000000000011";
        let locator = "abcdef00-0000-7000-8000-000000000012";
        let idle = "abcdef00-0000-7000-8000-000000000013";
        let child = "abcdef00-0000-7000-8000-000000000014";
        let schema = concat!(
            "CREATE TABLE threads (id TEXT, title TEXT, tokens_used INTEGER, model TEXT, ",
            "rollout_path TEXT, thread_source TEXT, first_user_message TEXT); ",
            "CREATE TABLE thread_spawn_edges (parent_thread_id TEXT, child_thread_id TEXT);"
        );
        for (codex_dir, progress_tokens, progress_source, locator_path, idle_tokens) in [
            (&bad, 5, "agent_created_thread", "a.jsonl", 3),
            (&good, 7, "user", "b.jsonl", 0),
        ] {
            let db = Connection::open(codex_dir.join("state_5.sqlite")).unwrap();
            db.execute_batch(schema).unwrap();
            for (id, tokens, source, rollout_path) in [
                (progress, progress_tokens, progress_source, "p.jsonl"),
                (locator, 1, "user", locator_path),
                (idle, idle_tokens, "user", "i.jsonl"),
            ] {
                db.execute(
                    "INSERT INTO threads VALUES (?1, 'same', ?2, 'm', ?3, ?4, NULL)",
                    rusqlite::params![id, tokens, rollout_path, source],
                )
                .unwrap();
            }
        }
        let db = Connection::open(bad.join("state_5.sqlite")).unwrap();
        db.execute(
            "INSERT INTO thread_spawn_edges VALUES (?1, ?2)",
            rusqlite::params![progress, child],
        )
        .unwrap();
        drop(db);
        let mut cross = CodexTitleMetadata::load_from_roots(&roots);
        assert!(cross.local_diagnostics.state_threads.identity_conflict);
        assert!(cross.state_census_incomplete && cross.sidecar_census_incomplete);
        assert!(!cross.state_census_unscoped_incomplete);
        assert!(!cross.sidecar_census_unscoped_incomplete);
        let mut index = ScanIndex::default();
        index
            .codex_state_only_snapshot_fingerprints
            .insert(locator.to_string(), "prior".to_string());
        cross.count_prior_state_only_conflicts(&index);
        let taxonomy = cross.local_diagnostics.identity_conflict_taxonomy;
        assert_eq!(
            (
                taxonomy.state_alias_keys,
                taxonomy.state_intra_root_row_keys,
                taxonomy.state_cross_root_keys,
                taxonomy.state_cross_root_progress_only_keys,
                taxonomy.state_cross_root_identity_field_keys,
            ),
            (0, 0, 2, 1, 1)
        );
        assert_eq!(
            taxonomy.state_cross_root_field_differs,
            StateRowFieldDiffs {
                tokens_used: 1,
                rollout_path: 1,
                ..Default::default()
            }
        );
        assert_eq!(
            (
                taxonomy.conflict_keys_total,
                taxonomy.conflict_keys_state_created,
                taxonomy.conflict_keys_prior_state_only,
                taxonomy.conflict_parent_child_edges,
            ),
            (2, 1, 1, 1)
        );
        let serialized = serde_json::to_string(&cross.local_diagnostics).unwrap();
        for id in [progress, locator, idle, child, "p.jsonl", "a.jsonl"] {
            assert!(!serialized.contains(id));
        }
        fs::remove_dir_all(home).unwrap();
    }

    #[test]
    fn codex_local_diagnostics_trace_successors_empty_and_incomplete_finalization() {
        for disposition in [FileReason::Complete, FileReason::ReadOrLineLoss] {
            for empty in [false, true] {
                let (home, root, mut index) = projection_adoption_fixture("codex-local-lineage", 1);
                let old_fingerprint = index
                    .file_snapshot_fingerprints
                    .values()
                    .next()
                    .unwrap()
                    .iter()
                    .next()
                    .unwrap()
                    .clone();
                let quarantines = BTreeMap::from([(
                    old_fingerprint.clone(),
                    snapshot_quarantine_record(SnapshotSource::Codex),
                )]);
                if disposition == FileReason::ReadOrLineLoss {
                    let path = PathBuf::from(index.files.keys().next().unwrap());
                    let mut bytes = fs::read(&path).unwrap();
                    bytes.extend_from_slice(b"not valid json\n");
                    fs::write(&path, bytes).unwrap();
                }
                index.activate_effective_upload_body_witness_revision(1);
                let mut scan =
                    projection_adoption_scan(&root, &mut index, MAX_BACKFILL_FILES_PER_SOURCE);
                prepare_codex_recovery_diagnostics(&mut scan, &index, &quarantines);
                assert_eq!(
                    scan.pending_finalization[0].parse_complete,
                    disposition == FileReason::Complete
                );
                let parsed_count = scan.pending_finalization[0].parsed_snapshot_count as u64;
                if empty {
                    crate::backfill::apply_backfill_cutoff(
                        &mut scan.snapshots,
                        &crate::backfill::BackfillState {
                            backfill_cutoff_at: Some("2026-07-23T00:00:00Z".into()),
                            ..Default::default()
                        },
                    );
                } else if let Some(snapshot) = scan.snapshots.first_mut() {
                    snapshot.output_tokens += 1;
                }
                let mut control = scan.clone();
                control.local_codex_diagnostics = None;
                let mut control_index = index.clone();
                finalize_scan_after_policy(SnapshotSource::Codex, &mut control, &mut control_index);
                finalize_scan_after_policy(SnapshotSource::Codex, &mut scan, &mut index);
                assert_eq!(
                    serde_json::to_value(&index).unwrap(),
                    serde_json::to_value(&control_index).unwrap()
                );
                assert_eq!(
                    serde_json::to_value(&scan.snapshots).unwrap(),
                    serde_json::to_value(&control.snapshots).unwrap()
                );
                let sample = scan.local_codex_diagnostics.unwrap().lineage[0].unwrap();
                assert!(sample.before_current);
                assert_eq!(sample.parsed_count, parsed_count);
                assert_eq!(sample.file_reason, disposition);
                assert_eq!(sample.finalized, disposition == FileReason::Complete);
                if sample.finalized {
                    assert_eq!(sample.finalized_entity_count, u64::from(!empty));
                    assert!(!index
                        .current_snapshot_fingerprints()
                        .contains(&old_fingerprint));
                    assert_eq!(sample.final_body_revision, 1);
                    if !empty {
                        assert_ne!(sample.successor_digests[0], sample.fingerprint_digest);
                        assert!(sample.final_body_digest.is_some());
                    }
                } else {
                    assert!(index
                        .current_snapshot_fingerprints()
                        .contains(&old_fingerprint));
                }
                fs::remove_dir_all(home).unwrap();
            }
        }
    }

    #[test]
    fn codex_local_diagnostics_rotate_only_four_quarantines() {
        let (home, root, mut index) = projection_adoption_fixture("codex-local-rotation", 7);
        let quarantines: BTreeMap<_, _> = index
            .current_snapshot_fingerprints()
            .iter()
            .map(|fingerprint| {
                (
                    fingerprint.clone(),
                    snapshot_quarantine_record(SnapshotSource::Codex),
                )
            })
            .collect();
        index.activate_effective_upload_body_witness_revision(1);
        let mut scan = projection_adoption_scan(&root, &mut index, MAX_BACKFILL_FILES_PER_SOURCE);
        let mut observed = BTreeSet::new();
        for generation in 0..7 {
            scan.local_codex_diagnostics.as_mut().unwrap().generation = generation;
            prepare_codex_recovery_diagnostics(&mut scan, &index, &quarantines);
            let diagnostic = scan.local_codex_diagnostics.unwrap();
            assert_eq!(diagnostic.quarantine_count, 7);
            assert_eq!(diagnostic.lineage.iter().flatten().count(), 4);
            observed.extend(
                diagnostic
                    .lineage
                    .iter()
                    .flatten()
                    .map(|sample| sample.fingerprint_digest),
            );
        }
        assert_eq!(observed.len(), 7);
        fs::remove_dir_all(home).unwrap();
    }

